        if (a[i] * (b[j] + 1) != a[j] * (b[i] + 1)) {
            return a[i] * (b[j] + 1) > a[j] * (b[i] + 1);
        }
        return a[i] > a[j];
    };
    sort(c.begin(), c.end(), cmp);
    vector<long long> dp(33, t * 2);
    multiset<long long> ms; dp[0] = 0;
    for (int i = 0; i < n; i++) {
        if (a[c[i]] == 0) {
            ms.insert(b[c[i]]);
            continue;
        }
        for (int j = 31; j >= 0; j--) {
            if (dp[j] > t) continue;
            if ((a[c[i]] + 1) * (dp[j] + 1) + b[c[i]] <= t) {
                dp[j+1] = min(dp[j+1], (a[c[i]] + 1) * (dp[j] + 1) + b[c[i]]);
            } 
        }
    }
    vector<long long> v;
    long long curr = 0;
    v.emplace_back(curr);
    for (auto &x: ms) {
        curr += x + 1;
        v.emplace_back(curr);
    }
