    cin>>memo[i].first>>memo[i].second;
  }
  sort(memo,memo+n);
  reverse(memo,memo+n);
  deque<int> ans;
  ll sum=0;
  ll time=1;
  ll prev_time=0;
  for(int i=0;i<n;i++){
    if(ans.empty()){
      if(memo[i].first+memo[i].second+1<=t) {
        prev_time=time;
        time=memo[i].first+memo[i].second+2;
        ans.push_back(i);
        sum+=memo[i].first;
      }
    }
    else{
      if(time*memo[i].first+memo[i].second<=t){
        prev_time=time;
        time+=time*memo[i].first+memo[i].second+1;
        ans.push_back(i);
        sum+=memo[i].first;
      }
      else if((time-(sum-memo[ans.at(0)].first+1)*(memo[ans.at(0)].first+memo[ans.at(0)].second)-1)*memo[i].first+memo[i].second<=t){
        prev_time=time-(sum-memo[ans.at(0)].first+1)*(memo[ans.at(0)].first+memo[ans.at(0)].second)-1;
        time=(time-(sum-memo[ans.at(0)].first+1)*(memo[ans.at(0)].first+memo[ans.at(0)].second)-1)*memo[i].first+memo[i].second+1;
        sum-=memo[ans.at(0)].first;
        sum+=memo[i].first;
        ans.pop_front();ans.push_back(i);
