const int N = 2e5 + 10;
const int L = 44;
const ll oo = 1e9 + 10;

ll dp[N][L];

void smain() {

    int n, T;
    cin >> n >> T;
    vector<pll> a;
    vl bones;
    fori (i, n) {
        pll cur;
        cin >> cur.first >> cur.second;
        cur.first++;
        if (cur.first == 1) {
            bones.push_back(cur.second);
        } else {
            a.push_back(cur);
        }
    }

    sort(ALL(a), [&] (const pll & f, const pll & s) -> bool {
        return f.second * s.first + s.second + s.first < s.second * f.first + f.second + f.first;
    });

    fori (i, L) {
        dp[0][i] = oo;
    }
    dp[0][0] = 0;
    n = a.size();
    for (int i = 0; i < n; ++i) {
        fori (cnt, L) {
            dp[i + 1][cnt] = dp[i][cnt];
        }

        fori (cnt, L - 1) if (dp[i][cnt] < oo) {
            inmin(dp[i + 1][cnt + 1], (dp[i][cnt] + 1) * a[i].first + a[i].second );
        }
    }
    cin >> T;
    sort(ALL(bones));
    int ans = 0;
    fori (cnt, L) {
        if (dp[n][cnt] > T)
            continue;
        ll fre = T - dp[n][cnt];
        int cans = cnt;
        for (auto b : bones) {
            if (fre - b - 1 >= 0) {
                fre -= b + 1;
                cans++;
            }
        }
        inmax(ans, cans);
    }
    cout << ans;

}

