	int N, T; cin >> N >> T;
	vector<int>A(N), B(N);

	REP(i, N) {
		cin >> A[i] >> B[i];
		if (A[i] > 0)v1.push_back({ A[i],B[i] });
		else v0.push_back({ A[i],B[i] });
	}
	//print("input");
	if(v1.size()>0)sort(v1.begin(),v1.end(), comp);
	//print("sorted");
	//exit(0);
	VSORT(v0);
	int M = v1.size();
	REP(i, M + 1) {
		REP(j, 50) {
			dp[i][j] = 1e12;
		}
	}
	dp[0][0] = 0;
	REP(i, M) {
		REP(j, 49) {
			ll t = dp[i][j];
			if (t > T)continue;
			chmin(dp[i + 1][j], dp[i][j]);
			//買う
			ll nt = (t + 1)*v1[i].first + v1[i].second + t + 1;;
			if (nt > T)continue;
			chmin(dp[i + 1][j + 1], nt);
		}
	}
	ll ans = 0;
	//print("a");
	REP(k, 50) {
		if (dp[M][k] > T)continue;
		int cnt = k;
		int rem = T - dp[M][k];
		int mm = v0.size();
		REP(i, mm) {
			if (v0[i].second + 1 <= rem) {
				cnt++;
				rem -= (v0[i].second + 1);
			}
		}
		ans = max(ans, cnt);
	}
	print(ans);
}

