	while( cc < '0' || cc > '9' ) {  if( cc == '-' ) flus = - flus ; cc = getchar() ; }
	while( cc >= '0' && cc <= '9' )  cn = cn * 10 + cc - '0', cc = getchar() ;
	return cn * flus ;
}
const int N = 2e5 + 5 ; 
const int inf = 1e9 + 7 ;
int n, m, cnt, num, dp[40], Pre[N] ; 
struct Node {
	int a, b ; 
} t[N], p[N], r[N] ;
bool cmp( Node x, Node y ) {
	return x.b < y.b ; 
} 
bool cmp2( Node x, Node y ) {
	return ( 1ll * x.b * y.a - x.b - x.a ) < ( 1ll * y.b * x.a - y.b - y.a ) ;
}
int check( int x ) {
	int l = 0, r = num, ans = 0 ; 
	while( l <= r ) {
		int mid = ( l + r ) >> 1 ; 
		if( Pre[mid] <= x ) ans = mid, l = mid + 1 ;
		else r = mid - 1 ;
	} return ans ; 
}
signed main()
{
	n = gi(), m = gi() ;
	rep( i, 1, n ) {
		t[i].a = gi(), t[i].b = gi() ; 
		if( t[i].a != 0 ) p[++ cnt] = t[i] ; 
		if( t[i].a == 0 ) r[++ num] = t[i] ; 
	}
	rep( j, 0, 32 ) dp[j] = m + 1 ; 
	sort( p + 1, p + cnt + 1, cmp2 ) ;
	sort( r + 1, r + num + 1, cmp ) ;
	dp[0] = 0 ; 
	for( re int i = 1; i <= cnt; ++ i ) {
		for( re int j = 32; j > 0; -- j ) {
			if( dp[j - 1] > m ) continue ; 
			if( p[i].a * dp[j - 1] > m ) continue ; 
			dp[j] = min( dp[j - 1] + ( dp[j - 1] + 1 ) * ( p[i].a ) + p[i].b, dp[j] ) ;
		}
	}
	for( re int i = 1; i <= num; ++ i ) Pre[i] = Pre[i - 1] + r[i].b + 1 ; 
	int Ans = 0 ;
	for( re int i = 0; i <= 32; ++ i ) {
		int ans = i, T = dp[i] ;
		if( T > m ) continue ; 
		ans = ans + check( m - dp[i] ) ;
		Ans = max( Ans, ans ) ;
	}
	printf("%lld\n", Ans ) ;
	return 0 ;
}

