using namespace std;
#define ll long long
#define N 200005
int a[N],b[N];

int ids[N];

bool cmp(int x,int y) {
  ll r = (ll)(a[x]+b[x])*a[y] + b[y] + a[y];
  ll u = (ll)(a[y] + b[y])*a[x] + b[x] + a[x];
  if(r!=u)
    return r<u;
  else {
    return a[x]<a[y];
  }
}
void solve() {
  int n,T;scanf("%d %d ", &n,&T);
  ll dp[N];
  for(int i=0;i<=n;++i) {
    dp[i] = 1e18;
  }
  for(int i=0;i<n;++i) {
    scanf("%d %d ", &a[i],&b[i]);
    ++a[i];
    ids[i] = i;
  }
  sort(ids,ids+n,cmp);
  int ret = 0;
  dp[0] = 0;
  for(int i=0;i<n;++i) {
    int id = ids[i];
    for(int j= n-1;j>=0;--j) {
      if(dp[j]<=T) {
        dp[j+1] = min(dp[j+1], dp[j]*a[id]+b[id]);
      }
    }
  }
  for(int i=n;i>=0;--i) {
    if(dp[i]<=T) {
      ret = i;
      break;
    }
  }
  printf("%d\n", ret);
}

int main() {
    //freopen("input.txt","r",stdin);
    solve();
    return 0;
}

#define _CRT_SECURE_NO_WARNINGS
#include <stdio.h>

int n, t;
int a[200000], b[200000];
bool check[200000];

int main(void) {
	scanf("%d%d", &n, &t);
	for (int i = 1; i <= n; i++) {
		scanf("%d%d", &a[i], &b[i]);
	}

	int time = 1;
	int cnt = 0, p;
	for (int i = 1; i <= n; i++) {
		if (time > t) break;
		int min = 2000000000;
		for (int j = 1; j <= n; j++) {
			if (check[j]) continue;
			if (min > time* a[j] + b[j]) {
				min = time * a[j] + b[j];
				p = j;
			}
		}
		if (min != 2000000000) {
			check[p] = 1;
			if (time + min > t) break;
			time += min + 1;
			cnt++;
		}

	}

	printf("%d", cnt);
	return 0;
}

