void solve(){
    int n,T; cin>>n>>T; T++;
    dp[0] = 1;
    FOR(j,1,L-1) dp[j] = T+1;

    vector<int> offs = {0};
    vector<pair<int,int>> shops;

    for(int i=0;i<n;i++){
        int a,b; cin>>a>>b; b++;
        if(a == 0) offs.push_back(b);
