        for(int m = L-2;m >= 0;m--){
            int off = dp[m] + dp[m]*sp.first + sp.second;
            if(off <= T) dp[m+1] = min(dp[m+1],off);
        }
    }

    sort(all(offs));
    for(int i=1;i<sz(offs);i++) offs[i] += offs[i-1];

    int j = sz(offs) - 1;

    int ans = 0;

    for(int m=0;m<L;m++){
        while(j >= 0 && dp[m] + offs[j] > T) j--;
        if(j < 0) break;
        ans = max(ans,m + j);
    }

    cout<<ans<<endl;
}

