long long int mine(const long long int* array, size_t size)
{
    assert(array != NULL);
    assert(size >= 1);

    long long int min = array[0];
    for (size_t i = 1; i < size; ++i) {
        if (min > array[i]) {
            min = array[i];
        }
    }
    return min;
}
long long int maxe(const long long int* array, size_t size)
{
    assert(array != NULL);
    assert(size >= 1);

    long long int max = array[0];
    for (size_t i = 1; i < size; ++i) {
        if (max < array[i]) {
            max = array[i];
        }
    }
    return max;
}

