    if (dp[n][i] > t) continue;
    int hv = t - dp[n][i];
    int l = 0, r = m + 1;
    while (r - l > 1) {
      int mid = (l + r) >> 1;
      if (pref[mid] + mid <= hv) l = mid;
      else r = mid;
    }
    ans = max(ans, i + l);
  }
  cout << ans << '\n';
}

