		for (int j = 0; j <= 40; j++) {
			if (dp[i - 1][j] == (1LL << 60)) continue;
			dp[i][j] = min(dp[i][j], dp[i - 1][j]);
			long long V = dp[i - 1][j] + 1LL;
			long long S = V * L[i - 1].a + L[i - 1].b;
			dp[i][j + 1] = min(dp[i][j + 1], V + S);
		}
