	for (int i = 0; i <= 40; i++) {
		if (dp[L.size()][i] > T) continue;
		long long R = dp[L.size()][i], cnt = i;
		for (int j = 0; j < L2.size(); j++) {
			if (R + L2[j] + 1LL <= T) { cnt++; R += L2[j] + 1LL; }
