LL head[maxn],p[maxn],dep[maxn];
std::vector<LL> V[3],a[3];
void Add(LL u,LL v){
	dis[++num]=(node){v,head[u]}; head[u]=num;
}
void Dfs(LL u,LL f){
	V[dep[u]].pb(u);
	for(LL i=head[u];i;i=dis[i].nxt){
		LL v(dis[i].to); if(v==f) continue;
		dep[v]=dep[u]^1; Dfs(v,u); 
	}
}
