typedef long long ll;
const int maxn = 2e5 + 5,inf = 0x3f3f3f3f;
int n,t,cnt,tot;
ll dp[35],pre[maxn];

struct node
{
    int a,b;
    bool operator<(const node&rhs) const
    {
        return 1LL * a * (rhs.b + 1) > 1LL * rhs.a * (b + 1);
    }
}p[maxn];

int cal()
{
    for(int i=0;i<35;i++) dp[i] = inf;
    dp[0] = 0;
    for(int i=0;i<tot;i++){
        for(int j=30;j>=0;j--){
            if(dp[j]==inf) continue;
            dp[j+1] = min(dp[j+1],(dp[j] + 1) * (p[i+1].a + 1) + p[i+1].b);
            if(dp[j+1]>t) dp[j+1] = inf;
        }
    }
    int ans = 0;
    for(int i=0;i<=31;i++){
        if(dp[i]!=inf){
            int x = t - dp[i];
            int y = upper_bound(pre,pre+cnt+1,x) - pre - 1;
            ans = max(ans,i+y);
        }
    }
    return ans;
}

