struct node {
	long long A;
	long long B;
	bool operator < (node rhs) const {
		long long val1 = (A - 1) * rhs.B;
		long long val2 = (rhs.A - 1) * B;
		return (val1 > val2) || (val1 == val2 && A < rhs.A);
	}
} vec[N];

long long num[N], pre[N];

int main () {
	read(n), read(t);
