        napsack[i] = t + 1;
    }
    napsack[0] = 0;
    reverse(ALL(others));
    REP(i, others.size()) {
        for (int q = 40; q >= 0; --q) {
            if (napsack[q] == t + 1) continue;
            int next = napsack[q];
            next *= others[i].second.first;
            next += others[i].second.second;
            napsack[q + 1] = min(napsack[q + 1], next);
        }
    }

    int goi = 0;
    REP(q, 40) {
        int now = napsack[q];
        if (now > t) continue;
        int ans = q;
        for (int q = 0; q < zero.size(); ++q) {
            now += zero[q];
            if (now <= t) ans++;
        }
        goi = max(goi, ans);
    }
    cout << goi << endl;
}

