        else a.pb(A),b.pb(B);
    }
    int m=a.size();
    vec id;
    rep(i,m)id.pb(i);
    sort(all(id),[&](int x,int y){
        return (a[x])/b[x] > (a[y])/b[y];
    });
    vec id2;
    rep(i,n-m){
        id2.pb(i);
    }
    sort(all(id2),[&](int x,int y){
        return b2[x]<b2[y];
    });
    rep(i,n+1)rep(j,40)dp[i][j]=INT_MAX;
    dp[0][0]=1;
    rep(i,m){
        rep(j,31){
            chmin(dp[i+1][j],dp[i][j]);
            chmin(dp[i+1][j+1],dp[i][j]+dp[i][j]*a[id[i]]+b[id[i]]);
        }
    }
    t++;
    int ans=0;
    rep(j,31){
        ll T=dp[m][j];
        if(T>t)continue;
        int now=j;
        int p=0;
        while(p<n-m and T+b2[id2[p]]<=t){
            T+=b2[id2[p]]; p++;
        }
        chmax(ans,p+(int)j);
    }
    cout<<ans<<endl;

}

