  	ll a,b;
  	cin>>a>>b;
  	ps.push_back(P(a+1,a+b+1));
  }
  sort(all(ps),[](const P& a,const P& b){
  	if(a.fi==1&&b.fi==1) return a.se < b.se;
  	else return b.fi*a.se+b.se < a.fi*b.se+a.se;
  });

  ll M=N;
  rep(i,N){
  	if(ps[i].fi==1){
  		M=i;
  		break;
  	}
  }
