  	if(dp[i][j]==INF)continue;
  	minch(dp[i+1][j],dp[i][j]);
  	if(j+1<=K)minch(dp[i+1][j+1],ps[i].fi*dp[i][j]+ps[i].se);
  }

  ll res=0;
  rep(j,K+1){
  	if(dp[M][j]>T)continue;
  	ll crtt=dp[M][j];
