using namespace std;
int N;
long long T;
long long dp[200100][31] = {};
long long a[200100], b[200100];

int main() {
    cin >> N >> T;
    for(int i=0; i<N; ++i) cin >> a[i] >> b[i];

    vector<int> order(N);
    iota(begin(order), end(order), 0);
    sort(begin(order), end(order), [](int i, int j){return a[i] * (b[j] + 1) > a[j] * (b[i] + 1);});

    int nmax = 0;
    for(int i=0; i<N; ++i) if(a[order[i]] > 0) nmax = i + 1;

    for(int j=1; j<=30; ++j) dp[0][j] = 1001001001001001001;
    for(int i=0; i<nmax; ++i) {
        dp[i + 1][0] = 0;
        for(int j=1; j<=30; ++j) {
            dp[i + 1][j] = min(dp[i][j], dp[i][j - 1] + 1 + a[order[i]] * (dp[i][j - 1] + 1) + b[order[i]]);
        }
    }

    vector<long long> B(N - nmax);
    for(int i=0; i<N-nmax; ++i) B[i] = b[order[nmax + i]];
    sort(begin(B), end(B));

    int res = 0;
    for(int j=0; j<=min(nmax, 30); ++j) {
        if(dp[nmax][j] > T) break;
        int cnt = j;
        long long t = dp[nmax][j];
        for(long long tmp : B) {
            if(t + 1 + tmp <= T) {
                t += 1 + tmp;
                ++cnt;
            }
        }
        res = max(res, cnt);
    }

    cout << res << '\n';
}

