#include <bits/stdc++.h>
using namespace std;
using LL = long long;
#define repex(i, a, b, c) for(int i = a; i < b; i += c)
#define repx(i, a, b) repex(i, a, b, 1)
#define rep(i, n) repx(i, 0, n)
#define repr(i, a, b) for(int i = a; i >= b; i--)
#define pb push_back
#define a first
#define b second
#define all(x) x.begin(), x.end()
const LL UPPER = 202020202020202020;
const int LIMIT = 29;
LL dp[202020][LIMIT], zCum[202020];
int cnt[LIMIT];

struct store{
    LL a, b;
    bool operator < (const store& rhs) const{
        return a * (rhs.b + 1) > rhs.a * (b + 1);
    }
};

int main(){

    // 1. 入力情報.
    int N;
    LL T, a, b;
    scanf("%d %lld", &N, &T);
    vector<store> v1;
    vector<LL> v2;
    rep(i, N){
        scanf("%lld %lld", &a, &b);
        if(a == 0){
            v2.pb(b);
        }else{
            store s;
            s.a = a;
            s.b = b;
            v1.pb(s);
        }
    }

    // 2. sort.
    sort(all(v1));
    sort(all(v2));
    // for(auto &p : v1) printf("a=%lld b=%lld\n", p.a, p.b);

    // 3. 累積和.
    int l2 = v2.size();
    rep(i, l2) zCum[i + 1] = zCum[i] + v2[i] + 1;
    // rep(i, l2 + 1) printf("%lld ", zCum[i]);
    // puts("");

    // 4. 初期化.
    rep(i, 202020) repx(j, 1, LIMIT) dp[i][j] = UPPER;

    // 5. dp更新.
    int l1 = v1.size();
    dp[0][0] = 0;
    repx(i, 1, l1 + 1){
        rep(j, min(LIMIT, i + 1)){
            if(j){
                LL t = min(T + 1, v1[i - 1].a * (dp[i - 1][j - 1] + 1) + v1[i - 1].b + dp[i - 1][j - 1] + 1);
                if(i > j) dp[i][j] = min(dp[i - 1][j], t);
                else      dp[i][j] = t;
            }
        }
    }
    // rep(i, l1 + 1){
    //     rep(j, min(LIMIT, i + 1)) printf("%lld ", dp[i][j]);
    //     puts("");
    // }

    // 6. いくつのお店を回ることができるか？
    rep(i, min(LIMIT, l1 + 1)){
        // a >= 1 となるお店を, i個回る場合について, それぞれ計算.
        LL res = T - dp[l1][i];
        if(res >= 0){
            int at = upper_bound(zCum, zCum + l2 + 1, res) - zCum;
            cnt[i] = i + (at - 1);
            // printf("at=%d cnt[%d]=%d\n", at, i, cnt[i]);
        }
    }

    // 7. 出力.
    int ans = 0;
    rep(i, LIMIT) ans = max(ans, cnt[i]);
    printf("%d\n", ans);
    return 0;

}

