int main(){
    ios_base::sync_with_stdio(false);
    cin.tie(NULL);

    int N;
    ll T;
    cin >> N >> T;
    vll A(N);
    vll B(N);

    for (int i=0;i<N;i++) cin >> A[i] >> B[i];

    vector<pair<ll, ll>> funcs;
    vll zeros;
    for (int i=0;i<N;i++) {
        if (A[i] > 0) {
            funcs.push_back({A[i], A[i] + B[i] + 1});
        } else {
            zeros.push_back(B[i]+1);
        }
    }

    sort(funcs.begin(), funcs.end(), mycomp);
    sort(zeros.begin(), zeros.end());

    // for (auto func : funcs) {
    //     cout << func.first << " " << func.second << endl;
    // }

    int M = funcs.size();
    vll dprow(M,T+1);
    vvll dp(40, dprow);

    for (int i=0;i<M;i++) dp[0][i] = 0;
    for (int i=1;i<40;i++) {
        ll cmin = T+1;
        if (i==1) cmin = 0;
        for (int j=0;j<M;j++){
            if (cmin < T) {
                ll a = funcs[j].first;
                ll b = funcs[j].second;
                dp[i][j] = min(dp[i][j], (a+1)*cmin + b);
            }

            cmin = min(cmin, dp[i-1][j]);
        }
    }

    // for (int i=0;i<5;i++) {
    //     cout << i << ": ";
    //     for (int j=0;j<M;j++) cout << dp[i][j] << " ";
    //     cout << endl;
    // }

    int Z = zeros.size();
    vll czeros(Z+1, 0);
    for (int i=0;i<Z;i++) czeros[i+1] = czeros[i] + zeros[i];

    int ans = 0;
    for (int i=0;i<40;i++) {
        ll best = T+1;
        if (i == 0) best = 0;
        for (int j=0;j<M;j++) {
            best = min(best, dp[i][j]);
        }

        // cout << i << " " << best << endl;

        if (best < T) {
            auto low = upper_bound(czeros.begin(), czeros.end(), T-best);
            int num_lt = (low - czeros.begin());
            num_lt--;

            ans = max(ans, i + num_lt);
        }

    }

    cout << ans << endl;

    return 0;
}

