long long invF(int idx, long long tm) {
  long long initTm = tm;
  tm -= b[idx];
  if (tm <= 0) {
    return -1;
  }
  tm = tm / (1 + a[idx]);
  if (f(idx, tm) > initTm) {
    return -1;
  }
  return tm - 1;
}

long long calc(int a, int b) {
  return f(b, f(a, 1) + 1);
}

