		rep(i, P.size()) {
			UL l = 0, r = B.size() + 1;
			while (l + 1 < r) {
				UL m = (l + r) >> 1;
				if (P[i] + B[m - 1] <= T) l = m;
				else r = m;
			}
			ans = max(ans, i + l);
			//cout << "i = " << i << ", l = " << l << endl;
		}

		cout << ans << endl;
	}

	Problem();
};
