constexpr ll INF = 2e18;

struct Hull {
	using T = ll;

	struct Line {
		T a, b, end;
		int id;
		T intersect(const Line& r) const {
			if (a==r.a) return b > r.b ? INF : -INF;
			ll u = b-r.b, d = r.a-a;
			return u/d + ((u^d) >= 0 || !(u%d));
		}
	};

	vector<Line> S;

	void init() {
		S.clear();
		S.pb({ 0, -INF, INF, -1 });
	}

	void push(T a, T b, int id) {
		Line l{a, b, INF, id};
		while (true) {
			T e = S.back().end = S.back().intersect(l);
			if (sz(S) < 2 || S[sz(S)-2].end < e)
				break;
			S.pop_back();
		}
		S.pb(l);
	}

	pair<T, int> query(T x) {
		auto t = *upper_bound(all(S), x, [](int l, const Line& r) { return l < r.end; });
		return {t.a*x + t.b, t.id};
	}
};

Hull hull;

void add(Pii l, int id) {
	hull.push(l.x, -l.y, id);
}

pair<ll, int> query(ll x) {
	auto p = hull.query(-x);
	return {-p.x, p.y};
}

void answer(int k) {
	cout << k << endl;
	exit(0);
}

int main() {
	cin.sync_with_stdio(0); cin.tie(0);
	cout << fixed << setprecision(18);

	int n; cin >> n;
	ll T; cin >> T;

	vector<Pii> shops(n);
	each(s, shops) cin >> s.x >> s.y;
	sort(all(shops));

	vector<bool> seen(n);
	int ans = 0;
	ll time = 0;

	while (ans < n) {
		time++;

		bool has = 0;
		hull.init();

		rep(i, 0, n) {
			if (!seen[i]) {
				add(shops[i], i);
				if (shops[i].x > 0) has = 1;
			}
		}

		if (!has) {
			rep(i, 0, n) {
				if (!seen[i]) {
					auto& s = shops[i];
					time += s.y;
					if (time > T) answer(ans);
					ans++;
					time++;
				}
			}
			answer(ans);
		}

		auto p = query(time);
		time += p.x;
		if (time > T) answer(ans);
		seen[p.y] = 1;
		ans++;
	}

	answer(ans);
	return 0;
}

