}

int main()
{
	int n;
	long long T;
	scanf("%d%lld", &n, &T);
	int tt = 1;
	for (int i = 1; i <= n; i++, tt++)
	{
		scanf("%lld%lld", &mar[tt].a, &mar[tt].b);
		if (mar[tt].a == 0)
			spe.push(mar[tt].b + 1), tt--;
	}
	n = tt - 1;
	sort(mar + 1, mar + n + 1, cmp);
	int tn = min(n, (int)log2(T));
	memset(f, 0x3f, sizeof(f));
	f[0][0] = 0;
	for (int i = 1; i <= n; i++)
		for (int j = 1; j <= min(tn, i); j++)
			f[i][j] = min(f[i - 1][j], (f[i - 1][j - 1] + 1) * (mar[i].a + 1) + mar[i].b);
	int total = 0, answer = 0;
	for (int i = tn; i; i--)
	{
		if (f[n][i] > T)
