using ll = long long;
struct Market
{
    ll a,b;
    bool operator<(const Market &o)const
    {
        if(o.a || a)
            return o.a*b < a*o.b;
        else
            return b < o.b;
    }
};
void solve(ll T, vector<Market> m)
{
    vector<Market>m1,m0;
    for(auto x:m)
    {
        if(x.a==0)m0.push_back(x);
        else m1.push_back(x);
    }
    sort(m1.begin(),m1.end());
    sort(m0.begin(),m0.end());
    vector<ll> dp(34,INT_MAX);
    dp[0] = 0;
    for(int i=0;i<m1.size();++i)
    {
        int j = 32;
        while(dp[j] >= T) j--;
        for(;j>=0;--j)
        {
            if(dp[j] * m1[i].a + m1[i].b < dp[j+1])
                dp[j+1] = dp[j] * m1[i].a + m1[i].b;
        }
    }
    int ans = 0;
    int j;
    for(int i=0;i<=32;++i)
        if(dp[i] <= T)
        {    
            ans = i;
            j = i;
        }
    ll sum = 0;
    for(int i=0;i<m0.size();++i)
    {
        sum += m0[i].b;
        if(sum > T) break;
        while(j>=0 && dp[j] + sum > T)
        {
            j--;
        }
        ans = max(ans,j + i + 1);
    }
    cout<<ans<<endl;
}

