struct shop {
	ll a, b;
	bool operator<(const shop& o) const {
		if (a == 1 and o.a == 1) {
			return b < o.b;
		} else {
			return b * (o.a - 1) < o.b * (a - 1);
		}
	}
};

int main() {
	fast_cin();
	int n; ll T;
	cin >> n >> T;
	++T;
	vector<shop> s(n);
	for (auto& i : s) {
		cin >> i.a >> i.b;
