	int bak_n = n;
	while (n > 0 and s[n - 1].a == 1) {
		--n;
	}
	vector<ll> dp(LOG + 1, inf);
	dp[0] = 1;
	for (int i = 0; i < n; ++i) {
		for (int j = LOG - 1; j >= 0; --j) {
			dp[j + 1] = min(dp[j + 1], s[i].a * dp[j] + s[i].b);
