#include <bits/stdc++.h>
using namespace std;
#define ll long long
#define N 200005
int a[N],b[N];

int ids[N];

bool cmp(int x,int y) {
  ll r = (ll)(a[x]+b[x])*a[y] + b[y] + a[y];
  ll u = (ll)(a[y] + b[y])*a[x] + b[x] + a[x];
  return r<u;
}
void solve() {
  int n,T;scanf("%d %d ", &n,&T);
  ll dp[N];

  vector<int> ones;
  int pos = 0;
  for(int i=0;i<n;++i) {
    scanf("%d %d ", &a[i],&b[i]);
    ++a[i];
    if(a[i]!=1) {
      ids[pos++] = i;
    } else {
      ones.push_back(b[i]);
    }
  }
  sort(ones.begin(),ones.end());
  if(pos>0) {
    sort(ids,ids+pos,cmp);
  }
  int ret = 0;
  const int MAX_LEN = 60;
  for(int i=0;i<=MAX_LEN;++i) {
    dp[i] = 1e18;
  }
  dp[0] = 0;
  for(int i=0;i<pos;++i) {
    int id = ids[i];
    for(int j= MAX_LEN-1;j>=0;--j) {
      if(dp[j]<=T) {
        dp[j+1] = min(dp[j+1], dp[j]*a[id]+b[id] + a[id]);
      }
    }
  }
  int size = ones.size();
  ll sum = 0;
  for(int num : ones) {
    sum += num + 1;
  }
  for(int i=0;i<=MAX_LEN;++i) {
    ll c = dp[i];
    if(c<=T) {
      while(size>0 && c + sum>T) {
        sum -= ones[size-1] + 1;
        --size;
      }
      ret = max(ret, i + size);
    } else {
      continue;
    }
  }

  printf("%d\n", ret);
}

