#include <iostream>
#include <vector>
using namespace std;

int ans = 0;
int *a, *b, *L;
int N, T;

void swap_(int i, int j)
{
  int c;
  c = a[i];
  a[i] = a[j];
  a[j] = c;
}

void perm(int n)
{
  if (n <= 1) {
    int t = 0;
    int i = 0;
    for (; i < N; i++) {
      t++;
      t += a[L[i]] * t + b[L[i]];
      if (t > T + 0.5) {
        break;
      }
      i++;
    }
    ans = max(ans, i - 1);
  } else {
    for (int i = 0; i < n; i++) {
      swap_(i, n - 1);
      perm(n - 1);
      swap_(n - 1, i);
    }
  }
}

int main() {
  cin.tie(0);
  ios::sync_with_stdio(false);

  cin >> N >> T;

  a = new int[N];
