  for (int i = 0; i < N; i++) {
    cin >> a[i] >> b[i];
  }

  L = new int[N];
  for (int i = 1; i < N; i++) {
    L[i] = i;
  }

  perm(N);

  cout << ans << "\n";
  delete[] a;
  delete[] b;
  delete[] L;

  return 0;
}

