      long long r = t - dp[i][j];
      auto itr = upper_bound(ALL(sbs), r);
      int cnt = distance(sbs.begin(), itr);
      ans = max(ans, j + cnt);
    }
  }
  cout<<ans<<endl;
  return 0;
}

