const long long INF = 9e18;

std :: set <long long> num;
std :: map <int, std :: priority_queue <long long, std :: vector <long long>, std :: greater <long long>>> minn;

inline void read() {}
template <typename Tp1, typename ...Tp2>
inline void read(Tp1 &num, Tp2 &...rest) {
    char c = getchar();
    while (c < '0' || c > '9') c = getchar();
    for (num = 0; c >= '0' && c <= '9'; c = getchar()) num = (num << 1) + (num << 3) + (c ^ '0');
    read(rest...);
}

int main() {
    long long t;
    int n, ans = 0;
    for(read(n, t); n; n--) {
        long long a, b;
        read(a, b);
        num.insert(a);
        minn[a].push(b);
    }
    for (long long tim = 1; tim <= t; tim++) {
        long long id, qtim = INF;
        for (const long long it : num) {
            long long tmp = minn[it].top();
            if (tim * it + tmp < qtim) {
                id = it;
                qtim = tim * it + tmp;
            } else if (tim * it + tmp == qtim && it > id) id = it;
        }
        if (tim + qtim > t) break;
        ans++; tim += qtim;
        minn[id].pop();
        if (minn[id].empty()) num.erase(id);
    }
    printf("%d\n", ans);
    return 0;
}

