  }
  */

  vector<long long> a_z_sum;
  a_z_sum.push_back(0);
  for(int i = 0; i < a_z.size(); i++){
    a_z_sum.push_back(a_z_sum[i] + a_z[i] + 1);
  }

  // dp[i][j] := using mise[0: i), with time dp[i][j], j shop
  // dp[i + 1][j + 1] = a * (dp[i][j] + 1) + b
  vector<vector<long long>> dp(a_nz.size() + 1,
                               vector<long long>(31, T + 1));
  for(int i = 0; i <= a_nz.size(); i++){
    dp[i][0] = 0;
  }
  for(int i = 0; i < a_nz.size(); i++){
    int a = a_nz[i].second.first, b = a_nz[i].second.second;
    for(int j = 0; j < 30; j++){
      dp[i + 1][j + 1] = min(dp[i][j + 1], min(a * (dp[i][j] + 1) + b, T + 1));
    }
  }

  /*
  for(int i = 0; i < 30; i++){
    cout << i << ' ' << dp[a_nz.size()][i] << endl;
  }
  */

  int ans = 0;
  for(int i = 0; i < 30; i++){
    int zero_cnt = 0;
    long long t_nz = dp[a_nz.size()][i];
    if(t_nz <= T){
      long long t_resid = T - t_nz;
      zero_cnt = (lower_bound(a_z_sum.begin(), a_z_sum.end(), t_resid + 1) - a_z_sum.begin() - 1);
      ans = max(ans, i + zero_cnt);
    }
    //cout << i << ' ' << zero_cnt << ' ' << endl;
  }
  cout << ans << endl;

}

