const size_type SIZE = 64;
mdarray<ll, SIZE> dp;
const ll inf = 1e9 + 10;

int main() {
    ll n, t;
    std::cin >> n >> t;
    vec<pll> ab(n);
    for (auto& [ a, b ] : ab) std::cin >> a >> b;
    std::fill(ALL(dp), inf);
    dp[0] = 0;

    vec<pll> ab0, ab1;
    for (auto [ a, b ] : ab) {
        auto &v = (a == 0 ? ab0 : ab1);
        v.emplace_back(a, b);
    }

    std::sort(ALL(ab0));
    std::sort(ALL(ab1), [](pll p, pll q) {
        auto [ ai, bi ] = p;
        auto [ aj, bj ] = q;
        return aj * (bi + 1) < ai * (bj + 1);
    });

    vec<ll> sumv(ab0.size() + 1);
    for (ll i = 0; i < ab0.size(); i++) sumv[i + 1] = sumv[i] + ab0[i].second + 1;
    if (sumv.back() < inf) sumv.push_back(inf);

    for (auto [ a, b ] : ab1) {
        for (ll i = SIZE - 2; 0 <= i; i--) {
            ll cur = dp[i];
            ll wait = a * (cur + 1) + b;
            chmin(dp[i + 1], cur + 1 + wait);
        }
    }

    ll ans = 0;
    for (ll i = 0; i < SIZE; i++) {
        if (t < dp[i]) continue;
        ll rest = t - dp[i];
        auto ite = std::upper_bound(ALL(sumv), rest) - 1;
        ll add = std::distance(sumv.begin(), ite);
        chmax(ans, i + add);
    }

    std::cout << ans << "\n";
    return 0;
}

