struct Line {
  mutable ll k, m, p;
  bool operator<(const Line& o) const { return k < o.k; }
  bool operator<(ll x) const { return p < x; }
};

struct LineContainer : multiset<Line, less<>> {
  // (for doubles, use inf = 1/.0, div(a,b) = a/b)
  const ll inf = LLONG_MAX;
  ll div(ll a, ll b) { // floored division
    return a / b - ((a ^ b) < 0 && a % b); }
  bool isect(iterator x, iterator y) {
    if (y == end()) { x->p = inf; return false; }
    if (x->k == y->k) x->p = x->m > y->m ? inf : -inf;
    else x->p = div(y->m - x->m, x->k - y->k);
    return x->p >= y->p;
  }
  void add(ll k, ll m) {
    auto z = insert({k, m, 0}), y = z++, x = y;
    while (isect(y, z)) z = erase(z);
    if (x != begin() && isect(--x, y)) isect(x, y = erase(y));
    while ((y = x) != begin() && (--x)->p >= y->p)
      isect(x, erase(y));
  }
  ll query(ll x) {
    assert(!empty());
    auto l = *lower_bound(x);
    return l.k * x + l.m;
  }
};

int n, t, ile, a[N], b[N], cnt[SQ];
bool rem[N];
LineContainer l[SQ];

signed main() {
  init_ios();
  cin >> n >> t;
  for (int i = 0; i < n; ++i) {
    cin >> a[i] >> b[i];
    a[i]++;
    b[i]++;
    l[i/SQ].add(-a[i], -b[i]);
    ++cnt[i/SQ];
  }
  int cur = 0;
  while (cur < t) {
    int wh = -1, res = 6e18;
    for (int i = 0; i < SQ; ++i) {
      if (cnt[i] == 0)
        continue;
      int hm = -l[i].query(cur);
      if (hm < res) {
        wh = i;
        res = hm;
      }
    }
    if (res > t)
      break;
    ++ile;
    int r1 = SQ*wh;
    int r2 = min(n, r1+SQ);
    bool jest = false;
    for (int i = r1; i < r2; ++i)
      if (!rem[i] && a[i]*cur+b[i] == res) {
        l[wh].clear();
        --cnt[wh];
        rem[i] = true;
        for (int j = r1; j < r2; ++j) {
          if (!rem[j])
            l[wh].add(-a[j], -b[j]);
        }
        jest = true;
        break;
      }
    assert(jest);
    cur = res;
  }
  cout<<ile<<"\n";
}

