const int N = 2e5 + 5, LG = 35;

int DP[N][LG];
int A[N], B[N], P[N];

bool CMP(int i, int j) {
	if (A[i] == 0 && A[j] == 0) return B[i] < B[j];
	else return 1LL * A[i] * (B[j] + 1) > 1LL * A[j] * (B[i] + 1);
}

int32_t main() {

	ios::sync_with_stdio(0), cin.tie(0), cout.tie(0);
	mt19937 Rnd(time(0));

	memset(DP, 63, sizeof DP);

	int n, t, m = 0; cin >> n >> t;
	for (int i = 0; i < n; i++) cin >> A[i] >> B[i], P[i] = i, m += (A[i] != 0);
	sort(P, P + n, CMP);
	DP[0][0] = 0;
	for (int i = 0; i < m; i++) {
		DP[i + 1][0] = 0;
		for (int j = 0; j + 1 < LG; j++)
			if (DP[i][j] > t) DP[i + 1][j + 1] = DP[i][j + 1];
			else DP[i + 1][j + 1] = min(DP[i][j + 1],  1LL * (DP[i][j] + 1) * (1 + A[P[i]]) + B[P[i]]);
	}
	int ans = 0;
	for (int i = 0; i < LG; i++) {
		int x = DP[m][i], y = i;
		if (x >	t) continue;
		for (int j = m; j < n; j++, y += (t >= x)) x += B[P[j]] + 1;
		ans = max(ans, y);
	}
	cout << ans << endl;

	return 0;
}

