const ll MAX = 1e9 + 42;

struct node {
  node(ll a, ll b) : a(a), b(b) {}

  ll a, b;
  bool operator<(const node& other) const {
    return b * other.a < a * other.b;
  }
  ll advance(ll t) const {
//    if (t > MAX) return MAX;
    return min(MAX, (a + 1) * t + b);
  }
};

int main() {
#ifdef LOCAL_EXEC
//	freopen("sample.in", "r", stdin);
//	freopen("sample.out", "w", stdout);
#else
  ios_base::sync_with_stdio(false); cin.tie(NULL);
#endif

  int n; ll T; cin >> n >> T;
  vector<node> vals;
  vector<ll> zero;
  while (n--) {
    ll a, b; cin >> a >> b;
    ++b;
    if (a == 0) zero.push_back(b);
    else vals.emplace_back(a, b);
  }
  sort(vals.begin(), vals.end());

  n = vals.size();
  const int LOG = 40;
  vector<vector<ll>> best(n + 1, vector<ll>(LOG, MAX));
  best[0][0] = 0;
  for (int i = 1; i <= n; i++) {
    best[i][0] = 0;
    for (int j = 1; j < LOG; j++) {
      best[i][j] = min(best[i - 1][j], vals[i - 1].advance(best[i - 1][j - 1]));
    }
  }

  sort(zero.begin(), zero.end());
  ll extra = 0;
  for (ll z: zero) extra += z;
  int ans = 0;
  for (int j = 0, e = zero.size(); j < LOG; j++) {
    ll rem = T - best[n][j];
    if (rem < 0) break;
    while (extra > rem) {
      extra -= zero[--e];
    }
    ans = max(ans, j + e);
  }
  cout << ans << endl;

  return 0;
}

