#define rep(i, n) for(UL i = 0; i < (n); i++)

bool Cmp(const pair<ULL, ULL>& l, const pair<ULL, ULL>& r) {
	return r.first * l.second < l.first * r.second;
}

struct Problem {

	void Solve() {
		UL N; cin >> N;
		ULL T; cin >> T;
		vector<pair<ULL, ULL>> A;
		vector<ULL> B;
		rep(i, N) {
			ULL a, b; cin >> a >> b;
			if (a == 0) { N--; i--; B.push_back(b + 1); }
			else A.push_back({ a, b });
		}
		sort(A.begin(), A.end(), Cmp);
		deque<ULL> P; P.push_back(0);
		rep(i, N) {
			P.push_back(-1);
			for (UL j = P.size() - 1; j > 0; j--) {
				ULL t = P[j - 1] + 1;
				t += A[i].first * t + A[i].second;
				if (t > T) P.pop_back();
				else P[j] = min(P[j], t);
			}
		}
		if (B.size()) rep(i, B.size() - 1) B[i + 1] += B[i];

		//cout << "out A" << endl;
		//rep(i, A.size()) cout << A[i].first << " " << A[i].second << endl;
		//cout << "out P" << endl;
		//rep(i, P.size()) cout << P[i] << " "; cout << endl;

		UL ans = 0;
		rep(i, P.size()) {
			UL l = 0, r = B.size() + 1;
			while (l + 1 < r) {
				UL m = (l + r) >> 1;
				if (P[i] + B[m - 1] <= T) l = m;
				else r = m;
			}
			ans = max(ans, i + l);
			//cout << "i = " << i << ", l = " << l << endl;
		}

		cout << ans << endl;
	}

	Problem();
};
