inline void pushup(int p)
{
    f[p].sz=f[f[p].l].sz+f[f[p].r].sz+1;
}
inline void pushdown(int p)
{
	if(f[f[p].l].val!=inf) f[f[p].l].val=f[f[p].l].val*f[p].tag1+f[p].tag2;
	if(f[f[p].r].val!=inf) f[f[p].r].val=f[f[p].r].val*f[p].tag1+f[p].tag2;
	f[f[p].l].tag1*=f[p].tag1,f[f[p].r].tag1*=f[p].tag1;
	f[f[p].l].tag2*=f[p].tag1,f[f[p].r].tag2*=f[p].tag1;
	f[f[p].l].tag2+=f[p].tag2,f[f[p].r].tag2+=f[p].tag2;
	f[p].tag1=1,f[p].tag2=0;
}
void split(int p,int k,int &x,int &y)
{
    if(p==0)
    {
        x=y=0;
        return;
    }
    pushdown(p);
    if(k>f[f[p].l].sz)
    {
        x=p;
        split(f[p].r,k-f[f[p].l].sz-1,f[p].r,y);
    }
    else
    {
        y=p;
        split(f[p].l,k,x,f[p].l);
    }
    pushup(p);
}
int merge(int a,int b)
{
    if(!a||!b) return a+b;
    if(f[a].dat<=f[b].dat)
    {
        pushdown(a);
        f[a].r=merge(f[a].r,b);
        pushup(a);
        return a;
    }
    else
    {
        pushdown(b);
        f[b].l=merge(a,f[b].l);
        pushup(b);
        return b;
    }
}
inline long long getVal(int p,int rk)
{
	while(p)
	{
		pushdown(p);
		if(f[f[p].l].sz>=rk) p=f[p].l;
		else if(f[f[p].l].sz+1==rk) return f[p].val;
		else rk-=f[f[p].l].sz+1,p=f[p].r;
	}
	return -1;
}
