        pushdown(b);
        f[b].l=merge(a,f[b].l);
        pushup(b);
        return b;
    }
}
inline long long getVal(int p,int rk)
{
	while(p)
	{
		pushdown(p);
		if(f[f[p].l].sz>=rk) p=f[p].l;
		else if(f[f[p].l].sz+1==rk) return f[p].val;
		else rk-=f[f[p].l].sz+1,p=f[p].r;
	}
	return -1;
}
bool cmp(node x,node y)
{
	return x.a>y.a;
}
int find(int p,long long a,long long b)
{
	int l=0,r=p-1;
	while(l+1<r)
	{
		int mid=(l+r)>>1;
		if(getVal(rt,mid+1)*a+b<getVal(rt,mid+2)) r=mid;
		else l=mid;
	}
	return r;
}
