struct node {
  node(ll a, ll b) : a(a), b(b) {}

  ll a, b;
  bool operator<(const node& other) const {
    return b * other.a < a * other.b;
  }
  ll advance(ll t) const {
    return min(MAX, (a + 1) * (t + 1) + b);
  }
};

