const int maxn=2e5+10;
int n;
ll T,a[maxn],b[maxn];
int od[maxn];
bool less2(int x,int y)
{
	return a[y]*(b[x]+1)<a[x]*(b[y]+1);
}
ll lft[maxn][24];
void solve(int st)
{
	vector<ll> bs;bs.clear();
	for(int i=st;i<n;i++)
	{
		bs.push_back(b[od[i]]+1);
	}
	sort(bs.begin(),bs.end());
	for(int i=1;i<bs.size();i++)bs[i]+=bs[i-1];
	int ans=0;
	for(int j=0;j<24;j++)
	{
		ll L=lft[st][j];
		if(L>T)break;
		ans=max(ans,j+int(lower_bound(bs.begin(),bs.end(),T-lft[st][j]+1)-bs.begin()));
	}
	printf("%d\n",ans);
	exit(0);
}
int main()
{
	scanf("%d%lld",&n,&T);
	for(int i=0;i<n;i++)
	{
		scanf("%lld%lld",&a[i],&b[i]);
		od[i]=i;
	}
	sort(od,od+n,less2);
	memset(lft,0x3f,sizeof(lft));
	lft[0][0]=0;
	for(int i=0;i<n;i++)
	{
		int k=od[i];
	//	cout<<k<<endl;
		if(!a[k])
		{
			solve(i);
			return 0;
		}
		for(int j=0;j<=i&&j<24;j++)
		{
			if(lft[i][j]>T)break;
		//	cout<<i<<" "<<j<<" "<<lft[i][j]<<endl;
			lft[i+1][j]=min(lft[i+1][j],lft[i][j]);
			if(lft[i][j]+1+(a[k]*(lft[i][j]+1)+b[k])<=T)
			{
				lft[i+1][j+1]=min(lft[i+1][j+1],lft[i][j]+1+(a[k]*(lft[i][j]+1)+b[k]));
			}
		}
	}
