using namespace std;
typedef long long ll;

template<typename T>
inline bool chmin(T& x, T a) {
	if (x >= a) { x = a; return true; }
	return false;
}

template<typename T>
inline bool chmax(T& x, T a) {
	if (x <= a) { x = a; return true; }
	return false;
}

struct Info
{
	ll a, b;
	bool operator<(const Info& another) const
	{
		ll c = another.a * (b + 1) < a * (another.b + 1);
		if (c != 0) { return c < 0; }
		return b < another.b;
	};
};

int main() {
	int N; cin >> N;
	ll T; cin >> T;

	vector <Info> temp;
	vector<ll> z;
	for (int i = 0; i < N; i++) {
		ll a, b; cin >> a >> b;
		if (a == 0) { z.push_back(b + 1); continue; }
		temp.push_back({ a,b });
	}
	sort(temp.begin(), temp.end());
	sort(z.begin(), z.end());

	vector<pair<ll, ll>> v;
	for (int i = 0; i < temp.size(); i++) {
		v.push_back({ temp[i].a, temp[i].b });
	}
	for (int i = 1; i < z.size(); i++) {
		z[i] += z[i - 1];
		chmin(z[i], T + 100);
	}

	N = v.size();

	if (N == 0) {
		ll ans = 0;
		for (int i = 0; i < z.size(); i++) {
			if (z[i] <= T) { chmax(ans, i + 1LL); }
		}
		cout << ans << endl;
		return 0;
	}

	ll** dp = new ll * [N];
	for (int i = 0; i < N; i++) {
		dp[i] = new ll[40];
		for (int j = 0; j < 40; j++) {
			dp[i][j] = T + 100000;
		}
	}
	dp[0][0] = 0;
	dp[0][1] = v[0].first + v[0].second + 1;
	for (int i = 1; i < N; i++) {
		dp[i][0] = 0;
		dp[i][1] = min(dp[i-1][1], v[i].first + v[i].second + 1LL);
		for (int j = 2; j < 40; j++) {
			dp[i][j] = dp[i - 1][j];
			if (dp[i - 1][j - 1] + 1 <= T) {
				chmin(dp[i][j], dp[i - 1][j - 1] + 1 + (dp[i - 1][j - 1] + 1) * v[i].first + v[i].second);
			}
		}
	}

	ll ans = 0;
	for (ll i = 0; i < 40; i++) {
		ll t = dp[N - 1][i];
		if (t <= T) {
			chmax(ans, i);
			for (int j = 0; j < z.size(); j++) {
				if (t + z[j] <= T) {
					chmax(ans, i + j + 1);
				}
			}
		}
	}

	cout << ans << endl;

	return 0;
}

