using namespace std;
const int MAXN = 200005, MAXM = 40;

struct Node
{
    ll a, b;
};

int cmp(Node &n1, Node &n2)
{
    return n2.a * n1.b + n2.a < n1.a * n2.b + n1.a;
}

vector<int> A;
vector<Node> B;
ll fa[MAXN], fb[MAXM];

int main()
{
    int n, t;
    scanf("%d%d", &n, &t);
    for (int i = 1; i <= n; i++)
    {
        ll a, b;
        scanf("%lld%lld", &a, &b);
        if (a == 0) A.push_back(b);
        else B.push_back({ a, b });
    }
    sort(A.begin(), A.end());
    sort(B.begin(), B.end(), cmp);

    for (int i = 1; i < MAXM; i++) fb[i] = 1e15;
    for (int i = 0; i < B.size(); i++)
    {
        for (int j = MAXM - 1; j >= 0; j--)
        {
            if (fb[j] > t) continue;
            fb[j + 1] = min(fb[j + 1], fb[j] + 1 + (fb[j] + 1) * B[i].a + B[i].b);
        }
    }

    for (int i = 1; i <= A.size(); i++)
        fa[i] = fa[i - 1] + A[i - 1] + 1;

    int ans = 0;
    for (int i = 0; i <= A.size(); i++)
    {
        for (int j = 0; j <= MAXM - 1; j++)
        {
            if (fa[i] + fb[j] <= t)
                ans = max(ans, i + j);
        }
    }
    printf("%d\n", ans);
}

