struct shop
{
    int a, b, c, d;
    shop(int a, int b) : a(a), b(b)
    {
        c = a + 1;
        d = a + b + 1;
    }

    int getTime(int T)
    {
        return c * T + d;
    }
};

// int t=1000;
const int nmax = 200005;
// std::array<std::array<int, nmax>, nmax> dp;
int dp[nmax][30];

int main()
{
    std::vector<shop> vec;

    int N, T;
    std::cin >> N >> T;
    int a_tmp, b_tmp;
    for (size_t i = 0; i < N; ++i)
    {
        std::cin >> a_tmp >> b_tmp;
        vec.push_back(shop(a_tmp, b_tmp));
    }

    std::sort(vec.begin(), vec.end(), [](shop x, shop y) {
        if (x.a == 0 || y.a == 0)
        {
            return x.b < y.b;
        }
        else
        {
            return (x.c - 1) * y.d > (y.c - 1) * x.d;
        }
    });

    int N1 = 0;
    for (size_t i = 0; i < N; ++i)
    {
        if (vec[i].a == 0)
        {
            N1 = i;
            break;
        }
    }
    //  std::cout << "N1=" << N1 << std::endl;
    int jmax = 28;

    // for (auto v : vec)
    // {
    //     std::cout << v.a << ", " << v.b << ", " << static_cast<double>(v.c - 1) / v.d << std::endl;
    // }

    dp[1][1] = vec[0].getTime(0);
    for (size_t i = 2; i <= N1; ++i)
    {
        dp[i][i] = vec[i - 1].getTime(dp[i - 1][i - 1]);
    }

    // j=1
    for (size_t i = 2; i <= N1; ++i)
    {
        dp[i][1] = std::min(dp[i - 1][1], vec[i - 1].getTime(0));
    }

    // j>=2
    for (size_t j = 2; j <= jmax; ++j)
    {
        for (size_t i = j + 1; i <= N1; ++i)
        {
            dp[i][j] = std::min(dp[i - 1][j], vec[i - 1].getTime(dp[i - 1][j - 1]));
        }
    }

    int t = 0, ans = 0;
    for (size_t i = 1; i <= N1; ++i)
    {
        if (dp[N1][i] > T)
            break;

        t = dp[N1][i];
        ans = i;
    }

    for (size_t i = N1 + 1; i <= N; ++i)
    {
        if (vec[i - 1].getTime(t) > T)
            break;
        ans++;
        t = vec[i - 1].getTime(t);
    }

    // for (size_t i = 1; i <= N; ++i)
    // {
    //     std::cout << dp[N1][i] << " ";
    // }
    //  std::cout << std::endl;
    std::cout << ans << std::endl;
    return 0;
}

