using namespace std;
const int MAXN=200005;
const int MAXA=40;
const int INF=0x3f3f3f3f;
pair<int,int> shop[MAXN];
int dp[MAXN][MAXA];
int main()
{
    int n,T;
    scanf("%d%d",&n,&T);
    for(int i=1;i<=n;i++)
        scanf("%d%d",&shop[i].first,&shop[i].second);
    auto f=[](const pair<int,int> &p,int t){
        return 1LL*(p.first+1)*(t+1)+p.second;
    };
    auto cmp=[f](const pair<int,int> &x,const pair<int,int> &y){
        return f(y,f(x,0))<f(x,f(y,0));
    };
    sort(shop+1,shop+n+1,cmp);
    memset(dp,INF,sizeof(dp));
    int res=0,i;
    for(i=(dp[0][0]=0);i<n;i++)
    {
        if(shop[i+1].first==0)break;
        for(int j=0;j<MAXA;j++)
        {
            dp[i+1][j]=min(dp[i+1][j],dp[i][j]);
            if(j+1<MAXA)dp[i+1][j+1]=min(1LL*dp[i+1][j+1],f(shop[i+1],dp[i][j]));
        }
    }
    for(int j=0;j<MAXA;j++)
    {
        if(dp[i][j]>T)continue;
        int now=j,cost=dp[i][j];
        for(int k=i+1;k<=n;k++)
            if(f(shop[k],cost)<=T)
                cost=f(shop[k],cost),now++;
        res=max(res,now);
    }
    return 0*printf("%d\n",res);
}

