typedef long long ll;
#define all(x) (x).begin(),(x).end()
const int mod=1000000007,MAX=35;
const ll INF=1LL<<60;

ll dp[MAX];

int main(){

    std::ifstream in("text.txt");
    std::cin.rdbuf(in.rdbuf());
    cin.tie(0);
    ios::sync_with_stdio(false);

    ll N,T;cin>>N>>T;
    T++;
    vector<ll> A;
    vector<pair<ll,ll>> B;

    for(int i=0;i<N;i++){
        ll a,b;cin>>a>>b;
        if(a==0) A.push_back(b);
        else B.push_back({a,b});
    }

    sort(all(A));

    sort(all(B),[](pair<ll,ll> a,pair<ll,ll> b){
        return (1+a.second)*b.first<(1+b.second)*a.first;
    });

    for(int i=0;i<MAX;i++) dp[i]=INF;

    dp[0]=1;

    for(auto p:B){
        for(int i=33;i>=0;i--){
            if(dp[i]==INF) continue;

            dp[i+1]=min(dp[i+1],dp[i]+dp[i]*p.first+p.second+1);
        }
    }

    int ans=0;

    for(int i=0;i<=33;i++){
        if(dp[i]>T) continue;
        ans=max(ans,i);
        for(int j=0;j<A.size();j++){
            dp[i]+=A[j]+1;
            if(dp[i]<=T) ans=max(ans,i+j+1);
            else break;
        }
    }

    cout<<ans<<endl;
}

