int main()
{
    // 標準入力から値を取得
    ll N, T;
    cin >> N >> T;

    // 入力数がN個の場合
    vector< pair <ll, ll> > ab;
    forn (i, N)
    {
        ll a, b;
        cin >> a >> b;
        pair <ll, ll> p = make_pair(a, b);
        ab.push_back(p);

    }
    sort(ab.begin(), ab.end());

    ll wait_time[N];
    bool done[N];
    forn(i, N)
    {
        done[i] = false;
    }
    double t = 1;
    int ans = 0;
    while (t <= T + 0.5 && ans <= N)
    {
        // 待ち時間を計算
        ll min_wait_time = 9223372036854775807-1;
        int min_index = 0;
        forn(i, N)
        {
            if (min_wait_time < ab[i].first * t)
            {
                // ソートされているので、これ以上探しても最小値は更新されないため探索打ち切り
                break;
            }
            if (!done[i])
            {
                if (min_wait_time > (ll)(ab[i].first * t + ab[i].second))
                {
                    min_wait_time = (ll)(ab[i].first * t + ab[i].second);
                    min_index = i;
                }
            }
        }

        t += min_wait_time;
        if (t > T + 0.5)
        {
            break;
        }

        // 待ち時間が最小の店に向かう
        done[min_index] = true;
        t++;
        ans++;
    }

    // 結果出力
    printf("%d\n", ans);
}

