bool comp(pair <int, int> a, pair <int, int> b) {
	return 1LL * b.first * (1 + a.second) < 1LL * a.first * (1 + b.second);
}

int F(int rem) {
	return upper_bound(sum0.begin(), sum0.end(), rem) - sum0.begin();
}

int main() {
	ios :: sync_with_stdio(0);
	cin >> n >> T;
	for (int i = 0; i < n; ++ i) {
		int a, b; cin >> a >> b;
		if (a) v1.push_back(make_pair(a, b));
		else v0.push_back(b);
	}
	sort(v0.begin(), v0.end());
	sum0.resize(v0.size());
	for (int i = 0; i < v0.size(); ++ i) {
		if (i) sum0[i] = sum0[i - 1];
		sum0[i] += 1 + v0[i];
	}
	sort(v1.begin(), v1.end(), comp);
	for (int i = 0; i <= 30; ++ i)
		for (int j = 0; j <= v1.size(); ++ j)
			f[i][j] = T + 5;
	f[0][0] = -1;
	for (int i = 0; i < 30; ++ i) {
		for (int j = 0; j < v1.size(); ++ j) {
			f[i][j + 1] = min(f[i][j + 1], f[i][j]);
			f[i + 1][j + 1] = min(f[i + 1][j + 1], 1 + 1LL * (1 + v1[j].first) * (1 + f[i][j]) + v1[j].second);
		}
	}
	int ans = 0;
	for (int i = 1; i <= 30; ++ i) {
		for (int j = 0; j <= v1.size(); ++ j) {
