int main()
{
    // 標準入力から値を取得
    ll N, T;
    cin >> N >> T;

    // 入力数がN個の場合
    ll a[N], b[N];
    forn (i, N)
    {
        cin >> a[i] >> b[i];
    }

    ll wait_time[N];
    bool done[N];
    forn(i, N)
    {
        done[i] = false;
    }
    double t = 1;
    int ans = 0;
    while (t <= T + 0.5)
    {
        // 待ち時間を計算
        ll min_wait_time = 9223372036854775807-1;
        int min_index = 0;
        forn(i, N)
        {
            if (!done[i])
            {
                if (min_wait_time > (ll)(a[i] * t + b[i]))
                {
                    min_wait_time = (ll)(a[i] * t + b[i]);
                    min_index = i;
                }
            }
        }

        t += min_wait_time;
        if (t > T + 0.5)
        {
            break;
        }

        // 待ち時間が最小の店に向かう
        done[min_index] = true;
        t++;
        ans++;
    }

    // 結果出力
    printf("%d\n", ans);
}

