const ll INF = 1e15;

vi zeroes;
ll N,T,a,b;
vpi V;
vpi outs;
ll done[MAXN];
vpi frees;

int main(){
	cin>>N>>T;
	for (int i=0;i<N;++i){
		cin>>a>>b;
