{
	return x.a>y.a;
}
int find(int p,long long a,long long b)
{
	int l=-1,r=p-1;
	while(l+1<r)
	{
		int mid=(l+r)>>1;
		if(getVal(rt,mid+1)*(a+1)+(b+1)<getVal(rt,mid+2)) r=mid;
		else l=mid;
	}
	return r;
}
