#define MAXN 200002
#define LL long long

struct Node {
    LL a, b;
    Node () {}
    Node (LL x, LL y) { a = x, b = y; }
} s[MAXN];

int n, ans = 0, B[MAXN];
LL t, dp[33] = {0};
int cnt = 0, pf = 0;

bool cmp (Node x, Node y) {
    return x.a * (y.b + 1) > y.a * (x.b + 1);
}

int main () {
    cin >> n >> t;
    for (int i = 0; i < 33; i ++) dp[i] = 2e9; 
    for (int i = 1; i <= n; i ++) {
        int a, b; cin >> a >> b;
        if (a == 0) B[++ cnt] = b;
        else s[++ pf] = Node (a, b);
    }
    sort (B + 1, B + cnt + 1);
    sort (s + 1, s + pf + 1, cmp);

    int k = (int) (log2 (t));

    dp[0] = 0, dp[1] = 1 + s[1].a + s[1].b;

    for (int i = 2; i <= pf; i ++) 
        for (int j = min (k, i); j >= 1; j --)
            dp[j] = min (dp[j], dp[j - 1] + 1 + s[i].a * (dp[j - 1] + 1) + s[i].b);

    LL sum[cnt + 1] = {0}; sum[1] = B[1];
    for (int i = 2; i <= cnt; i ++) sum[i] = sum[i - 1] + 1 + 1LL * B[i];

    int i = 1;
    while (i <= min (k, pf)) {
        if (dp[i] > t) break;
        int j = cnt;
        LL rem = t - dp[i] - 1;
        while (j >= 1) {
            if (rem - sum[j] >= 0) break;
            j --;
        }
        ans = max (ans, i + j);
        i ++;
    }

    cout << ans;

    return 0;
}

