void dfs(const vector<vector<int> > &g, int root, int d, vector<int> &c)
{
	if (c[root] >= 0) return;
	c[root] = d;
	for (int i = 0; i < g[root].size(); i++)
		if (c[g[root][i]] < 0) dfs(g, g[root][i], d ^ 1, c);
}

