ll memo[200000][30];
ll solve(int n, int k){ // 0～n 番目のうちから k 個選ぶ場合の最小時間
    if(n == -1){
        if(k == 0) return 0;
        else return T+1;
    }
    if(memo[n][k] != -1) return memo[n][k];
    ll ret = min(solve(n-1, k), T+1);
    if(k > 0) ret = min(ret, solve(n-1, k-1)*v[n].second.first+v[n].second.second);
    return memo[n][k] = ret;
}

