using namespace std;
typedef long long ll;

ll n, T;
vector<ll> a0;
ll presum[200200];
vector< pair<ll, ll> > a;
ll dp[200200][22];
bool cmp(pair<ll, ll> i, pair<ll, ll> j){
	return j.first * (i.second + 1LL) < i.first * (j.second + 1LL);
}

int main(){
	scanf("%lld%lld", &n, &T);
	rep(i, n){
		ll x, y;
		scanf("%d%d", &x, &y);
		if(x == 0) a0.push_back(y);
		else a.push_back(make_pair(x, y));
	}
	sort(a.begin(), a.end());
	rep(i, a0.size()){
		presum[i] = a0[i] + (i ? presum[i-1] : 0);
	}
	memset(dp, 0x3f, sizeof(dp));
	dp[0][0] = 1;
	rep(i, a.size()){
		rep(j, 21){
			if(dp[i][j] > T) continue;
			if(dp[i][j] < dp[i+1][j]) dp[i+1][j] = dp[i][j];
			ll now_t = a[i].first * (dp[i][j] + 1) + a[i].second;
			if(now_t > T) continue;
			if(now_t < dp[i+1][j+1]) dp[i+1][j+1] = now_t;
		}
	}
	ll ans = 0;
	ll fdsa = a.size();
	rep(i, 21){
		if(dp[fdsa][i] > T) continue;
		ll val = T - dp[fdsa][i];
		ll l = 0, r = a0.size()-1;
		while(l <= r){
			ll mid = (l+r) >> 1;
			if(presum[mid] <= val) l = mid+1;
			else r = mid-1;
		}
		if(i + r + 1 > ans) ans = i+r+1;
	}
	cout << ans << endl; 
	return 0;
}

