int main() {
	ios::sync_with_stdio(false);
	cin.tie(0);
	int N;
	ll T;
	cin >> N >> T;
	set<P> S;
	for (int i = 0; i < N; i++) {
		int a, b;
		cin >> a >> b;
		S.insert(P(a + 1, a + b + 1));
	}
	ll t = 0;
	int ans = 0;
	while (t < T) {
		P sel;
		ll best = 1LL << 60;
		for (P p : S) {
			ll after = p.first*t + p.second;
			if (after < best) {
				best = after;
				sel = p;
