		} else {
			for(int j = 1; j < Tlg; ++j) {
				dp[i][j] = min((dp[i - 1][j - 1] == -1 ? inf : (dp[i - 1][j - 1] + 1 + (dp[i - 1][j - 1] + 1) * v[i].f + v[i].s)), (dp[i - 1][j] == -1 ? inf : dp[i - 1][j]));
				if(dp[i][j] == inf) dp[i][j] = -1;
			}
		}
	}
	for(int i = 0; i < Tlg; ++i) {
		if(dp[m][i] != -1) {
			for(int j = 0; j <= ni; ++j) {
				if(dp[m][i] + nb[j] <= t) {
					fp = max(fp, i + j);
				}
			}
		}
	}
	cout << fp << endl;
	return 0;
}

