inline int read()
{
	int x = 0; bool f = true;
	char c = getchar();
	for (; ! IsDigit(c); c = getchar()) if (c == '-') f = false;
	for (; IsDigit(c); c = getchar()) x = (x << 3) + (x << 1) + (c ^ '0');
	return f ? x : -x;
}
inline void write(int x)
{
    if (x < 0)
	{
        putchar('-');
		x = -x;
	}
    if (x > 9) write(x / 10);
	putchar(x % 10 + '0');
}

