                dp[j+1] = min(dp[j+1], (a[c[i]] + 1) * (dp[j] + 1) + b[c[i]]);
            } 
        }
    }
    vector<long long> v;
    long long curr = 0;
    v.emplace_back(curr);
    for (auto &x: ms) {
        curr += x + 1;
        v.emplace_back(curr);
    }
    int ans = 0;
    for (int i = 0; i < 32; i++) {
        if (t < dp[i]) continue;
        int x = upper_bound(v.begin(), v.end(), t-dp[i]) - v.begin();
