    }
    if(now == -1){
        return T + 1;
    }
    if(dp[now][need] != -1){
        return dp[now][need];
    }
    lint ans = buy(now - 1, need);
    lint buy_time = buy(now - 1, need - 1) + 1;
    ans = min(ans, buy_time + a[now] * buy_time + b[now]);
    return dp[now][need] = ans;
}


