#include<bits/stdc++.h>

int main() {
    using namespace std;
    unsigned long N, T;
    cin >> N >> T;
    ++T;
    vector<pair<unsigned long, unsigned long>> c;
    vector<unsigned long> d;
    for(unsigned long i{0}, a, b; i < N; ++i){
        cin >> a >> b;
        ++a;
        ++b;
        if(a == 1) d.push_back(b);
        else if(b <= T) c.emplace_back(a, b);
    }
    d.push_back(0);
    sort(d.begin(), d.end());
    partial_sum(d.begin(), d.end(), d.begin());
    sort(c.begin(), c.end(), [](auto i, auto j){return i.second * (j.first - 1) < j.second * (i.first - 1);});
    vector<unsigned long> dp{1, numeric_limits<unsigned long>::max()};
    dp.reserve(c.size() + 2);
    for(const auto& i : c){
        unsigned long t = upper_bound(dp.begin(), dp.end(), (T - i.second) / i.first) - dp.begin();
        if(t + 1 == dp.size())dp.emplace_back(numeric_limits<unsigned long>::max());
        for(; t--; )dp[t + 1] = min(dp[t + 1], dp[t] * i.first + i.second);
    }
    unsigned long ans{0};
    for(unsigned long i{0}; i + 1 < dp.size(); ++i)ans = max(ans, i + max<unsigned long>(1UL, upper_bound(d.begin(), d.end(), T - min(T, dp[i])) - d.begin()) - 1);
    cout << ans << endl;
    return 0;
}

