				Dp[i][k] = min(Dp[i][k], (t + 1) * A[i - 1].a + A[i - 1].b + 1);
			}
			if (Dp[i][k] <= (long long) T) {
				int Le = T - Dp[i][k];
				int it = upper_bound(BSu.begin(), BSu.end(), Le) - BSu.begin();
				Res = max(Res, k + it);
			}
		}
	}
	printf("%d\n", Res);
}

