                dp[i][j]=min({inf,dp[i-1][j],dp[i-1][j-1]+1+notzero[i-1].first*(dp[i-1][j-1]+1)+notzero[i-1].second});
            }
        }
    }
    int ans=0;
    for(int i=0 ; i<=30 ; i++) {
        if(dp[n][i]<=t) {
            int cnt=i,cur=dp[n][i];
            for(int j=0 ; j<k ; j++) {
                if(cur+zero[j]<t) {
                    cur+=zero[j]+1;
                    cnt++;
                }
            }
            ans=max(ans,cnt);
        }
    }
    cout<<ans;
}

