    setIO();

    int N, T; re(N, T);

    struct store { int a, b; };
    vector<store> st;

    vi a0;
    F0R (i, N) {
        int a, b; re(a, b);
        if (a == 0) a0.pb(b + 1);
        else st.pb({a, b});
    }

    sort(all(st), [](store f, store g) {
        return ll(f.b + 1) * g.a < ll(g.b + 1) * f.a;
    });

    const int INF = 1e9 + 7;
    vi mint(sz(st) + 1, INF);
    mint[0] = 0;

    F0R (i, sz(st)) {
        vi MINT = mint;
        for (int bef = 0; bef <= i; bef++) {
            ll add = 1 + ll(mint[bef] + 1) * st[i].a + st[i].b;
            if (add > T) break;
            ckmin(MINT[bef + 1], mint[bef] + int(add));
        }
        mint = move(MINT);
    }

    sort(all(a0));
    vll pref = prefixes(a0, 0ll, plus<ll>());

    int ans = 0;
    F0R (vis, sz(mint)) if (mint[vis] <= T) {
        ckmax(ans, vis + int(ub(all(pref), T - mint[vis]) - pref.begin() - 1));
    }
    ps(ans);

