struct shop {
    ll a, b;
    shop(ll a, ll b) : a(a), b(b) {}
    inline bool operator<(const shop &r) const {
        return a * (r.b + 1) > r.a * (b + 1);
    }
    ll time(const ll &t) { return (t + 1) * (a + 1) + b; }
};

int main() {
    cin.tie(0);
    ios::sync_with_stdio(0);

    ll N, T;
    cin >> N >> T;

    vector<shop> shops1;
    vector<ll> shops0;
    rep(i, N) {
        ll a, b;
        cin >> a >> b;
        if(a == 0)
            shops0.push_back(b + 1);
        else
            shops1.push_back(shop(a, b));
    }

    sort(ALL(shops1));
    sort(ALL(shops0));

    rep(i, shops0.size() - 1) shops0[i + 1] += shops0[i];
    vector<ll> dp(30, inf);
    dp[0] = 0;
    for(auto sp : shops1) {
        for(int i = 30 - 1; i >= 0; i--) {
            if(dp[i] > T) continue;
            chmin(dp[i + 1], sp.time(dp[i]));
        }
    }
    ll ans = 0;
    rep(i, 30) {
        if(dp[i] > T) break;
        chmax<ll>(ans,
                  i + upper_bound(ALL(shops0), T - dp[i]) - shops0.begin());
    }

    cout << ans << endl;

    return 0;
}

