#define IsDigit(c) ('0' <= (c) && (c) <= '9')

#define MAX 5 + 1000

using namespace std;

typedef long long LL;
typedef pair<LL, LL> Pll;

inline LL read()
{
	LL x = 0; bool f = true;
	char c = getchar();
	for (; ! IsDigit(c); c = getchar()) if (c == '-') f = false;
	for (; IsDigit(c); c = getchar()) x = (x << 3) + (x << 1) + (c ^ '0');
	return f ? x : -x;
}
inline void write(LL x)
{
    if (x < 0)
	{
        putchar('-');
		x = -x;
	}
    if (x > 9) write(x / 10);
	putchar(x % 10 + '0');
}

LL n, T, Max, Ans, f[MAX];

vector<Pll> A;
vector<LL> B;

inline bool mycmp(Pll x, Pll y)
{
	return x.first * (y.second + 1) > y.first * (x.second + 1);
}

signed main()
{
	n = read(); T = read(); Max = log(T) + 1;
	for (LL x, y, i = 1; i <= n; i++)
	{
		x = read(); y = read();
		if (x != 0) A.push_back(make_pair(x, y));
		    else B.push_back(y + 1);
	}

	for (LL i = 1; i <= Max; i++)
		f[i] = T + 1;
	sort(A.begin(), A.end(), mycmp);
	sort(B.begin(), B.end());
	for (LL i = 1; i < B.size(); i++) B[i] += B[i - 1];

	for (LL i = 0; i < A.size(); i++)
		for (LL j = Max; j; j--)
			    f[j] = min(f[j], (f[j - 1] + 1) * (A[i].first + 1) + A[i].second);
	for (LL i = 0; i <= Max; i++)
		if (f[i] <= T) Ans = max(Ans, i + (LL)(B.empty() ? 0 : upper_bound(B.begin(), B.end(), T - f[i]) - B.begin()));
	write(Ans);

	return 0;
}

