int main() {
  int n, t;
  cin >> n >> t;
  vector<int> a(n), b(n);
  for (int i = 0; i < n; ++i) cin >> a[i] >> b[i];
  vector<int> ord, oth;
  for (int i = 0; i < n; ++i) {
    if (a[i] > 0) ord.push_back(i);
    else oth.push_back(i);
  }
  sort(ord.begin(), ord.end(), [&](int i, int j) {
    // T + a[i] * T + b[i] + a[j] * (T + a[i] * T + b[i] + 1) + b[j]
    // T + a[j] * T + b[j] + a[i] * (T + a[j] * T + b[j] + 1) + b[i]
    return 1LL * a[j] * b[i] + a[j] < 1LL * a[i] * b[j] + a[i];
  });
  vector<int> dp(40, t + 1);
  dp[0] = 0;
  for (int i = 0; i < ord.size(); ++i) {
    vector<int> nxt(dp.begin(), dp.end());
    for (int j = 1; j < 40; ++j) {
      int v = dp[j - 1];
      int64_t tk = v + 1 + 1LL * a[ord[i]] * (v + 1) + b[ord[i]];
      if (tk <= t) nxt[j] = min(nxt[j], (int)tk);
    }
    dp = nxt;
  }
  sort(oth.begin(), oth.end(), [&](int i, int j) { return b[i] < b[j]; });
  int res = 0;
  for (int i = 0; i < 40; ++i) {
    if (dp[i] <= t) res = i;
  }
  int64_t sum = 0;
  for (int i = 0; i < oth.size(); ++i) {
    sum += b[oth[i]];
    for (int j = 0; j < 40; ++j) {
      if (dp[j] > t) break;
      if (sum + dp[j] + i + 1 <= t) res = max(res, i + 1 + j);
    }
  }
  cout << res << "\n";
  return 0;
}

