ll memo[N][35];
ll dp(int now, int take){
	if(now < 0){
		if(take == 0)return 0;
		else return t+1;
	}

	ll& ret = memo[now][take];
	if(ret != -1)return ret;

	// leave
	ret = dp(now-1, take);

	// take
	if(take > 0)ret = min(ret, (dp(now-1, take-1) + 1) * vec[now].F + vec[now].S);

	// limit the time
	ret = min(ret, (ll)t + 1);

	return ret;
}

