bool C(int x)
{
	int t = 0;
	vector<int> pc(x);
	rep(i, 0, x) pc[i] = p[i]; //deadline earlier first
	sort(all(pc), cmp2); //wait more first
	rep(i, 0, x)
	{
		t++;
		t += a[pc[i]].X*t+a[pc[i]].Y;
	}
	return t <= T;
}

bool cmp(int x, int y)
{
	//if((T-a[x].Y) * (a[y].X+1) > (T-a[y].Y) * (a[x].X+1) ) return 1; //deadline
	//else if((T-a[x].Y) * (a[y].X+1) == (T-a[y].Y) * (a[x].X+1) ) return a[x].X < a[y].X;
	if(t[x] > t[y]) return 1;
	return t[x]==t[y] && a[x].X<a[x].X;
}

void solve()
{
	cin >> n >> T;
	a.resize(n);
	rep(i, 0, n) cin >> a[i].X >> a[i].Y;
	rep(i, 0, n) t[i] = (T-a[i].Y)/(a[i].X+1); //time for others
	rep(i, 0, n) p[i] = i;
	sort(p, p+n, cmp);
	//rep(i, 0, n) cout << p[i] << " \n"[i==n-1];
	int L = 0, R = n+1, M;
	while(L+1 < R)
	{
		M = (L+R)/2;
		if(C(M)) L = M;
		else R = M; //cannot => upperbound low
	}
	cout << L << endl;
  return;
}


