				v.pb(1 + x[i].se);
				break;
			}
			dp[i][j] = dp[i - 1][j - 1] + (dp[i - 1][j - 1] + 1) * x[i].fi + x[i].se;
			remin(dp[i][j], dp[i - 1][j]);
			remin(dp[i][j], INF);
		}
	}
      debug("done");
	int ans = 0, s = 0;
	k = sz(v);
	for(i = 0; i < k; i++) {
		s += v[i];
