using namespace std;
const int M = 220000;
typedef long long ll;
int n,m,k,t;
struct node{
    int a,b;
}e[M];
ll dp[60]={0};
int main(){
    cin>>n>>t;
    fo(i,1,n) cin>>e[i].a>>e[i].b;
    sort(e+1,e+1+n,
        [](const node & u,const node & v)->bool{
        return 1ll*u.a*(v.b+1)<1ll*v.a*(u.b+1);
    });
    memset(dp,inf,sizeof(dp));
    k=30;
    dp[0]=0;
    vector<ll> zero;
    fo(i,1,n){
        if(!e[i].a) {
            zero.push_back(e[i].b+1);
            continue;
        }
        rv(j,k,0){
            if(dp[j]>t) continue;
            ll ti=dp[j]+1;
            ti=e[i].a*ti+e[i].b+ti;
            dp[j+1]=min(dp[j+1],ti);
        }
    }
    int ans=0;
    if(SZ(zero)){
        sort(zero.begin(),zero.end());
        fo(i,1,SZ(zero)-1) zero[i]+=zero[i-1];
        fo(i,0,k){
            if(dp[i]>t) break;
            int now=i;
            int it = lower_bound(zero.begin(), zero.end(), t-dp[i]) - zero.begin();
            if(zero[it]==t-dp[i]) now+=it+1;
            else if(it) now+=it;
            ans = max(ans, now);
        }
    }
    else
    {
        rv(i,k,1)
            if(dp[i]<=t){
                ans=i;
                break;
            }
    }

