  for (i=0; i<n; i++) if (i+1<n && a[k[i]]!=a[k[i+1]]) {
    z=(b[k[i+1]]-b[k[i]])/(a[k[i]]-a[k[i+1]])+1;
    if (a[k[i]]*z+b[k[i]]>a[k[i+1]]*z+b[k[i+1]]) q.push({int(z),i});
  }
  for (cur=1; cur<m && pos<n; cur=nxt+1) {
    while (!q.empty() && q.top().first<=cur) {
      c=q.top().first;
      i=q.top().second;
      q.pop();
      //printf("[%d %d]\n",c,i);
      //for (int j=0; j<n; j++) printf("%d,",k[j]);
      //printf(" pos=%d\n",pos);
      if (a[k[i]]==a[k[i+1]] || (b[k[i+1]]-b[k[i]])/(a[k[i]]-a[k[i+1]])+1!=c) continue;
      swap(k[i],k[i+1]);
      if (i>pos && a[k[i]]!=a[k[i-1]]) {
