int main() {
  int N, T;
  cin >> N >> T;

  ll ans = 0;
  vector<int> as = vector<int>(N, 0);
  vector<int> bs = vector<int>(N, 0);
  vector<int> cost = vector<int>(N, 0);
  vector<bool> used = vector<bool>(N, false);

  for (int i = 0; i < N; i++) {
    int a, b;
    cin >> a >> b;
    as[i] = a;
    bs[i] = b;
    cost[i] = b;
  }

  unordered_set<int> canvisit = unordered_set<int>();
  for (int i = 0; i < N; i++) {
    canvisit.insert(i);
  }

  ll passed = 0;
  while (passed <= T) {
    // 残りの店が全てai = 0 なら小さい順に足す
    int j = 0;
    for (int pos1 : canvisit) {
      if (as[pos1] > 0) {
        break;
      }
      j++;
      if (j == canvisit.size()) {
        // val, pos
        priority_queue<pair<int, int>, vector<pair<int, int>>,
                       greater<pair<int, int>>>
            pq = priority_queue<pair<int, int>, vector<pair<int, int>>,
                                greater<pair<int, int>>>();
        for (int pos : canvisit) {
          pq.push(make_pair(bs[pos], pos));
        }
        while (pq.size() > 0) {
          pair<int, int> current = pq.top();
          pq.pop();
          int val = current.first;
          int pos = current.second;
          passed++;
          if (passed > T) {
            cout << ans << endl;
            return 0;
          }
          passed += bs[pos];
          if (passed > T) {
            cout << ans << endl;
            return 0;
          }
          ans++;
        }
        cout << ans << endl;
        return 0;
      }
    }

    passed++;
    if (passed > T) {
      break;
    }
    // update and find min
    ll mincost = INF;
    ll minI = -1;
    for (int i : canvisit) {
      cost[i] += as[i];
      if (mincost > cost[i]) {
        mincost = cost[i];
        minI = i;
      }
    }
    canvisit.erase(minI);
    passed += mincost;
    // used[minI] = true;

    if (passed > T) {
      break;
    }

    ans++;

    if (ans == N) {
      break;
    }
  }

  cout << ans << endl;
}

