	rep(i,n){
		if(v[i].a==0){
			pnt=i;
			break;
		}
		rep(k,40)cop[k]=dp[k];
		rep(k,39)if(cop[k]<1e18){
			ll res=v[i].a*cop[k]+v[i].b;
			if(res<=T+1)chmin(dp[k+1],res);
		}
	}
