        sort(v.begin(), v.end());
        vvll dp(v.size() + 3, vll(100, 1e18));
        dp[0][0] = 0;
        REP(i,1,v.size()){
                REP(k,0,min(i, 99ll)){
                        ll tmp = dp[i-1][k-1] + 1 + v[i].a * (dp[i-1][k-1] + 1) + v[i].b;
                        dp[i][k] = min({t+1, dp[i-1][k], tmp});
                }
        }
