    if(dp[a_b.size()][i + 1] > T)break;
    cur_time = dp[a_b.size()][i + 1];
    ++count;
  }

  for(int i = 0; i < b.size(); ++i){
    if(cur_time + b[i] > T)break;
    cur_time += b[i];
    ++count;
  }

  cout << count << endl;

  return 0;
}

