using int64 = long long;

const int64 INF = (1LL<<60);

struct Line {
    int64 a, b;

    void Read() {
        cin >> a >> b;
        //++a, ++b;
    }

    bool operator < (const Line& other) const {
        return (other.a) * (b + 1) < (a) * (other.b + 1);
    }

    int64 operator () (const int64 t) const {
        return a * t + b;
    }
};

int64 N, T;

vector<Line> L;
vector<Line> zero;

vector<vector<int64>> dp;

int can_do(int64 delta) {
    int64 tot = 0;
    for (int i = 0; i < zero.size(); i++) {
        tot += 1 + zero[i](0);
        if (tot > delta)
            return i;
    }
    return zero.size();
}

int main() {
    cin >> N >> T;    

    for (int i = 0; i < N; i++) {
        auto l = Line();
        l.Read();
        if (!l.a) {
            zero.push_back(l);
        } else {
            L.push_back(l);
        }
    }

    sort(zero.begin(), zero.end(), [&] (const Line& A, const Line& B){
        return A.b < B.b;
    });

    N = L.size();

    sort(L.begin(), L.end());

    if (T == 1) {
        cout << 0 << "\n";
        return 0;
    }

    int res = can_do(T);

    if (!N) {
        cout << res << "\n";
        return 0;
    }

    const int MJ = 32;

    dp.assign(N, vector<int64>(MJ, INF));

    dp[0][0] = 0;
    dp[0][1] = L[0](1);

    for (int i = 1; i < N; i++) {
        for (int j = 0; j < MJ && j <= i + 1; j++) {
            int64 av = dp[i-1][j];
            int64 bv = (j >= 1 ? L[i](dp[i-1][j-1] + 1): INF);

            int64 cv = min(av, bv);
            if (cv <= T)
                dp[i][j] = cv;
        }
    }

    for (int j = 1; j < MJ; j++) {
        if (dp[N-1][j] <= T) {
            //cerr << j << " : " << dp[N-1][j] << " " << can_do(T - dp[N-1][j]) << "\n"; 
            res = max(res, j + can_do(T - dp[N-1][j]));
        }
    }

    cout << res << "\n";
    return 0;
}

