struct solver
{

    solver()
    {
        int n; cin>>n;
        int T; cin>>T;
        vector<i64> a(n),b(n); cin>>a>>b;
        vector<int> id(n);
        iota(__all(id),0);
        auto comp=[&](int x,int y)->bool
        {
            return a[x]*(1+b[y])>a[y]*(1+b[x]);
        };
        sort(__all(id),comp);
        dump(id);

        i64 dp[32];
        const i64 inf=1e18;
        init(dp, inf);
        dp[0]=0;
        dump(dp);

        auto itr=id.begin();
        for(; itr!=end(id) && a[*itr]; ++itr)
        {
            for(int i=30;i>=0;--i)
            {
                if(dp[i]>T) continue;
                chmin(dp[i+1],(dp[i]+1)*(a[*itr]+1)+b[*itr]);
            }
        }

        vector<i64> rest;
        i64 now=0;
        while(itr!=end(id))
        {
            i64 nxt=now+b[*itr]+1;
            rest.emplace_back(nxt);
            now=nxt;
            ++itr;
        }

        i64 ans=0;
        for(int i=0;i<=31;++i)
        {
            dump(i,dp[i]);
            if(dp[i]>T) break;
            chmax(ans, upper_bound(__all(rest), T-dp[i])-rest.begin() + i);
        }
        cout << ans << "\n";
    }
};

