int dp[200005][102];

signed main() {
	INIT;

	VAR(int, n, t);

	V<int> a, b;
	V<int> c;
	REP(i, n) {
		VAR(int, s, t);
		if (s == 0) c.emplace_back(t);
		else a.emplace_back(s), b.emplace_back(t);
	}

	V<int> o(a.size());
	std::iota(ALL(o), 0);
	std::sort(ALL(o), [&](int l, int r) {
		return (b[l] + 1) * a[r] < (b[r] + 1) * a[l];
		});

	FILL(dp, INFLL);
	dp[0][0] = 0;

	REP(i, a.size()) REP(j, 102) {
		if (dp[i][j] >= INFLL) continue;
		assert(j != 101);
		CHMIN(dp[i + 1][j], dp[i][j]);
		int cost = 1 + a[o[i]] * (dp[i][j] + 1) + b[o[i]];
		if (dp[i][j] + cost <= t) CHMIN(dp[i + 1][j + 1], dp[i][j] + cost);
	}

	std::sort(ALL(c));
	V<int> cc(c.size() + 1);
	REP(i, c.size()) cc[i + 1] = cc[i] + c[i] + 1;

	cc.emplace_back(INFLL);

	int ans = 0;
	REP(j, 102) {
		if (dp[a.size()][j] >= t) continue;
		int num = std::upper_bound(ALL(cc), t - dp[a.size()][j]) - cc.begin() - 1;
		CHMAX(ans, j + num);
	}
	OUT(ans)BR;

	return 0;
}

