const int N = 2e5 + 6;
const int L = 7;

ll dp[N][L];

int smart(int n, int T, vector<pair<int, int>> t) {
	vector<pair<int, int>> a;
	vector<int> b;
	for (int i = 0; i < n; i++) {
		if (t[i].first) a.push_back(t[i]);
		else b.push_back(t[i].second);
	}
	sort(all(a), [](pair<int, int> x, pair<int, int> y) {
		return (x.second + 1) * y.first < (y.second + 1) * x.first;
	});
	sort(all(b));
	n = a.size();
	int m = b.size();
	for (int i = 0; i < N; i++) {
		for (int j = 0; j < L; j++) {
			dp[i][j] = inf;
		}
	}
	dp[0][0] = 0;
	for (int i = 0; i < n; i++) {
		for (int j = 0; j < L; j++) {
			if (dp[i][j] > T) continue;
			dp[i + 1][j] = min(dp[i + 1][j], dp[i][j]);
			if (j != (L - 1))
				dp[i + 1][j + 1] = min(dp[i + 1][j + 1], dp[i][j] + 1 + a[i].first * (dp[i][j] + 1) + a[i].second);
			//cout << i << " " << j << " " << dp[i][j] << endl;
		}
	}
	int ans = 0;
	for (int i = 0; i < L; i++) {
		int cur = dp[n][i];
		if (cur > T) continue;
		ans = max(ans, i);
		int t = 0;
		for (int j : b) {
			if (cur + 1 + j > T) break;
			t++;
			cur = cur + 1 + j;
		}
		ans = max(ans, i + t);
	}
	return ans;
}

int kek[1 << 20];

int stupid(int n, int T, vector<pair<int, int>> t) {
	int ans = 0;
	kek[0] = 0;
	for (int mask = 1; mask < (1 << n); mask++) {
		kek[mask] = inf;
		int cnt = 0;
		for (int i = 0; i < n; i++) {
			if ((1 << i) & mask) {
				cnt++;
				if (kek[mask ^ (1 << i)] > T) continue;
				kek[mask] = min(kek[mask], kek[mask ^ (1 << i)] + 1 + t[i].first * (kek[mask ^ (1 << i)] + 1) + t[i].second);
				if (mask == 5 && kek[mask] == 19) {
					cout << i << endl;					//cout << kek[mask ^ (1 << i)] + 1 + t[i].first * (kek[mask ^ (1 << i)] + 1) << endl;
				}
			}
		}
		cout << mask << " " << kek[mask] << endl;
		if (kek[mask] <= T) {
			ans = max(ans, cnt);
		}
	}
	return ans;
}

