ll dp[40][222222];

bool cmp(ii a, ii b)
{
	return ((b.fi)*1LL*a.se<(a.fi)*1LL*b.se);
}

int main()
{
	ios_base::sync_with_stdio(0); cin.tie(0);
	int n,t; cin>>n>>t; t++;
	vector<int> zero;
	vector<ii> vec;
	for(int i=0;i<n;i++)
	{
		int a,b; cin>>a>>b;
		b++;
		if(a==0) zero.pb(b);
		else vec.pb({a,b});
	}
	sort(zero.begin(),zero.end());
	sort(vec.begin(),vec.end(),cmp);
	for(int i=0;i<vec.size();i++)
	{
		dp[0][i]=1;
	}
	for(int i=0;i<vec.size();i++)
	{
		dp[1][i]=vec[i].fi+vec[i].se+1;
	}
	for(int j=2;j<=39;j++)
	{
		ll best = ll(1e18);
		for(int i=0;i<vec.size();i++)
		{
			if(best<=ll(1e9)+7)
			{
				dp[j][i]=best*(vec[i].fi+1)+vec[i].se;
			}
			else dp[j][i]=0;
			if(dp[j-1][i]>0) best=min(best,dp[j-1][i]);
		}
	}
	int ans=0; 
	for(int j=0;j<=39;j++)
	{
		ll res = ll(1e18);
		for(int i=0;i<vec.size();i++)
		{
			if(dp[j][i]!=0) res=min(res,dp[j][i]);
		}
		if(vec.empty()&&j==0) res=1;
		if(res<=t)
		{
			int cnt=0;
			ll remtime = t - res;
			while(cnt<zero.size()&&remtime>=zero[cnt])
			{
				remtime-=zero[cnt];
				cnt++;
			}
			ans=max(ans,j+cnt);
		}
	}
	cout<<ans<<'\n';
}

