        }
    }
    sort(res.begin(), res.end());
    return res;
}


template<class T> struct CHT {
    using Line = pair<T, T>;
    deque<Line> lines;

    //overflowのためdouble
    inline bool check(const Line &a, const Line &b, const Line &c) {
        return (double)(b.f - a.f) * 1. * (c.s - b.s) >= (double)(b.s - a.s) * 1. * (c.f - b.f);
    }

    inline ll get(int k, T x) {
        return (double)lines[k].f * x + lines[k].s;
    }

    void insert(T a, T b) {
        Line l(a, b);
        while (lines.size() >= 2
               && check(lines[(int)lines.size()-2], lines[(int)lines.size()-1], l)){
            lines.pop_back();
          }
        lines.push_back(l);
    }


    // クエリの単調性も成り立つ場合 (x が単調増加)
    T query_monotone(T x) {
        while (lines.size() >= 2 && get(0, x) >= get(1, x)) lines.pop_front();
        return lines[0].first * x + lines[0].second;
    }
};


ll N, T;
vector<pair<ll, ll>> ab;
vector<ll> zero;
bool comp(pair<ll, ll> &abi, pair<ll, ll> &abj){
  return 1.0 * (abi.s + 1) / abi.f <= 1.0 * (abj.s + 1) / abi.f;
}

ll dp[200010][33];
ll Min[33];
void solve(){
  cin >> N >> T;
  rep(i, N){
    ll a, b;
    cin >> a >> b;
    if(a == 0){
      zero.pb(b);
    }else{
      ab.pb({a, b});
    }
  }
  sort(ab.begin(), ab.end(), comp);
  sort(zero.begin(), zero.end());
  N = ab.size();
  ll M = zero.size();
  rep(i, 200010)rep(j, 33) dp[i][j] = INF;
  dp[0][0] = 0;
  rep(i, N)rep(j, 30){
    dp[i+1][j] = min(dp[i+1][j], dp[i][j]);
    dp[i+1][j+1] = min(dp[i+1][j+1], dp[i][j] + 1 + ab[i].f * (dp[i][j] + 1) + ab[i].s);
  }

  rep(i, 33) Min[i] = INF;
  rep(i, N+1)rep(j, 33){
    Min[j] = min(Min[j], dp[i][j]);
  }
  ll ans = 0;
  rep(i, 33){
    ll now = Min[i];
    if(now <= T) ans = max(ans, (ll)i);
    rep(j, M){
      now += zero[j] + 1;
      if(now <= T) ans = max(ans, (ll)i + j + 1);
    }
  }
