		for (auto itr = z.begin(); itr != z.end(); itr++) {
			s += *itr;
			mp.insert({ s, c });
			c++;
			if (s > T) { break; }
		}
	}

	N = v.size();

	if (N == 0) {
		ll ans = 0;
		for (auto itr = mp.begin(); itr != mp.end(); itr++) {
			if (itr->first <= T) { chmax(ans, itr->second); }
		}
		cout << ans << endl;
		return 0;
	}

	ll** dp = new ll * [N];
	for (int i = 0; i < N; i++) {
		dp[i] = new ll[30];
		for (int j = 0; j < 30; j++) {
			dp[i][j] = T + 100000;
		}
	}
	dp[0][0] = 0;
	dp[0][1] = v[0].first + v[0].second + 1;
	for (int i = 1; i < N; i++) {
		dp[i][0] = 0;
		dp[i][1] = v[i].first + v[i].second + 1;
		for (int j = 2; j < 30; j++) {
			dp[i][j] = dp[i - 1][j];
			if (dp[i - 1][j - 1] <= T) {
				chmin(dp[i][j], dp[i - 1][j - 1] + (dp[i - 1][j - 1] + 1) * v[i].first + v[i].second);
			}
		}
	}

	ll ans = 0;
	for (ll i = 0; i < 30; i++) {
		ll t = dp[N - 1][i];
		if (t <= T) {
			chmax(ans, i);
			if (mp.size() > 0) {
				ll rest = T - t;
				auto itr = mp.lower_bound(rest);
				if (itr != mp.end()) {
					chmax(ans, i + mp.lower_bound(rest)->second);
				}
			}
		}
	}

	cout << ans << endl;

	return 0;
}

