typedef long long ll;
typedef pair <int, int> ii;

const int Maxd = 40;

int n, t;
vector <ii> seq;
vector <int> zers;
ll dp[Maxd];

bool Less(const ii &fir, const ii &sec)
{
    return ll(sec.first) * fir.second < ll(fir.first) * sec.second;
}

int main()
{
    scanf("%d %d", &n, &t);
    for (int i = 0; i < n; i++) {
        int a, b; scanf("%d %d", &a, &b);
        if (a == 0) zers.push_back(b);
        else seq.push_back(ii(a, b));
    }
    sort(seq.begin(), seq.end(), Less);
    fill(dp, dp + Maxd, t + 1);
    dp[0] = 0;
    for (int i = 0; i < seq.size(); i++) {
        for (int j = Maxd - 2; j >= 0; j--) if (dp[j] <= t) {
            ll cand = dp[j] + 1;
            cand += ll(seq[i].first) * cand + seq[i].second;
            dp[j + 1] = min(dp[j + 1], cand);
        }
    }
    sort(zers.begin(), zers.end());
    int res = 0;
    for (int i = 0; i < Maxd; i++) if (dp[i] <= t) {
        int cand = i;
        ll cur = dp[i];
        for (int j = 0; j < zers.size(); j++)
            if (cur + 1 + zers[j] <= t) {
                cur += 1 + zers[j];
                cand++;
            }
        res = max(res, cand);
    }
    printf("%d\n", res);
    return 0;
}

