  int res = 0;
  for (int i = 0; i < 40; ++i) {
    if (dp[i] <= t) res = i;
  }
  int64_t sum = 0;
  for (int i = 0; i < oth.size(); ++i) {
    sum += b[oth[i]];
    for (int j = 0; j < 40; ++j) {
      if (dp[j] > t) break;
      if (sum + dp[j] + 1 <= t) res = max(res, i + 1 + j);
    }
  }
  cout << res << "\n";
  return 0;
}

