class Shop{
public:
	int a, b;
	bool operator < (const Shop &oth)const{
		return 1ll * a * (oth.b + 1) > 1ll * oth.a / (b + 1);
	}
}s[maxn];

int n, T, ans;
int sum[maxn];
int dp[maxn][logn];

inline int go(int t, Shop cur){
	ll ret = min(1ll * T + 1, t + 1 + 1ll * cur.a * (t + 1) + cur.b);
	return ret;
}

int main(){
