const int LOG = 35;
const long long LL_INF = (long long) 2e18 + 5;

int N;
long long T;
vector<pair<long long, long long>> stores;

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    cin >> N >> T;

    for (int i = 0; i < N; i++) {
        int a, b;
        cin >> a >> b;
        a++;
        stores.emplace_back(a, b);
    }

    auto &&compare_stores = [&](const pair<long long, long long> &x, const pair<long long, long long> &y) {
        long long a = x.first, b = x.second;
        long long c = y.first, d = y.second;
        return c * b + c + d < a * d + a + b;
    };

    sort(stores.begin(), stores.end(), compare_stores);
    assert(is_sorted(stores.begin(), stores.end(), compare_stores));
    dbg(stores);

    vector<long long> dp(LOG + 1, LL_INF);
    dp[0] = 0;

    auto &&evaluate = [&](const pair<long long, long long> &store, long long time) {
        return store.first * time + store.second;
    };

    for (auto &store : stores) {
        if (store.first == 0)
            continue;

        for (int s = LOG - 1; s >= 0; s--)
            if (dp[s] <= T)
                dp[s + 1] = min(dp[s + 1], evaluate(store, dp[s] + 1));
    }

    sort(stores.begin(), stores.end());
    int zeros = 0;

    while (zeros < N && stores[zeros].first == 0)
        zeros++;

    int best = 0;

    for (int s = 0; s <= LOG; s++) {
        int count = s;
        long long time = dp[s];

        for (int i = 0; i < zeros; i++)
            if (time <= T && evaluate(stores[i], time + 1) <= T) {
                time = evaluate(stores[i], time + 1);
                count++;
            }

        if (time <= T)
            best = max(best, count);
    }

    cout << best << '\n';
}

