int main() {
	cin >> N >> T;
	REP(i, 0, N) {
		int a, b;
		cin >> a >> b;
		if (a == 0) {
			qs.push_back(b + 1);
		} else {
			ps.push_back(PP(a, b));
		}
	}

	sort(ps.begin(), ps.end(), [](PP a, PP b) {
		if (a.first != b.first) return a.first > b.first;
		return a.second > b.second;
		return (b.first + 1) * (a.second + 1) + b.second
			> (a.first + 1) * (b.second + 1) + a.second;
		}
	);
	sort(qs.begin(), qs.end());

	const int MAX = 30;
	vector<LL> dp(MAX, INF);
	dp[0] = 1;
	for (PP p : ps) {
		REM(k, 1, MAX) {
			dp[k] = min(dp[k], dp[k - 1] + p.first * dp[k - 1] + p.second + 1);
		}
	}

	vector<LL> acc(qs.size() + 1);
	partial_sum(qs.begin(), qs.end(), acc.begin() + 1);

	int ans = 0;
	REP(k, 0, MAX) {
		LL now = dp[k];
		if (now > T) continue;
		LL rem = T - now + 1;
		auto it = upper_bound(acc.begin(), acc.end(), rem) - 1;
		int sum = k + (it - acc.begin());
		ans = max(ans, sum);
	}
	cout << ans << endl;
