const int inf = 0x7fffffff;
const int N = 2e5 + 10, K = 32;
int n, T, a[N], b[N], p[N], k;
bool cmp(const int &i, const int &j)
{
	ll A = 1LL * (b[i] + 1) * a[j], B = 1LL * (b[j] + 1) * a[i];
	return A == B ? b[i] < b[j] : A < B;
}
int dp[2][K];
int main()
{
//	freopen("eriri.in", "r", stdin);
//	freopen("eriri.out", "w", stdout);
	n = read(), T = read();
	for (int i = 1; i <= n; ++i)
		a[i] = read(), b[i] = read();
	iota(p + 1, p + 1 + n, 1);
	sort(p + 1, p + 1 + n, cmp);
	k = 0;
	for (int i = 1; i <= n; ++i)
	{
		if (a[p[i]] == 0)
			break;
		k = i;
	}
	int id = 0;
	for (int j = 0; j < K; ++j)
		dp[id][j] = T + 1;
	dp[id][0] = 0;
	for (int i = 1; i <= k; ++i)
	{
		for (int j = 0; j < K; ++j)
			dp[id ^ 1][j] = dp[id][j];
		for (int j = 0; j < K - 1; ++j)
			if (dp[id][j] < T)
			{
				ll t = 1 + 1LL * a[p[i]] * (1 + dp[id][j]) + b[p[i]];
				if (t + dp[id][j] < T)
					dp[id ^ 1][j + 1] = min(dp[id ^ 1][j + 1], (int)(t + dp[id][j]));				
			}
		id ^= 1;
	}
	int ans = 0;
	for (int j = 0; j < K; ++j)
		if (dp[id][j] < T)
		{
			int s = j, cur = dp[id][j];
			for (int i = k + 1; i <= n; ++i)
			{
				ll t = 1 + 1LL * a[p[i]] * (1 + cur) + b[p[i]];
				if (t + cur > T)
					break;
				cur += t, ++s;
			}
			ans = max(ans, s); 
		}
	write(ans);
	return 0;
}

