typedef long long LL;
typedef pair<LL,LL> P;


struct comp
{
	bool operator()(P p, P q)
	{
		return q.first*(p.second+1)<p.first*(q.second+1);
	}
};

const LL inf=1e9+1;
int main(){
    long long N;
    scanf("%lld",&N);
    long long T;
    scanf("%lld",&T);
	vector<P> ps;
	vector<LL> bs;
    for(int i = 0 ; i < N ; i++){
		LL a,b;
        scanf("%lld",&a);
        scanf("%lld",&b);
		if(a==0)
		{
			bs.push_back(b);
		}
		else{
			ps.push_back(P(a,b));
		}
    }
	sort(bs.begin(),bs.end());
	int ret=0;
	for(int i=0;i<bs.size();i++){
		if(i>0){
			bs[i]+=bs[i-1];
		}
		bs[i]++;
		if(bs[i]<=T)
		{
			ret=i+1;
		}
	}
	sort(ps.begin(),ps.end(),comp());
	vector<LL> dp;
	for(auto p:ps){
		dp.push_back(min(inf,p.first+p.second));
		//cerr << dp.back() << endl;
	}

	for(int k=1;;k++){
		LL m=inf;
		for(int i=0;i<ps.size();i++){
			if(dp[i]<=T){
				LL r=T-dp[i];
				int c=upper_bound(bs.begin(),bs.end(),r)-bs.begin();
				ret=max(ret,k+c);
			}
			LL m2=min(m,dp[i]);
			dp[i]=min(inf,ps[i].first*(m+1)+ps[i].second+m+1);
			m=m2;
		}

		if(m==inf)
		{
			break;
		}
	}

	printf("%d\n",ret);


    return 0;
}

