typedef long long ll;
int n;
ll k;

struct T {
  ll a;
  ll b;
};

bool operator < (T f, T s) {
  /// t => t * f.a + f.b => (t * f.a + f.b) * s.a + s.b = t * f.a * s.a + f.b * s.a + s.b
  /// t => t * s.a + s.b => (t * s.a + s.b) * f.a + f.b = t * f.a * s.a + s.b * f.a + f.b
  return f.b * s.a + s.b < s.b * f.a + f.b;
}

vector<T> a;
vector<ll> one;
const int N = 40;
const ll INF = (ll) 1e18;
ll mn[N];

int main() {
  ios::sync_with_stdio(0);
  cin.tie(0);

  cin >> n >> k;
  for (int i = 1; i <= n; i++) {
    ll x, y;
    cin >> x >> y;
    x++;
    y++;
    if (x == 1) {
      one.push_back(y);
    } else {
      a.push_back({x, y});
    }
  }
  sort(a.begin(), a.end());
  sort(one.begin(), one.end());
  mn[0] = 0;
  for (int i = 1; i < N; i++) {
    mn[i] = INF;
  }
  for (auto &it : a) {
    for (int i = N - 2; i >= 0; i--) {
      mn[i + 1] = min(mn[i + 1], mn[i] * it.a + it.b);
    }
  }
  int ret = 0;
  for (int i = 0; i < N; i++) {
    if (mn[i] <= k) {
      int cur = i;
      for (auto &it : one) {
        if (mn[i] + it <= k) {
          mn[i] += it;
          cur++;
        } else {
          break;
        }
      }
      ret = max(ret, cur);
    }
  }
  cout << ret << "\n";
}

