        if(u==0) zero.push_back(v);
        else notzero.push_back(ii(u,v));
    }
    sort(notzero.begin(),notzero.end(),cmp);
    sort(zero.begin(),zero.end());
    n=notzero.size();
    k=zero.size();
    for(int i=0 ; i<k ; i++) {
        if(i==0) sum.push_back(zero[i]);
        else sum.push_back(sum[i-1]+zero[i]);
    }
