    for(int i=1 ; i<=n ; i++) {
        for(int j=1 ; j<=min(n,30) ; j++) {
            if(i==j) {
                dp[i][j]=min(inf,dp[i-1][j-1]+1+notzero[i-1].first*(dp[i-1][j-1]+1)+notzero[i-1].second);
            }
