ll a[200010],b[200010],dp[200010][40],c[200010];
int main(){
	ll i,j,n,t;
	cin >> n >> t; t++;
	for(i=0;i<n;i++){
		cin >> a[i] >> b[i];
		a[i]++; b[i]++;
		if(a[i]>=2){
			p.push_back({(ld)(a[i] - 1)/(ld)b[i],i});
		}else{
			v.push_back(b[i]);
		}
	}
	sort(p.rbegin(),p.rend());
	sort(v.begin(),v.end());
	for(i=0;i<=p.size();i++){
		for(j=0;j<40;j++){
			dp[i][j] = 100000000000;
		}
	}
	dp[0][0] = 1;
	for(i=1;i<=p.size();i++){
		for(j=0;j<40;j++){
			int k = p[i - 1].second;
			if(dp[i - 1][j]<=t) dp[i][j] = min(dp[i][j],dp[i - 1][j]);
			if(j>=1 && dp[i - 1][j - 1]<=t && a[k]*dp[i - 1][j - 1] + b[k]<=t) dp[i][j] = min(dp[i][j],a[k]*dp[i - 1][j - 1] + b[k]);
		}
	}
	ll sum = 0;
	int k = 0;
	for(j=39;j>=0;j--){
		while(k<v.size() && dp[p.size()][j] + sum + v[k]<=t){
			sum += v[k];
			k++;
		}
		c[j] = k;
	}
	ll ans = 0;
	for(j=0;j<40;j++){
		if(dp[p.size()][j]<=t){
			ans = max(ans,j + c[j]);
		}
	}
