using namespace std;
using lint     = long long;
const lint inf = 1LL << 60;
const lint mod = 1000000007;

template <class T>
bool chmax(T &a, const T &b) {
    return (a < b) ? (a = b, 1) : 0;
}
template <class T>
bool chmin(T &a, const T &b) {
    return (b < a) ? (a = b, 1) : 0;
}

int main() {
    cin.tie(nullptr);
    ios::sync_with_stdio(false);
    int n, t;
    cin >> n >> t;
    vector<pair<lint, lint>> ab;
    vector<lint> zero;
    for (int i = 0; i < n; ++i) {
        lint a, b;
        cin >> a >> b;
        b++;
        if (a != 0) {
            ab.emplace_back(a, b);
        } else {
            zero.push_back(b);
        }
    }
    auto f = [](pair<lint, lint> l, pair<lint, lint> r) { return r.first * l.second < l.first * r.second; };
    sort(ab.begin(), ab.end(), f);
    sort(zero.begin(), zero.end());
    int na = ab.size();
    int nz = zero.size();
    vector<vector<lint>> dp(na + 1, vector<lint>(40, inf));
    dp[0][0] = 1;
    for (int i = 1; i <= na; ++i) {
        chmin(dp[i][0], 1LL);
        for (int j = 1; j < 20; ++j) {
            chmin(dp[i][j], dp[i - 1][j]);
            if (dp[i - 1][j - 1] < 1e9 + 10)
                chmin(dp[i][j], dp[i - 1][j - 1] + ab[i - 1].first * dp[i - 1][j - 1] + ab[i - 1].second);
        }
    }
    int ret = 0;
    for (int i = 0; i < 40; ++i) {
        if (dp[na][i] > t + 1)
            continue;
        int cnt = i;
        int iz  = 0;
        while (iz < nz && dp[na][i] + zero[iz] <= t + 1) {
            dp[na][i] += zero[iz];
            cnt++;
            iz++;
        }
        chmax(ret, cnt);
    }
    cout << ret << "\n";
    return 0;
}

