int main() {
    cin.tie(nullptr);
    ios::sync_with_stdio(false);
    int n; long long t; cin >> n >> t;
    vector<long long> a(n), b(n), c(n);
    for (int i = 0; i < n; i++) cin >> a[i] >> b[i], c[i] = i;
    auto cmp = [&](int i, int j) {
        return a[i] * (b[j] + 1) > a[j] * (b[i] + 1);
    };
    sort(c.begin(), c.end(), cmp);
    vector<long long> dp(33, t * 2);
    multiset<long long> ms; dp[0] = 0;
    for (int i = 0; i < n; i++) {
        if (a[c[i]] == 0) {
            ms.insert(b[c[i]]);
            continue;
        }
        for (int j = 31; j >= 0; j--) {
            if (dp[j] > t) continue;
            if ((a[c[i]] + 1) * (dp[j] + 1) + b[c[i]] <= t) {
                dp[j+1] = min(dp[j+1], (a[c[i]] + 1) * (dp[j] + 1) + b[c[i]]);
            } 
        }
    }
    vector<long long> v;
    long long curr = 0;
    v.emplace_back(curr);
    for (auto &x: ms) {
        curr += x + 1;
        v.emplace_back(curr);
    }
    v.emplace_back(1e18);
    int ans = 0;
    for (int i = 0; i < 32; i++) {
        if (t < dp[i]) continue;
        int x = upper_bound(v.begin(), v.end(), t-dp[i]) - v.begin();
        ans = max(ans, i + max(0, x-1));
    }
    cout << ans << "\n";
    return 0;
}

