bool cmp(pair < ll, ll > A, pair < ll, ll > B) {
    return A.fir * (B.sec + 1) > B.fir * (A.sec + 1);
}

void solve() {

    int n; ll t;
    scanf("%d %lld", &n, &t);
    int cnt1 = 0, cnt2 = 0;
    rep(i, 1, n) {
        scanf("%lld %lld", &tmp.fir, &tmp.sec);
        if(tmp.fir == 0) c[++ cnt2] = tmp.sec + 1;
        else a[++ cnt1] = tmp;
    }
    sort(c + 1 , c + cnt2 + 1) ;
    sort(a + 1 , a + cnt1 + 1 , cmp) ;
    for(int i = 1; i <= 30 ;i ++) dp[i] = t + 1 ;
    dp[0] = 0 ;
    int cnt = 0 ;
    for(int i = 1; i <= cnt2 ;i ++) c[i] += c[i - 1] ;

    for(int i = 1; i <= cnt1 ;i ++)
    {
      for(int j = 30 ;j >= 1 ;j --)
       dp[j] = min(dp[j] , (dp[j - 1] + 1) * (a[i].first + 1)+ a[i].second) ;
    }
    int ans = 0 ;
    for(int i = 0 ;i <= 30 ;i ++)
     {
       if(dp[i] > t) continue ;
       int j = 0 ;
       if(cnt2)
        j = upper_bound(c + 1 , c + cnt2 + 1 , t - dp[i]) - c - 1;
       ans = max(ans , i + j) ;
     }
    printf("%d\n", ans);
    return ;
}
int main() {
    solve();
    return 0;
