	long long int a, b;
	Shop(const long long int aa, const long long int bb) {
		a = aa, b = bb;
	}
	bool operator<(const Shop &s)const {
		return make_pair(-a, b) < make_pair(-s.a, s.b);
	}
};

int main() {
