using namespace std;

typedef long long ll;
const ll inf = (ll) 1e18;

ll mul(ll a, ll b) {
  if (a == 0 || b == 0) {
    return 0;
  }
  ll p = a * b;
  if (p % a == 0 && p / a == b && p <= inf) {
    return p;
  } else {
    return inf;
  }
}

ll add(ll a, ll b) {
  return min(inf, a + b);
}

struct T {
  ll a;
  ll b;
};

bool operator < (T f, T s) {
  ll a1 = f.a, b1 = f.b;
  ll a2 = s.a, b2 = s.b;
  return a1 * b2 < a2 * b1;
  return add(b2, mul(b1, a2)) < add(b1, mul(b2, a1));
}

ll b[40], b2[40];

int main() {
  ios::sync_with_stdio(0);
  cin.tie(0);

  int n;
  ll lim;
  cin >> n >> lim;
  vector<T> a;
  vector<ll> bb;
  for (int i = 0; i < n; i++) {
    ll x, y;
    cin >> x >> y;
    x++;
    y++;
    if (x == 1) {
      bb.push_back(y);
    } else {
      a.push_back({x, y});
    }
  }
  sort(a.begin(), a.end());
  sort(bb.begin(), bb.end());
  for (int i = 1; i < 40; i++) {
    b[i] = inf;
  }
  for (auto &it : a) {
    for (int i = 0; i < 40; i++) {
      b2[i] = b[i];
      if (i >= 1) {
        b2[i] = min(b2[i], add(it.b, mul(it.a, b[i - 1])));
      }
    }
    for (int i = 0; i < 40; i++) {
      b[i] = b2[i];
    }
  }
  int ret = 0;
  for (int i = 0; i < 40; i++) {
    ll cur = b[i];
    if (cur <= lim) {
      int j = i;
      for (auto &x : bb) {
        if (add(cur, x) <= lim) {
          cur = add(cur, x);
          j++;
        } else {
          break;
        }
      }
      ret = max(ret, j);
    }
  }
  cout << ret << "\n";
}

