bool comp(const P &p1, const P &p2) {
	int c1 = p1.first + 1, c2 = p2.first + 1;
	int d1 = p1.first + p1.second + 1, d2 = p2.first + p2.second + 1;
	return c2 * d1 + d2 < c1*d2 + d1;
}
vector<P>v1, v0;

ll dp[200020][50];//i番目まででj個買った時の時間のmin

void solve() {
	int N, T; cin >> N >> T;
	vector<int>A(N), B(N);

	REP(i, N) {
		cin >> A[i] >> B[i];
		if (A[i] > 0)v1.push_back({ A[i],B[i] });
		else v0.push_back({ A[i],B[i] });
	}
	//print("input");
	sort(v1.begin(),v1.end(), comp);
	//print("sorted");
	VSORT(v0);
	int M = v1.size();
	REP(i, M + 1) {
		REP(j, 50) {
			dp[i][j] = 1e18;
		}
	}
	dp[0][0] = 0;
	REP(i, M) {
		REP(j, 45) {
			ll t = dp[i][j];
			if (t > T)continue;
			chmin(dp[i + 1][j], dp[i][j]);
			//買う
			ll nt = (t + 1)*v1[i].first + v1[i].second;
			if (nt > T)continue;
			chmin(dp[i + 1][j + 1], nt);
		}
	}
	ll ans = 0;
	//print("a");
	REP(k, 50) {
		if (dp[M][k] > T)continue;
		int cnt = k;
		int rem = T - dp[M][k];
		REP(i, (int)v0.size()) {
			if (v0[i].second + 1 <= rem) {
				cnt++;
				rem -= (v0[i].second + 1);
			}
		}
		ans = max(ans, cnt);
	}
	print(ans);
}

