pair<long,long> D[200000];
long sum[200001];
void Calc(){
	int N = rei();
	long T = rei()+1;
	for(int i=0;i<N;i++){
		long a = rei();
		long b = rei();
		D[i] = {a+1,b+1};
	}
	sort(D,D+N,[](pair<long,long> l,pair<long,long> r){
		return l.first*r.second + l.second == r.first*l.second + r.second ? l.second < r.second : l.first*r.second + l.second > r.first*l.second + r.second;
	});
	vector<long> DP1(50); 
	vector<long> DP2(50);
	for(int i=1;i<50;i++){
		DP1[i] = T+1; 
	}
	DP1[0] = 1;
	int p = 0;
	for(;p<N && D[p].first != 1;p++){
		DP2[0] = 1;
		for(int i=1;i<50;i++){
			DP2[i] = min(DP1[i],DP1[i-1]*D[p].first + D[p].second);
		}
		swap(DP1,DP2);
	}
	int st = p;
	for(;p<N;p++){
		sum[p+1] = sum[p] + D[p].second;
	}
	int ans = 0;
	for(int i=0;i<50;i++){
		int bf = st-1;
		int bl = N;
		while(bf != bl){
			int bc = (bf+bl+1)/2;
			if(bc == st-1 || sum[bc]+DP1[i] <= T){
				bf = bc;
			}
			else{
				bl = bc-1;
			}
		}
		if(bf != st-1){
			ans = max(ans,i+bf-st);
		}
	}
	cout << ans << endl;
}
int main(int argc,char** argv){
	ios::sync_with_stdio(false), cin.tie(0);
	cout.tie(0); Calc(); return 0;
}

