	cin >> n >> t;
	vector <pair <int, int>> arr(n + 1);
	for(i = 1; i <= n; i++) {
		cin >> arr[i].a >> arr[i].b;
		arr[i].a++;
	}
	sort(next(arr.begin()), arr.end(), [&](const pair <int, int> &x, const pair <int, int> &y) {
		if(x.a == 1 && y.a == 1) {
			return x.b < y.b;
		}
		return 1LL * x.b * y.a + y.a + y.b > 1LL * y.b * x.a + x.a + x.b;
	});

	vector <ll> best(41, INF);
	best[0] = 0;

	while(arr.size() && arr.back().a >= 2) {
		vector <ll> cur(41, INF);
		for(int j = 0; j < 40; j++) {
			if(best[j] <= t) {
				cur[j + 1] = 1LL * (best[j] + 1) * arr.back().a + arr.back().b;
			}
		}
		for(int j = 0; j <= 40; j++) {
			best[j] = min(best[j], cur[j]);
		}
		arr.pop_back();
	}
	int ans = 0;
	for(int j = 0; j <= 40; j++) {
		if(best[j] >= t + 1) continue;

		ll cur = best[j];
		i = 1;
		while(i < (int)arr.size() && cur + arr[i].b + 1 <= t) {
			cur += arr[i].b + 1;
			i++;
		}
		ans = max(ans, j + i - 1);
	}

	cout << ans;

	return 0;
}

