    for (int i=1;i<40;i++) {
        ll cmin = T+1;
        if (i==1) cmin = 0;
        for (int j=0;j<M;j++){
            if (cmin < T) {
                ll a = funcs[j].first;
                ll b = funcs[j].second;
                dp[i][j] = min(dp[i][j], (a+1)*cmin + b);
