bool cmp(pair<ll,ll> a, pair<ll,ll> b) {
	if(a.fst == 0&&b.fst == 0) return a.snd < b.snd;
	return a.fst * b.snd + a.fst > b.fst * a.snd + b.fst;
}
ll dp[2][32];

int main() {
	int n, t;
	scanf("%d%d", &n, &t);
	for(int i = 1;i <= n;++i) {
		scanf("%d%d", &a[i].fst, &a[i].snd);
	}

	sort(a + 1,a + 1 + n, cmp);
	memset(dp, - 1,sizeof dp);
	dp[0][0] = 0;
	int now = 0,last = 1, idx = n + 1;
	for(int i = 1;i <= n;++i) {
		if(!a[i].fst) break;
		swap(now, last);
		memcpy(dp[now], dp[last], sizeof(dp[now]));
		for(int j = 1;j < 32;++j) {
			if(dp[last][j-1] != -1) {
				ll to = a[i].fst * (dp[last][j-1] + 1) + a[i].snd + dp[last][j-1] + 1;
