ll getTime(int cnt) {
  vector<P> v;
  for(int i = 1; i <= N; ++i) v.push_back({a[i]*T+b[i], i});
  sort(v.begin(), v.end());
  ll t = 0LL;
  for(int i = cnt; i >= 1; --i) {
    int idx = v[i-1].second;
    ++t;
