}
int check( int x ) {
	int l = 0, r = num, ans = 0 ; 
	while( l <= r ) {
		int mid = ( l + r ) >> 1 ; 
		if( Pre[mid] <= x ) ans = mid, l = mid + 1 ;
		else r = mid - 1 ;
	} return ans ; 
