#include <bits/stdc++.h>
using namespace std;


using ll = long long;
int N, T;
vector<pair<int, int>> store;


ll g(ll t0, int k)
{
    ll a = store[k].first;
    ll b = store[k].second;
    return t0 + 1 + a * (t0 + 1) + b;
}


void solve()
{
    sort(store.begin(), store.end(),
    [](const pair<int, int> &p1, const pair<int, int> &p2) {
        ll x1 = (ll)p1.first * (p2.second + 1);
        ll x2 = (ll)p2.first * (p1.second + 1);
        return ((x1 > x2) || (x1 == x2 && p1.second < p2.second));
    });

    const ll Inf = 2e9;
    int len = 0;
    int s = 1;
    int k = N;
    while (s <= T) {
        s *= 2;
        len++;
    }
    len = min(len, N);
    vector<ll> dp(len + 1);
    for (int j = 1; j <= len; j++)
        dp[j] = Inf;
    for (int i = 0; i < N; i++) {
        if (store[i].first == 0) {
            k = i;
            break;
        }
        for (int j = len; j > 0; j--)
            dp[j] = min(dp[j], g(dp[j - 1], i));
    }

    int ans = 0;
    for (int i = 0; i <= len; i++) {
        int c = i, k0 = k;
        ll x = dp[i];
        if (x > T)
            break;
        while (k0 < N && (x = g(x, k0)) <= T) {
            c++;
            k0++;
        }
        ans = max(ans, c);
    }
    cout << ans << endl;
}


int main()
{
    cin >> N >> T;
    store.resize(N);
    for (int i = 0; i < N; i++)
        cin >> store[i].first >> store[i].second;
    solve();
    return 0;
}

