vector<ll> divisor(ll n){
    vector<ll> res(0);
    for(ll i = 1; i * i <= n; i++){
        if(n % i == 0){
            res.push_back(i);
            if(i != n/i) res.push_back(n/i);
        }
    }
    sort(res.begin(), res.end());
    return res;
}


template<class T> struct CHT {
    using Line = pair<T, T>;
    deque<Line> lines;

    //overflowのためdouble
    inline bool check(const Line &a, const Line &b, const Line &c) {
        return (double)(b.f - a.f) * 1. * (c.s - b.s) >= (double)(b.s - a.s) * 1. * (c.f - b.f);
    }

    inline ll get(int k, T x) {
        return (double)lines[k].f * x + lines[k].s;
    }

    void insert(T a, T b) {
        Line l(a, b);
        while (lines.size() >= 2
               && check(lines[(int)lines.size()-2], lines[(int)lines.size()-1], l)){
            lines.pop_back();
          }
        lines.push_back(l);
    }


    // クエリの単調性も成り立つ場合 (x が単調増加)
    T query_monotone(T x) {
        while (lines.size() >= 2 && get(0, x) >= get(1, x)) lines.pop_front();
        return lines[0].first * x + lines[0].second;
    }
};


ll N, T;
vector<pair<ll, ll>> ab;
bool comp(pair<ll, ll> abi, pair<ll, ll> abj){
  return (abi.s + 1) * abj.f <= (abj.s + 1) + abi.f;
}
void solve(){
  cin >> N >> T;
  ab.resize(N);
  rep(i, N) cin >> ab[i].f >> ab[i].s;
  sort(ab.begin(), ab.end(), comp);

  vector<ll> need(N+1, 0);
  ll now = 0;
  for(ll i = 1; i <= N; i++){
    need[i] = need[i-1] + 1 + (need[i-1] + 1) * ab[i-1].f + ab[i-1].s;
  }

  ll ans = 0;
  CHT<ll> cht;
  for(ll i = N; i >= 0; i--){
    if(need[i] <= T){
      ans = max(ans, i);
    }
    if(i != N){
      ll now = need[i];
      ll x = cht.query_monotone(now) + 1;
      if(now + x <= T){
        ans = max(ans, i+1);
      }
    }
    cht.insert(ab[i-1].f, ab[i-1].f + ab[i-1].s);
  }
  cout << ans << endl;
}

int main(){
  ios_base::sync_with_stdio(0);
  cin.tie(0), cout.tie(0);
  solve();
}

