const int N = 2e5 + 6;
const int L = 33;

ll dp[N][L];

void solve() {
	int n; cin >> n;
	int T; cin >> T;
	vector<pair<int, int>> t(n);
	for (int i = 0; i < n; i++)
		cin >> t[i].first >> t[i].second;
	vector<pair<int, int>> a;
	vector<int> b;
	for (int i = 0; i < n; i++) {
		if (t[i].first) a.push_back(t[i]);
		else b.push_back(t[i].second);
	}
	sort(all(a), [](pair<int, int> x, pair<int, int> y) {
		return (x.second + 1) * (y.first - 1) < (y.second + 1 ) * (x.first - 1);
	});
	sort(all(b));
	n = a.size();
	int m = b.size();
	for (int i = 0; i < N; i++) {
		for (int j = 0; j < L; j++) {
			dp[i][j] = inf;
		}
	}
	dp[0][0] = 0;
	for (int i = 0; i < n; i++) {
		for (int j = 0; j < L; j++) {
			if (dp[i][j] > T) continue;
			dp[i + 1][j] = min(dp[i + 1][j], dp[i][j]);
			if(j != (L - 1))
				dp[i + 1][j + 1] = min(dp[i + 1][j + 1], a[i].first * (dp[i][j] + 1) + a[i].second);
			//cout << i << " " << j << " " << dp[i][j] << endl;
		}
	}
	int ans = 0;
	for (int i = 0; i < L; i++) {
		int cur = dp[n][i];
		if (cur > T) continue;
		ans = max(ans, i);
		int t = 0;
		for (int j : b) {
			if (cur + 1 + j > T) break;
			t++;
			cur = cur + 1 + j;
		}
		ans = max(ans, i + t);
	}
	cout << ans << endl;
	return;
}

