inline bool chmin(T& x, T a) {
	if (x >= a) { x = a; return true; }
	return false;
}

template<typename T>
inline bool chmax(T& x, T a) {
	if (x <= a) { x = a; return true; }
	return false;
}

int main() {
	int N; cin >> N;
	ll T; cin >> T;

	vector <pair<int,int>> v;
	vector<ll> z;
	for (int i = 0; i < N; i++) {
		ll a, b; cin >> a >> b;
		if (a == 0) { z.push_back(b + 1); continue; }
		v.push_back({ a,b });
	}
	sort(z.begin(), z.end());

	map<ll, ll, greater<ll>> mp;
	{
		ll s = 0;
		ll c = 1;
		for (auto itr = z.begin(); itr != z.end(); itr++) {
			s += *itr;
			mp.insert({ s, c });
			c++;
			if (s > T) { break; }
		}
	}

	N = v.size();

	if (N == 0) {
		ll ans = 0;
		for (auto itr = mp.begin(); itr != mp.end(); itr++) {
			if (itr->first <= T) { chmax(ans, itr->second); }
		}
		cout << ans << endl;
		return 0;
	}

	ll** dp = new ll * [N];
	for (int i = 0; i < N; i++) {
		dp[i] = new ll[40];
		for (int j = 0; j < 40; j++) {
			dp[i][j] = T + 100000;
		}
