			if (dp[i - 1][j - 1] <= T) {
				chmin(dp[i][j], dp[i - 1][j - 1] + (dp[i - 1][j - 1] + 1) * v[i].first + v[i].second);
			}
		}
	}

	ll ans = 0;
	for (ll i = 0; i < 40; i++) {
		ll t = dp[N - 1][i];
		if (t <= T) {
			chmax(ans, i);
			if (mp.size() > 0) {
				ll rest = T - t;
				auto itr = mp.lower_bound(rest);
				if (itr != mp.end()) {
					chmax(ans, i + mp.lower_bound(rest)->second);
				}
			}
		}
	}

	cout << ans << endl;

	return 0;
}

