      chmin(dp[j + 1], (A[i] + 1) * (dp[j] + 1) + B[i]);
    }
  }
  int res = 0;
  for (int i = 0; i < (int)dp.size(); i++) {
    if (dp[i] > T) continue;
    int64_t r = T - dp[i];
    int p = 0;
    while (p < (int)C.size() && r >= C[p]) {
      r -= C[p++];
    }
    res = max(res, i + p);
  }
  cout << res << '\n';
  return 0;
}

