struct range {
  struct itr {
    int i;
    constexpr itr(int i_): i(i_) { }
    constexpr void operator ++ () { ++i; }
    constexpr int operator * () const { return i; }
    constexpr bool operator != (itr x) const { return i != x.i; }
  };
  const itr l, r;
  constexpr range(int l_, int r_): l(l_), r(std::max(l_, r_)) { }
  constexpr itr begin() const { return l; }
  constexpr itr end() const { return r; }
};

// [l, r) from r to l
struct revrange {
  struct itr {
    int i;
    constexpr itr(int i_): i(i_) { }
    constexpr void operator ++ () { --i; }
    constexpr int operator * () const { return i; }
    constexpr bool operator != (itr x) const { return i != x.i; }
  };
  const itr r, l;
  constexpr revrange(int l_, int r_): l(l_ - 1), r(std::max(l_, r_) - 1) { }
  constexpr itr begin() const { return r; }
  constexpr itr end() const { return l; }
};

struct func {
  long long a, b;
  long long operator () (long long x) const {
    return a * x + b;
  }
};

constexpr long long inf = (1 << 30) - 1;

int main() {
  int N;
  long long T;
  std::cin >> N >> T;
  ++T;
  std::vector<func> former, latter;
  for (int i: range(0, N)) {
    func f;
    std::cin >> f.a >> f.b;
    ++f.a; ++f.b;
    (f.a > 1 ? former : latter).push_back(f);
  }
  std::sort(former.begin(), former.end(), [](auto x, auto y) {
    return (x.a - 1) * y.b > (y.a - 1) * x.b;
  });
  std::vector<long long> dp(50, inf);
  dp[0] = 1;
  for (auto f: former) {
    for (int i: revrange(0, 50)) {
      if (dp[i] == inf) continue;
      chmin(dp[i + 1], f(dp[i]));
    }
  }
  std::sort(latter.begin(), latter.end(), [](auto x, auto y) {
    return x.b < y.b;
  });
  std::vector<long long> sum(latter.size() + 1);
  for (int i: range(0, latter.size())) {
    sum[i + 1] = sum[i] + latter[i].b;
  }
  int ans = 0;
  for (int i: range(0, 50)) {
    if (dp[i] > T) continue;
    chmax(ans, i + std::upper_bound(sum.begin(), sum.end(), T - dp[i]) - sum.begin() - 1);
  }
  std::cout << ans << '\n';
  return 0;
}

