constexpr int INF = 1 << 30;
constexpr ll MOD = ll(1e9) + 7;
constexpr int di[] = {0, 1, 0, -1};
constexpr int dj[] = {1, 0, -1, 0};
constexpr double EPS = 1e-8;

void chmin(ll &a, ll b){
    a = min(a,b);
}

int solve(){
    ll n, T;
    cin >> n >> T;
    vector<P3> v;
    vector<ll> cnst = {0};
    for(int i=0;i<n;i++){
        ll a, b;
        cin >> a >> b;
        if(a > 0) v.push_back(P3(double(b)/(a+1),P(a,b)));
        else cnst.push_back(b);
    }
    sort(v.begin(), v.end());
    sort(cnst.begin(), cnst.end());
    for(int i=0;i<int(cnst.size())-1;i++){
        cnst[i+1] += cnst[i]+1;
    }
    int m = v.size();
    vector<vector<ll> > dp(m+1, vector<ll>(36, T+1));
    dp[0][0] = 0;
    for(int i=0;i<m;i++){
        for(int j=0;j<35;j++){
            if(dp[i][j] > T) continue;
            ll a = v[i].second.first, b = v[i].second.second;
            chmin(dp[i+1][j], dp[i][j]);
            chmin(dp[i+1][j+1], min(a*(dp[i][j]+1)+b, T+1));
        }
    }
    int ans = 0;
    for(int i=0;i<=35;i++){
        if(dp[m][i] > T) break;
        ans = max(ans, i+int(upper_bound(cnst.begin(),cnst.end(),T-dp[m][i])-cnst.begin())-1);
    }
    cout << ans << endl;
    return 0;
}

