using namespace std;
using ll=long long;
using P=pair<ll,ll>;
const ll INF=1LL<<60;
const ll MOD=998244353LL;
template<class T> void chmin(T &a,T b){a=min(a,b);}
template<class T> void chmax(T &a,T b){a=max(a,b);}
int main(){
	ios::sync_with_stdio(0);
	cin.tie(0);
	ll n,t;cin>>n>>t;
	vector<ll> bs;
	vector<P> v;
	for(int i=0;i<n;i++){
		ll a,b;cin>>a>>b;
		if(a==0){
			bs.eb(b+1LL);
		}else{
			v.eb(a,b);
		}
	}
	sort(all(bs));
	vector<ll> sum(bs.size()+1);
	for(int i=0;i<bs.size();i++){
		sum[i+1]=sum[i]+bs[i];
	}
	sum.eb(INF);
	ll res=upper_bound(all(sum),t)-sum.begin();
	--res;
	n=v.size();
	sort(all(v),[](P &a,P &b){return (a.second+1LL)*(b.first-1LL)<(a.first-1LL)*(b.second+1LL);});
	vector<vector<ll>> dp(35,vector<ll>(n+1,INF));
	for(int i=0;i<n;i++){
		dp[1][i]=(v[i].first+1LL)+v[i].second;
		if(dp[1][i]<=t){
			ll s=upper_bound(all(sum),t-dp[1][i])-sum.begin();
			chmax(res,s);
		}
	}
	for(int i=2;i<=30;i++){
		ll mi=INF;
		for(int j=0;j<n;j++){
			if(mi<=t){
				dp[i][j]=(v[j].first+1LL)*mi+v[j].second;
				if(dp[i][j]<=t){
					ll s=upper_bound(all(sum),t-dp[i][j])-sum.begin();
					s+=i-1LL;
					chmax(res,s);
				}
			}
			chmin(mi,dp[i-1][j]+1LL);
		}
	}
	cout<<res<<endl;
}

