struct Data
{
	int a,b;
}p[maxn],q[maxn];
int n,m,ans,tot1,tot2;
long long f[40],sum[maxn];
bool cmp1(const Data &x,const Data &y)
{
	return x.b<y.b;
}
bool cmp2(const Data &x,const Data &y)
{
	return (1ll*x.b*y.a+y.a)<(1ll*y.b*x.a+x.a);
}
int check(int x)
{
	int l=0,r=tot2;
	while(l<=r)
	{
		int mid=(l+r)>>1;
		if(sum[mid]<=x)
			l=mid+1;
		else
			r=mid-1;
	}
	return r;
}
