vector<pair<int,int>> A;
vector<long long> B;
int T, ans, res;
long long t;

void solve(int c)
{
	long long b=t;
	int s=c+1, e=A.size()-1;
	t+=A[c].first*(t+1)+A[c].second;
	if(t>T) {
		t=b;
		return;
	}
	ans=max(ans,++res+(int)(upper_bound(B.begin(),B.end(),T-t)-B.begin()));
	while(s<=e) {
		int m=(s+e)>>1;
		if(A[m].first*(t+1)+A[m].second>T) s=m+1;
		else e=m-1;
	}
	if(s<A.size()) solve(s);
	for(int i=max(s+1,(int)A.size()-30);i<A.size();i++) solve(i);
	res--;
	t=b;
}

