		b[i].build();
	}
	int cur = 0, res = 0;
	for (int it = 0; it < n; it++) {
		cur++;
		int pos = -1;
		ll mn = inf;
		for (int i = 0; i <= (n - 1) / K; i++) {
			ll val = b[i].ch.getmin(cur);
			if (pos == -1 || val < mn)
				pos = i, mn = val;
