using namespace std;

typedef pair<int, int> Pii;

inline int read()
{
	int x = 0; bool f = true;
	char c = getchar();
	for (; ! IsDigit(c); c = getchar()) if (c == '-') f = false;
	for (; IsDigit(c); c = getchar()) x = (x << 3) + (x << 1) + (c ^ '0');
	return f ? x : -x;
}
inline void write(int x)
{
    if (x < 0)
	{
        putchar('-');
		x = -x;
	}
    if (x > 9) write(x / 10);
	putchar(x % 10 + '0');
}

int n, T, Max, Ans, f[MAX];

vector<Pii> A;
vector<int> B;

inline bool mycmp(Pii x, Pii y)
{
	return x.first * (y.second + 1) > y.first * (x.second + 1);
}

signed main()
{
	n = read(); T = read(); Max = log(T) + 1;
	for ( int x, y, i = 1; i <= n; i++)
	{
		x = read(); y = read();
		if (x != 0) A.push_back(make_pair(x, y));
		    else B.push_back(y + 1);
	}	

	for ( int i = 0; i <= Max; i++)
		f[i] = T + 1;
	sort(A.begin(), A.end(), mycmp);
	sort(B.begin(), B.end());
	for ( int i = 1; i < B.size(); i++) B[i] += B[i - 1];	

	f[0] = 0;
	for ( int i = 0; i < A.size(); i++)
		for ( int j = Max; j; j--)
			    f[j] = min(f[j], (f[j - 1] + 1) * (A[i].first + 1) + A[i].second);
	for ( int i = 0	; i <= Max; i++)
		if (f[i] <= T) Ans = max(Ans, i + (int)(B.empty() ? 0 : upper_bound(B.begin(), B.end(), T - f[i]) - B.begin() - 1));
	write(Ans);

	return 0;
}

