using namespace std;

typedef pair<long long, long long> ii;

long long f(ii x, ii y){
	long long ax = x.first;
	long long ay = y.first;
	long long bx = x.second;
	long long by = y.second;

	return ax * ay + bx * ay + 2 * ay + by + ax + bx + 2;
}

long long g(long long t, ii x){
	return t * x.first + x.first + x.second + t + 1;
}

bool comp(ii a, ii b){
	//cout << a.first << " " << b.first << " " << (f(a,b) < f(b,a)) << "\n";
	if(a.first >= b.first && a.second >= b.second) return false;
	if(a.first <= b.first && a.second <= b.second) return true;
	return f(a,b) < f(b,a);
}
int main(){
	//freopen("i.txt","r",stdin);
	ios_base::sync_with_stdio(false);
	cin.tie(0);

	long long n, T; cin >> n >> T;
	ii arr[n];

	for(int i = 0;i < n;i++){
		cin >> arr[i].first >> arr[i].second;
	}


	sort(arr,arr+n,comp);

	long long ans = 0;
	long long t = 0;
	long long pt = 0;
	for(int i = 0;i < n;i++){
		//cout << arr[i].first << " " << arr[i].second << "\n";
		if(g(t,arr[i]) <= T){
			pt = t;
			t = g(t,arr[i]);
			ans++;
		}
		else if(g(pt,arr[i]) < t) t = g(pt,arr[i]);
	}

	cout << ans;
}

