    }
    sort(a.rbegin(),a.rend());
    sort(b.begin(),b.end());
    n=a.size();
    for(i=1;i<min(n,30);i++)
        for(d[i][(j=i)-1]=t+1;j<n;j++)
            d[i][j]=min(1LL*d[i][j-1],1LL*(d[i-1][j-1]+1)*(a[j].x+1)+a[j].y);
    s.push_back(0);
    for(auto it:b)
    {
        s.push_back(s.back()+it+1);
        if(s.back()>t)
            break;
    }
    for(k=0,i=1;i<n&&d[i][n-1]<=t;i++)
        k=max(k,i+bs(t-d[i][n-1]));
    cout<<k;
    return 0;
}

