ll getdiam(vector<ll> v[], ll n, ll sta)
{

   ll dis[n];
   memset(dis,-1,sizeof(dis));
   dis[sta] = 1;

   queue<ll> q;
   q.push(sta);
   while(q.size()>0)
   {
       ll curr = q.front();
       q.pop();

       autoit(v[curr],it)
       {
           if(dis[*it]!=-1)
                continue;
           dis[*it] = dis[curr] + 1;
           q.push(*it);
       }
   }

   ll nod = -1;
   ll maxi = 0;
   for(ll i=0;i<n;i++)
   {
       if(dis[i]>maxi)
       {
           maxi = dis[i];
           nod = i;
       }
   }

   memset(dis,-1,sizeof(dis));
   dis[nod] = 1;

   //queue<ll> q;
   q.push(nod);
   ll par[n];
   par[nod] = -1;
   while(q.size()>0)
   {
       ll curr = q.front();
       q.pop();

       autoit(v[curr],it)
       {
           if(dis[*it]!=-1)
                continue;
           dis[*it] = dis[curr] + 1;
           par[*it] = curr;
           q.push(*it);
       }
   }

   ll nod1 = -1;
   maxi = 0;
   for(ll i=0;i<n;i++)
   {
       if(dis[i]>maxi)
       {
           maxi = dis[i];
           nod1 = i;
       }
   }

   vector<ll> nodes;
   nodes.pb(nod1);
   while(par[nodes.back()]!=-1)
        nodes.pb(par[nodes.back()]);
   return (ll)nodes.size()-1;    
}



