using lint = long long;
constexpr lint INF = 1LL << 30;
constexpr int K = 40;

void solve() {
    int n;
    lint t;
    std::cin >> n >> t;

    std::vector<std::pair<lint, lint>> ps;
    std::vector<lint> ones;
    while (n--) {
        lint a, b;
        std::cin >> a >> b;
        if (a == 0) {
            ones.push_back(b);
        } else {
            ps.emplace_back(a + 1, a + b + 1);
        }
    }

    std::sort(ones.begin(), ones.end());

    n = ps.size();
    std::sort(ps.begin(), ps.end(),
              [](auto p, auto q) {
                  return (p.first - 1) * q.second > (q.first - 1) * p.second;
              });

    std::vector<lint> dp(K + 1, INF);
    dp[0] = 0;
    for (auto p : ps) {
        lint a, b;
        std::tie(a, b) = p;

        for (int k = K; k > 0; --k) {
            dp[k] = std::min(dp[k], dp[k - 1] * a + b);
        }
    }

    int ans = 0;
    for (int k = 0; k <= K; ++k) {
        if (dp[k] > t) break;

        int cnt = k;
        for (auto pt : ones) {
            dp[k] += pt + 1;
            if (dp[k] > t) break;
            ++cnt;
        }

        ans = std::max(ans, cnt);
    }

    std::cout << ans << std::endl;
}

int main() {
    std::cin.tie(nullptr);
    std::cout.tie(nullptr);
    std::ios::sync_with_stdio(false);

    solve();

    return 0;
}

