int main(){
  cin.tie(0);
  ios::sync_with_stdio(false);

  int N;
  ll T;
  cin>>N>>T;
  vector<ll> A(N),B(N);
  rep(i,N) cin>>A[i]>>B[i];

  vector<int> zero;
  vector<int> ord;
  rep(i,N){
    if(A[i]==0) zero.push_back(i);
    else ord.push_back(i);
  }

  sort(ord.begin(),ord.end(),[&](int a,int b){
    return (A[a]*(B[b]+1)>A[b]*(B[a]+1));
  });

  int M=ord.size();
  vector<vector<ll>> dp(M+1,vector<ll> (62,INF));
  dp[0][0]=0;
  for(int i=0;i<M;i++){
    int now=ord[i];
    for(int j=0;j<=60;j++){
      if(dp[i][j]==INF) continue;
      chmin(dp[i+1][j],dp[i][j]);

      ll neco=A[now]*(dp[i][j]+1)+B[now];
      if(dp[i][j]+1+neco<=T) chmin(dp[i+1][j+1],dp[i][j]+1+neco);
    }
  }

  int P=zero.size();
  int ans=0;
  int pos=0;
  ll zs=0;
  for(int j=0;j<=60;j++){
    ll val=dp[M][j];
    if(val==INF) continue;
    while(pos<P&&val+zs+1+B[zero[pos]]<=T){
      zs+=B[zero[pos]]+1;
      pos++;
    }
    chmax(ans,j+pos);
  }
  cout<<ans<<endl;

  return 0;
}

