const ll dp_H = 222222;
const ll dp_W = 111;

ll dp[dp_H][dp_W];

int main(){
	cin.tie(0);cout.tie(0);ios::sync_with_stdio(false);

	ll n, t;cin >> n >> t;
	vector<pair<double, P>> v;
	vector<ll> g;
	REP(i, n){
		ll a, b;cin >> a >> b;

		if(a == 0){
			g.PB(b+1);
		}
		else {
			ll c = a + 1;
			ll d = a + b + 1;
			v.EB(-(c - 1.) / d, MP(c, d));
		}
	}
	g.PB(0);

	sort(ALL(v));
	sort(ALL(g));
	REP(i, g.size() - 1)g[i+1] += g[i];

	REP(i, 222222)REP(j, 111)dp[i][j] = 2 * INF;
	dp[0][0] = 0;

	REP(i, v.size()){
		auto now = v[i].SE;
		REP(j, dp_W){
			dp[i+1][j] = min(dp[i+1][j], dp[i][j]);
			if(j != dp_W - 1)dp[i+1][j+1] = min(dp[i+1][j+1], now.FI * dp[i][j] + now.SE);
		}
	}

	ll ans = 0;
	REP(i, 111){
		REP(j, g.size()){
			if(dp[v.size()][i] + g[j] <= t)ans = max(ans, i + j);
		}
	}

	cout << ans << endl;

