bool comp(pair<ll, ll> a, pair<ll, ll> b)
{
    if(a.fi * (b.se+1ll) > b.fi * (a.se+1ll))
        return 1;
    return 0;
}

ll dp[200005][35];

int main()
{
    ios_base::sync_with_stdio(0);
    cin.tie(0); cout.tie(0);

    ll n, T; cin >> n >> T; T;
    pair<ll, ll> dat[n];
    for(int i = 0; i < n; i++)
    {
        cin >> dat[i].fi >> dat[i].se;
    }
    vector<pair<ll, ll> > vc;
    vector<ll> v;
    for(int i = 0; i < n; i++)
    {
        if(dat[i].fi)
        {
            vc.push_back(dat[i]);
        }
        else
        {
            v.push_back(dat[i].se);
        }
    }
    for(int i = 0; i <= vc.size(); i++)
    {
        for(int j = 0; j < 35; j++)
        {
            dp[i][j] =T+1;
        }
    }
    sort(vc.begin(), vc.end(), comp);
    sort(v.begin(), v.end());
    dp[0][0] = 0;
    for(int i = 0; i < vc.size(); i++)
    {
        for(int j = 0; j < 35; j++)
        {
            if(dp[i][j] > T)
                continue;
            if(j < 34)
            {
                ll mt = dp[i][j] + vc[i].fi * (dp[i][j]+1) + vc[i].se + 1;
                dp[i+1][j+1] = min(dp[i+1][j+1], mt);
            }
            dp[i+1][j] = min(dp[i+1][j], dp[i][j]);
        }
    }
    ll ans = 0;
    for(int j = 0; j < 35; j++)
    {
        if(dp[vc.size()][j] > T)
            continue;
        ll sm = T-dp[vc.size()][j], res = j;
        for(int i = 0; i < v.size(); i++)
        {
            if(v[i]+1 > sm)
                break;
            res++;
            sm -= v[i]+1;
        }
        ans = max(ans, res);
    }
    cout << ans << '\n';
}






































