const int maxn = 200005;

struct market
{
	long long a, b;
};

market mar[maxn];
long long f[maxn];
priority_queue<long long, vector<long long>, greater<long long> > spe;
stack<int> load;

inline bool cmp(market a, market b)
{
	return a.a * (b.b + 1) > b.a * (a.b + 1);
}

int main()
{
	int n;
	long long T;
	scanf("%d%lld", &n, &T);
	int tt = 1;
	for (int i = 1; i <= n; i++, tt++)
	{
		scanf("%lld%lld", &mar[tt].a, &mar[tt].b);
		if (mar[tt].a == 0)
			spe.push(mar[tt].b + 1), tt--;
	}
	n = tt - 1;
	sort(mar + 1, mar + n + 1, cmp);
	int tn = 32;
	f[0] = 0;
	for (int i = 1; i <= tn; i++)
		f[i] = T + 1;
	for (int i = 1; i <= n; i++)
		for (int j = tn; j; j--)
			f[j] = min(f[j], (f[j - 1] + 1) * (mar[i].a + 1) + mar[i].b);
	int total = 0, answer = 0, cnt = 0;
	for (int i = 0; i <= tn; i++)
	{
		if (f[i] > T)
			continue;
		while (!spe.empty() && total + f[i] + spe.top() <= T)
		{
			total += spe.top();
			load.push(spe.top());
			cnt++;
			spe.pop();
		}
		while (total + f[i] > T)
		{
			total -= load.top();
			load.pop();
		}
		answer = max(answer, i + cnt);
	}
	printf("%d\n", answer);
	return 0;
}

