using namespace std;

/* constant */

const int MAX_N = 200000;
const int MAX_J = 30;
const int INF = 1 << 30;

/* typedef */

typedef long long ll;
typedef vector<int> vi;
typedef queue<int> qi;
typedef pair<int,int> pii;

struct Shop {
  int a, b;
  double d;
  Shop() {}
  Shop(int _a, int _b): a(_a), b(_b), d((double)_a / (_b + 1)) {}

  bool operator<(const Shop &s) const { return d < s.d; }
  ll next_t(int t) { return (ll)a * (t + 1) + b + t + 1; }
};

/* global variables */

Shop ss[MAX_N];
int bs[MAX_N];
ll bss[MAX_N + 1];
int dp[2][MAX_J + 1];

/* subroutines */

/* main */

int main() {
  int n, t;
  scanf("%d%d", &n, &t);

  int m = 0, k = 0;
  for (int i = 0; i < n; i++) {
    int a, b;
    scanf("%d%d", &a, &b);
    if (a > 1) ss[m++] = Shop(a, b);
    else bs[k++] = b + 1;
  }
  sort(ss, ss + m);
  sort(bs, bs + k);

  for (int i = 0; i < k; i++) bss[i + 1] = bss[i] + bs[i];

  fill(dp[0], dp[0] + MAX_J + 1, t + 1);
  dp[0][0] = 0;
  int cur = 0, nxt = 1;

  for (int i = 0; i < m; i++) {
    memcpy(dp[nxt], dp[cur], sizeof(dp[cur]));
    for (int j = 0; j < MAX_J; j++)
      if (dp[cur][j] <= t) {
	ll t1 = ss[i].next_t(dp[cur][j]);
	if (dp[nxt][j + 1] > t1) dp[nxt][j + 1] = t1;
      }
    swap(cur, nxt);
  }

  int maxx = 0;
  for (int j = 0; j <= MAX_J; j++)
    if (dp[cur][j] <= t) {
      int dt = t - dp[cur][j];
      int l = upper_bound(bss, bss + k + 1, (ll)dt) - bss - 1;
      int x = j + l;
      if (maxx < x) maxx = x;
    }

  printf("%d\n", maxx);
  return 0;
}

