int main() {
  ios_base::sync_with_stdio(false);
  cin.tie(nullptr);
  Z N, T;
  cin >> N >> T;
  vector<pair<Z, Z>> ab(N);
  for (auto i = 0; i < N; i++) {
    cin >> ix(ab, i).first >> ix(ab, i).second;
    ix(ab, i).second += ix(ab, i).first + 1;
  }
  sort(begin(ab), end(ab),
      [] (auto p, auto q) {
        if (p.first == q.first) return p.second < q.second;
        return p.first > q.first;
      });
  dump(ab);
  Z logT = 0;
  while ((1 << logT) < T) logT++;
  logT += 10; // ?
  Z finiteA = 0;
  for (finiteA = 0; finiteA < N; finiteA++)
    if (ix(ab, finiteA).first == 0) break;
  dump(finiteA);
  vector<vector<Z>> dp(finiteA + 1, vector<Z>(logT + 1, T + 1));
  ix(dp, 0, 0) = 0;
  for (auto i = 0; i < finiteA; i++) {
    for (auto j = 0; j < logT; j++) {
      ix(dp, i + 1, j) = min(ix(dp, i + 1, j), ix(dp, i, j));
      ix(dp, i + 1, j + 1) = min(ix(dp, i + 1, j + 1), (ix(ab, i).first + 1) * ix(dp, i, j) + ix(ab, i).second);
    }
  }
  dump(dp);
  Z ans = 0;
  vector<Z> zeros_sum(N - finiteA + 1);
  for (auto i = finiteA; i < N; i++)
    ix(zeros_sum, i + 1 - finiteA) += ix(zeros_sum, i - finiteA) + ix(ab, i).second;
  for (auto i = 0; i <= logT; i++) {
    if (ix(dp, finiteA, i) > T) continue;
    auto ok = upper_bound(begin(zeros_sum), end(zeros_sum), T - ix(dp, finiteA, i));
    Z rest = distance(begin(zeros_sum) + 1, ok);
    dump(rest);
    ans = max(ans, i + rest);
  }
  cout << ans << endl;
}

