const int N = 200005, Tlg = 36;
const long long inf = 1e17;
int n, t, x, y, ni, m, fp;
vector<pair<long double, pair<int, int> > > v;
vector<int> ve;
long long dp[N][Tlg], nb[N];
bool bn;

int main() {
	ios::sync_with_stdio(0);
	cin.tie(0);
	cin >> n >> t;
	for(int i = 0; i <= n; ++i) {
		if(i) cin >> x >> y;
		else x = 1000000001, y = 0;
		if(x) v.push_back({(long double)x / (y + 1), {x, y}});
		else ve.push_back(y);
	}
	m = v.size(); --m;
	sort(v.begin(), v.end());
	reverse(v.begin(), v.end());
	for(int i = 1; i < Tlg; ++i) dp[0][i] = -1;
	for(int i = 1; i < v.size(); ++i) {
		for(int j = 1; j < Tlg; ++j) {
			dp[i][j] = min((dp[i - 1][j - 1] == -1 ? inf : (dp[i - 1][j - 1] + 1 + (dp[i - 1][j - 1] + 1) * v[i].second.first + v[i].second.second)), (dp[i - 1][j] == -1 ? inf : dp[i - 1][j]));
			assert(dp[i][j] > 0);
			if(dp[i][j] == inf) dp[i][j] = -1;
		}
	}
	sort(ve.begin(), ve.end());
	for(int i = 0; i < ve.size(); ++i) {
		++ni;
		nb[ni] = nb[ni - 1] + 1 + ve[i];
	}
	for(int i = 0; i < Tlg; ++i) {
		if(dp[m][i] != -1) {
			for(int j = 0; j <= ni; ++j) {
				if(dp[m][i] + nb[j] <= t) {
					fp = max(fp, i + j);
				}
			}
		}
	}
	cout << fp << endl;
	return 0;
}

