int main() {
    ios_base::sync_with_stdio(0);
    cin.tie(nullptr);

    int n, t;
    cin>>n>>t;

    vector<pair<pair<ll, ll>, int>> base;
    vector<int> free;

    ll u, v;
    for (int i = 0; i<n; i++)
    {
        cin>>u>>v;
        v = u + v + 1;
        if (u==0) free.push_back(v);
        else base.push_back(mp(mp(u, v), base.size()));
    }

    int N = base.size();

    sort(base.begin(), base.end(), [](auto x, auto y)
    {
        if (x.first.first*y.first.second == x.first.second * y.first.first) return (x.second>y.second);
        else return   x.first.first*y.first.second >= x.first.second * y.first.first;
    });

    sort(free.begin(), free.end());


    vector<pair<ll, ll>> prs(N);
    for (int i = 0; i<N; i++) prs[i] = base[i].first;

    //for (auto it: prs) cout<<it.first<<' '<<it.second<<endl;

    for (int i = 0; i<N; i++) prs[i].first++;

    vector<vector<ll>> dp(N+1, vector<ll>(31, -1));

    dp[0][0] = 0;
    for (int i = 1; i<=N; i++)
        for (int cnt = 1; cnt<=30; cnt++)
        {
            dp[i][cnt] = dp[i-1][cnt];
            if (dp[i-1][cnt-1]!=-1)
            {
                ll time = dp[i-1][cnt-1]*prs[i-1].first + prs[i-1].second;
                if (time<=t)
                {
                    if (dp[i][cnt]==-1) dp[i][cnt] = time;
                    else dp[i][cnt] = min(dp[i][cnt], time);
                }
            }
        }

    int best = 0;
    for (int i = 0; i<=30; i++) if (dp[N][i]!=-1)
    {
        int timeleft = t - dp[N][i];
        int cur = 0;
        while (cur<free.size() && timeleft>=free[cur])
        {
            timeleft-=free[cur];
            cur++;
        }
        best = max(best, i+cur);
    }
    cout<<best;

}

