#include <bits/stdc++.h>

using namespace std;

#define int long long

bool cmp(pair <int, int> a, pair <int, int> b) {
    return a.first / (a.second + 1.0) > b.first / (b.second + 1.0);
}

int lul = 50;

void solve() {
    int n, t;
    cin >> n >> t;
    pair <int, int> a[n];
    for (int i = 0; i < n; ++i) cin >> a[i].first >> a[i].second;
    sort(a, a + n, cmp);
    //for (int i = 0; i < n; ++i) cout << a[i].first << ' ' << a[i].second << '\n';
    int dp[n][lul];
    for (int i = 0; i < n; ++i) for (int j = 0; j < lul; ++j) dp[i][j] = t + 1;
    for (int i = 0; i < n; ++i) dp[i][0] = 0;
    dp[0][1] = min(dp[0][1], 1 + a[0].first + a[0].second);
    int id = n;
    for (int i = 1; i < n; ++i) {
        if (a[i].first == 0) {
            id = i;
            break;
        }
        for (int j = 0; j < lul; ++j) dp[i][j] = dp[i - 1][j];
        for (int j = 0; j < lul - 1; ++j) {
            if (dp[i - 1][j] <= t) dp[i][j + 1] = min(dp[i][j + 1], dp[i - 1][j] + 1 + a[i].first * (dp[i - 1][j] + 1) + a[i].second);
        }
    }
    vector <int> lol;
    for (int i = id; i < n; ++i) lol.push_back(a[i].second);
    sort(lol.begin(), lol.end());
    int ans = 0;
    for (int i = 0; i < lul; ++i) {
        if (dp[id - 1][i] <= t) {
            int val = i, tt = dp[id - 1][i];
            //cout << val << ' ' << tt << ' ' << i << '\n';
            for (int j = 0; j < lol.size(); ++j) {
                if (1 + lol[j] + tt > t) break;
                ++val;
                tt += lol[j] + 1;
            }
            //cout << val << '\n';
            ans = max(ans, val);
        }
    }
    cout << ans;
}

signed main() {
    ios_base::sync_with_stdio(false);
    cin.tie(0);
    cout.tie(0);
    solve();
    return 0;
}

