using namespace std;

void solve() {
  ll N, T;
  cin >> N >> T;
  unordered_map<ll, priority_queue<ll>> mpq;
  rep (i, N) {
    ll a, b;
    cin >> a >> b;
    mpq[a].push(-b);
  }
  ll current = 0;
  ll ans = 0;
  while (true) {
    if (mpq.size() == 0) break;
    ll tmpa = mpq.begin()->first;
    ll tmpb = mpq.begin()->second.top();
    ll tmp = (current + 1) * (tmpa + 1) - tmpb; 
    for (auto it: mpq) {
      ll a = it.first;
      ll b = it.second.top();
      ll aaa = (current + 1) * (a + 1) - b;
      if (aaa <= tmp) {
        tmp = aaa;
        tmpa = a;
        tmpb = b;
      }
    }
    // cerr << "tmp: " << tmp << "< T: " << T << endl;
    if (tmp > T) break;
    current = tmp;
    ans++;
    mpq[tmpa].pop();
    if (mpq[tmpa].size() == 0) mpq.erase(tmpa);
  }

  cout << ans << endl;
}

