  int ans = 0;
  for (int i = 0; i <= 29; ++i) {
    ll cur = T - dp[i];
    if (cur < 0) break;
    for (int j = 0; j < a0.size(); ++j)
      if ((cur -= a0[j]) < 0) {
        ans = max(ans, i + j);
        break;
      }
    if (cur >= 0) ans = max(ans, i + (int)a0.size());
  }
  cout << ans << '\n';

#ifdef LBT
  LOG("Time: %dms\n", int ((clock()
          -nol_cl) / (double)CLOCKS_PER_SEC * 1000));
#endif
  return 0;
}

