#include <bits/stdc++.h>
using namespace std;

const int N = 2e5 + 100, LOG = 40;

typedef long long LL;

int a[N], b[N];
int dp[N][LOG];
int tmin[LOG];

bool cmp(pair<int,int> &p, pair<int,int> &q) {
    int a1 = p.first, b1 = p.second;
    int a2 = q.first, b2 = q.second;
    a1++, a2++;
    b1++, b2++;
    LL lft = 1ll*b1*a2+b2, rgt = 1ll*b2*a1+b1;
    return lft < rgt;
}

int main() {
    // freopen("in.txt", "r", stdin);
    ios::sync_with_stdio(0);
    cin.tie(0);

    int n, T;
    cin >> n >> T;
    vector<int> a0s;
    vector<pair<int,int>> a1s;
    for(int i = 1; i <= n; i++) {
        int x, y;
        cin >> x >> y;
        if(x == 0) a0s.push_back(y);
        else a1s.push_back({x, y});
    }
    sort(a0s.begin(), a0s.end());
    sort(a1s.begin(), a1s.end(), cmp);
    int sz = a1s.size();
    a1s.insert(a1s.begin(), make_pair(0,0));

    for(int i = 0; i <= sz; i++) {
        for(int j = 0; j < LOG; j++) {
            dp[i][j] = T+1;
        }
    }
    dp[0][0] = 0;
    for(int i = 1; i < LOG; i++) tmin[i] = T+1;

    for(int i = 1; i <= sz; i++) {
        for(int j = 0; j < LOG; j++) {
            dp[i][j] = min(dp[i][j], dp[i-1][j]);
            if(j > 0) {
                LL tt = dp[i-1][j-1];
                tt = tt+1 + (tt+1)*a1s[i].first + a1s[i].second;
                dp[i][j] = min((LL)dp[i][j], tt);
            }
            tmin[j] = min(tmin[j], dp[i][j]);
        }
    }
    int ans = 0;
    for(int i = 0; i < LOG; i++) {
        int t = tmin[i];
        if(t > T) continue;
        int cur = i;
        for(int j = 0; j < a0s.size(); j++){
            if(t + a0s[j] + 1 > T) break;
            cur++;
            t += a0s[j]+1;
        }
        ans = max(ans, cur);
    }
    cout << ans << endl;

    return 0;
}

