int get(int x) {
	if (b.empty()) return 0;
	int l = 0, r = b.size() - 1, ans;
	while (l <= r) {
		int mid = (l + r) >> 1;
		if (b[mid] <= x) l = mid + 1, ans = mid;
		else r = mid - 1;
	}
	return ans + 1;
}
