namespace bst = boost;
template<typename T> class in {
    T value;
public:
    in() { cin >> value; }
    operator const T&() const { return value; }
    operator T&() { return value; }
    in& operator=(T source) { value = source; return *this; }
};
template<> class in<string> : public string {
public:
    in() { cin >> *this; }
};
template<class T> class inseq : public T {
public:
    template<typename... Arg> inseq(Arg... arg) : T(forward<Arg>(arg)...) { for (auto&& i : *this) cin >> i; }
};
template<class T> using invec = inseq<vector<T>>;

auto solve() {
  in<int> N, T;
  vector<pair<int,int>> ab;
  vector<int> zero_b;

  REP(i, N) {
    int a, b;
    cin >> a >> b;
    if (a > 0)
    	ab.emplace_back(a, b);
    else 
      zero_b.push_back(b + 1);
  }

  bst::sort(ab, greater<pair<int,int>>());
  bst::sort(zero_b);
  for (int i = 1; i < zero_b.size(); i++)
    zero_b[i] += zero_b[i-1];

  map<int,int> dp;
  dp[0] = 0;
  int maxx = 0, maxv = 0;
  if (!ab.empty())
  	REP(i, N) {
    auto newdp = dp;
    for (auto it = dp.rbegin(); it != dp.rend(); ++it) {
      int newv = it->first + 1 + ab[i].first * (it->first+1) + ab[i].second;
      if (newv > T) break;
      else if (it->second * it->second <= T) {
        newdp[newv] = max(newdp[newv], it->second + 1);
        if (maxx < newdp[newv]) {
          maxx = newdp[newv];
          maxv = newv;
        }
      }
    }
    dp = move(newdp);
  }

  const int max0 = distance(zero_b.begin(), bst::lower_bound(zero_b, T - maxv));

  return maxx + max0;
}

