    if(a == 0){
      a_z.push_back(b);
    }else{
      a_nz.push_back(make_pair(-1.0 * a / (b + 1), make_pair(a, b)));
    }
  }
  sort(a_z.begin(), a_z.end());
  sort(a_nz.begin(), a_nz.end());

  vector<long long> a_z_sum;
  a_z_sum.push_back(0);
  for(int i = 0; i < a_z.size(); i++){
    a_z_sum.push_back(a_z_sum[i] + a_z[i] + 1);
  }

  // dp[i][j] := using mise[0: i), with time dp[i][j], j shop
  // dp[i + 1][j + 1] = a * (dp[i][j] + 1) + b
  vector<vector<long long>> dp(a_nz.size() + 1,
                               vector<long long>(31, T + 1));
  for(int i = 0; i <= a_nz.size(); i++){
    dp[i][0] = 0;
  }
  for(int i = 0; i < a_nz.size(); i++){
    long long a = a_nz[i].second.first, b = a_nz[i].second.second;
    for(int j = 0; j < 30; j++){
      dp[i + 1][j + 1] = min(dp[i][j + 1], min(dp[i][j] + 1 + a * (dp[i][j] + 1) + b, T + 1));
    }
  }

  /*
  for(int i = 0; i < 30; i++){
    cout << i << ' ' << dp[a_nz.size()][i] << endl;
  }
