  int ans = 0;
  for(int i = 0; i < 30; i++){
    int zero_cnt = 0;
    long long t_nz = dp[a_nz.size()][i];
    if(t_nz <= T){
      long long t_resid = T - t_nz;
      zero_cnt = (lower_bound(a_z_sum.begin(), a_z_sum.end(), t_resid + 1) - a_z_sum.begin() - 1);
      ans = max(ans, i + zero_cnt);
    }
    //cout << i << ' ' << zero_cnt << ' ' << endl;
  }
  cout << ans << endl;

}

