struct store {
    int a, b;
    store(int a, int b): a(a), b(b) {}
    bool operator< (const store& oth) const {return (ll)a*(oth.b+1)>(ll)oth.a*(b+1);}
};

const ll INF=1e18;
ll dp[2][33];

int32_t main() {
    fastio;
    int n, t; cin>>n>>t;
    vector<store> stores;
    vector<store> zeroes;
    rep(i, n) {
        int a, b; cin>>a>>b;
        if(a!=0) stores.eb(a, b);
        else zeroes.eb(a, b);
    }
    sort(all(stores));
    sort(all(zeroes));
    rep(i, 2) rep(j, 33) dp[i][j]=INF;
    dp[0][0]=0;
    rep(i, stores.size()) {
        rep(j, 33) dp[(i+1)&1][j]=INF;
        auto s=stores[i];
        rep(j, 33) {
            if(dp[i&1][j]==INF) continue;
            dp[(i+1)&1][j]=min(dp[(i+1)&1][j], dp[i&1][j]);
            ll c=(dp[i&1][j]+1)*(s.a+1)+s.b;
            if(c<=t&&j<32) dp[(i+1)&1][j+1]=min(dp[(i+1)&1][j+1], c);
        }
    }
    int ans=0;
    vll pf(zeroes.size()+1, 0);
    rep1(i, zeroes.size()) pf[i]=pf[i-1]+zeroes[i].b+1;
	rep(i, 33) {
		ll res=t-dp[stores.size()&1][i];
		if(res<0) continue;
		ans=max(ans, int(upper_bound(all(pf), res)-pf.begin()+i-1));
	}
	cout<<ans<<endl;
}

