const int K = 40;

int main() {

#ifdef DEBUG
    freopen("input.txt", "r", stdin);
#endif

    ios_base::sync_with_stdio(0);
    cin.tie(0);

    int n, T;

    cin >> n >> T;

    vector<int> a(n + 1), b(n + 1), perm(n), bs;

    for (int i = 1; i <= n; i++) {
        cin >> a[i] >> b[i];
        perm[i - 1] = i;
        if (a[i] == 0) {
            bs.push_back(b[i]);
        }
    }

    sort(bs.begin(), bs.end());

    sort(perm.begin(), perm.end(), [&](int i, int j) {
        return 1ll * a[j] * (b[i] + 1) < 1ll * a[i] * (b[j] + 1);
    });

    vector<vector<int>> dp(n + 1, vector<int>(K, T + 1));

    dp[0][0] = 0;

    for (int i = 1; i <= n; i++) {
        int I = perm[i - 1];
        for (int j = 0; j < K; j++) {
            dp[i][j] = dp[i - 1][j];
            if (a[I] > 0 && j > 0) {
                int tmp = (int) min(1ll + T, 1ll * (dp[i - 1][j - 1] + 1) * (a[I] + 1) + b[I]);
                dp[i][j] = min(dp[i][j], tmp);
            }
        }
    }

    int res = 0;

    for (int j = 0; j < K; j++) {
        int tmp = j;
        int cur = dp[n][j];
        for (int bi : bs) {
            if (cur + 1 + bi <= T) {
                cur += 1 + bi;
                tmp++;
            }
        }
        if (cur <= T)
            res = max(res, tmp);
    }

    cout << res << "\n";

    return 0;
}

