struct Info
{
	ll a, b;
	bool operator<(const Info& another) const
	{
		ll c = another.a * (b + 1) < a * (another.b + 1);
		if (c != 0) { return c > 0; }
		return b < another.b;
	};
};

int main() {
	int N; cin >> N;
	ll T; cin >> T;

	vector <Info> temp;
	vector<ll> z;
	for (int i = 0; i < N; i++) {
