	sort(z.begin(), z.end());

	vector<pair<ll, ll>> v;
	for (int i = 0; i < temp.size(); i++) {
		v.push_back({ temp[i].a, temp[i].b });
	}
	for (int i = 1; i < z.size(); i++) {
		z[i] += z[i - 1];
		chmin(z[i], T + 100);
	}

	N = v.size();

	if (N == 0) {
		ll ans = 0;
		for (int i = 0; i < z.size(); i++) {
			if (z[i] <= T) { chmax(ans, i + 1LL); }
		}
		cout << ans << endl;
		return 0;
	}

	ll** dp = new ll * [N];
	for (int i = 0; i < N; i++) {
		dp[i] = new ll[40];
		for (int j = 0; j < 40; j++) {
			dp[i][j] = T + 100000;
		}
