	dp[0][0] = 0;
	dp[0][1] = v[0].first + v[0].second + 1;
	for (int i = 1; i < N; i++) {
		dp[i][0] = 0;
		dp[i][1] = min(dp[i - 1][1], v[i].first + v[i].second + 1LL);
		for (int j = 2; j < 40; j++) {
			dp[i][j] = dp[i - 1][j];
			if (dp[i - 1][j - 1] + 1 <= T) {
				chmin(dp[i][j], dp[i - 1][j - 1] + 1 + (dp[i - 1][j - 1] + 1) * v[i].first + v[i].second);
			}
		}
	}

	ll ans = 0;
	for (ll i = 0; i < 40; i++) {
