                else
                {
                    ans1=max(ans1,ans+(int)min((ldb)t+1.5-cr,(ldb)cnt));
                    break;
                }
            }
        }
        else
        {
            for(int i=0;i<p.size();i++)
                if(!visited[i])
                {
                    int z=p[i].first*cr+cr+p[i].second;
                    if(zmin>z)
                    {
                        zmin=z;
                        mni=i;
                    }
                }


            cr=zmin;
            if(cr<(t+0.5))
                ans++;
            else
            {
                ans1=max(ans1,ans+(int)min((ldb)t+1.5-cr,(ldb)cnt));
                break;
            }
            visited[mni]=1;
        }
    }

    cout<<max(ans,ans1)<<endl;
}

