struct Shop {
	LL a, b;
};
vector<Shop> shops;
vector<int> extra;

bool operator<(Shop I, Shop J) {
	return J.a * I.b + J.a < I.a * J.b + I.a;
}
LL dp[2][40];

void solve(int ks) {
	int n;
	LL T;
	scanf("%d %lld", &n, &T);
	shops.reserve(200000);
	for (int i = 0; i < n; i++) {
		Shop s;
		scanf("%lld %lld", &s.a, &s.b);
		if (s.a == 0) {
			extra.push_back(s.b);
		}
		else {
			shops.push_back(s);
		}
	}
	sort(ALL(shops));
	sort(ALL(extra));

	dp[0][0] = 0;
	for (int i = 1; i < 40; i++) dp[0][i] = -1;
	int u = 0, v = 1;
	for (int i = 0; i < SZ(shops); i++) {
		for (int j = 0; j < 40; j++) dp[v][j] = dp[u][j];
		for (int j = 38; j >= 0; j--) {
			if (dp[u][j] == -1) continue;
			LL tt = dp[u][j] + 1;
			LL nxt = tt + shops[i].a * tt + shops[i].b;
			if (dp[v][j + 1] == -1 || dp[v][j + 1] > nxt) dp[v][j + 1] = nxt;
		}
		for (int j = 0; j < 40; j++) if (dp[u][j] > T) dp[u][j] = -1;
		swap(u, v);
	}
	int ans = 0;
	for (int i = 0; i < 40; i++) {
		if (dp[u][i] == -1 || dp[u][i] > T) continue;
		int now = i;
		LL cur = dp[u][i];
		int k = 0;
		while (k < SZ(extra)) {
			if (cur + extra[k] + 1<= T) {
				cur += extra[k] + 1;
				now++;
				k++;
			}
			else {
				break;
			}
		}
		ans = MAX(ans, now);
	}
	printf("%d\n", ans);

}

