pint ab[220000];
constexpr int B = 44;
int dp[220000][B];
signed main() {
    cin >> N >> T;
    rep(i, N) { cin >> a[i] >> b[i], ab[i] = {a[i] + 1, a[i] + b[i] + 1}; }
    sort(ab, ab + N, [](pint l, pint r) { return l.second < r.second; });
    stable_sort(ab, ab + N, [](pint l, pint r) { return (l.first - 1) * r.second > (r.first - 1) * l.second; });
    vint last{0};
    rep(i, N + 1) { fill(dp[i], dp[i] + B, T + 1); }
    dp[0][0] = 0;
    rep(i, N) {
        a[i] = ab[i].first, b[i] = ab[i].second;
        if (a[i] == 1) {
            last.emplace_back(last.back() + b[i]);
            continue;
        }
        rep(j, B) {
            chmin(dp[i + 1][j], dp[i][j]);
            if (a[i] * dp[i][j] + b[i] <= T && j != B - 1) { chmin(dp[i + 1][j + 1], a[i] * dp[i][j] + b[i]); }
        }
    }
    N -= last.size() - 1;
    int ans = 0;
    rep(i, B) { if (dp[N][i] <= T) { chmax(ans, upper_bound(all(last), T - dp[N][i]) - last.begin() - 1 + i); }}
    cout << ans << endl;
}

