#define norm qwert
int n,T;
vector<pair<long long,long long> > norm;//动态
vector<long long> sta;//静态 
long long a,b;
bool fractal_cmp(pair<long long,long long> x1,pair<long long,long long> y1){
	return ((x1.first*(y1.second+1LL))>((x1.second+1LL)*y1.first));
}
long long dp[40];
long long calc(pair<long long,long long> p1,long long ti){
	return (ti*(p1.first+1LL)+p1.second);
}
int main(){
	ios::sync_with_stdio(0);
	cin.tie(NULL);
	cout.tie(NULL);
	cin>>n>>T;
	for(int i=1;i<=n;i++){
		cin>>a>>b;
		if(a!=0){
			norm.push_back(make_pair(a,b));
		}
		else{
			sta.push_back(b);
		}
	}
	sort(sta.begin(),sta.end());
	sort(norm.begin(),norm.end(),fractal_cmp); 
	memset(dp,63,sizeof(dp));
	dp[0]=0LL;
	for(int i=0;i<norm.size();i++){//背包问题 
		for(int j=32;j>=1;j--){
			if(dp[j-1]>=T)
				continue;
			dp[j]=min(dp[j],dp[j-1]+1LL+calc(norm[i],dp[j-1]));
		}
	}
	int ans=0;
	int lim;
	int cand;
	for(int i=0;i<=32;i++){
		if(dp[i]>=T)
			continue;
		lim=T-dp[i];
		cand=i;
		for(int j=0;j<sta.size();j++){
			if((1+sta[j])<=lim){
				cand++;
				lim-=sta[j];
				lim--;
			}
		}
		ans=max(ans,cand);
	}
