	for (register int x, y, i = 1; i <= n; i++)
	{
		x = read(); y = read();
		if (x != 0) A.push_back(make_pair(x, y));
		    else B.push_back(y + 1);
	}

	for (register int i = 1; i <= Max; i++)
		f[i] = T + 1;
	sort(A.begin(), A.end(), mycmp);
	sort(B.begin(), B.end());
	for (register int i = 1; i < B.size(); i++) B[i] += B[i - 1];	

	f[0] = 0;
	for (register int i = 0; i < A.size(); i++)
		for (register int j = Max; j; j--)
			    f[j] = min(f[j], (f[j - 1] + 1) * (A[i].first + 1) + A[i].second);
	for (register int i = 0	; i <= Max; i++)
		if (f[i] <= T) Ans = max(Ans, i + (B.empty() ? 0 : upper_bound(B.begin(), B.end(), T - f[i]) - B.begin()));
	write(Ans);

	return 0;
}

