int main() {
	ll N, T;
	cin >> N >> T;

	vector<ll> a(N + 1), b(N + 1);
	vector<pair<ll, ll>> p;
	vector<ll> q;

	repn(i, N) {
		cin >> a[i] >> b[i];
		if (a[i] > 0) {
			p.push_back({ a[i] + 1,a[i] + b[i] + 1 });
		}
		else {
			q.push_back(b[i] + 1);
		}
	}

	ll M = p.size();
	sort(p.begin(), p.end(), cmp);
	//rep(i, M) cout << p[i].first <<" "<< p[i].second<< endl;

	vector<vector<ll>> dp(M + 1, vector<ll>(40, T+1));
	rep(i, M+1) dp[i][0] = 0;

	repn(i, M)repn(j, 39) {
		dp[i][j] = min(dp[i - 1][j], p[i - 1].first*dp[i - 1][j - 1] + p[i - 1].second);
		if (dp[i][j] > T) { dp[i][j] = T + 1; }
		//else { cout << i << j << dp[i][j] << endl; }
	}

	ll L = q.size();
	sort(q.begin(), q.end());

	ll ans = 0;

	rep(j, 40) {

		if (dp[M][j] > T) { continue; }

		ll c = 0;
		while (c<L&&dp[M][j] + q[c] <= T) {
			dp[M][j] += q[c];
			c++;
		}


		ans = max(j+c, ans);
	}

	cout << ans;





	system("PAUSE");
}

