#include <iostream>
#include <vector>
#include <algorithm>
using namespace std;
using ll = long long;

const int H = 40;
int dp[H];

struct Shop {
	int a, b;

	bool operator<(const Shop& rhs) const {
		return (ll)a * rhs.b > (ll)rhs.a * b;
	}
};

int main() {
	ios_base::sync_with_stdio(false);
	cin.tie(0);

	// Increment all b_i's by one to account for the time to traverse between stores

	// If we visit stores i and j, and have already spent k time, we spend
	// (a_i k + b_i) + (a_j (a_i k + b_i + k) + b_j)
	// = a_i k + b_i + a_j a_i k + a_j b_i + a_j k + b_j
	// = (a_i k + a_j k + b_i + b_j + a_i a_j k) + a_j b_i

	// So we visit i first if a_j b_i <= a_i b_j
	// that is, a_j / b_j <= a_i / b_i
	// So we visit in decreasing order of a_i / b_i

	int n, t;
	cin >> n >> t;
	++t;

	dp[0] = 1;
	for (int j = 1; j < H; ++j) dp[j] = t + 1;

	vector<ll> offs = {0};
	vector<Shop> shops;
	for (int i = 0; i < n; ++i) {
		int a, b;
		cin >> a >> b;
		++b; // Time to move to next shop
		if (a == 0) offs.push_back(b);
		else shops.push_back({a, b});
	}
	sort(shops.begin(), shops.end());

	for (int i = 0; i < shops.size(); ++i) {
		for (int n = H-2; n >= 0; --n) {
			ll off = (ll)dp[n] * shops[i].a + shops[i].b;
			if (off <= t) dp[n+1] = min((ll)dp[n+1], off);
		}
	}

	sort(offs.begin(), offs.end());
	for (int i = 1; i < offs.size(); ++i) offs[i] += offs[i-1];

	int j = (int)offs.size() - 1;
	int res = 0;
	for (int n = 0; n < H; ++n) {
		while(j >= 0 && dp[n] + offs[j] > t) --j;
		if (j < 0) break;
		res = max(res, n + j);
	}
	cout << res << '\n';
}

