        int a, b;

        scanf("%d %d", &a, &b);

        if (a > 0) {
            v.push_back(make_pair(a, b));
        } else {
            w.push_back(make_pair(a, b));
        }
    }

    sort(v.begin(), v.end(), [](pair <int, int>& p1, pair <int, int>& p2) { return (long long)p2.first * (p1.second + 1) < (long long)p1.first * (p2.second + 1); });
    sort(w.begin(), w.end());

    for (i = 1; i < 50; i++) dp[i] = 1e18;
    dp[0] = 1;

    for (i = 0; i < v.size(); i++) {
        int a = v[i].first;
        int b = v[i].second;

        for (j = 49; j >= 0; j--) {
            long long nt;

            if (dp[j] == 1e18) continue;

            nt = dp[j] + a * dp[j] + b;
            if (nt > t) continue;

            dp[j + 1] = min(dp[j + 1], nt + 1);
