using ll = long long;
using vll = vector<ll>;
using vvll = vector<vector<ll>>;
using P = pair<ll, ll>;

vll dx = {1, 0, -1, 0};
vll dy = {0, 1, 0, -1};

bool comp(const P p1, const P p2){
    return p1.first * (p2.second + 1) > p2.first * (p1.second + 1);
}

bool bcomp(const P p1, const P p2) {
    return p1.second < p2.second;
}

int main(){
	cin.tie(0);
    ios::sync_with_stdio(false);

    ll n, T;
    cin >> n >> T;
    ll a, b;
    vector<P> p(n);
    REP(i, n) {
        cin >> a >> b;
        p[i] = {a, b};
    }
    sort(ALL(p), comp);
    vector<P> q1, q2;
    REP(i, n) {
        if (p[i].first > 0) q1.push_back(p[i]);
        else q2.push_back(p[i]);
    }
    sort(ALL(q2), bcomp);
    n = q1.size();
    ll inf = 1e15;
    ll len = min(35LL, n);
    vvll dp(n + 1, vll(len + 1, inf)); // dp[i][j] : i 番目の店までのうち j コの店を選択したときの最短時間
    REP(i, n + 1) dp[i][0] = 0;
    REP(i, n) {
        REP(j, len) {
            if (j > i) break;
            // i + 1 番目の店を選ばないとき
            dp[i + 1][j] = min(dp[i + 1][j], dp[i][j]);
            // i + 1 番目の店を j + 1 コ目の選択するとき
            // 直前の店まで x --> 移動で x + 1
            // (x + 1) --> a(x + 1) + b
            // total = x + 1 + a(x + 1) + b = (a + 1)(x + 1) + b;
            dp[i + 1][j + 1] = min(dp[i + 1][j + 1], (q1[i].first + 1) * (dp[i][j] + 1) + q1[i].second);
        }
    }
    ll res = 0;
    REP(j, len + 1) {
        ll cnt = dp[n][j], tmp = 0;
        if (cnt > T) break;
        for (auto qq : q2) {
            cnt += 1 + qq.second;
            if (cnt > T) break;
            tmp++;
        }
        res = max(res, j + tmp);
    }
    cout << res << endl;
    return 0;
}

