using namespace std;

typedef long long ll;

const int N = 2e5 + 7;
const int K = 21;

int dp[N][K];

const int Inf = 1e9;

int main() {
  ios_base::sync_with_stdio(false); cin.tie(0);
#ifdef LOCAL
  freopen("input.txt", "r", stdin);
#endif
  int n, t;
  cin >> n >> t;
  vector <int> have;
  vector <int> a, b;
  for (int i = 0; i < n; ++i) {
    int x, y;
    cin >> x >> y;
    if (x == 0) have.push_back(y);
    else {
      a.push_back(x);
      b.push_back(y);
    }
  }
  sort(have.begin(), have.end());
  int m = have.size();
  vector <ll> pref(m + 1);
  for (int i = 0; i < m; ++i) pref[i + 1] = pref[i] + have[i];
  n = a.size();
  vector <int> p(n);
  iota(p.begin(), p.end(), 0);
  sort(p.begin(), p.end(), [&] (int i, int j) {
    return (ll)a[i] * b[j] > (ll)a[j] * b[i];
  });
  for (int i = 0; i <= n; ++i) {
    for (int j = 0; j < K; ++j) {
      dp[i][j] = Inf;
    }
  }
  dp[0][0] = 0;
  for (int i = 0; i < n; ++i) {
    for (int j = 0; j < K; ++j) {
      if (dp[i][j] == Inf) continue;
      dp[i + 1][j] = min(dp[i + 1][j], dp[i][j]);
      int need = min((ll)Inf, dp[i][j] + 1 + (ll)(dp[i][j] + 1) * a[p[i]] + b[p[i]]);
      dp[i + 1][j + 1] = min(dp[i + 1][j + 1], need);
    }
  }
  int ans = 0;
  for (int i = 0; i < K; ++i) {
    if (dp[n][i] > t) continue;
    int hv = t - dp[n][i];
    int l = 0, r = m + 1;
    while (r - l > 1) {
      int mid = (l + r) >> 1;
      if (pref[mid] + mid <= hv) l = mid;
      else r = mid;
    }
    ans = max(ans, i + l);
  }
  cout << ans << '\n';
}

