    cin>>N>>T;
    vector<long long> a(N), b(N);
    for (int i=0; i<N; i++)
        cin>>a[i]>>b[i];

    vector<long long> a0, b0, a1, b1;
    for (int i=0; i<N; i++)
        if (a[i]==0)
            a0.push_back(a[i]),
            b0.push_back(b[i]);
        else
            a1.push_back(a[i]),
            b1.push_back(b[i]);
    int n0 = (int)a0.size();
    int n1 = (int)a1.size();

    sort(b0.begin(), b0.end());

    vector<pair<long long, long long>> ab(n1);
    for (int i=0; i<n1; i++)
        ab[i] = make_pair(b1[i], a1[i]);
    sort(ab.begin(), ab.end(), [&](pair<long long, long long> x, pair<long long, long long> y)
        {return x.first*(y.second+1) < y.first*(x.second+1);});
    for (int i=0; i<n1; i++)
        a1[i] = ab[i].second,
        b1[i] = ab[i].first;

    vector<long long> X(100, T+1);
    X[0] = 0;
    for (int i=0; i<n1; i++)
    {
        for (int j=99; j>0; j--)
            if (X[j-1]<T)
                X[j] = min(X[j], X[j-1]+1+(X[j-1]+1)*a1[i]+b1[i]);
    }

    vector<long long> Y(n0+2);
    Y[0] = 0;
    for (int i=0; i<n0; i++)
        Y[i+1] = min(Y[i]+b0[i]+1, T+1);
    Y[n0+1] = T+1;

    int ans = 0;
    for (int i=0; i<100; i++)
        if (X[i]<=T)
        {
            int n = (int)(upper_bound(Y.begin(), Y.end(), T-X[i]) - Y.begin())-1;
            ans = max(ans, i+n);
        }
    cout<<ans<<endl;
}

