			++time;
			ll opt = INF;
			ll in = 1;
			for (int k=0;k<SZ(V);++k)if (!done[k]){
				pi t = V[k];
				ll c = t.f*time+t.s;
				if (c<opt){
					opt=c;
					in = k;
				}else if (c == opt){
					int t = rand()%2;
					if (t == 1){
						in = k;
					}
				}
			}
			if (opt==INF)break;
			ll c = V[in].f*time+V[in].s;
			done[in] = 1;
			time += c;
			++cnt;
			outs.pb(cnt,time);
		}
