using namespace std;

struct Data {
    int a, b;

    bool operator< (const Data &other) const {
        if(a == 0 && a == other.a)
            return b < other.b;
        return (1LL * a * (other.b + 1) > 1LL * other.a * (b + 1));
    }
};

int main() {
    //freopen("a.in", "r", stdin);
    ios::sync_with_stdio(false);
    cin.tie(0);
    cout.tie(0);

    int n, t;
    cin >> n >> t;
    vector<Data> v(n + 1, {0, 0});
    for(int i = 1; i <= n; i ++)
        cin >> v[i].a >> v[i].b;
    sort(v.begin() + 1, v.end());

    int m = n;
    n = 1;
    while(n <= m && v[n].a != 0)
        n ++;
    n --;

    vector<int> lg(n + 1, 0);
    for(int i = 2; i <= n; i ++)
        lg[i] = 1 + lg[i >> 1];

    int lim = lg[n] + 5;
    vector<vector<ll>> dp(n + 1, vector<ll> (lim + 1, t + 5));
    dp[0][0] = 0;
    for(int i = 1; i <= n; i ++) {
        dp[i][0] = 0;
        for(int j = 1; j <= lim; j ++)
            dp[i][j] = min(dp[i - 1][j], 1LL * (dp[i - 1][j - 1] + 1) * (v[i].a + 1) + 1LL * v[i].b);
    }

    int ans = 0;
    for(int i = 0; i <= lim; i ++) {
        int j = n + 1;
        while(j <= m && dp[n][i] + 1 + v[j].b <= t) {
            dp[n][i] += (1 + v[j].b);
            j ++;
        }
        if(dp[n][i] <= t)
            ans = max(ans, i + j - n - 1);
    }
    cout << ans;

    return 0;
}

