int n,T;
struct Node
{
	int a,b;
}s[N];
long long f[N][M];
int main()
{
	scanf("%d%d",&n,&T);
	for(int i=1;i<=n;i++)
		scanf("%d%d",&s[i].a,&s[i].b);
	sort(s+1,s+n+1,[](const Node &x,const Node &y){return x.a==0&&y.a==0?x.b<y.b:(double)x.a/(x.b+1)>(double)y.a/(y.b+1);});
	memset(f,63,sizeof(f));
	f[0][0]=0;
	int ans=0;
	for(int i=1;i<=n;i++)
		for(int j=0;j<=min(i,20);j++)
		{
			f[i][j]=f[i-1][j];
			if(j>=1) f[i][j]=min(f[i][j],f[i-1][j-1]+(1+1LL*s[i].a*(f[i-1][j-1]+1)+s[i].b));
			if(f[i][j]<=T) ans=max(ans,j);
		}
	printf("%d",ans);
	return 0;
}

