int n, t;
LL sum[N];
struct Pair{
	LL a, b;
	Pair(){}
	Pair(LL a, LL b):a(a),b(b){}
	bool operator < (const Pair &A)const{
		return A.a * (b + 1) + A.b < a * (A.b + 1) + b;
	}
};
vector<Pair> V;
vector<LL> G;

LL dp[N][L];

int main(){
	LL a, b;
	scanf("%d %d", &n, &t);
	for(int i=0; i<n; i++){
		scanf("%lld %lld", &a, &b);
		if(a == 0){
			G.pb(b);
		} else {
			V.pb(Pair(a, b));
		}
	}

	sort(V.begin(), V.end());
	sort(G.begin(), G.end());

	for(int i=0; i<L; i++){
		dp[0][i] = t + 1;
	}
	dp[0][0] = 0;

	int m = V.size();
	for(int i=1; i<=m; i++){
		for(int j=L-1; j>0; j--){
			dp[i][j] = min(dp[i-1][j], (dp[i-1][j-1] + 1) * V[i-1].a + V[i-1].b);
		}
		dp[i][0] = dp[i-1][0];
	}

	sum[0] = 0;
	for(int i=0; i<G.size(); i++){
		sum[i+1] = sum[i] + G[i] + 1;
	}

	n = G.size() + 1;

	int ans = 0;
	for(int i=0; i<L; i++){
		if(dp[m][i] > t)	continue;
		int j = upper_bound(sum, sum+n, t - dp[m][i]) - sum;
		ans = max(ans, j + i - 1);
	}

	printf("%d\n", ans);

	return 0;
}

