typedef long long ll;
typedef long double ld;
int main() {
	int n, T;
	scanf("%d%d", &n, &T);
	vector<int> a0;
	vector<pair<int, int>> P;
	for (int i = 0; i < n; ++i) {
		int a, b;
		scanf("%d%d", &a, &b);
		if (!a) {
			a0.push_back(b + 1);
		} else {
			P.push_back({a + 1, a + b + 1});
		}
	}
	sort(P.begin(), P.end(), [&](pair<int, int> x, pair<int, int> y) {
		return (x.second - 1) * y.first < (y.second - 1) * x.first;
	});
	const ll INF = T + 1;
	vector<ll> dp(32, INF);
	dp[0] = 0;
	for (auto& p : P) {
		auto ndp = dp;
		for (int i = 0; i < 31; ++i) {
			ndp[i + 1] = min(ndp[i + 1], dp[i] * p.first + p.second);
		}
		swap(dp, ndp);
	}
	sort(a0.begin(), a0.end());
	vector<ll> sum(a0.size() + 1);
	for (int i = 0; i < a0.size(); ++i) {
		sum[i + 1] = sum[i] + a0[i];
	}
	int ans = 0;
	for (int i = 0; i <= 31; ++i) {
		if (dp[i] > T) continue;
		int t = upper_bound(sum.begin(), sum.end(), T - dp[i]) - sum.begin() - 1;
		ans = max(ans, i + t);
	}
	printf("%d\n", ans);
}

