template<class T> inline bool chmax(T& a, T b) { if (a < b) { a = b; return 1; } return 0; }
template<class T> inline bool chmin(T& a, T b) { if (a > b) { a = b; return 1; } return 0; }

void solve() {
	int n, t; cin >> n >> t;
    vector<int> a(n), b(n);
    vector<int> zeroshop;
    vector<P> shop(n);
    rep(i, n) {
        cin >> a[i] >> b[i];
        shop[i] = make_pair(a[i], b[i]);
        if(a[i] == 0) zeroshop.pb(b[i] + 1);
    }
    sort(all(shop), [&](P x, P y){ return (x.sc + 1) * y.fr < (y.sc + 1) * x.fr;});
    sort(all(zeroshop));
    static int dp[200200][40];
    rep(i, 200200) {
        rep(j, 40) {
            dp[i][j] = INF;
        }
        dp[i][0] = 0;
    }
    rep(i, n) {
        for(int j = 1; j < 40; ++j) {
            //cerr << shop[i].fr << " " << shop[i].sc << endl;
            chmin(dp[i + 1][j], dp[i][j]);
            if(shop[i].fr != 0 && (shop[i].fr + 1) * (dp[i][j - 1] + 1) + shop[i].sc <= t) chmin(dp[i + 1][j], (shop[i].fr + 1) * (dp[i][j - 1] + 1) + shop[i].sc);
        }
    }
    // vector<int> sum((int)zeroshop.size() + 1, 0);
    // rep(i, (int)zeroshop.size()) {
    //     sum[i + 1] = sum[i] + zeroshop[i];
    // }
    int ans = 0;
    for(int j = 0; j < 40; ++j) {
        if(dp[n][j] > t) continue;
        int cnt = j, ti = dp[n][j], i = 0;
        while(i < (int)zeroshop.size() && ti + zeroshop[i] <= t) {
            ti += zeroshop[i];
            ++ i;
            ++ cnt;
        }
        chmax(ans, cnt);
    }
    cout << ans << endl;
}

