    return false;
}


void solve(long long n, long long t, std::vector<long long> a, std::vector<long long> b){
    for(int i = 0; i < n; ++i)
        ++a[i];
    auto comp = [&](int i, int j){
        i64 x = (b[i] + 1) * a[j] + b[j];
        i64 y = (b[j] + 1) * a[i] + b[i];
        return x < y;
    };
    vector<int> idxes(n);
    iota(idxes.begin(), idxes.end(), 0);
    sort(idxes.begin(), idxes.end(), comp);

    auto aa = a, bb = b;
    int cnt = 0;
    for(int i = 0; i < n; ++i){
        if(aa[idxes[i]] != 1){
            a[cnt] = aa[idxes[i]];
            b[cnt] = bb[idxes[i]];
            ++cnt;
        }
    }
    int border = cnt;
    for(int i = 0; i < n; ++i){
        if(aa[idxes[i]] == 1){
            a[cnt] = aa[idxes[i]];
            b[cnt] = bb[idxes[i]];
            ++cnt;
        }
    }
    assert(n <= 4000);
    vector<vector<i64>> dp(border + 1, vector<i64>(33, INF));
    dp[0][0] = 0;
    for(int i = 0; i < border; ++i){
        for(int j = 0; j <= 32; ++j){
            chmin(dp[i + 1][j], dp[i][j]);
            if(j != 32){
                i64 time = dp[i][j] + 1;
                if(time > t)
                    continue;
                chmin(dp[i + 1][j + 1], a[i] * time + b[i]);
            }
        }
    }
    vector<i64> res = dp.back();
    auto comp2 = [&](int i, int j){
        assert(a[i] == 1);
        assert(a[j] == 1);
        return b[i] < b[j];
    };
    sort(next(idxes.begin(), border), idxes.end(), comp2);
    bb = b, aa = a;
    for(int i = border; i < n; ++i){
        a[i] = aa[idxes[i]];
        b[i] = bb[idxes[i]];
    }
    vector<int> v(1, 0);
    for(int i = border; i < n; ++i)
        v.push_back(v.back() + b[i] + 1);
    int ans = 0;
    for(int i = 0; i <= 32; ++i){
        if(res[i] > t)
            continue;
        auto it = upper_bound(v.begin(), v.end(), t - res[i]);
        int d = distance(v.begin(), it) - 1;
        chmax(ans, i + d);
    }
    cout << ans << endl;

}


