template<class T> inline bool MX(T &l,const T &r){return l<r?l=r,1:0;}
template<class T> inline bool MN(T &l,const T &r){return l>r?l=r,1:0;}

int N;
LL T;
LL A[214514];
LL B[214514];
LL dp[214514][114];
vector<vector<int>> clss;

signed main(){
  ios_base::sync_with_stdio(false);
  cout<<fixed<<setprecision(0);

  cin >> N >> T;

  vector<int> ps, qs;
  rep(i, N) {
    cin >> A[i] >> B[i];
    if (A[i] > 0) ps.eb(i);
    else qs.eb(i);
  }
  sort(all(ps), [](int i, int j) {
    return (B[i]+1)*A[j] < (B[j]+1)*A[i];
  });
  sort(all(qs), [](int i, int j) {
    return B[i] < B[j];
  });

  vector<LL> cuml;
  for (int i : qs) {
    LL t = 0;
    if (!cuml.empty()) t = cuml.back()+1;
    cuml.eb(t+B[i]);
  }
  auto Find = [&cuml](LL t) {
    LL rem = T-t-1;
    auto itr = upper_bound(all(cuml), rem);
    return int(itr - cuml.begin());
  };

  LL INF = 1LL << 60;
  fill(dp[0], dp[ps.size()+1], INF);
  dp[0][0] = 0;
  rep(i, ps.size()) { 
    int idx = ps[i];
    rep(j, 30) {
      MN(dp[i+1][j], dp[i][j]);
    }
    rep(j, 30) {
      LL t = dp[i][j]+1;
      MN(dp[i+1][j+1], dp[i][j] + t*A[idx] + B[idx]);
    }
  }

  int ans = 0;
  rep(j, 30) {
    LL t = dp[ps.size()][j];
    //cout << j << ": " << t << endl;
    if (t > T) continue;
    int cand = j + Find(t);
    MX(ans, cand);
  }
  cout << ans << endl;
}

