void solve() {
	int i = 0, j = 0, k = 0, n = 0, m = 0, T;
	cin >> n >> T;
	vpi x(n);
	fr(i, 0, n) {
		cin >> x[i].fi>>x[i].se;
	}
	sort(all(x), [&](pii a, pii b) {
		int u = a.fi * (b.se + 1);
		int v = b.fi * (a.se + 1);
		if(u != v) {
		        return u > v;
		}
		if(u == 0) {
		        return a.se < b.se;
		}
		return a.fi > b.fi;
	});
      debug("done");
	vi v;
	fr(i, 0, n) {
		for(j = 1; j < MAXLOG; j++) {
			// i = 0
			if(i == 0) {
				dp[i][j] = j == 1 ?  x[0].fi + x[0].se + 1 : INF;
				continue;
			}
			if(x[i].fi == 0) {
				v.pb(1 + x[i].se);
				break;
			}
			dp[i][j] = dp[i - 1][j - 1] + (dp[i - 1][j - 1] + 1) * x[i].fi + x[i].se;
			remin(dp[i][j], dp[i - 1][j]);
			remin(dp[i][j], INF);
		}
	}
      debug("done");
	int ans = 0, s = 0;
	k = sz(v);
	for(i = 0; i < k; i++) {
		s += v[i];
		v[i] = s;
	}
      debug(v);
	for(j = 1; j < MAXLOG; j++) {
		if(dp[n - k - 1][j] <= T) {
			int t = dp[n - k - 1][j], a = j;
			if(k > 0 and v[0] <= T-t) {
				a    += (upper_bound(all(v), T - t) - v.begin());
			}
			remax(ans, a);
		}
	}

	cout << ans << el;
}

