  }
  int cur = 0;
  while (cur < t) {
    int wh = -1, res = 6e18;
    for (int i = 0; i < mx; ++i) {
      if (cnt[i] == 0)
        continue;
      int hm = -l[i].query(cur);
      if (hm < res) {
        wh = i;
        res = hm;
      }
    }
    if (res > t)
      break;
    ++ile;
    int r1 = SQ*wh;
    int r2 = min(n, r1+SQ);
    bool jest = false;
    for (int i = r1; i < r2; ++i)
      if (!rem[i] && a[i]*cur+b[i] == res) {
