int n, T, dp[32];

void Solve() {
    cin >> n >> T; T++;
    vector<pii> a;
    vector<int> v;
    for (int i = 0, x, y; i < n; i++){
        cin >> x >> y;
        if (!x) v.eb(y + 1);
        else a.eb(x + 1, x + y + 1);
    }
    sort(all(a), [] (const pii& x, const pii& y){
        return (x.F - 1) * y.S > (y.F - 1) * x.S;
    });
