    for (int i = 0; i <= 30; i++){
        dp[i] = inf;
    }
    dp[0] = 0;
    for (int i = 0; i < n; i++){
        for (int j = 30; j > 0; j--){
            dp[j] = min(dp[j], dp[j-1] * a[i].F + a[i].S);
        }
    }
    vector<int> pf(v.size() + 1, 0);
    for (int i = 0; i < v.size(); i++){
        pf[i + 1] = pf[i] + v[i];
    }
    int res = 0;
    for (int i = 0; i <= 30; i++){
        if (dp[i] > T) continue;
//        cerr << dp[i] << ' ' << (upper_bound(all(pf), T - dp[i]) - pf.begin()) << endl;
        res = max(res, i - 1 + (upper_bound(all(pf), T - dp[i]) - pf.begin()));
    }
    cout << res;
}

