template<class T> inline bool chmin(T& a, T b) {
    if (a > b) {
        a = b;
        return true;
    }
    return false;
}
template<class T> inline bool chmax(T& a, T b) {
    if (a < b) {
        a = b;
        return true;
    }
    return false;
}

struct Edge {
	ll to, cap, rev;
	Edge(ll _to, ll _cap, ll _rev) {
	to = _to; cap = _cap; rev = _rev;
	}
};
typedef vector<Edge> Edges;
typedef vector<Edges> Graph;

void add_edge(Graph& G, ll from, ll to, ll cap, bool revFlag, ll revCap) {
	G[from].push_back(Edge(to, cap, (ll)G[to].size()));
	if (revFlag)G[to].push_back(Edge(from, revCap, (ll)G[from].size() - 1));
}

void solve(){
	ll n,t;
	cin>>n>>t;

	vector<P> ab;
	Array bb;//a=0
	REP(i,n){
		ll a,b;
		cin>>a>>b;
		b++;
		if(a==0){
			bb.push_back(b);
		}else{
			ab.push_back({a,b});
		}
	}

	//a>0のパターン
	sort(all(ab),[&](P x, P y){
		return y.first*x.second < x.first*y.second;
	});

	ll m=30;
	Matrix dp(ab.size()+1,Array(m+1,INF));//i番目までにj点回る最小時間
	dp[0][0]=0;
	REP(i,ab.size()){
		ll a=ab[i].first;
		ll b=ab[i].second;
		REP(j,m){
			if(dp[i][j]==INF) break;
			if(a*dp[i][j]+b<=t) chmin(dp[i+1][j+1],a*dp[i][j]+b);
			chmin(dp[i+1][j],dp[i][j]);
		}
	}

	//a=0のパターン
	sort(all(bb));
	Array sum(bb.size()+1,0);
	REP(i,bb.size()) sum[i+1]=sum[i]+bb[i];

	ll ans=0;
	REP(i,m+1){
		if(dp[ab.size()][i]==INF) break;
		ll con=i;
		if(bb.size()>0) con += upper_bound(all(sum), t-dp[ab.size()][i]) - sum.begin() -1;
		chmax(ans,con);
	}
	cout<<ans<<en;
}

int main() {
    ios::sync_with_stdio(false);
    cin.tie(0);
    cout.tie(0);

	solve();
    return 0;
}

