class Data
{
public:
    int a, b;
    bool operator<(const Data& other) const
    {
        long long x = other.a * (b + 1LL);
        long long y = a * (other.b + 1LL);
        if(x != y)
            return x < y;
        else
            return b < other.b;
    }
};

const int MAX = 50;

int main()
{
    int n, t;
    cin >> n >> t;
    vector<Data> v(n);
    for(int i=0; i<n; ++i)
        cin >> v[i].a >> v[i].b;
    sort(v.begin(), v.end());

    vector<long long> dp(MAX+1, t+1);
    dp[0] = 0;
    for(int i=0; i<n; ++i){
        if(v[i].a == 0)
            continue;
        for(int j=MAX-1; j>=0; --j){
            long long x = dp[j] + (dp[j] + 1) * v[i].a + v[i].b;
            dp[j+1] = min(dp[j+1], x);
        }
    }

    int ans = 0;
    while(dp[ans+1] <= t)
        ++ ans;
    long long x = dp[ans];
    for(int i=0; i<n; ++i){
        if(v[i].a == 0 && x + v[i].b + 1 <= t){
            x += v[i].b + 1;
            ++ ans;
        }
    }
    cout << ans << endl;

    return 0;
}

