    for (int i = 0; i < n; ++i) {
        if (a[i] > 1) {
            for (int j = 30; j + 1; --j) {
                if (mint[j] * a[i] + b[i] < mint[j + 1]) {
                    mint[j + 1] = mint[j] * a[i] + b[i];
                }
