int DP[200005][65];
void Read(){
    cin >> N >> T;
    for(int i = 1; i <= N; i++){
        cin >> L[i].first >> L[i].second;
        L[i].second += 1 + L[i].first;
    }
}

inline bool cmp(pair <int, int> a, pair <int, int> b){
    if(a.first == b.first)
        return a.second < b.second;
    return a.first > b.first;
}

void Solve(){
    sort(L + 1, L + N + 1, cmp);
    int ans = 0;
    int point = N + 1;
    for(int j = 0; j <= 60; j++){
        for(int i = 0; i <= N; i++)
            DP[i][j] = T + 1;
    }
    DP[0][0] = 0;
    for(int i = 1; i <= N; i++){
        if(L[i].first == 0){
            point = i;
            break;
        }
        DP[i][0] = 0;
        for(int j = 1; j <= 60; j++){
            DP[i][j] = DP[i - 1][j];
            if(DP[i - 1][j - 1] <= T){
                long long aux = DP[i - 1][j - 1] + (1LL * L[i].first * DP[i - 1][j - 1] + L[i].second);
                aux = min(aux, (1LL * (T + 1)));
                DP[i][j] = min(DP[i][j], (int)aux);
            }
        }
    }
    for(int j = 0; j <= 60; j++){
        int val = DP[point - 1][j], cnt = j;
        if(val == T + 1)
            continue;
        for(int k = point; k <= N; k++){
            if(val + L[k].second > T){
                break;
            }
            val += L[k].second;
            cnt++;
        }
        ans = max(ans, cnt);
    }
    cout << ans << '\n';
}


int main()
{
    Read();
    Solve();
    return 0;
}

