        if (last || i == N) break;
        p = q+1;
    }
    return i;
}




int solve(int N, ll T,vi& a,vi& b) {
    using P = pair<double, int>;

    auto intime = [&](ll t) -> bool {
        return (t <= T+1);
    };

    vii ab(N); rep(i,N) ab[i] = ii(a[i]+b[i], i);
    sort(ALL(ab));

    if (!intime((ll)1 + ab[0].first + 1)) return 0;

    vector<P> p; p.reserve(N-1);
    rep(i,N) {
        if (i == ab[0].second) continue;
        p.pb( P((double)a[i] / (b[i]+1), i) );
    }
    sort(ALL(p));

    auto sim = [&](int till) -> bool {
        if (till == 0) return true;

        ll t = 1 + (ab[0].first + 1);
        if (t > T+1) return false;

        --till;
        rep(i,till){
            int ix = p[till-1 -i].second;
            int ai = a[ix], bi = b[ix];
            ll w = ai * t + (bi + 1);
            t += w;
            if (t > T+1) break;
        }
        return (t <= T+1);
    };

    if (sim(N)) return N;

    int lo =0, hi =N;
    while (lo+1 < hi) {
        int mi = (lo+hi)/2;
        if (sim(mi)) {
            lo = mi;
        } else {
            hi = mi;
        }
    }
    return lo;
}

