const int maxn = 2e5+7;
int n;
ll T;
//ll a[maxn];
vector<ll> m, b;


void solve()
{
	cin >> n >> T;
	vector<ll> m(n), b(n);
	vector<ll> consts; //store bs
	vector<int> lines; //store id
	rep(i, 0, n)
	{
		cin >> m[i] >> b[i];
		if(m[i] == 0) consts.pb(b[i]+1);
		else lines.pb(i);
	}
	sort(all(lines), [&](int x, int y)->bool
	{
		return (m[x])*(b[y]+1) > (m[y])*(b[x]+1); //
	});
	//rep(i, 0, lines.size()) cout << lines[i] << " \n"[i==lines.size()-1];
	sort(all(consts));
	//max T = 1000000000
	//max log2T = 30
	const int maxlogT = 30;
	auto f = [&](int pre, int id)->ll
	{
		pre++;
		return pre + m[id]*pre + b[id];
	};
	//dp[i] means the least time required for shop i stores
	vector<ll> dp(maxlogT+5, 1e9+5);
	dp[0] = 0;
	//cout << "T: " << T << endl;
	rep(i, 0, n) repinv(j, 0, maxlogT)
	{
		if(dp[j] < T)
		{
			/*cout << "f : " << i << " " << " " << j << " " << f(dp[j], i) << endl;*/
			dp[j+1] = min(dp[j+1], f(dp[j], i));
		}

	}

	//for(auto x : dp ) cout << x << endl;

	int ans = 0;
	rep(i, 0, maxlogT+1)
	{
		ll curt = dp[i];
		if(curt > T) break; //later is not ok
		int id = 0;
		while(id < consts.size() && curt+consts[id] <= T) curt += consts[id++];
		ans = max(ans, i+id);
	}

	cout << ans << endl;
}


signed main()
{
  fastIO();
  solve();
  return 0;
}

