	sort(rbegin(dat), rend(dat), comp);
	vll A, B;
	vll zs;

	for (int i = 0; i < N; i++) {
		if (dat[i].first > 0) {
			A.push_back(dat[i].first);
			B.push_back(dat[i].second);
		} else {
			zs.push_back(dat[i].second+1);
		}
	}

	sort(begin(zs), end(zs));
	for (int i = 1; i < zs.size(); i++) {
		zs[i] += zs[i-1];
	}

	int n = A.size();
