    sort(ALL(bs));
    long long temp = 0;
    long long ans = 0;
    REP(i, n){
      temp += 1 + bs[i];
      if(temp <= t){
        ans++;
      }else{
        break;
      }
    }
    cout<<ans<<endl;
    return 0;
  }
  if(vi.size() == n){
    sort(ALL(vi), cmp);
    long long temp = 0;
    long long ans = 0;
    REP(j, n){
      int i = vi[j].second;
      temp++;
      temp = a[i] * temp + b[i];
      if(temp <= t){
        ans++;
      }else{
        break;
      }
    }
    cout<<ans<<endl;
    return 0;
  }
  sort(ALL(vi), cmp);
  sort(ALL(bs));
  int gnum = vi.size();
  int znum = bs.size();
  vector<vector<long long>> dp(gnum + 1, vector<long long>(31, INF));
  vector<long long> sbs(znum);
  REP(i, gnum + 1){
    REP(j, 31){
      if(j == 0){
        dp[i][j] = 0;
        continue;
      }
      if(i < j)continue;
      dp[i][j] = dp[i - 1][j];
      int ti = vi[i - 1].second;
      if(dp[i - 1][j - 1] > t)continue;
      long long temp = dp[i - 1][j - 1] + 1 + a[ti] * (dp[i - 1][j - 1] + 1) + b[ti];
      dp[i][j] = min(dp[i][j], temp);
      if(dp[i][j] > t)break;
    }
  }
  REP(i, znum){
    if(i == 0){
      sbs[i] = 1 + bs[i];
    }else{
      sbs[i] = sbs[i - 1] + 1 + bs[i];
    }
  }
  int ans = 0;
  REP(i, gnum + 1){
    REP(j, 31){
      if(dp[i][j] > t)break;
      long long r = t - dp[i][j];
      auto itr = upper_bound(ALL(sbs), r);
      int cnt = distance(sbs.begin(), itr);
      ans = max(ans, j + cnt);
    }
  }
