        rep(j,M) {
            if (dp[i][j] > T) continue;
            chmin(dp[i+1][j+1],A[i].first*(dp[i][j]+1)+A[i].second+dp[i][j]+1);
            chmin(dp[i+1][j],dp[i][j]);
        }
    }
    int ans = 0;
    rep(i,M+1) {
        if (dp[M][i] > T) continue;
        ll t = dp[M][i];
        int cnt = i;
        rep(j,L) {
            if (t+1+B[j].second <= T) {
                cnt++;
                t += B[j].second+1;
            } else break;
        }
        chmax(ans,cnt);
    }

    cout << ans << ln;
}

