void Main() {
	ll N, T; cin >> N >> T;
	vector<tuple<long double, ll, ll>> dat(N);
	for (int i = 0; i < N; i++) {
		ll a, b; cin >> a >> b;
		dat[i] = make_tuple((long double)a / (long double)(b+1), a, b);
	}
	sort(rbegin(dat), rend(dat));
	vll A, B;
	vll zs;
	zs.push_back(0);
	for (int i = 0; i < N; i++) {
		//cout << get<1>(dat[i]) << " " << get<2>(dat[i]) << endl;
		if (get<1>(dat[i]) > 0) {
			A.push_back(get<1>(dat[i]));
			B.push_back(get<2>(dat[i]));
		} else {
			zs.push_back(get<2>(dat[i])+1);
		}
	}

	sort(begin(zs), end(zs));
	for (int i = 1; i < zs.size(); i++) {
		zs[i] += zs[i-1];
	}

	int n = A.size();
	vvll dp(31, vll(n+1, LLINF));
	dp[0][0] = 0;
	int ans = --upper_bound(begin(zs), end(zs), T) - begin(zs);
	for (int c = 0; c < 31; c++) {
		ll minv = LLINF;
		for (int i = 1; i < n+1; i++) {
			chmin(dp[c][i], dp[c][i-1]);
			if (c > 0 && dp[c-1][i-1] <= T) {
				ll val = dp[c-1][i-1] + (dp[c-1][i-1]+1) * A[i-1] + B[i-1];
				if (val <= T) chmin(dp[c][i], val);
			}
			chmin(minv, dp[c][i]);
		}
		if (minv > T) break;
		int num = --upper_bound(begin(zs), end(zs), T - minv) - begin(zs);
		chmax(ans, c + num);
	}
	cout << ans << endl;
}

int main() {
	cin.tie(0);
	ios::sync_with_stdio(0);
	cout << fixed << setprecision(20);
	Main();
	return (0);
}

