		return (int64_t) i.first * j.second + i.second > (int64_t) j.first * i.second + j.second;
	});
	// one
	std::vector<int> adds;
	std::vector<std::pair<int, int > > all;
	for (auto i : a) {
		if (i.first == 1) adds.push_back(i.second);
		else all.push_back(i);
	}
	std::sort(adds.begin(), adds.end());
	std::vector<int64_t> res0(adds.size() + 1);
	for (int i = 0; i < (int) adds.size(); i++) res0[i + 1] = res0[i] + adds[i];
	static int dp[40];
