pair<long, long> a[222222];
long d[222222], e[222222];
int main() {
    int n, T;
    cin >> n >> T;
    for(int i = 0; i < n; i++) {
        int x, y;
        cin >> x >> y;
        a[i] = {x, y};
    }
    sort(a, a + n, [](auto x, auto y) {
        if(y.first * (x.second + 1) == x.first * (y.second + 1))
            return x.second < y.second;
        return y.first * (x.second + 1) < x.first * (y.second + 1);
    });
    int i = 0;
    long t = 0;
    fill(d + 1, d + n + 1, 1e9);
    for(; i < n; i++) {
        if(!a[i].first)
            break;
        for(int j = 0; j < n; j++) {
            if(d[j] >= T)
                break;
            d[j + 1] =
                min(d[j + 1], (a[i].first + 1) * (d[j] + 1) + a[i].second);
        }
    }
    int I = n - i;
    for(i = 0; i < I; i++)
        e[i + 1] = e[i] + a[i + n - I].second + 1;
    int r = 0;
    for(int j = 0; j <= n; j++) {
        if(d[j] > T)
            break;
        int x = upper_bound(e, e + I + 1, T - d[j]) - e;
        r = max(r, j + x);
    }
    cout << r - 1 << endl;
    return 0;
}

