template <class T>
inline bool chmin(T& a, T b) {
  if (a > b) {
    a = b;
    return true;
  }
  return false;
}

int main() {
  ll N, T;
  cin >> N >> T;
  vector<P> ab(N);
  vector<ll> z;
  REP(i, N) {
    ll a, b;
    cin >> a >> b;
    if (a == 0) {
      z.push_back(b);
    }
    ab[i] = make_pair(a, b);
  }
  sort(ALL(z));
  ll M = SZ(z);
  vector<ll> s(M + 1, 0);
  REP(i, M) { s[i + 1] = s[i] + z[i]; }
  sort(ALL(ab), [&](P p1, P p2) {
    return 1.0 * p1.first / (p1.second + 1) > 1.0 * p2.first / (p2.second + 1);
  });
  ll L = 40, INF = 1e18;
  vector<vector<ll>> dp(N - M + 1, vector<ll>(L + 1, INF));
  dp[0][0] = 0;
  REP(i, N - M) {
    REP(j, L) {
      if (dp[i][j] == INF) {
        continue;
      }
      chmin(dp[i + 1][j], dp[i][j]);
      ll nt = (dp[i][j] + 1) * (ab[i].first + 1) + ab[i].second;
      if (nt > T) {
        continue;
      }
      chmin(dp[i + 1][j + 1], nt);
    }
  }
  // REP(i, N - M + 1) {
