  //       DUMP(i);
  //       DUMP(j);
  //       DUMP(dp[i][j]);
  //     }
  //   }
  // }
  ll ans = 0;
  REP(j, L + 1) {
    if (dp[N - M][j] == INF) {
      continue;
    }
    ll cnt = (lower_bound(ALL(s), T - dp[N - M][j]) - s.begin()) + j - 1;
    ans = max(ans, cnt);
  }
  cout << ans << endl;
}

