		for (j = 38; j >= 0; j--) {
			if (D[j] > T)continue;
			D[j + 1] = min(D[j + 1], D[j]+1 + (D[j] + 1)*A[i].a + A[i].b);
		}
	}
	int m = B.size();
	for (i = 1; i <= m; i++) {
		S[i] = S[i - 1] + B[i - 1] + 1;
	}
	int res = 0;
	for (i = 0; i <= m; i++) {
		for (j = 0; j < 40; j++) {
			if (S[i] + D[j] <= T) {
				res = max(res, i + j);
			}
		}
	}
	printf("%d\n", res);
