#define REP(i, n) for (int i = 0; i < (int)(n); i++)
using namespace std;

using ll = long long;

int main() {
  ios::sync_with_stdio(false);
  cin.tie(nullptr);
  int N, T;
  cin >> N >> T;
  vector<pair<ll, ll> > shop(N);
  REP(i, N) {
    int a, b;
    cin >> a >> b;
    shop[i] = make_pair(a, b);
  }

  int ans = 0;
  int time = 0;
  while (true) {
    if (ans == N) break;
    if (shop.empty()) break;
    time++;
    ll end = T;
    ll del = 0;
    for (int i = 0; i < shop.size(); i++) {
      if(end > shop[i].first * time + shop[i].second){
        end = shop[i].first * time + shop[i].second;
        del = i;
      }
    }

    if (time + end > T) break;
    shop.erase(shop.begin() + del);
    time += end;
    ans++;
  }

  cout << ans << endl;
  return 0;
}

