const int maxn=2e5+10;
P a[maxn];
ll dp[maxn][33];
ll pre[maxn];
bool cmp(P p1,P p2)
{
    if(p1.first<p2.first)
        return 1;
    else if(p1.first==p2.first)
    {
        return p1.second>p2.second;
    }
    else
        return 0;
}
int main()
{
    ll N,T;
    cin>>N>>T;
    for(int i=0;i<N;i++)
    {
        cin>>a[i].first>>a[i].second;
    }
    sort(a, a+N,cmp);
    ll ans=0;
    for(int i=0;i<maxn;i++)
        for(int j=0;j<32;j++)
            dp[i][j]=1e9+7;

    ll i=N-1;
    dp[N][0]=0;
    for(;i>=0;i--)
    {
        if(a[i].first==0){
            break;
        }
        dp[i][0]=0;
        for(int j=1;j<32;j++)
        {
            dp[i][j]=min(dp[i+1][j],dp[i+1][j-1]+a[i].first*(dp[i+1][j-1]+1)+a[i].second+1);
            if(dp[i][j]>T)
                dp[i][j]=1e9+7;
        }
    }
    i++;

    sort(a, a+i);

    pre[0]=a[0].second+1;

    for(int j=1;j<i;j++)
    {
        pre[j]=pre[j-1]+a[j].second+1;
    }

    for(int j=0;j<31;j++)
    {
        if(dp[i][j]<=T)
        {
            ans=max(ans,(ll)(j+upper_bound(pre, pre+i, T-dp[i][j])-pre));
        }
    }

    cout<<ans;
}
