using namespace std;
struct mat{
  long a,b;
  mat(){}
  mat(long a_,long b_):a(a_),b(b_){}
};
mat dot(mat m1,mat m2){
  return mat(m1.a*m2.a,m1.a*m2.b+m1.b);
}
bool cmp(mat m1,mat m2){
  return dot(m1,m2).b>dot(m2,m1).b;
}

int main(){
  long N,T;cin>>N>>T;
  vector<long>A(N),B(N);
  for(long i=0;i<N;i++)cin>>A[i]>>B[i];
  vector<long>C;vector<mat>M;
  for(long i=0;i<N;i++){
    if(A[i]==0)C.push_back(B[i]+1);
    else M.push_back(mat(A[i]+1,A[i]+B[i]+1));
  }

  sort(C.begin(),C.end());sort(M.begin(),M.end(),cmp);  
  vector<long>S(C.size()+1,0);
  for(long i=0;i<C.size();i++)S[i+1]=S[i]+C[i];

  //DP準備
    //i個まで見て, j個使う時の経過時間の最小値
  vector<vector<long>>DP(M.size()+1,vector<long>(min(32,(int)M.size()+1),T+1));
  for(long i=0;i<DP.size();i++)DP[i][0]=0; 
  long ans=0;
  for(long i=0;i<DP.size();i++)for(long j=0;j<DP[i].size();j++){  
    if(i!=0&&j!=0)DP[i][j]=min(DP[i-1][j],M[i-1].a*DP[i-1][j-1]+M[i-1].b);
    if(T-DP[i][j]>=0){//Sでbinsearch: S[z]<=T-DP[i][j]となる最大のzを返すと, それが個数
      long l=0,r=C.size()+1;
      while(r-l!=1){
        long z=(l+r)/2;
        if(S[z]<=T-DP[i][j])l=z;
        else r=z;
      }
      ans=max(ans,l+j);
    }
  }
  cout<<ans;
}

