const long long INF = 1000000010;

struct Store
{
    long long a, b;
    Store(long long _a, long long _b):a(_a), b(_b){};
};

int main()
{
    int N, T;
    cin >> N >> T;

    vector<Store> store;
    vector<long long> bs;
    rep(i, 0, N)
    {
        long long a, b;
        cin >> a >> b;

        if (a == 0)
            bs.push_back(b);
        else
            store.push_back(Store(a, b));
    }

    // sort
    sort(store.begin(), store.end(), [](const Store&si, const Store&sj)
    {
        return (si.b+1)*sj.a<(sj.b+1)*si.a;
    });

    // dynamic programming
    int max_num = 30;
    vector<long long> dp(max_num, INF);
    dp[0] = 0;
    rep(i, 0, store.size())
    {
        Store& s = store[i];
        rrep(n, max_num, 1)
            dp[n] = min(dp[n], s.a*(1+dp[n-1])+s.b);
    }

    // take cumulative sum of store with a=0
    sort(bs.begin(), bs.end());
    vector<long long> csum = {0};
    for (long long b: bs)
        csum.push_back(b+csum.back()+1);

    int ans = 0;
    rep(n, 0, max_num)
    {
        // cout << n << ' ' << dp[n] << endl;
        if (dp[n]<=T)
        {
            int num = upper_bound(csum.begin(), csum.end(), T-dp[n]) - csum.begin() - 1;
            ans = max(ans, num+n);
        }
    }
    cout << ans << endl;
    return 0;
}

