	for(int i = 0; i < n; i++){
		int a, b; cin >> a >> b;
		if(a) no.push_back({a, b});
		else {
			can.push_back(b);
		}
	}
	sort(can.begin(), can.end());
	vector<long long> sums;
	int ans = 0;
	long long s = 0;
	for(int i = 0; i < (int)can.size(); i++){
		s++;
		s += can[i];
		sums.push_back(s);
		if(s <= T){
			ans = max(ans, i + 1);
		}
	}
	auto eval = [&](vector<int> ord){
		long long c = 0;
		for(int p : ord){
			c++;
			c = c + no[p].first * c + no[p].second;
		}
		return c;
	};
	int len = no.size();
	vector<int> used(len, 0);
	int m = 0;
	vector<int> done;
	for(int i = 0; i < len; i++){
		m++;
		int option = 1<<30, ch = -1;
		vector<int> ndone;
		for(int j = 0; j < len; j++){
			if(!used[j]){
				for(int k = 0; k <= done.size(); k++){
					vector<int> now = done;
					now.insert(now.begin() + k, j);
					if(eval(now) < option){
						option = eval(now);
						ndone = now;
						ch = j;
					}
				}
			}
		}
		if(option > T) break;
		used[ch] = 1;
		m = option;
		done = ndone;
		int p = lower_bound(sums.begin(), sums.end(), T - m + 1) - sums.begin();
