#define INF (1 << 30) - 1

bool cmp(P p, P q){
  return p.first * (q.second + 1) >= q.first * (p.second + 1);
}

int main(){
  ll n, T;
  cin >> n >> T;

  vector<ll> b;
  vector<P> a_b;
  for(int i = 0; i < n; ++i){
    ll a_, b_;
    cin >> a_ >> b_;
    if(a_ == 0)b.push_back(b_ + 1);
    else a_b.push_back(P(a_, b_));
  }

  sort(a_b.begin(), a_b.end(), cmp);
  sort(b.begin(), b.end());

  vector<ll> dp(33, INF);
  dp[0] = 0;
  for(auto p : a_b){
    ll a = p.first;
    ll b = p.second;
    for(int i = 32; i > 0; --i){
      if(dp[i - 1] > T)continue;
      dp[i] = min(dp[i], (a + 1) * dp[i - 1] + a + b + 1);
    }
  }

  ll count = 0;
  for(int i = 32; i >= 0; --i){
    ll cur = dp[i];
    if(cur > T)continue;
    ll tmp_count = i;
    for(int j = 0; j < b.size(); ++j){
      if(cur + b[j] > T)break;
      cur += b[j];
      ++tmp_count;
    }
    if(count < tmp_count){
      count = tmp_count;
    }
  }

  cout << count << endl;

  return 0;
}

