	vector<pair<int,int>> no;
	vector<int> can;
	for(int i = 0; i < n; i++){
		int a, b; cin >> a >> b;
		if(a) no.push_back({a, b});
		else {
			can.push_back(b);
		}
	}
	sort(can.begin(), can.end());
	vector<long long> sums;
	int ans = 0;
	long long s = 0;
	for(int i = 0; i < (int)can.size(); i++){
		s++;
		s += can[i];
		sums.push_back(s);
		if(s <= T){
			ans = max(ans, i + 1);
		}
	}
