		long long c = 0;
		for(int p : ord){
			c++;
			c = c + no[p].first * c + no[p].second;
			if(c > stp) break;
		}
		return c;
	};
	int len = no.size();
	vector<int> used(len, 0);
	int m = 0;
	vector<int> done;
	for(int i = 0; i < len; i++){
		m++;
		int option = 1<<30, ch = -1;
		vector<int> ndone;
		for(int j = 0; j < len; j++){
			if(!used[j]){
				for(int k = 0; k <= done.size(); k++){
					vector<int> now = done;
					now.insert(now.begin() + k, j);
					long long v = eval(now, option);
					if(v < option){
						option = v;
						ndone = now;
						ch = j;
					}
				}
			}
		}
		if(option > T) break;
		used[ch] = 1;
		m = option;
		done = ndone;
		int p = lower_bound(sums.begin(), sums.end(), T - m + 1) - sums.begin();
