template<typename T>
class CHT{
    typedef pair<T, T> Pair;

private:
    vector<Pair> lines;
    bool isMonotonicX;
    function<bool(T l, T r)> comp;

public:
    CHT(bool flagX=false, function<bool(T l, T r)> compFunc=greater<T>())
        :isMonotonicX(flagX), comp(compFunc){
    }

    bool check(Pair l1, Pair l2, Pair l3){
        if(l1 < l3) swap(l1, l3);
        return (l3.second - l2.second) * (l2.first - l1.first) >= (l2.second - l1.second) * (l3.first - l2.first);
    }

    void add(T a, T b){
        Pair line(a, b);
        while(lines.size() >= 2 && check(*(lines.end()-2), lines.back(), line)){
            lines.pop_back();
        }
        lines.emplace_back(line);
    }

    T f(int i, T x){
        return lines[i].first*x + lines[i].second;
    }

    T f(Pair line, T x){
        return line.first*x + line.second;
    }

    T get(T x){
        if(isMonotonicX){
            static int head = 0;
            while(lines.size()-head>=2 && comp(f(head, x), f(head+1, x))){
                head++;
            }
            return f(head, x);
        }else{
            int low = -1, high = lines.size()-1;
            while(high-low>1){
                int mid = (high+low)/2;
                (comp(f(mid, x), f(mid+1, x)) ? low : high) = mid;
            }
            return f(high, x);
        }
    }
};

