signed main(){
	int n,t;
	cin>>n>>t;
	vector<int> a(n), b(n),c(n),d(n);
	for(int i=0;i<n;i++){
		cin>>a[i]>>b[i];
		c[i] = a[i] + 1;
		d[i] = a[i] + b[i] + 1;
	}
	vector< pair<int,int> > s;
	vector<int> si;
	for(int i=0;i<n;i++){
		if( c[i] > 1 ) s.pb( mp (c[i], d[i] ) );
		else si.pb(d[i]);
	}
	sort( s.begin(), s.end() );
	sort( si.begin(), si.end() );
	dp[0] = t;
	int good = 0;
	for(int i=0;i<si.size();i++){
		dp[i+1] = dp[i] - si[i];
		if( dp[i+1] > 0 ) good = i+1;
	}
	int start = max( 0LL, good - 31 );
	int ans = 0;
	for(int i = start; i <= good ; i++ ){
		int cnt = i;
		for(int j=0;j<s.size();j++){
			used[j] = 0;
		}
		int cur = dp[i];
		while( cur > 0 ){
			int ma = -1;
			int g = -1;
			for(int j=0;j<s.size();j++){
				if( used[j] == 0 && cur >= s[i].second && ( cur - s[i].second  ) / s[i].first > ma ){
					ma = ( cur - s[i].second ) / s[i].first;
					g = j;
				}
			}
			if( g != -1 ){
				cnt++;
				cur = ( cur - s[i].second ) / s[i].first ;
				used[ g ] = 1;
			}
			if( g == -1 )break;
		}
		if( cnt > ans ) ans = cnt;
	}
	cout<<ans<<endl;
	return 0;
}

