#include <bits/stdc++.h>
using namespace std;
#define MAXN 200002

struct Node {
    int a, b;
    Node () {}
    Node (int x, int y) {a = x, b = y; }
} s[MAXN];

int n, t, ans = 0, B[MAXN];
int dp[33] = {0};
int cnt = 0, pf = 0;

bool cmp (Node x, Node y) {
    return x.a * (y.b + 1) > y.a * (x.b + 1);
}

int main () {
    cin >> n >> t;
    memset (dp, 0x3f, sizeof (dp)); // max_int
    for (int i = 1; i <= n; i ++) {
        int a, b; cin >> a >> b;
        if (a == 0) B[++ cnt] = b;
        else s[++ pf] = Node (a, b);
    }
    sort (B + 1, B + cnt + 1);
    sort (s + 1, s + pf + 1, cmp);

    int k = (int) (log2 (t));

    dp[0] = 0, dp[1] = 1 + s[1].a + s[1].b;

    for (int i = 2; i <= pf; i ++) 
        for (int j = min (k, i); j >= 2; j --)
            dp[j] = min (dp[j], s[i].a * (dp[j - 1] + 1) + s[i].b);

    int tmp = min (k, pf);
    while (tmp >= 1 && dp[tmp] > t) tmp --;
    ans = tmp;

    int rem = dp[tmp] + 1, i = 1;
    while (i <= cnt && rem + B[i] <= t ) 
        ans ++, rem += B[i] + 1;

    cout << ans;

    return 0;
}

