#include<bits/stdc++.h>
using namespace std;

typedef long long LL;

const int N=200000,C=40;
const LL INF=(1LL<<30)-1;

int n,m;
struct thing{
  int x,y;
}a[N+9];

bool cmp(const thing &a,const thing &b){return (LL)b.y*(a.x-1)>(LL)b.x*(a.y-1);}

void into(){
  scanf("%d%d",&n,&m);
  for (int i=1;i<=n;++i){
	scanf("%d%d",&a[i].x,&a[i].y);
	a[i].y+=++a[i].x;
  }
}

LL dp[N+9][C+9];
int ans;

void Get_dp(){
  sort(a+1,a+n+1,cmp);
  for (int i=0;i<C;++i) dp[0][i]=m+1;
  dp[0][0]=0;
  int i=1;
  for (;i<=n;++i){
    if (a[i].x==1) break;
	for (int j=0;j<C;++j) dp[i][j]=min(dp[i-1][j],j?a[i].x*dp[i-1][j-1]+a[i].y:(LL)m+1);
  }
  for (int j=0;j<C;++j){
	LL t=dp[i-1][j];
	if (t>m) continue;
	ans=max(ans,j);
	for (int k=i;k<=n;++k)
	  if ((t=a[k].x*t+a[k].y)>m||k==n) ans=max(ans,j+k-i+(t<=m&&k==n));
  }
}

void work(){
  Get_dp();
}

void outo(){
  printf("%d\n",ans);
}

int main(){
  into();
  work();
  outo();
  return 0;
}

