struct Point {
	long long a, b;
};

bool operator<(const Point& a1, const Point& a2) {
	if ((a1.b + 1LL) * a2.a < (a2.b + 1LL) * a1.a) return true;
	return false;
}

bool operator==(const Point& a1, const Point& a2) {
	if ((a1.b + 1LL) * a2.a == (a2.b + 1LL) * a1.a) return true;
	return false;
}

long long N, T;
long long A[1 << 18], B[1 << 18];
long long dp[1 << 18][44];
vector<Point> L;
vector<long long> L2;

int main() {
	cin >> N >> T;
	for (int i = 1; i <= N; i++) {
		cin >> A[i] >> B[i];
		if (A[i] != 0) L.push_back(Point{ A[i], B[i] });
		if (A[i] == 0) L2.push_back(B[i]);
	}
	sort(L.begin(), L.end());
	sort(L2.begin(), L2.end());

	for (int i = 0; i <= N; i++) {
		for (int j = 0; j <= 40; j++) dp[i][j] = (1LL << 60);
	}
	dp[0][0] = 0;
	for (int i = 1; i <= L.size(); i++) {
		for (int j = 0; j <= 40; j++) {
			if (dp[i - 1][j] > T) continue;
			dp[i][j] = min(dp[i][j], dp[i - 1][j]);
			long long V = dp[i - 1][j] + 1LL;
			long long S = V * L[i - 1].a + L[i - 1].b;
			dp[i][j + 1] = min(dp[i][j + 1], V + S);
		}
	}

	long long Answer = 0;
	for (int i = 0; i <= 40; i++) {
		if (dp[L.size()][i] > T) continue;
		long long R = dp[L.size()][i], cnt = i;
		for (int j = 0; j < L2.size(); j++) {
			if (R + L2[j] + 1LL <= T) { cnt++; R += L2[j] + 1LL; }
		}
		Answer = max(Answer, cnt);
	}
	cout << Answer << endl;
	return 0;
}

