void solve(){
  ini(N , T);
  vp v(N); in(v);

  vp vv , vvv;
  each(x , v){
    if(x.first==0) vv.pb(x);
    else vvv.pb(x);
  }
  swap(vvv , v);
  sort(all(v) , [&](P i, P j){
    return j.fi*(i.se+1) < i.fi*(j.se+1);
  });

  // 0のもの
  sort(all(vv));
  vl rui(sz(vv) + 1);
  rep(i , sz(vv)){
    rui[i + 1] = rui[i] + vv[i].second + 1;
  }
  // rui i個買うのに何分かかる
  auto f = [&](ll t) ->ll{
    return (upper_bound(all(rui) , t) - rui.begin() ) - 1;
  };

  trc(v);
  ll ans = 0;
  vl dp(32 , inf) , nxt(32 , inf);
  dp[0] = 0;
  rep(i , sz(v)){
    fill(all(nxt) , inf);
    rep(j , sz(dp)){
      if(dp[j] == inf) continue;
      trc(i , j , dp[j]);
      amin(nxt[j] , dp[j]);
      ll nya = (dp[j] + 1) * (v[i].fi + 1) + v[i].se;
      if(nya > T) continue;
      else {
        amin(nxt[j + 1] , nya);
        amax(ans , j + 1 + f(T - nya));
      }
    }
    swap(dp , nxt);
  }

  out(ans);





}

