  inf=f[0][0]; f[0][0]=0;
  for (ii=0; ii<n; ii++, mx=nxt) {
    ip=ii&1; ic=1-ip; i=k[ii];
    memset(f[ic],120,sizeof(f[ic]));
    nxt=mx;
    for (j=0; j<=mx; j++) if (f[ip][j]<inf) {
      if (f[ip][j]<f[ic][j]) f[ic][j]=f[ip][j];
      cur=(f[ip][j]+1LL)*(a[i]+1LL)+b[i];
      if (cur<=m && cur<f[ic][j+1]) {
        f[ic][j+1]=cur;
        nxt=max(nxt,j+1);
      }
    }
  }
  printf("%d\n",mx);
  return 0;
}

