	return a[i] * ll(b[j]+1) > a[j] * ll(b[i]+1);
}

bool order1(int i, int j) {
	return b[i] < b[j];
}

int main() {
	ios::sync_with_stdio(0), cin.tie(0);
	cin >> n >> T;
	a.resize(n), b.resize(n);
	for (int i = 0; i < n; i++) {
		cin >> a[i] >> b[i];
	}
	vector<int> store0, store1;
	for (int i = 0; i < n; i++) {
		if (a[i] >= 1) {
			store0.push_back(i);
		} else {
			store1.push_back(i);
		}
	}
	sort(store0.begin(), store0.end(), order0);
	sort(store1.begin(), store1.end(), order1);
	const int M = 45;
	vector<int> dp(M, T+1);
	dp[0] = 0;
	vector<int> newdp(M);
	for (int _ = 0; _ < int(store0.size()); _++) {
		int i = store0[_];
		fill(newdp.begin(), newdp.end(), T+1);
		for (int j = 0; j < M; j++) {
			if (dp[j] == T+1) continue;
			newdp[j] = min(newdp[j], dp[j]);
			// dp[j] + dp[j] * a + b + 1 < dp[j+1]
			// dp[j+1] - dp[j] - b - 1 > dp[j] * a
			if ((newdp[j+1] - dp[j] - b[i] - 1) / a[i] > dp[j]) {
				assert(dp[j] + dp[j] * a[i] + b[i] + 1 < newdp[j+1]);
				newdp[j+1] = dp[j] + dp[j] * a[i] + b[i] + 1;
			}
		}
		swap(dp, newdp);
	}
	int ans = 0;
	for (int j = 0; j < M; j++) {
		if (dp[j] == T+1) continue;
		int cnd = j;
		int cur = dp[j];
		for (int _ = 0; _ < int(store1.size()); _++) {
			int i = store1[_];
			assert(a[i] == 0);
			if (cur + b[i] + 1 <= T) {
				cnd++;
				cur += b[i] + 1;
			} else {
				break;
			}
		}
		ans = max(ans, cnd);
	}
	cout << ans << '\n';
}

