	sort(p+1,p+n+1,cmp);
	vector<int>got;
	for(int i=1;i<50;i++)dp[i]=inf;
	dp[0]=0;
	for(int i=1;i<=n;i++){
		if(p[i].first==0){
			got.push_back(p[i].second+1);
		}else{ 
			update(p[i].first,p[i].second);
		}
	}
	sort(got.begin(),got.end());
	for(int i=1;i<got.size();i++)got[i]+=got[i-1];
	int ans=0;
	for(int i=0;i<50;i++){
//		cerr<<i<<" "<<dp[i]<<endl;
		if(dp[i]<=T)ans=max(ans,i+(upper_bound(got.begin(),got.end(),T-dp[i])-got.begin()));
	}
	if(dp[49]<inf)while(1);
	cout<<ans<<endl;
	return 0;
}

