int n, cnt1 = 0, cnt2 = 0;
long long a[N], b[N], f[N][M + 1], t;

struct node {
	long long A;
	long long B;
	bool operator < (node rhs) const {
		double val1 = (1.0 * A - 1.0) / B;
		double val2 = (1.0 * rhs.A - 1.0) / rhs.B;
		return val1 >= val2;
	}
} vec[N];

long long num[N], pre[N];

int main () {
	read(n), read(t);
	for (int i = 1; i <= n; i++) {
		read(a[i]), read(b[i]);
		if (a[i]) {
			node x = {a[i] + 1, b[i] + 1};
			vec[++cnt1] = x;
		}
		else num[++cnt2] = b[i] + 1;
	}

	sort(vec + 1, vec + cnt1 + 1);
	sort(num + 1, num + cnt2 + 1);

	pre[0] = 0ll;
	for (int i = 1; i <= cnt2; i++) pre[i] = pre[i - 1] + num[i];

	for (int i = 0; i <= M; i++) f[0][i] = t + 1;
	f[0][0] = 0ll;

	for (int i = 1; i <= cnt1; i++) {
		for (int j = 0; j <= M; j++) {
			f[i][j] = f[i - 1][j];
			if (j) f[i][j] = min(f[i][j], vec[i].A * f[i - 1][j - 1] + vec[i].B);
		}
	}

	int ans = 0;
	for (int i = 0; i <= M; i++) {
		if (f[cnt1][i] > t) continue;
		int pos = lower_bound(pre, pre + cnt2 + 1, t + 1 - f[cnt1][i]) - pre - 1;
		ans = max(ans, pos + i);
	}
	write(ans), putchar('\n');
	return 0;
}

