typedef long long ll;
const ll MOD = 1e9 + 7;
const long double EPS = 1e-8;

void solve(long long N, long long T, std::vector<long long> a, std::vector<long long> b){
    // (x+1) + (a1(x+1) + b1) + 1 + ((x+1) + (a1(x+1) + b1) + 1) * a2 + b2 <= ...
    // <=> x + 1 + a1x + a1 + b1 + 1 + a2x + a2 + a1a2x + a1a2 + b1a2 + a2 + b2 <= ...
    // <=> (1 + a1 + a2 + a1a2)x + (1 + a1 + b1 + 1 + a2 + a1a2 + b1a2 + a2 + b2) <= ...
    // <=> a2 + b1a2 <= a1 + b2a1
    // <=> a2(b1+1) <= a1(b2+1)
    // <=> a2/(b2+1) <= a1/(b1+1)
    vector<pair<double, pair<int,int>>> tmp(N);
    rep(i,0,N) tmp[i] = {(double)(a[i]) / (double)(b[i]+1), {a[i],b[i]}};
    sort(all(tmp), [&](const pair<double, pair<int,int>> & p, const pair<double, pair<int,int>> & q){
        return p.first > q.first || (p.first == q.first && p.second.second <= q.second.second);
    });
    rep(i,0,N) {
        a[i] = tmp[i].second.first;
        b[i] = tmp[i].second.second;
    }
    vector<vector<ll>> dp(N+1, vector<ll>(31, T+1)); // minimum time (until ith market, visit j markets)
    rep(i,0,N+1) dp[i][0] = 0;
    auto processTime = [&] (const int i, ll t) -> ll {
        t++;
        t += t * a[i] + b[i];
        return t;
    };
    int tail = N;
    rep(i,0,N) {
        if (a[i] == 0) {
            tail = i;
            break;
        }
        rep(j,1,31) {
            dp[i+1][j] = min(dp[i][j], processTime(i, dp[i][j-1]));
            if (dp[i+1][j] > T) break;
        }
    }
    int answer = 0;
    rep(i,0,31) {
        int cnt = i;
        ll t = dp[tail][i];
        if (t > T) break;
        rep(j,tail,N) {
            if (processTime(j, t) <= T) {
                t = processTime(j, t);
                cnt++;
            } else {
                break;
            }
        }
        answer = max(answer, cnt);
    }
    cout << answer << endl;
}

