  void solve() {
    for (int i = 0; i < n; ++i) {
      cin >> a[i] >> b[i];
    }
    vector<int> perm, perm0;
    for (int i = 0; i < n; ++i) {
      if (a[i] == 0)
        perm0.push_back(i);
      else
        perm.push_back(i);
    }
    sort(perm.begin(), perm.end(), [&](int x, int y) -> bool { return a[y] * (b[x] + 1) < a[x] * (b[y] + 1); });
    sort(perm0.begin(), perm0.end(), [&](int x, int y) -> bool { return b[x] < b[y]; });
    vector<LL> dp(50, T + 1);
    dp[0] = 0;
    for (auto i : perm) {
      for (int j = 50 - 1; j >= 1; --j) {
        dp[j] = min(dp[j], (a[i] + 1) * (dp[j - 1] + 1) + b[i]);
      }
    }
    DBG(dp)
