      a0.push_back({a, b});
    else
      AB.push_back({a, b});
  }
  sort(ALL(AB), [](const P&i, const P& j) {
    return i.second*j.first + j.first + j.second <
           j.second*i.first + i.first + i.second;
  });

  REP(i, MAX_N) REP(j, 33) dp[i][j] = T+1;
  dp[0][0] = 0;

  REP(i, AB.size()) {
