    for (int j = 0; j < 32; j++) {
      if (dp[i][j] < T+1) {
        chmin(dp[i+1][j], dp[i][j]);
        chmin(dp[i+1][j+1], (dp[i][j]+1) * (ai+1) + bi);
      }
