}

void solve() {

    int n; ll T;
    scanf("%d %lld", &n, &T);
    int cnt1 = 0, cnt2 = 0;
    rep(i, 1, n) {
      ll x , y ;
        scanf("%lld %lld", &x, &y);
        if(x == 0) c[++ cnt2] = y + 1;
