const int32_t INF = 1e9 + 1;

struct Shop {
	int32_t a, b;

	Shop() {}
	Shop(int32_t _a, int32_t _b) : a(_a), b(_b) {}

	bool operator< (const Shop &o) const {
		double p = (double) a / (b + 1);
		double q = (double) o.a / (o.b + 1);

		return p > q;
	}
};

int main() {
	std::ios_base::sync_with_stdio(false);
	std::cin.tie(nullptr);

	int32_t n, t;
	std::cin >> n >> t;

	std::vector< int32_t > x;
	std::vector< Shop > y;
	for(int32_t i = 0; i < n; i++) {
		int32_t a, b;
		std::cin >> a >> b;

		if(a == 0) {
			x.push_back(b + 1);
		}
		else {
			y.push_back(Shop(a, b));
		}
	}

	std::sort(x.begin(), x.end());
	std::sort(y.begin(), y.end());

	std::vector< int64_t > prefSums(x.size());
	for(int32_t i = 0; i < x.size(); i++) {
		prefSums[i] = x[i];

		if(i != 0) {
			prefSums[i] += prefSums[i - 1];
		}
	}

	int32_t ans = 0;
	for(int32_t i = 0; i < x.size(); i++) {
		if(prefSums[i] > t) {
			ans = i;
			break;
		}
	}

	if(y.size() == 0) {
		std::cout << ans << '\n';
		return 0;
	}

	int32_t logT = 1;
	while(((int64_t) 1 << logT) < t) {
		logT++;
	}

	std::vector< std::vector< int64_t > > dp(n, std::vector< int64_t >(logT + 1, t + 1));
	dp[0][0] = 0;
	dp[0][1] = y[0].b + 1;
	for(int32_t i = 1; i < y.size(); i++) {
		dp[i][0] = 0;
		for(int32_t j = 1; j <= std::min(i + 1, logT); j++) {
			dp[i][j] = std::min(dp[i][j], (int64_t) dp[i - 1][j - 1] + (int64_t) (dp[i - 1][j - 1] + 1) * y[i].a + y[i].b);
			dp[i][j] = std::min(dp[i][j], dp[i - 1][j]);
		}
	}

	for(int32_t i = 1; i <= std::min((int32_t) y.size(), logT); i++) {
		int64_t currMin = t + 1;
		for(int32_t j = i - 1; j < y.size(); j++) {
			currMin = std::min(currMin, dp[j][i]);
		}

		if(currMin > t) {
			continue;
		}

		int32_t low = 0, high = x.size() - 1;
		while(low <= high) {
			int32_t mid = (low + high) / 2;

			if(prefSums[mid] <= t - currMin) {
				low = mid + 1;
			}
			else {
				high = mid - 1;
			}
		}

		ans = std::max(ans, i + low);
	}

	std::cout << ans << '\n';
}

