    for(read(n, t); n; n--) {
        long long a, b;
        read(a, b);
        num.insert(a);
        minn[a].push(b);
    }
    for (long long tim = 1; tim <= t; tim++) {
        long long id, qtim = INF;
        for (const long long it : num) {
            long long tmp = minn[it].top();
            if (tim * it + tmp < qtim) {
                id = it;
                qtim = tim * it + tmp;
            } 
        }
        if (tim + qtim > t) break;
        ans++; tim += qtim;
        minn[id].pop();
        if (minn[id].empty()) num.erase(id);
    }
    printf("%d\n", ans);
    return 0;
}

