ll mul(ll a, ll b) {
  if (a == 0 || b == 0) {
    return 0;
  }
  ll p = a * b;
  if (p % a == 0 && p / a == b && p <= inf) {
    return p;
  } else {
    return inf;
  }
}

ll add(ll a, ll b) {
  return min(inf, a + b);
}

struct T {
