        }
    }
    sort(v.begin(),v.end());
    sort(a+1,a+tot+1,cmp);
    for(int i=0;i<=tot;i++)
        for(int j=0;j<40;j++) 
            dp[i][j]=INF;
    dp[0][0]=0;
    for(int i=0;i<tot;i++)
