template<typename T1, typename T2>
inline bool chmax(T1 &a, T2 b) { return a < b && (a = b, true); }
template<typename T1, typename T2>
inline bool chmin(T1 &a, T2 b) { return a > b && (a = b, true); }

int modpow(int a, long long n, int mod = MOD) {
  int ret = 1;
  do {
    if (n & 1) ret = 1LL * ret * a % mod;
    a = 1LL * a * a % mod;
  } while (n >>= 1);
  return ret;
}

template<typename T>
T GCD(T a, T b) { return b ? GCD(b, a%b) : a; }
template<typename T>
T LCM(T a, T b) { return a / GCD(a, b) * b; }

template<typename T1, typename T2>
bool CompareBySecond(pair<T1, T2> a, pair<T1, T2> b) {
  return a.second != b.second ? a.second < b.second : a.first < b.first;
}
template<typename T>
bool CompareBySlope(pair<T, T> a, pair<T, T> b) {
// counterclockwise from 12 o'clock direction
  if (a.first * b.first < 0) return a.first < b.first;
  if (a.first == 0) return a.second >= 0 || b.first > 0;
  if (b.first == 0) return b.second < 0 && a.first < 0;
  return a.second * b.first < a.first * b.second;
}


/* -------- <templates end> -------- */


bool mycomp(pii a, pii b) {
  return a.first * (b.second + 1) < b.first * (a.second + 1);
}

void solve() {
  int n, t; cin >> n >> t;
  vector<pii> arr(n);
  rep(i,n) cin >> arr[i];
  sort(RALL(arr), mycomp);

  Graph<int> dp(32, vi(n+1, t+1));
  dp[0] = vi(n+1, 0);
  int zero = n;
  rep(i,n) {
    if (arr[i].first == 0) {
      zero = i;
      break;
    }
    for (int j=1; j<dp.size(); ++j) {
      chmin(dp[j][i+1], min(dp[j][i], dp[j-1][i] * (arr[i].first + 1) + (arr[i].second + 1)));
    }
  }

  vi nowait(n-zero);
  rep(i,nowait.size()) nowait[i] = arr[i+zero].second + 1;
  sort(ALL(nowait));
  rep(i,nowait.size()-1) nowait[i+1] += nowait[i];

  int ans = 0;
  rep(i,dp.size()) {
    if (dp[i][zero] > t) break;
    int cnt = upper_bound(ALL(nowait), t - dp[i][zero]) - nowait.begin();
    chmax(ans, i + cnt);
  }
  cout << ans << endl;
}


/* -------- <programs end> -------- */


signed main() {
  cin.tie(nullptr);
  ios::sync_with_stdio(false);
  cout << fixed << setprecision(12);
  solve();
  return 0;
}

