class Solve {
public:
    void solve() {
        Int N, T;
        cin >> N >> T;
        vector<Int> a(N), b(N);
        for (int i = 0; i < N; ++i) {
            cin >> a[i] >> b[i];
        }

        vector<pair<Int, Int>> ab; // a > 0
        vector<Int> c; // a == 0
        for (int i = 0; i < N; ++i) {
            if (a[i] > 0) ab.emplace_back(a[i], b[i]);
            else c.push_back(b[i]);
        }

        sort(all(ab), [](auto l, auto r) {
            Int ai = l.first;
            Int bi = l.second;
            Int aj = r.first;
            Int bj = r.second;
            return aj * (1 + bi) < ai * (1 + bj);
        });

        Int n = ab.size();
        vector<vector<Int>> dp(n + 1, vector<Int>(31, INFl));
        dp[0][0] = 0;
        for (int i = 0; i < n; ++i) {
            for (int j = 0; j < dp[i].size(); ++j) {
                if (dp[i][j] != INFl) {
                    Int t = dp[i][j];
//                    for (int k = 0; k < dp[i].size(); ++k) {
//                    }
                    {
                        // use
                        Int nt = t + 1 + ab[i].first * (t + 1) + ab[i].second;
                        if (nt <= T) {
                            chmin(dp[i + 1][j + 1], nt);
                        }
                    }

                    {
                        // not use
                        chmin(dp[i + 1][j], dp[i][j]);
                    }
                }
            }
        }

        sort(all(c));
        vector<Int> sc(c.size());
        if (sc.size())sc[0] = c[0];
        for (int i = 1; i < c.size(); ++i) {
            sc[i] = sc[i - 1] + c[i];
        }

        Int ans = 0;
        for (int i = 0; i < dp[0].size(); ++i) {
            if (dp[n][i] <= T) {
                Int left = i;
                Int right = upper_bound(all(sc), dp[n][i]) - sc.begin();
                Int tmp = left + right;
                chmax(ans, tmp);
            }
        }
        cout << ans << endl;
    }
};


