// dp[i][j] := i個目の店まで見ていて, 尚且つその時点でj個の店に入ったときの時間の最小値
ll dp[200200][33];

ll N, T;
vector<shop> shops;

signed main() {

    cin >> N >> T;

    vector<ll> a_is_0;

    REP(i, N) {
        ll A, B;
        cin >> A >> B;
        ++B;
        if (A == 0) {
            a_is_0.emplace_back(B);
        } else {
            shops.emplace_back(A, B);
        }
    }

    sort(a_is_0.begin(), a_is_0.end());
    sort(shops.begin(), shops.end(), [](shop s, shop t){
        return s.A * (t.B + 1) > t.A * (s.B + 1);
    });

    REP(i, 200200) REP(j, 33) dp[i][j] = 1LL << 60;
    dp[0][0] = 0;

    int sz = shops.size();
    REP(i, sz) {
        REP(j, 30) {
            chmin(dp[i + 1][j], dp[i][j]);
            ll tm = shops[i].A * (dp[i][j] + 1) + shops[i].B;
            if (tm <= T) chmin(dp[i + 1][j + 1], tm);
        }
    }

    int res = 0, a_sz = a_is_0.size();
    REP(j, 30) {
        int idx = 0, cnt = j;
        ll tm = dp[sz][j];
        if (tm > T) continue;
        while (tm <= T and idx < a_sz) {
            ll nw = tm + a_is_0[idx];
            if (nw > T) break;
            tm = T;
            ++cnt;
            ++idx;
        }
        chmax(res, cnt);
    }

    cout << res << endl;

}

