void shop(bool visited[], int a[], int b[], int t, int t_max, int n, int shopcount, int &shopcount_max){
    int i;
    if(shopcount > shopcount_max) shopcount_max = shopcount;
    for(i=0; i<n; i++){
        if(visited[i]) continue;
        if(t + a[i] * t + b[i] <= t_max){
            visited[i] = true;
            shop(visited, a, b, t + a[i] * t + b[i] + 1, t_max, n, shopcount + 1, shopcount_max);
            visited[i] = false;
        }
    }
}
