#define l_ength size

void mul_mod(ll& a, ll b){
	a *= b;
	a %= MOD;
}

void add_mod(ll& a, ll b){
	a = (a<MOD)?a:(a-MOD);
	b = (b<MOD)?b:(b-MOD);
	a += b;
	a = (a<MOD)?a:(a-MOD);
}

vector<P> v;
vector<ll> u;

ll dp[225816][50];

bool comp(P a, P b){
	return ((b.first+1)*a.second > (a.first+1)*b.second);
}

int main(void){
	int n,i,m,ans=0,j,tmp;
	ll a,b,t;
	cin >> n >> t;
	for(i=0; i<n; ++i){
