    sort(base.begin(), base.end(), [](auto x, auto y)
    {
        if (x.first.first*y.first.second == x.first.second * y.first.first) return (x.second>y.second);
        else return   x.first.first*y.first.second >= x.first.second * y.first.first;
    });

    sort(free.begin(), free.end());


    vector<pair<ll, ll>> prs(N);
    for (int i = 0; i<N; i++) prs[i] = base[i].first;

    //for (auto it: prs) cout<<it.first<<' '<<it.second<<endl;

