vector<Q> d;

int main() {
  scanf("%lld%lld", &n, &t);
  t++;
  for (ll i = 0; i < n; i++) {
    scanf("%lld%lld", &a, &b);
    b++;
    if (a == 0) {
      zero.push_back(b);
    } else {
      d.push_back(Q((double)b/a, P(a+1, b)));
    }
  }
  sort(d.begin(), d.end());
  sort(zero.begin(), zero.end());
  vector<ll> dp(30, INF);
  dp[0] = 1;
  for (Q q : d) {
    P p =q.second;
    a = p.first, b = p.second;
    for (ll i = 29; i > 0; i--) dp[i] = min(dp[i], dp[i-1] * a + b);
  }
  for (ll i = 0; i < 30; i++) {
    if (dp[i] > t) continue;
    ll counter = i;
    for (ll j : zero) {
      if (dp[i] + j > t) break;
      dp[i] += j;
      counter++;
    }
    ans = max(ans, counter);
  }
  printf("%lld\n", ans);
}

