using namespace std;
typedef long long ll;
typedef pair<ll,ll> pp;
const ll INF = 1e10;
const int MOD = 1000000007;

bool f(pp x,pp y){
  return x.first/(x.second+1) < y.first/(y.second+1);
}

int main() {
  ll n,t;
  cin >> n >> t;
  vector<pp> ab;
  vector<ll> B;
  rep(i,n){
    ll a,b;
    cin >> a >> b;
    if(a == 0LL) B.push_back(b);
    else ab.push_back(pp(a,b));
  }

  sort(ab.begin(),ab.end(),f);
  sort(B.begin(),B.end());

  int k = (int)ab.size();
  vector<vector<ll>> dp(k+1,vector<ll>(30,INF));

  dp[0][0] = 0LL;
  for(int i=1;i<=k;i++){
    rep(j,30){
      if(j > 0){
        dp[i][j] = min(dp[i-1][j],dp[i-1][j-1]+1+ab.at(i-1).first*(dp[i-1][j-1]+1)+ab.at(i-1).second);
      }
      else{
        dp[i][j] = dp[i-1][j];
      }
    }
  }

  int ans = 0;

  rep(i,30){
    if(dp[k][i] > t) continue;
    int j = 0;
    ll time = dp[k][i];
    if(B.size() > 0){
      while(time + 1 + B.at(j) <= t){
        time += B.at(j)+1;
        j ++;
        if(j == (int)(B.size())) break;
      }
    }
    ans = max(ans,i+j);
  } 
  cout << ans << endl;

  return 0;
}

