template<typename T> struct SegmentTree {
    using F = function<T(T, T)>;
    vector<T> seg;
    int sz;
    const F func;
    const T IDENT;
    SegmentTree() {}
    SegmentTree(int n, const F f, const T &ID) : func(f), IDENT(ID) {
        sz = 1; while (sz < n) sz <<= 1;
        seg.assign(2 * sz - 1, IDENT);
    }
    SegmentTree(vector<T> v, const F f, const T &ID) : func(f), IDENT(ID) {
        int n = v.size();
        sz = 1; while (sz < n) sz <<= 1;
        seg.assign(2 * sz - 1, IDENT);
        for (int i = 0; i < n; ++i) seg[i + sz - 1] = v[i];
        for (int i = sz - 2; i >= 0; --i) seg[i] = func(seg[2 * i + 1], seg[2 * i + 2]);
    }
    void update(int k, T x) {
        k += sz - 1;
        seg[k] = x;
        while (k > 0) {
            k = (k - 1) / 2;
            seg[k] = func(seg[2 * k + 1], seg[2 * k + 2]);
        }
    }
    void add(int k, T x) {
        k += sz - 1;
        seg[k] += x;
        while (k > 0) {
            k = (k - 1) / 2;
            seg[k] = func(seg[2 * k + 1], seg[2 * k + 2]);
        }
    }
    T query(int a, int b, int k = 0, int l = 0, int r = -1) {
        if (r < 0) r = sz;
        if (r <= a || l >= b) return IDENT;
        if (l >= a && r <= b) return seg[k];
        T f_l = query(a, b, 2 * k + 1, l, (l + r) / 2);
        T f_r = query(a, b, 2 * k + 2, (l + r) / 2, r);
        return func(f_l, f_r);
    }
    void print() {
        for (int i = 0; i < 2 * sz - 1; ++i) {
            cerr << seg[i] << ' ';
            if (!((i + 2) & (i + 1))) cerr << endl;
        }
    }
};

using P = pair<int, int>;

int N, T;
vector<int> B_const;
vector<P> shop;

signed main() {

    cin >> N >> T;

    REP(i, N) {
        SS(int, A, B);
        if (A == 0) {
            B_const.emplace_back(B);
        } else {
            shop.emplace_back(A, B);
        }
    }

    sort(shop.begin(), shop.end(), [](P s1, P s2) {
        auto [a1, b1] = s1;
        auto [a2, b2] = s2;
        return ll(a2) * (b1 + 1) < ll(a1) * (b2 + 1);
    });
    int sz = shop.size();

    vector<ll> B_const_acc;
    if (B_const.size() > 0) {
        sort(B_const.begin(), B_const.end());
        B_const_acc.emplace_back(B_const.front() + 1);
        int n = B_const.size();
        REP(i, 1, n) {
            ll prv = B_const_acc.back();
            B_const_acc.emplace_back(prv + B_const[i] + 1);
        }
    }
    // 残り時間pでa=0の店を何軒回れるか (最初の移動時間も込み)
    //   => LEQ(B_const_acc, p)

    vector<SegmentTree<ll>> dp(40, SegmentTree<ll>(sz + 1, [](ll a, ll b){
        return min(a, b);
    }, INFF));
    dp[0].update(0, 0);     // 家

    REP(i, sz) {
        auto [a, b] = shop[i];
        REP(j, 39) {
            ll t = dp[j].query(0, i + 1);
            if (t == INFF) continue;
            t = ll(a) * (t + 1) + b;
            dp[j + 1].update(i + 1, t);
        }
    }

    int b_sz = B_const_acc.size();
    int res = 0;
    REP(j, 40) {    // j店舗回った
        REP(i, j, sz + 1) {
            ll t = dp[j].query(i, i + 1);
            if (t > T) continue;
            ll b = (b_sz > 0) ? LEQ(B_const_acc, T - t) : 0;
            chmax(res, j + b);
        }
    }
    print(res);

}

