	sort(u.begin(),u.end());
	m = v.l_ength();
	fill(dp[0],dp[225816],INFLL);
	dp[0][0] = 0ll;
	for(i=0; i<m; ++i){
		for(j=0; j<41; ++j){
			if(dp[i][j]>t){
				continue;
			}
			dp[i+1][j] = min(dp[i+1][j],dp[i][j]);
			dp[i+1][j+1] = min(dp[i+1][j+1],dp[i][j]*v[i].first+v[i].second);
		}
	}
	for(j=0; j<41; ++j){
		if(dp[m][j]>t){
			continue;
		}
		tmp = j;
		for(i=m; i<n; ++i){
