int Qsort(int x,int y,nn v[])
{
	nn k=v[(x+y)>>1];
	int l=x;
	int r=y;
	while(l<=r)
	{
		while(v[l]<k)
			l++;
		while(v[r]>k)
			r--;
		if(l<=r)
		{
			nn t=v[l];
			v[l]=v[r];
			v[r]=t;
			l++;
			r--;
		}
	}
	if(x<r)
		Qsort(x,r,v);
	if(l<y)
		Qsort(l,y,v);
}
