int main(){
    // InOut();
    ios_base::sync_with_stdio(0);
    cin.tie(0);
    cout.tie(0);
    cin >> nStore >> totalTime;
    for(int iStore = 1 ; iStore <= nStore ; ++iStore){
        LL x, y;
        cin >> x >> y;
        if(x == 0) remain.push_back(y);
        else stores.push_back({x, y});
    }
    sort(stores.begin(), stores.end(), cmp);
    sort(remain.begin(), remain.end());
    fill(dp, dp + 101, INF);
    dp[0] = 0;
    for(int iStore = 0 ; iStore < stores.size() ; ++iStore){
        for(int iVisited = min(50, iStore + 1) ; iVisited > 0 ; --iVisited){
            if(dp[iVisited - 1] > totalTime || dp[iVisited - 1] == INF) continue;
            dp[iVisited] = min(dp[iVisited], dp[iVisited - 1] + 1 + (dp[iVisited - 1] + 1) * stores[iStore].first + stores[iStore].second);
        }
    }
    // cout << dp[5] << endl;
    for(int iVisited = 0 ; iVisited <= 50 ; ++iVisited)
    if(dp[iVisited] <= totalTime){
        LL pos = 0;
        while(pos < remain.size()){
            if(dp[iVisited] + remain[pos] + 1 <= totalTime){
                dp[iVisited] += (remain[pos] + 1);
                pos++;
            } else break;
        }
        ans = max(ans, iVisited + pos);
    }
    cout << ans << endl;

    return 0;
}

