const ll MOD = (ll)(1e9+7);

#define l_ength size

void mul_mod(ll& a, ll b){
	a *= b;
	a %= MOD;
}

void add_mod(ll& a, ll b){
	a = (a<MOD)?a:(a-MOD);
	b = (b<MOD)?b:(b-MOD);
	a += b;
	a = (a<MOD)?a:(a-MOD);
}

vector<P> v;
vector<ll> u;

ll dp[225816][50];

bool comp(P a, P b){
	return ((b.first+1)*a.second > (a.first+1)*b.second);
}

int main(void){
	int n,i,m,ans=0,j,tmp;
	ll a,b,t;
	cin >> n >> t;
	for(i=0; i<n; ++i){
		cin >> a >> b;
		if(a){
			v.push_back(P(a,b));
		}else{
			u.push_back(b+1);
		}
	}
	sort(v.begin(),v.end(),comp);
	sort(u.begin(),u.end());
	m = v.l_ength();
	fill(dp[0],dp[225816],INFLL);
	dp[0][0] = 0ll;
	for(i=0; i<m; ++i){
		for(j=0; j<41; ++j){
			if(dp[i][j]>t){
				continue;
			}
			dp[i+1][j] = min(dp[i+1][j],dp[i][j]);
			dp[i+1][j+1] = min(dp[i+1][j+1],(dp[i][j]+1)*(v[i].first+1)+v[i].second);
		}
	}
	for(j=0; j<41; ++j){
		if(dp[m][j]>t){
			continue;
		}
		tmp = j;
		for(i=m; i<n; ++i){
			if(dp[m][j]+u[i-m]>t){
				break;
			}
			++tmp;
		}
		ans = max(ans,tmp);
	}
	cout << ans << endl;
	return 0;
}

