using namespace std;

typedef long long ll;

const int N = (int) 2e5 + 7;
int n;
ll t;
ll a[N];
ll b[N];
int ord[N];

bool cmp(int i, int j) {
  return a[j] * (b[i] + 1LL) < a[i] * (b[j] + 1);
}

const int E = 40;
ll m[E];

int main() {
  ios::sync_with_stdio(0);
  cin.tie(0);

  vector<ll> aso;
  int cnt;
  cin >> cnt >> t;
  for (int i = 1; i <= cnt; i++) {
    ll x, y;
    cin >> x >> y;
    if (x == 0) {
      aso.push_back(y + 1);
    } else {
      n++;
      ord[n] = n;
      a[n] = x;
      b[n] = y;
    }
  }
  sort(aso.begin(), aso.end());
  sort(ord + 1, ord + n + 1, cmp);
  for (int i = 1; i < E; i++) {
    m[i] = t + 1;
  }
  for (int j = 1; j <= n; j++) {
    int i = ord[j];
    for (int k = E - 2; k >= 0; k--) {
      m[k + 1] = min(m[k + 1], m[k] * (a[i] + 1LL) + b[i] + 1LL);
    }
  }
  int ret = 0;
  for (int k = 0; k < E; k++) {
    if (m[k] <= t) {
      int j = k;
      ll cur = m[k];
      for (auto &x : aso) {
        if (cur + x <= t) {
          cur += x;
          j++;
        }
      }
      ret = max(ret, j);
    }
  }
  cout << ret << "\n";
}

