	sort(v1.begin(), v1.end(), comp);
	for (int i = 0; i <= 30; ++ i)
		for (int j = 0; j <= v1.size(); ++ j)
			f[i][j] = T + 5;
	f[0][0] = 0;
	for (int i = 0; i < 30; ++ i) {
		for (int j = 0; j < v1.size(); ++ j) {
			f[i][j + 1] = min(f[i][j + 1], f[i][j]);
			f[i + 1][j + 1] = min(f[i + 1][j + 1], 1 + 1LL * (1 + v1[j].first) * f[i][j] + v1[j].second);
		}
	}
	int ans = 0;
	for (int i = 1; i <= 30; ++ i) {
		for (int j = 0; j <= v1.size(); ++ j) {
			if (f[i][j] <= T) ans = i + F(T - f[i][j]);
		}
	}
	cout << ans << endl;
	return 0;
}

