#define rep(i, n) for (ll i = 0; i < (n); i++)
#define rep2(i, a, b) for (ll i = (a); i < (b); i++)
#define chmax(x, v) do { x = max(x, v); } while (0)
#define chmin(x, v) do { x = min(x, v); } while (0)
typedef uint64_t ull;
typedef int64_t ll;
typedef std::pair<ll, ll> PLL;

using namespace std;

const ll INF=1e11;
struct F { ll c, d; };
ll N, N1, N2, T;
vector<F> g1, g2;
// log_2 (10^9) < 40
vector<vector<ll>> dp(202020, vector<ll>(40, INF)); // dp[i][j]: 先頭からi個までみて、j個を選んだ後の時刻

signed main() {
  cin >> N >> T;
  rep(i, N) {
    ll a, b, c, d;
    cin >> a >> b;
    c = a + 1;
    d = a + b + 1;
    if (c -1 > 0) {
      g1.push_back(F{c, d});
    } else {
      g2.push_back(F{c, d});
    }
  }
  N1 = g1.size();
  N2 = g2.size();
  sort(begin(g1), end(g1), [](const F &f1, const F &f2) {
      ll c1 = f1.c, d1 = f1.d, c2 = f2.c, d2 = f2.d;
      return (c2-1)*d1 < (c1-1)*d2;
      });
  sort(begin(g2), end(g2), [](const F &f1, const F &f2) {
      ll c1 = f1.c, d1 = f1.d, c2 = f2.c, d2 = f2.d;
      return d1 < d2;
      });

  dp[0][0] = 0;
  rep(i, 202020) rep(j, 40) {
    if (dp[i][j] == INF)
      continue;
    ll ni = i + 1;
    // 次の店（i = i）を追加する
    if (ni < 202020 && i < N1) chmin(dp[ni][j+1], g1[i].c * dp[i][j] + g1[i].d);
    // 次の店（i = i）を追加しない
    if (ni < 202020) chmin(dp[ni][j], dp[i][j]);
  }

  ll ans = 0;
  rep(j, 40) {
    ll n = j, t = dp[202020-1][j];
    for (auto f : g2) {
      if (t + f.d <= T) {
        n++;
        t += f.d;
      }
    }
    if (t <= T) {
      chmax(ans, n);
    }
  }
  cout << ans << endl;
  return 0;
}

