long long f(int idx, long long tm) {
    return tm + 1ll * a[idx] * tm + b[idx];
}

bool cmp(const int& a, const int& b) {
    return f(b, f(a, 1) + 1) < f(a, f(b, 1) + 1);
}

int main() {
    scanf("%d %d", &n, &t);
    for (int i = 0; i < n; i++) {
        scanf("%d %d", &a[i], &b[i]);
