            v.push_back(i);
        } else {
            vz.push_back(b[i]);
        }
    }
    sort(v.begin(), v.end(), cmp);
    sort(vz.begin(), vz.end());

    for (int i = 0; i <= 30; i++) {
        mn[i] = INF;
    }
    mn[0] = 0;

    for (int i = 0; i < (int)v.size(); i++) {
        for (int j = 30; j >= 1; j--) {
