const int INF = 2147483647;
const ll LLINF = 9223372036854775807LL;

// lambda-expression: [] (args) -> retType { body }

void run() {
	int n, t;
	cin >> n >> t;
	vii A(n);
	for (ii &pr : A) cin >> pr.x >> pr.y;
	// for (ii &pr : A) pr.x = rand() % 10, pr.y = rand() % 10;

	// travel time:
	for (ii &pr : A) pr.y++;

	sort(all(A), [] (ii a, ii b) -> bool {
		// do the ones with the smallest first component latest.
		if (a.x != b.x) return a.x > b.x;
		return a.y < b.y;
	});

	vector<ll> zeros;
	while (!A.empty() && A.back().x == 0) {
		zeros.pb(A.back().y);
		A.pop_back();
	}
	zeros.pb(0);
	// sort(all(zeros));
	reverse(all(zeros));
	for (int i=1; i < (int) zeros.size(); i++) {
		zeros[i] += zeros[i-1];
	}

	vi min_time = { 0 };
	for (ii pr : A) {
		int sz = min_time.size();
		if (ll(pr.x + 1) * min_time.back() + pr.y <= t) {
			min_time.pb((pr.x + 1) * min_time.back() + pr.y);
		}
		for (int i = sz - 2; i >= 0; i--) {
			ll alt = ll(pr.x + 1) * min_time[i] + pr.y;
			if (alt < min_time[i+1])
				min_time[i+1] = alt;
		}
	}

	int answer = 0, takeZeros = 0;
	for (int take = min_time.size() - 1; take >= 0; take--) {
		while (takeZeros+1 < zeros.size() && min_time[take] + zeros[takeZeros+1] <= t) {
			takeZeros++;
		}
		answer = max(answer, take + takeZeros);
	}

	cout << answer << endl;
}

