int a[N], b[N];
bool used[N];

signed main() {
    ios_base::sync_with_stdio(false);
    cin.tie(0);
    int n, T;
    cin >> n >> T;
    for (int i = 0; i < n; ++i) {
        cin >> a[i] >> b[i];
        ++a[i];
        ++b[i];
    }
    int t = 0;
    int cnt = 0;
    while (t <= T) {
        int mint = INF;
        int pos = -1;
        for (int i = 0; i < n; ++i) {
            if (!used[i]) {
                if (a[i] * t + b[i] < mint) {
                    mint = a[i] * t + b[i];
                    pos = i;
                }
            }
        }
        if (pos == -1) {
            break;
        }
        if (mint > T) break;
        used[pos] = 1;
        ++cnt;
        t = t * a[pos] + b[pos];
    }
    cout << cnt << endl;
    return 0;
}

