using namespace std;

int n, T;
pair<int, int> shop[200005];

const int INF = 1010101010;
int dp[200005][32]; // consider shops 1..i, chose j, minimum time?

bool comparator(pair<int, int> s, pair<int, int> t){
	return 1LL * s.first * (1 + t.second) > 1LL * t.first * (1 + s.second);
}

int main(){
	scanf("%d %d", &n, &T);
	for(int i = 1; i <= n; i++){
		scanf("%d %d", &shop[i].first, &shop[i].second);
	}
	sort(shop + 1, shop + n + 1, comparator);
	dp[0][0] = 0;
	for(int i = 1; i <= 30; i++){
		dp[0][i] = INF;
	}

	int final = n + 1;

	for(int i = 1; i <= n; i++){
		if(shop[i].first == 0){
			final = i;
			break;
		}
		for(int j = 0; j <= 30; j++){
			// shop or not shop, simple choice
			// shop
			long long next_time = 1LL * (dp[i - 1][j] + 1) * shop[i].first + shop[i].second;
			if(next_time <= T){
				dp[i][j + 1] = next_time;
			}else{
				dp[i][j + 1] = INF;
			}
			// not shop
			dp[i][j] = min(dp[i][j], dp[i - 1][j]);
		}
	}

	// consider doing some final shopping, in ascending order of time
	sort(shop + final, shop + n + 1);
	int ans = 0;
	for(int j = 0; j <= 30; j++){
		int cur_time = dp[final - 1][j];
		int cur_ans = j;
		int index = final;
		if(cur_time > T){
			continue;
		}
		while(index <= n && cur_time + 1 + shop[index].second <= T){
			cur_ans++;
			index++;
			cur_time += 1 + shop[index].second;
		}
		ans = max(ans, cur_ans);
	}
	printf("%d\n", ans);
	return 0;
}

