		}
	}

	sort(begin(zs), end(zs));
	for (int i = 1; i < zs.size(); i++) {
		zs[i] += zs[i-1];
	}

	int n = A.size();
	vvll dp(30, vll(n+1, LLINF));
	dp[0][0] = 0;
	int ans = --upper_bound(begin(zs), end(zs), T) - begin(zs);
	for (int c = 1; c < 30; c++) {
		ll minv = LLINF;
		for (int i = 1; i < n+1; i++) {
			chmin(dp[c][i], dp[c][i-1]);
			if (dp[c-1][i-1] <= T) {
				chmin(dp[c][i], dp[c-1][i-1] * (A[i-1] + 1) + A[i-1] + B[i-1]);
			}
			chmin(minv, dp[c][i]);
		}
		if (minv > T) break;
		int num = --upper_bound(begin(zs), end(zs), T - minv) - begin(zs);
		chmax(ans, c + num);
	}
	cout << ans << endl;
}

