using namespace std;

int main() {
    int64_t N, T;
    cin >> N >> T;
    struct Shop {
        int64_t a, b;
        bool operator<(const Shop& rhs) const {
            return (a * rhs.b == rhs.a * b ? a > rhs.a : a * rhs.b > rhs.a * b);
        }
    };

    vector<Shop> shops(N);
    for (Shop& s : shops) {
        cin >> s.a >> s.b;
    }
    sort(shops.begin(), shops.end());

    //先頭から連続で行ったときのiを出て次につく時間
    vector<int64_t> time(N + 1, 1);
    for (int64_t i = 0; i < N; i++) {
        time[i + 1] = time[i] * (shops[i].a + 1) + shops[i].b + 1;
    }

    //[0, i)の累積積
    vector<int64_t> prod(N + 1, 1);
    for (int64_t i = 0; i < N; i++) {
        prod[i + 1] = prod[i] * (shops[i].a + 1);
    }

    int64_t ok = 0, ng = N + 1;
    while (ng - ok != 1) {
        int64_t mid = (ok + ng) / 2;

        bool flag = false;
        for (int64_t i = 0; i < mid; i++) {
            //先頭からi店取る
            int64_t pre = time[i];

            //後半からmid - i店取る
            int64_t index = N - (mid - i);
            int64_t diff = time[index] - pre;
            int64_t diff2 = time[N] - diff * (prod[N] / prod[index]);

            if (diff2 - 1 <= T) {
                flag = true;
                break;
            }
        }

        if (time[mid] - 1 <= T) {
            flag = true;
        }

        (flag ? ok = mid : ng = mid);
    }

    cout << ok << endl;
}

