using i64 = std::int64_t;

struct Shop {
	i64 a, b;

	bool operator < (const Shop& rhs) const {
		return rhs.a * (b + 1) < a * (rhs.b + 1);
	}
};

int main() {
	i64 N, T;
	std::cin >> N >> T;

	std::vector<Shop> shops(N);
	for (auto&& s : shops)
		std::cin >> s.a >> s.b;

	std::sort(shops.begin(), shops.end());

	auto check = [&](int k) -> bool {
		if (k == 0)
			return true;

		i64 t = shops[0].a + shops[0].b + 1;
		int idx = 1, took = 1;
		while (took < k) {
			i64 min = std::numeric_limits<i64>::max();
			int minIdx = 0;
			for (int i = idx; i < N - k + took + 1; ++i) {
				int cand = (shops[i].a + 1) * (t + 1) + shops[i].b;

				if (cand < min) {
					minIdx = i;
					min = cand;
				}
			}

			idx = minIdx + 1;
			t = min;

			++took;
		}

		return t <= T;
	};

	int l = 0, r = N + 1;
	while (r - l > 1) {
		int mid = (l + r) / 2;

		if (check(mid))
			l = mid;
		else
			r = mid;
	}

	std::cout << l << std::endl;
}

