			if(dp[i][j] > t) continue;
			chmin(dp[i+1][j], dp[i][j]);
			ll tmp = dp[i][j] + 1 + (dp[i][j]+1)*other[i].second.first + other[i].second.second;
			if(tmp <= t) chmin(dp[i+1][j+1],tmp);
		}
	}
	ll ans = 0;
	rep(i,30){
		if(dp[N][i] > t) continue;
		if(zero.empty()){
			chmax(ans,i); continue;
		}
		auto itr = upper_bound(all(zero),t - dp[N][i]);
		chmax(ans, i + itr - zero.begin());
	}
	cout << ans << endl;
}

