	REP(i, n) {
		int a, b;
		cin >> a >> b;
		if(a == 0) z.emplace_back(a, b);
		else v.emplace_back(a, b);
	}

	sort(v.begin(), v.end(), [&](PII a, PII b) {
		LL x = LL(a.ST + a.ND + 1) * (b.ST + 1) + b.ND;
		LL y = LL(b.ST + b.ND + 1) * (a.ST + 1) + a.ND;
