	int LOG = 100, inf = 1e9 + 3;
	vector<int> dp(LOG, inf);
	dp[0] = 0;

	for(auto &p : v) {
		for(int i = LOG - 1; i >= 1; i--)
			dp[i] = min<LL>(dp[i], LL(dp[i - 1] + 1) * (p.ST + 1) + p.ND);
	}

	vector<int> pref(size(z) + 1);
	FOR(i, 1, size(z)) pref[i] = pref[i - 1] + z[i - 1].ND + 1;

