        dp[i + 1][j] =
            min(dp[i + 1][j],
                (v[i].a * (dp[i][j - 1] + 1) + v[i].b));
    }
  long long res = 0;
  for(int i = 0; i < 40; ++i)
    if(dp[n][i] <= t)
      res = max(res, (long long)i +
