            cout << ans << endl;
            return 0;
          }
          ans++;
        }
        cout << ans << endl;
        return 0;
      }
    }

    passed++;
    if (passed > T) {
      break;
    }
    // update and find min
    ll mincost = INF;
    ll minI = -1;
    for (int i : canvisit) {
      cost[i] += as[i];
      if (mincost > cost[i]) {
        mincost = cost[i];
        minI = i;
      }
    }
    canvisit.erase(minI);
    passed += mincost;
