template<class x, class y>
struct pear {
	x f;
	y s;
	void mp(x a, y b) {
		f = a;
		s = b;
	}
};

template<class x, class y>
pear<x, y> make_pear(x a, y b) {
	pear<x, y> dr;
	dr.f = a;
	dr.s = b;
	return dr;
}

bool operator>(pear<int, int> a, pear<int, int> b) {
	if(a.f == 0 && b.f == 0) {
		if(a.s > b.s) {
			return 1;
		} else {
			return 0;
		}
	} else if(a.f == 0) {
		return 1;
	} else if(b.f == 0) {
		return 0;
	} else if((long long)a.f * (b.s + 1) < (long long)b.f * (a.s + 1)) {
		return 1;
	}
	return 0;
}

bool operator==(pear<int, int> a, pear<int, int> b) {
	if((long long)a.f * (b.s + 1) == (long long)b.f * (a.s + 1)) {
		return 1;
	}
	return 0;
}

bool operator<(pear<int, int> a, pear<int, int> b) {
	if(a > b || a == b) {
		return 0;
	}
	return 1;
}

bool operator<=(pear<int, int> a, pear<int, int> b) {
	if(a > b) {
		return 0;
	}
	return 1;
}

bool operator>=(pear<int, int> a, pear<int, int> b) {
	if(a < b) {
		return 0;
	}
	return 1;
}

const int N = 200005, Tlg = 32;
const long long inf = 1e17;
int n, t, x, y, ni, m, fp;
vector<pear<int, int> > v;
long long dp[N][Tlg], nb[N];
bool bn;

int main() {
	ios::sync_with_stdio(0);
	cin.tie(0);
	v.push_back(make_pear(1000000001, 0));
	cin >> n >> t; m = n;
	for(int i = 1; i <= n; ++i) {
		cin >> x >> y;
		v.push_back(make_pear(x, y));
	}
	sort(v.begin(), v.end());
	for(int i = 1; i < Tlg; ++i) dp[0][i] = -1;
	for(int i = 1; i < v.size(); ++i) {
		if(v[i].s == 0) bn = 1, m = i - 1;
		if(bn) {
			++ni;
			nb[ni] = nb[ni - 1] + (ni > 1 ? 1 : 0) + v[i].s;
		} else {
			for(int j = 1; j < Tlg; ++j) {
				dp[i][j] = min((dp[i - 1][j - 1] == -1 ? inf : (dp[i - 1][j - 1] + 1 + (dp[i - 1][j - 1] + 1) * v[i].f + v[i].s)), (dp[i - 1][j] == -1 ? inf : dp[i - 1][j]));
				if(dp[i][j] == inf) dp[i][j] = -1;
			}
		}
	}
	for(int i = 0; i < Tlg; ++i) {
		if(dp[m][i] != -1) {
			for(int j = 0; j <= ni; ++j) {
				if(dp[m][i] + nb[j] + (j > 0 ? 1 : 0) <= t) {
					fp = max(fp, i + j);
				}
			}
		}
	}
	cout << fp << endl;
	return 0;
}

