bool cmp( array<ll,2> x, array<ll,2> y )
{
    ll ax = x[0], bx = x[1], ay = y[0], by = y[1];
    return ( ay*bx < ax*by );
}

int main() 
{
    fastio();

    ll n,t;
    cin>>n>>t;

    vector< array<ll,2> > v(n);
    for(int i=0;i<n;i++)
        cin>>v[i][0]>>v[i][1];
    sort(all(v), cmp);

    vector<ll>best(n,-1), dp(n,0);
    best[0] = v[0][0] + v[0][1] + 1;
    dp[0] = 1;
    for(int i=1;i<n;i++)
