            if( dp[j] + 1 > dp[i] )
            {
                dp[i] = dp[j] + 1;
                best[i] = poss;
            }
            else if( dp[j] + 1 == dp[i] )
            {
                best[i] = min( best[i], poss );
            }
        }
    }

    ll ans = 0;
    for(int i=0;i<n;i++)
    {
        if( best[i] <= t )
            ans = max( ans, dp[i] );
    }
    cout<<ans,nl;

