	vector<int> a0;
	vector<pair<int, int>> P;
	for (int i = 0; i < n; ++i) {
		int a, b;
		scanf("%d%d", &a, &b);
		if (!a) {
			a0.push_back(b + 1);
		} else {
			P.push_back({a + 1, a + b + 1});
		}
	}
	sort(P.begin(), P.end(), [&](pair<int, int> x, pair<int, int> y) {
		return (y.first - 1LL) * x.second < (x.first - 1LL) * y.second;
