void solve(long long n, long long t, std::vector<long long> a, std::vector<long long> b){
    auto comp = [&](int i, int j){
        i64 x = (b[i] + 1) * a[j] + b[j];
        i64 y = (b[j] + 1) * a[i] + b[i];
        return x < y;
    };
    vector<int> idxes(n);
    iota(idxes.begin(), idxes.end(), 0);
    sort(idxes.begin(), idxes.end(), comp);

    for(int i = 0; i < n; ++i)
