typedef long long ll;
const ll inf = (ll) 1e18;

ll mul(ll a, ll b) {
  if (a == 0 || b == 0) {
    return 0;
  }
  ll p = a * b;
  if (p % a == 0 && p / a == b && p <= inf) {
    return p;
  } else {
    return inf;
  }
}

ll add(ll a, ll b) {
  return min(inf, a + b);
}

struct T {
  ll a;
  ll b;
};

bool operator < (T f, T s) {
  ll a1 = f.a, b1 = f.b;
  ll a2 = s.a, b2 = s.b;
  return add(b2, mul(b1, a2)) < add(b1, mul(b2, a1));
}

ll b[40], b2[40];

