		//for(auto x:s) cerr<<x<<' ';
		//cerr<<'\n';
	}
	for(int i=1;i<=n;i++) if(a[i].fi==1) sum[++tt]=a[i].se;
	sort(sum+1,sum+tt+1);
	for(int i=1;i<=tt;i++) sum[i]+=sum[i-1];
	auto it=s.begin();
	//cerr<<T<<endl;
	for(int i=0,j=tt;it!=s.end();i++) {
		while(*it+sum[j]>T) --j;
		//cerr<<*it<<' '<<sum[j]<<'\n';
		ans=max(ans,i+j);++it;
	}
	cout<<ans;
	return 0;
}

#include <bits/stdc++.h>
using namespace std;
using ld=long double;
#define int long long
const int INF=1e9;
typedef pair<int,int> P;
typedef pair<ld,P> LP;
int dp[223456][35];//dp[i][j]:i番目まででj個行った時の最小タイム
template<typename T>
void chmax(T &a,T b){
  if(a<b)a=b;
}
template<typename T>
void chmin(T &a,T b){
  if(a>b)a=b;
}

signed main(){
  int n,t;cin>>n>>t;
  vector<LP> v;
  vector<int> w;
  w.push_back(0);
  for(int i=0;i<n;i++){
    int a,b;cin>>a>>b;
    if(a+b>t)continue;
    if(a)v.push_back(LP((ld)a/(ld)(b+1),P(a,b)));
    else w.push_back(b);
  }
  sort(v.rbegin(),v.rend());
  sort(w.begin(),w.end());
  for(int i=0;i<223456;i++)for(int j=0;j<30;j++)dp[i][j]=INF+10;
  dp[0][0]=0;
  for(int i=0;i<v.size();i++){
    int a=v[i].second.first,b=v[i].second.second;
    for(int j=0;j<30;j++){
      if(dp[i][j]>t)continue;
      chmin(dp[i+1][j],dp[i][j]);
      chmin(dp[i+1][j+1],dp[i][j]+(dp[i][j]+1)*a+b);
    }
  }
  for(int i=1;i<w.size();i++)w[i]+=w[i-1]+1;
  n=v.size();
  int ans=0;
  for(int j=0;j<30;j++){
    int res=t-dp[n][j];
    if(res<0)continue;
    int l=0,r=w.size();
    while(r-l>1){
      int mid=(r+l)>>1;
      if(w[mid]<=res)l=mid;
      else r=mid;
    }
    chmax(ans,j+l);
  }
  cout<<ans<<endl;
}

#include<bits/stdc++.h>
using namespace std;
long long n,t,a[202020],b[202020],dp[55],ans;
vector<long long>v0;
vector<pair<long long,long long> >v1;
bool cmp(pair<long long,long long>a,pair<long long,long long>b)
{
	return a.first*b.second>a.second*b.first;
}
int main()
{
	cin>>n>>t;
	for(int i=0;i<n;i++)
	{
		cin>>a[i]>>b[i];
		if(a[i]==0)
		{
			v0.push_back(b[i]);
		}
		else
		{
			v1.push_back(make_pair(a[i]+1,b[i]+1));
		}
	}
	sort(v0.begin(),v0.end());
	sort(v1.begin(),v1.end(),cmp);
	for(int i=0;i<30;i++)
	{
		dp[i]=1e9+1;
	}
	dp[0]=1;
	for(int i=0;i<v1.size();i++)
	{
		for(int j=29;j>0;j--)
		{
			dp[j]=min(dp[j],dp[j-1]*v1[i].first+v1[i].second);
			if(dp[j]<0)
			{
				dp[j]=1e9+1;
			}
		}
	}
	for(int i=0;i<30;i++)
	{
		long long nw=dp[i],cnt=i*1ll;
		if(nw>t)
		{
			continue;
		}
		if(v0.size()!=0)
		{
			int p=0;
			while(p<v0.size() && nw+v0[p]<=t)
			{
				nw+=v0[p];
				cnt++;
				p++;
			}
		}
		ans=max(ans,cnt);
	}
	cout<<ans<<endl; 
	return 0;
}

