int loadint() {
    if (fgets(_buf, INTSPACE+3, stdin)==NULL) return 0;
    return atoi(_buf);
}

int loadvec(vector<int>& v, int N=-1) {
    if (N == 0) {
        v.clear();
        return 0;
    }
    if (N == -1) {
        N = loadint();
        if (N==0) return 0;
    }
    int bufsize = INTSPACE*N + 3;
    if (fgets(_buf, bufsize, stdin)==NULL) return 0;
    v.resize(N);

    int i=0;
    bool last = false;
    for (char *p=&_buf[0]; ;) {
        char *q = p;
        while (*q > ' ') ++q;
        if (*q == 0x0D || *q == 0x0A) last = true;
        *q = 0;
        v[i++] = atoi(p);
        if (last || i == N) break;
        p = q+1;
    }
    return i;
}


int solve(int N, ll T,vi& a,vi& b) {
    using P = pair<double, int>;

    auto intime = [&](ll t) -> bool {
        return (t <= T+1);
    };

    vi bs; bs.reserve(N);
    vector<P> ps; ps.reserve(N);
    rep(i,N){
        if (a[i] == 0) bs.pb(b[i]);
        else {
            ps.emplace_back((double)a[i]/(b[i]+1), i);
        }
    }
    sort(ALL(bs)); int Lb = bs.size();
    sort(ALL(ps), greater<P>()); int Lp = ps.size();

    #define MAX_K 100
    vll dp(MAX_K, LLONG_MAX);
    dp[0] = 1;

    for (auto& p: ps) {
        int i = p.second, ai = a[i], bi = b[i];
        for (int k=MAX_K; k>=0; --k) {
            if (dp[k] == LLONG_MAX) continue;
            ll t = dp[k];
            ll w = ai*t + (bi + 1);
            amin(dp[k+1], dp[k] + w);
        }
    }

    int best = 0;
    rep(k, MAX_K+1){
        if (dp[k] == LLONG_MAX) break;
        ll t = dp[k];
        if (intime(t)) amax(best, k);
        rep(i, Lb){
            ll w = bs[i] + 1;
            t += w;
            if (intime(t)) amax(best, k+i+1);
        }
    }
    return best;
}

int main() {
    int N, T; scanf("%d %d%*c", &N, &T);
    vi a(N), b(N);
    rep(i,N){
        scanf("%d %d%*c", &a[i], &b[i]);
    }
    cout << solve(N,T,a,b) << endl;
    return 0;
}

