int main(){
    std::cin.tie(nullptr);std::ios_base::sync_with_stdio(false);
    std::cout.setf(std::ios_base::fixed);std::cout.precision(15);
    lint n,T;std::cin>>n>>T;
    std::vector<std::pair<lint,lint>>heavy;
    std::vector<lint>light;
    while(n--){
        lint a,b;std::cin>>a>>b;
        if(a)heavy.emplace_back(a,b);
        else light.push_back(b+1);
    }
    std::sort(heavy.begin(),heavy.end(),[](auto&&p,auto&&q){
            return (p.second+1)*q.first<p.first*(q.second+1);
    });
    light.push_back(0);
    std::sort(light.begin(),light.end());
    std::partial_sum(light.begin(),light.end(),light.begin());
    lint lg=std::log2(T+1);
    std::vector<lint>dp(lg+1,T+1);
    dp.at(0)=0;
    for(auto&&p:heavy){
        lint a,b;std::tie(a,b)=p;
        for(lint i=lg;i>0;i--){
            cmn(dp.at(i),(dp.at(i-1)+1)*(a+1)+b);
        }
    }
    lint ans=0;
    for(lint i=0,j=light.size()-1;i<=lg;i++){
        if(T<dp.at(i))break;
        for(;T<dp.at(i)+light.at(j);j--);
        cmx(ans,i+j);
    }
    std::cout<<ans<<'\n';
