#define maxn 200010
#define pii pair<int, int>
#define fi first
#define se second

int n, m, k;
ll T;
pii a[maxn], b[maxn];
ll c[maxn];

bool cmp(pii i, pii j) {
  return 1ll * j.fi * (i.se + 1) < 1ll * i.fi * (j.se + 1);
}

ll dp[51][maxn];

int main(){
    ios_base::sync_with_stdio(0); cin.tie(0); cout.tie(0);
//    freopen("abc.inp", "r", stdin); freopen("abc.out", "w", stdout);
    cin >> n >> T;
    foru(i, 1, n) {
      cin >> a[i].fi >> a[i].se;
    }
    ll cur = 0;
    sort(a + 1, a + n + 1, cmp);

    foru(i, 1, n) {
      if (a[i].fi) {
        b[++m] = a[i];
      } else {
        c[++k] = a[i].se;
      }
    }

    for (int i = 0; i < 51; i++) for (int j = 0; j < maxn; ++j)
      dp[i][j] = 1 << 30;
    for (int i = 0; i <= m; ++i)
      dp[0][i] = 0;

    sort(c + 1, c + k + 1);

    foru(i, 1, k) {
      c[i] = c[i-1] + c[i];
    }

    foru(j, 1, min(50, m) ) {
      foru(i, j, m) {
        dp[j][i] = dp[j][i-1];
        ll P = dp[j-1][i-1] + 1;
        dp[j][i] = min(dp[j][i], P * (b[i].fi + 1) + b[i].se);
      }
    }

    int ret = 0;
    for (int ans = min(m, 50); ans >= 0; --ans) {
      if (dp[ans][m] > T) continue;
      ll rem = T - dp[ans][m];
      int pl = upper_bound(c, c + k + 1, rem) - c;
      --pl;
      ret = max(ret, ans + pl);
    }
    int pl = lower_bound(c, c + k + 1, 26) - c;
    cout << ret;
    return 0;
}
