int main(){

    ll n, t;
    cin >> n >> t;

    rep(i, n){
        ll a,b;
        cin >> a >> b;

        wait.pback(mpair(a, b));
    }

    //行ける個数を貪欲

    ll tmptime = 0;
    int count = 0;

    vector<pair<ll, int>> tmpwaittime(n);

    rep(i, n){
        tmpwaittime[i] = mpair(0, i);
    }


    vector<bool> arrivev(n, false);

    //貪欲的に今の待ち時間が小さい店から入っていく

    while(true){
        //次の店に行く移動時間を加える
