pair<int, int> select(vector<pair<int, int>> &ab, int t) {
    int cost = pow(2, 30);
    int min_index = 0;
    int max_a = 0;
    int c;
    int n = ab.size();
    for(int i = 0; i < n; i++) {
        c = ab.at(i).first * t + ab.at(i).second;
        if(c < cost || (c == cost && max_a < ab.at(i).first)) {
            cost = c;
            min_index = i;
            max_a = ab.at(i).first;
        }
    }
    return make_pair(min_index, cost);
}

int main() {
