    }

    int ans = 0;
    int t = 0;
    pair<int, int> index_cost;
    while(t < T && ab.size() > 0) {
        t++;
        index_cost = select(ab, t);
        t += index_cost.second;
        ab.erase(ab.begin() + index_cost.first);
        if(t <= T) {
            ans++;
        }
    }

    cout << ans;

    return 0;
}

