static int mycompare(pair<long long int, long long int> p1, 
	pair<long long int, long long int> p2) {
	return (p1.second + 1) * p2.first < (p2.second + 1) * p1.first;
}

void dfs(vector<pair<long long int, long long int>>& vp, long long int tt, int t, int& res, int index, int c) {
	if (c + vp.size() - index < res) {
		return;
	}
	if (index == vp.size()) {
		res = max(res, c);
		return;
	}
	if (tt > t) {
		res = max(res, c);
		return;
	}
	dfs(vp, tt, t, res, index + 1, c);

	tt = tt * (vp[index].first + 1) + vp[index].second;
	if (tt <= t) {
		dfs(vp, tt + 1, t, res, index + 1, c + 1);
	}
}

