	sort(p + 1, p + 1 + n, cmp);
	k = 0;
	for (int i = 1; i <= n; ++i)
	{
		if (a[p[i]] == 0)
			break;
		k = i;
	}
	int id = 0;
	for (int j = 0; j < K; ++j)
		dp[id][j] = T + 1;
	dp[id][0] = 0;
	for (int i = 1; i <= k; ++i)
	{
		for (int j = 0; j < K; ++j)
			dp[id ^ 1][j] = dp[id][j];
		for (int j = 0; j < K - 1; ++j)
