	for (int i = 0; i < N; i++) {
		for (int j = 0; j < L; j++) {
			dp[i][j] = inf;
		}
	}
	dp[0][0] = 0;
	for (int i = 0; i < n; i++) {
		for (int j = 0; j < L; j++) {
			if (dp[i][j] > T) continue;
			dp[i + 1][j] = min(dp[i + 1][j], dp[i][j]);
			if(j != (L - 1))
				dp[i + 1][j + 1] = min(dp[i + 1][j + 1], a[i].first * (dp[i][j] + 1) + a[i].second);
			//cout << i << " " << j << " " << dp[i][j] << endl;
		}
	}
	int ans = 0;
	for (int i = 0; i < L; i++) {
		int cur = dp[n][i];
		if (cur > T) continue;
		ans = max(ans, i);
		int t = 0;
		for (int j : b) {
			if (cur + 1 + j > T) break;
			t++;
			cur = cur + 1 + j;
		}
		ans = max(ans, i + t);
	}
	cout << ans << endl;
	return;
}

