struct Node
{
	ll k, c;
}a[maxn];
int n, T, ans;
ll dp[maxb];
vector<Node> lin, ex;
bool cmplin(const Node & i, const Node & j) { return i.c < j.c;}
bool cmpex(const Node & i, const Node & j) { return j.k * i.c + j.c < i.k * j.c + i.c;}
int main()
{
	scanf("%d%d", &n, &T);
	for(int i = 1; i <= n; ++i)
	{
		scanf("%lld%lld", &a[i].k, &a[i].c);
		++a[i].k;
		a[i].c += a[i].k;
		if(a[i].k == 1) lin.push_back(a[i]);
		else ex.push_back(a[i]);
	}
	sort(ex.begin(), ex.end(), cmpex);
	sort(lin.begin(), lin.end(), cmplin);
	for(int j = 1; j < maxb; ++j) dp[j] = inf;
	for(auto v : ex)
		for(int j = maxb - 1; j; --j)
			dp[j] = min(dp[j], v.k * dp[j - 1] + v.c);
	for(int i = 1; i < lin.size(); ++i) lin[i].c += lin[i - 1].c;
	for(int j = 0; j < maxb; ++j)
		if(dp[j] <= T)
		{
			int cur = upper_bound(lin.begin(), lin.end(), Node{1, T - dp[j]}, cmplin) - lin.begin();
			ans = max(ans, j + cur);
		}
	printf("%d\n", ans);
	return 0;
}

