auto solve() {
  in<int> N, T;
  vector<pair<int,int>> ab;

  REP(i, N) {
    int a, b;
    cin >> a >> b;
    ab.emplace_back(a, -b);
  }

  bst::sort(ab, greater<pair<int,int>>());
  REP(i, N)
    ab[i].second *= -1;


  map<int,int> dp;
  dp[0] = 0;
  int maxx = 0;
  REP(i, N) {
    auto newdp = dp;
    for (auto it = dp.rbegin(); it != dp.rend(); ++it) {
      if (it->first + 1 + ab[i].first * (it->first+1) + ab[i].second <= T) {
      newdp[it->first + 1 + ab[i].first * (it->first+1) + ab[i].second] = 
        max(dp[it->first + 1 + ab[i].first * (it->first+1) + ab[i].second], it->second + 1);
      maxx = max(maxx, it->second + 1);
      }
    }
    dp = move(newdp);
  }

  return maxx;
}

