int calc(VP &ps, const LL &T) {
    int n = ps.size();
    int cnt = 0;
    LL t = 0;
    vector<bool> used(n);
    while (t <= T && cnt < n) {
        ++t;
        LL minv = 1LL << 60;
        REP(i,0,n) if (!used[i]) chmin(minv, 1LL * ps[i].first * t + ps[i].second);
        REP(i,0,n) if (1LL * ps[i].first * t + ps[i].second == minv) {
            t = minv;
            used[i] = true;
            break;
        }
        if (t <= T) ++cnt;
    }
    return cnt;
}

