	int x=0,o=1;char ch=getchar();
	while((ch<'0'||ch>'9')&&ch!='-') ch=getchar();
	if(ch=='-') o=-1,ch=getchar();
	while(ch>='0'&&ch<='9') x=x*10+ch-'0',ch=getchar();
	return x*o;
}

int n,T,tt,ans;
pii a[N];
multiset<int> s;
ll sum[N];

bool cmp(pii a,pii b) {
	return 1ll*a.se*b.fi<1ll*a.fi*b.se;
}

int main() {
	cin>>n>>T;++T;
	for(int i=1;i<=n;i++) a[i].fi=gi()+1,a[i].se=gi()+1;
	sort(a+1,a+n+1,cmp);
	//for(int i=1;i<=n;i++) cerr<<a[i].fi<<' '<<a[i].se<<'\n';
	s.insert(1);
	for(int i=1;i<=n;i++) {
		if(a[i].fi>=2) {
			int now=2;vector<pii> vec;
			while(1) {
				auto it=s.lower_bound(now);
				if(it==s.end()) break;
				auto pre=it;--pre;
				if(1ll*a[i].fi*(*pre)+a[i].se<*it) vec.pb(mp(*it,1ll*a[i].fi*(*pre)+a[i].se));
				now=(*it)<<1;
			}
			ll tmp=1ll*a[i].fi*(*s.rbegin())+a[i].se;
			if(tmp<=T) s.insert(tmp);
			for(auto x:vec) {
				//assert(s.find(x.fi)!=s.end());
				s.erase(s.find(x.fi)),s.insert(x.se);
			}
		}
		else break;
		//for(auto x:s) cerr<<x<<' ';
		//cerr<<'\n';
	}
	for(int i=1;i<=n;i++) if(a[i].fi==1) sum[++tt]=a[i].se;
	sort(sum+1,sum+tt+1);
	for(int i=1;i<=tt;i++) sum[i]+=sum[i-1];
	auto it=s.begin();
	//cerr<<T<<endl;
	for(int i=0,j=tt;it!=s.end();i++) {
		while(*it+sum[j]>T) --j;
		//cerr<<*it<<' '<<sum[j]<<'\n';
		ans=max(ans,i+j);++it;
	}
	cout<<ans;
	return 0;
}

