void solve(){
    int n, t;
    cin >> n >> t;
    vector<int> zero;
    vector<pair<int, int>> others;
    REP(i, n) {
        int a, b;
        cin >> a >> b;
        if (a == 0) {
            zero.push_back(b);
        }
        else {
            if (b <= t) {
                others.push_back(mp(a, -b));
            }
        }
    }
    sort(ALL(zero));
    sort(ALL(others));
    reverse(ALL(others));
    int final_napsack[50] = {};
    REP(i, 50) {
        final_napsack[i] = t + 1;
    }
    final_napsack[0] = 0;
    REP(i, others.size()) {
        others[i].second *= -1;
    }
    int N = others.size();
    if (N != 0) {
        while (clock() <= 1.9 * CLOCKS_PER_SEC) {
            int napsack[50] = {};
            REP(i, 50) {
                napsack[i] = t + 1;
            }
            napsack[0] = 0;
            REP(i, others.size()) {
                for (int q = 40; q >= 0; --q) {
                    if (napsack[q] == t + 1) continue;
                    int next = (napsack[q] + 1LL);
                    next *= (others[i].first + 1LL);
                    next += others[i].second;
                    napsack[q + 1] = min(napsack[q + 1], next);
                }
            }
            REP(q, 50) {
                final_napsack[q] = min(final_napsack[q], napsack[q]);
            }
            REP(j, 50000) {
                int a = xor128() % N;
                int b = xor128() % N;
                swap(others[a], others[b]);
            }
        }
    }
    int goi = 0;
    REP(q, 40) {
        int now = final_napsack[q] + 1LL;
        if (now > t) continue;
        int ans = q;
        for (int q = 0; q < zero.size(); ++q) {
            now += zero[q];
            if (now <= t) ans++;
        }
        goi = max(goi, ans);
    }
    cout << goi << endl;
}

