int n,a[N],b[N],T,p[N],ans;
ll s[N],dp[33];
int main(){
	n=read(),T=read();
	for(int i=1;i<=n;++i){
		a[i]=read()+1,b[i]=read()+a[i],p[i]=i;
	}
	sort(p+1,p+n+1,[&](int i,int j){
		return a[i]>a[j];
	});
	int m=n;
	while(m&&!a[p[m]])--m;
	sort(p+1,p+m+1,[&](int i,int j){return 1LL*b[i]*(a[j]-1)<1LL*b[j]*(a[i]-1);});
	sort(p+m+1,p+n+1,[&](int i,int j){return b[i]<b[j];});
	for(int i=1;i<=n-m;++i){
		s[i]=s[i-1]+b[p[i+m]];
	}
	for(int i=1;i<=30;++i){
