int main(){
    int N, T;
    cin >> N >> T;
    vector<pair<int64_t, int64_t>> AB;
    vector<int64_t> B0;
    for(int i=0; i<N; i++){
        int64_t a, b;
        cin >> a >> b;
        if(a > 0){
            AB.emplace_back(a, b);
        }else{
            B0.push_back(b);
        }
    }
    sort(AB.begin(), AB.end(), [](auto x, auto y){ return x.first * (y.second+1) > y.first * (x.second+1); });
    sort(B0.begin(), B0.end());
    int sz = AB.size();

    int64_t dp[50];
    for(int j=0; j<=35; j++) dp[j] = T+1;
    dp[0] = 0;
    for(int i=0; i<sz; i++){
        int64_t a = AB[i].first, b = AB[i].second;
        for(int j=34; j>=0; j--){
            int64_t t = dp[j]+1 + a*(dp[j]+1) + b;
