        }
    }

    int ans = 0;
    for(int j=0; j<=35; j++) if(dp[j] <= T){
        int res = j;
        int64_t t = dp[j];
        for(int64_t b : B0) if(t+1+b <= T){
            res++;
            t += 1+b;
        }
        ans = max(ans, res);
    }
    cout << ans << endl;
