int GetMinWaitTime( int* a, int* b, int N, int time, int shopCount, int *WentShopList );

using namespace std;
int main(void) {

	//入力
	int N = 0; //店の数
	int T = 0; //閉店時刻

	scanf("%d %d", &N, &T);

	int *a = NULL;
	int *b = NULL;

	a = (int*)malloc(sizeof(int)*N);
	b = (int*)malloc(sizeof(int)*N);

	for(int ii = 0; ii < N; ii++ ) {
		scanf("%d %d", &a[ii], &b[ii]);
	}

	int *WentShopList = NULL;
	WentShopList = (int*)malloc(sizeof(int)*N);
	//初期化
	for(int ii = 0; ii < N; ii++ ) {
		WentShopList[ii] = -1;
	}

	int time = 1;
	int shopCount = 0;
	for(int ii = 0; ii < N; ii++) {
		int minWaitTime = 0;

		//最小の待ち時間を取得する
		minWaitTime = GetMinWaitTime( a, b, N, time, shopCount, WentShopList );
		if( minWaitTime < 0 ) {
			break;
		}

		//閉店時間未満なら
		if( time <= ( (T + 0.5) - minWaitTime ) ) {
			time = time + minWaitTime + 1;
			shopCount++;
		}
		else {
			break;
		}

	}

	//出力
	cout << shopCount;

	//領域開放
	if( WentShopList != NULL ) {
		free(WentShopList);
	}

	if( b != NULL ) {
		free(b);
	}

	if( a != NULL ) {
		free(a);
	}

	return 0;
}

int GetMinWaitTime( int* a, int* b, int N, int time, int shopCount, int *WentShopList ) {
	//入力チェック
	if( a == NULL ) {
		return -1;
	}

	if( b == NULL ) {
		return -1;
	}

	if( time < 0 ) {
		return -1;
	}

	if( shopCount < 0 ) {
		return -1;
	}

	if( WentShopList == NULL ) {
		return -1;
	}


	int minTime = -1;
	int shopNumber = 1;
	for( int ii = 0; ii < N; ii++ ) {

		//今まで行ったことがある店か確認する
		int shopDualFlag = 0;
		for( int jj = 0; jj < N; jj++ ) {

			if( WentShopList[jj] == ii + 1 ) {
				shopDualFlag++;
				break;
			}
		}

		//今まで行ったことのない店の時
		if( shopDualFlag == 0 ) {
			int tmpMinTime = 0;
			tmpMinTime = a[ii] * time + b[ii];

			if( (minTime == -1) || ( tmpMinTime < minTime ) ) {
				minTime = tmpMinTime;
				shopNumber = ii + 1;
			}

		}

	}

	//行く店を登録する
	WentShopList[shopCount] = shopNumber;

	return minTime;


}

