int const nax = 3e5 + 10;
int const Magic = 32;

/**
Some Math note
Let's the last time visit be t
apply (ax, bx) -> (ay, by)
the waiting time of first round would be
ax(t + 1) + bx -> ends at
t + (ax)(t + 1) + bx + 1
apply again
ay(t) + (ax)(ay)(t + 1) + aybx + ay + by + t + (ax)(t + 1) + bx + 1
ax(t) + (ax)(ay)(t + 1) + axby + ax + bx + t + (ay)(y + 1) + by + 1

cut equal term
aybx + ay(t) + ax(t) + ay + by + bx
axby + ax(t) + ay(t) + ax + bx + by
aybx + ay <= axby + ax
ay / (by + 1) <= (ax) / (bx + 1)
So sorted by this comparator does make sense

*/

struct Item {
    ll a, b;

    Item () : a () ,b () {}
    Item (ll a, ll b) : a (a), b (b) {}

    void read () {
        scanf("%lld %lld", &a, &b);
    }

    friend bool operator < (const Item & x, const Item & y) {
        return y.a * x.b + y.a < x.a * y.b + x.a;
    }
};
vector<Item> it;
vector<int> z;
int n;
int T;
ll dp[Magic + 1];


int main () {
    scanf("%d %d", &n, &T);
    for (int i = 1 ; i <= n ; ++ i) {
        Item I;
        I.read();
        if (I.a == 0) z.push_back(I.b);
        else it.push_back(I);
    }
    sort(it.begin(), it.end());
    sort(z.begin(), z.end());
    ll const inf = 1e18;
    fill(dp + 1 , dp + Magic + 1, inf);
    for (Item &i : it) {
        for (int v = Magic - 1; v >= 0 ; -- v) {
            if (dp[v] > T ) continue;
            ll c = (dp[v] + 1) * i.a + i.b + dp[v] + 1;
            if (c <= T)
            dp[v + 1] = min(dp[v + 1], c);
        }
    }
    int ans = 0;
    for (int v = 0 ; v <= Magic; ++ v) {
        if (dp[v] > T) continue;
        int res = v;
        for (int i : z) {
            if (dp[v] + i + 1 <= T) {
                dp[v] += i + 1;
                ++ res;
            }
        }
        ans = max(ans, res);
    }
    printf("%d\n", ans);
}
