using namespace std;
typedef pair<llint, llint> P;

struct CHT{
	deque<P> deq;
	deque<llint> id;

	void init(){
		deq.clear();
		id.clear();
	}
	//assume a1 >= a2 >= a3
	bool check(P p1, P p2, P p3)
	{
		llint a1 = p1.first, b1 = p1.second;
		llint a2 = p2.first, b2 = p2.second;
		llint a3 = p3.first, b3 = p3.second;
		return (a2-a1)*(b3-b2) >= (b2-b1)*(a3-a2);
	}
	llint calc(P p, llint x){
		return p.first * x + p.second;
	}

	void add(llint a, llint b, llint x){ //slopes must be monotone decreasing
		P p = make_pair(a, b);
		while(deq.size() >= 2 && check(deq[(int)deq.size()-2], deq[(int)deq.size()-1], p)) deq.pop_back(), id.pop_back();
		deq.push_back(p);
		id.push_back(x);
	}
	llint query(llint x){ //queries must be monotone increasing
		while(deq.size() >= 2 && calc(deq[0], x) >= calc(deq[1], x)) deq.pop_back(), id.pop_back();
		if(deq.size() == 0) return inf;
		return calc(deq.front(), x);
	}
};


llint n, T;
CHT cht;
llint a[200005], b[200005];
P p[200005];
bool used[200005];
vector<P> vec;

void calc()
{
	cht.init();
	for(int i = 1; i <= n; i++){
		if(p[i].first > 0 && used[i] == false){
			cht.add(p[i].first, p[i].second, i);
		}
	}
}

int main(void)
{
	ios::sync_with_stdio(0);
	cin.tie(0);

	cin >> n >> T;
	for(int i = 1; i <= n; i++){
		cin >> a[i] >> b[i];
		p[i] = P(a[i], b[i]);
	}
	sort(p+1, p+n+1);
	reverse(p+1, p+n+1);

	for(int i = 1; i <= n; i++){
		if(p[i].first == 0) vec.push_back(P(p[i].second, i));
	}
	sort(vec.rbegin(), vec.rend());

	cht.init();

	calc();

	llint t = 0, ans = 0;
	for(int i = 1; ; i++){
		t++;
		llint x;
		x = cht.query(t);
		//cout << t << " " << x << endl;
		if(vec.size() > 0){
			x = min(x, vec.back().first);
		}
		//cout << x << endl;
		if(vec.size() > 0 && x == vec.back().first){
			used[vec.back().second] = true;
			vec.pop_back();
		}
		else{
			used[cht.id.front()] = true;
			calc();
		}
		if(x >= inf) break;
		t += x;
		if(t > T) break;
		ans++;
	}
	cout << ans << endl;

	return 0;
}

