bool mycomp(pii a, pii b) {
  return a.first * (b.second + 1) < b.first * (a.second + 1);
}

void solve() {
  int n, t; cin >> n >> t;
  vector<pii> arr(n);
  rep(i,n) cin >> arr[i];
  sort(RALL(arr), mycomp);

  Graph<ll> dp(32, vl(n+1, t+1));
  dp[0] = vl(n+1, 0);
  int zero = n;
  rep(i,n) {
    if (arr[i].first == 0) {
      zero = i;
      break;
    }
    for (int j=1; j<dp.size(); ++j) {
      chmin(dp[j][i+1], min(dp[j][i], (dp[j-1][i] + 1) * (arr[i].first + 1) + arr[i].second));
    }
  }

  vl nowait(n-zero);
  rep(i,nowait.size()) nowait[i] = arr[i+zero].second + 1;
  sort(ALL(nowait));
  rep(i,nowait.size()-1) nowait[i+1] += nowait[i];

  int ans = 0;
  rep(i,dp.size()) {
    if (dp[i][zero] > t) break;
    int cnt = upper_bound(ALL(nowait), t - dp[i][zero]) - nowait.begin();
    chmax(ans, i + cnt);
  }
  cout << ans << endl;
}


