    if (i > 0) zero[i] += zero[i - 1];
  }
  vector<int> idx(n);
  iota(ALL(idx), 0);
  sort(ALL(idx), [&](int l, int r) { return 1LL * a[l] * (b[r] + 1) > 1LL * a[r] * (b[l] + 1); });
  // REP(i, n) cout << idx[i] << " \n"[i + 1 == n];
  vector<vector<ll> > dp(n + 1, vector<ll>(X + 1, INF));
  dp[0][0] = 0;
  REP(i, n) REP(j, X + 1) {
    chmin(dp[i + 1][j], dp[i][j]);
    if (j + 1 <= X) chmin(dp[i + 1][j + 1], dp[i][j] + 1 + (dp[i][j] + 1) * a[i] + b[i]);
  }
  int ans = 0;
  REP(j, X + 1) {
    if (dp[n][j] <= t) chmax(ans, j + upper_bound(ALL(zero), t - dp[n][j]) - zero.begin());
  }
  cout << ans << '\n';
  return 0;
}

