    ll tmp_count = i;
    for(int j = 0; j < b.size(); ++j){
      if(cur + b[j] > T)break;
      cur += b[j];
      ++tmp_count;
    }
    if(count < tmp_count){
      count = tmp_count;
    }
  }

  cout << count << endl;

  return 0;
}

