    a=stores[i].first;
    b=stores[i].second;
    for(ll j=num;j>-1;--j) {
      if((dp[j]+1)*a+b<T+0.5) dp[j+1]=min(dp[j+1],(dp[j]+1)*a+b);
    }
  }
  rep(i,num) {
    if(dp[i]>T) continue;
    ll t_tmp=dp[i],ans_=i;
    for(ll j:B) {
      if(t_tmp+j+1<T+0.5) {t_tmp+=b+1;ans_++;}
      else break;
    }
    ans=max(ans,ans_);
  }
  print(ans);
  return 0;
}

