  };
  std::vector<shop_t> s(n);
  for (auto &e : s) {
    std::cin >> e.a >> e.b;
    e.a += 1;
    e.b += 1;
  }
  std::sort(s.begin(), s.end(), [](const auto &l, const auto &r) {
    u64 lf = r.a * l.b + r.b;
    u64 rf = l.a * r.b + l.b;
    return lf < rf;
  });
  constexpr usize dprem = 100;
  std::vector<u64> dp(dprem, t + 2);
  dp[0] = 1;
  std::vector<u64> bs;
  for (const auto &e : s) {
    if (e.a == 1) {
      bs.push_back(e.b);
      continue;
    }
    for (const usize i : revrep(1, dprem)) {
      chmin(dp[i], dp[i - 1] * e.a + e.b);
    }
  }
  std::sort(bs.begin(), bs.end());
  usize ans = 0;
  for (const usize i : rep(0, dprem)) {
    usize cur = i;
    for (const auto e : bs) {
      if (dp[i] + e <= t + 1) {
        dp[i] += e;
        cur += 1;
      }
    }
    if (dp[i] <= t + 1) {
      chmax(ans, cur);
    }
  }
  std::cout << ans << std::endl;
}

