struct Line
{
	int ind;
    ll a;
    ll b;

    Line(int _ind, ll _a, ll _b){
    	ind = _ind;
    	a = _a;
    	b = _b;
    }

    bool operator < (const Line& l2) const
    {
    	if(b*(l2.a-1) == l2.b*(a-1)) return b < l2.b;
        return b*(l2.a-1) < l2.b*(a-1);
    }
};

ll a[200005];
ll b[200005];
ll slope[200005];
ll inter[200005];
vector<Line> sot;
ll dp[200005]; //lowest time, just finished store i. min with T+1
ll ndp[200005];
ll csum[200005];

int main() {
	setIO();
	int N;
	ll T;
	cin >> N >> T;
	for(int i = 1; i <= N; i++){
		cin >> a[i] >> b[i];
		slope[i] = a[i]+1;
		inter[i] = a[i]+b[i]+1;
		sot.pb(Line(i, slope[i], inter[i]));
	}
	sort(all(sot));
	/*for(auto u: sot){
		ps(u.a, u.b);
	}*/
	ll curtim = 0;
	int curind = 0;
	while(curtim <= T && curind < sz(sot)){
		int val = sot[curind].ind;
		curtim*=slope[val];
		curtim+=inter[val];
		curind++;
	}

	for(int i = 0; i < N; i++){
		slope[i+1] = sot[i].a;
		inter[i+1] = sot[i].b;
	}



	for(int i = 0; i <= N; i++){
		dp[i] = T+1;
		ndp[i] = T+1;
	}
	dp[0] = 0;
	for(int i = 1; i <= 40; i++){
		ll curmin = dp[0];
		for(int j = 1; j <= N; j++){
			ndp[j] = curmin*slope[j]+inter[j];
			ckmin(ndp[j], T+1);
			curmin = min(curmin, dp[j]);
		}
		bool allT = true;
		for(int j = 0; j <= N; j++){
			//cout << ndp[j] << " ";
			if(ndp[j] != T+1) allT = false;
			dp[j] = ndp[j];
			ndp[j] = T+1;
		}
		//cout << "\n";
		if(allT == true){
			ps(i-1);
			return 0;
		}
	}
	int ans = 40;
	for(int i = 1; i <= N; i++){
		if(slope[i] > 1){
			assert(dp[i] == T+1);
			continue;
		}
		csum[i] = csum[i-1]+inter[i];
	}
	for(int i = 1; i <= N; i++){
		if(dp[i] == T+1) continue;
		//i+1.....N
		if(csum[N]-csum[i]+dp[i] <= T){
			ans = max(ans, 40+N-i);
			continue;
		}
		if(dp[i]+inter[i+1] > T){
			continue;
		}
		int lo = i+1;
		int hi = N;
		while(lo < hi){
			int mid = (lo+hi)/2+1;
			if(csum[mid]-csum[i]+dp[i] <= T){
				lo = mid;
			}
			else hi = mid-1;
		}
		ans = max(ans, lo-i+40);
	}
	ps(ans);
}

