        auto [a, b] = shop[i];
        REP(j, 39) {
            ll t = dp[j].query(0, i + 1);
            if (t > T) continue;
            t += 1;
            t += ll(a) * t + b;
            dp[j + 1].update(i + 1, t);
        }
    }

    int b_sz = B_const_acc.size();
    int res = 0;
    REP(j, 40) {    // j店舗回った
        ll t = dp[j].query(0, sz + 1);
        if (t > T) continue;
        ll b = (b_sz > 0) ? LEQ(B_const_acc, T - t) : 0;
        chmax(res, j + b);
    }
