pear<x, y> make_pear(x a, y b) {
	pear<x, y> dr;
	dr.f = a;
	dr.s = b;
	return dr;
}

bool operator>(pear<int, int> a, pear<int, int> b) {
	if(a.f == 0 && b.f == 0) {
		if(a.s > b.s) {
			return 1;
		} else {
			return 0;
		}
	} else if(a.f == 0) {
		return 1;
	} else if(b.f == 0) {
		return 0;
	} else if((long long)a.f * (b.s + 1) < (long long)b.f * (a.s + 1)) {
		return 1;
	}
	return 0;
}

bool operator==(pear<int, int> a, pear<int, int> b) {
	if((long long)a.f * (b.s + 1) == (long long)b.f * (a.s + 1)) {
		return 1;
	}
	return 0;
}

bool operator<(pear<int, int> a, pear<int, int> b) {
	if(a > b || a == b) {
		return 0;
	}
	return 1;
}

bool operator<=(pear<int, int> a, pear<int, int> b) {
	if(a > b) {
		return 0;
	}
	return 1;
}

bool operator>=(pear<int, int> a, pear<int, int> b) {
	if(a < b) {
		return 0;
	}
	return 1;
}

