int n;
ll T;


void relax(ll &x, ll y) {
    x = min(x, y);
}


int main() {
    ios_base::sync_with_stdio(false); cin.tie(0);  cout.tie(0);

    cin>>n>>T;
    vector<store> v;
    vector<ll> B;
    for (int i=0; i<n; i++) {
	store s;
