	} else {
	    v.push_back(s);
	}
    }


    sort(v.begin(), v.end());

    const int N = 50; // > 1e9
    // a(aT+b+1)+b -> a^i -> exponential time increase

    vector<ll> dp(N+1, inf);
    dp[0] = 0;

    for (int i=0; i<(int)v.size(); i++) {
	for (int j=N; j>=0; j--) {
	    if (dp[j] < T) {
		relax(dp[j+1], dp[j] + 1 + ((dp[j]+1)*v[i].a + v[i].b));
	    }
	}
    }



    sort(B.begin(), B.end());
    vector<ll> cost;
    cost.push_back(0);
    for (int i=1; i<(int)B.size(); i++) {
	B[i] += B[i-1];
    }
    for (int i=0; i<(int)B.size(); i++) {
	cost.push_back((i+1) + B[i]);
    }


    int hi = 0;
    for (int i=0; i<=N; i++) {
	if (dp[i] <= T) {
	    ll leftover = T-dp[i];
	    auto iter = std::prev(upper_bound(cost.begin(), cost.end(), leftover));
	    int take = i + (iter-cost.begin());
	    //watch(iter-cost.begin());
	    hi = max(hi, take);
	}
    }

    cout<<hi<<endl;    
    return 0;
}

