struct UnionFindTree{
    vector<int> v;
    vector<int> rank;

    UnionFindTree(int n): v(n, -1), rank(n, 0){}
    int Find(int x){
        if(v[x] < 0) return x;
        return v[x] = Find(v[x]);
    }
    UnionFindTree(){}
    void Union(int a, int b){
        a = Find(a);
        b = Find(b);
        if(a == b) return;
        if(rank[a] < rank[b]) swap(a, b);
        if(rank[a] == rank[b]) rank[a]++;
        v[b] = a;
    }
};

vector<vector<int>> adj;
vector<int> color;
UnionFindTree uf;
vector<vector<bool>> used;
map<int, vector<int>> c1;
map<int, vector<int>> c2;
void dfs(int v, int state, int col, int par, int prev){
	if(used[v][state]) return;
	used[v][state] = true;
	uf.Union(v, par);
	if(state == 0){
		color[v] = col;
		if(col==1) c1[par].push_back(v);
		else c2[par].push_back(v);
	}
	for(int next: adj[v]){
		if(state!=0 and prev==next) continue;
		dfs(next, (state+1)%3, (state==0)?3-col:col, par, v);
	}
}

