const int N = 200005;

int n, T;
int a[N], b[N];


int main() {

    scanf("%d %d", &n, &T);
    vector<int> t, special;
    for (int i = 1; i <= n; i++) {
        scanf("%d %d", &a[i], &b[i]);
        if (a[i] == 0) {
            special.push_back(i);
        } else {
            t.push_back(i);
        }
    }
    sort(t.begin(), t.end(), [&](int w, int u) { return a[w] > a[u]; });

    vector<int> dp;
    dp.push_back(0);
    for (int w : t) {
        for (int i = dp.size() - 1; i >= 0; i--) {
            long long finishTime = (long long)(dp[i] + 1) * a[w] + b[w];
            if (finishTime > T) {
                continue;
            }
            if (dp.size() == i + 1) {
                dp.push_back(finishTime);
            } else {
                dp[i + 1] = min(dp[i + 1], (int)finishTime);
            }
        }
    }

    sort(special.begin(), special.end(), [&](int w, int u) { return b[w] < b[u]; });
    vector<long long> sumPref;
    if (!special.empty()) {
        sumPref.push_back(b[special[0]]);
    }
    for (int i = 1; i < special.size(); i++) {
        sumPref.push_back(sumPref.back() + b[special[i]]);
    }

    int ans = dp.size() - 1;
    for (int i = 0; i < dp.size(); i++) {
        int low = 1;
        int high = special.size();
        int res = 0;
        while (low <= high) {
            int mid = (low + high) / 2;
            long long totalTime = (long long)dp[i] + mid + sumPref[mid - 1];
            if (totalTime <= T) {
                res = mid;
                low = mid + 1;
            } else {
                high = mid - 1;
            }
        }
        ans = max(ans, i + res);
    }

    printf("%d\n", ans);
    return 0;
}

