			if(c > stp) break;
		}
		return c;
	};
	int len = no.size();
	vector<int> used(len, 0);
	int m = 0;
	vector<int> done;
	for(int i = 0; i < len; i++){
		m++;
		int option = 1<<30, ch = -1;
		vector<int> ndone;
		int sz = done.size();
		using ll = long long;
		auto M = create<pair<ll, ll>>(sz, sz);
		for(int j = 0; j < sz; j++){
			pair<ll,ll> now = {1, 0};
			for(int k = j; k < sz; k++){
				now.first  *= (no[done[k]].first + 1);
				now.second *= (no[done[k]].first + 1);
				now.second += no[done[k]].first + no[done[k]].second + 1;
				M[j][k] = now;
			}
		}
		for(int j = 0; j < len; j++){
			if(!used[j]){
				for(int k = 0; k <= done.size(); k++){
					ll v = 0;
					if(k){
						v = M[0][k - 1].second;
					}
					v = (no[j].first + 1) * (v + 1) + no[j].second;
					if(k < done.size()){
						v *= M[k][done.size() - 1].first;
						v += M[k][done.size() - 1].second;
					}
					if(option > v){
						option = v;
						ch = j;
						vector<int> now = done;
						now.insert(now.begin() + k, j);
						ndone = now;
					}
				}
			}
		}
		if(option > T) break;
		// cout << "opt " << option << '\n';
		used[ch] = 1;
		m = option;
		done = ndone;
		int p = lower_bound(sums.begin(), sums.end(), T - m + 1) - sums.begin();
		ans = max(ans, p + i + 1);
	}
	cout << ans << '\n';
	return 0;
}

