class Data
{
public:
    int a, b;
    bool operator<(const Data& other) const
    {
        long long x = other.a * (b + 1LL);
        long long y = a * (other.b + 1LL);
        if(x != y)
            return x < y;
        else
            return b < other.b;
    }
};

const int MAX = 50;

int main()
{
    int n, t;
    cin >> n >> t;
    vector<Data> v(n);
    for(int i=0; i<n; ++i)
        cin >> v[i].a >> v[i].b;
