    vector<long long> dp(MAX+1, t+1);
    dp[0] = 0;
    for(int i=0; i<n; ++i){
        if(v[i].a == 0)
            continue;
        for(int j=MAX-1; j>=0; --j){
            long long x = dp[j] + 1 + (dp[j] + 1) * v[i].a + v[i].b;
            dp[j+1] = min(dp[j+1], x);
        }
    }

    int ans = 0;
    while(dp[ans+1] <= t)
        ++ ans;
    long long x = dp[ans];
    for(int i=0; i<n; ++i){
        if(v[i].a == 0 && x + v[i].b + 1 <= t){
            x += v[i].b + 1;
            ++ ans;
        }
    }
