void update(int k,int l,int r,int p,int v){
	if(l==r)
		t[k]+=v;
	else{
		int mid=(l+r)>>1;
		if(p<=mid)
			update(lson,l,mid,p,v);
		else
			update(rson,mid+1,r,p,v);
		pushup(k);
	}
}
int query(int k,int l,int r,int ql,int qr){
	if(ql<=l && r<=qr)
		return t[k];
}
