const int max_n = 200222, inf = 1000111222;

struct state {
    int a, b;
};

int n, t;
vector<int> p, zero;
state a[max_n];

long long get_time(const state &a, const state &b) {
    long long res = 1 + a.a + a.b;
    res += 1;
    res *= b.a + 1;
    res += b.b;
    return res;
}

bool cmp(int x, int y) {
    return get_time(a[x], a[y]) < get_time(a[y], a[x]);
}

int solve(int p[]) {
    long long res = 0;
    for (int i = 0; i < n; ++i) {
        const int id = p[i];
        res = (res + 1) * (a[id].a + 1) + a[id].b;
        if (res > t) {
            return i;
        }
    }
    return n;
}

