    for (int j=1;j<=32;j++) dp[0][j]=inff;

    for (int i=1;i<=n;i++)
    {
        for (int j=1;j<=32;j++)
        {
            dp[i][j]=dp[i-1][j];
            if (dp[i-1][j-1]!=inff) dp[i][j]=min(dp[i][j],dp[i-1][j-1]+1+(dp[i-1][j-1]+1)*A[i]+B[i]);
            if (dp[i][j]>t) dp[i][j]=inff;
        }
    }

    int ans=0;
    for (int j=0;j<=32;j++)
    {
        int tmp=j,now=dp[n][j];
        if (dp[n][j]!=inff)
        {
            for (int i:ttmp)
                if (now+i+1<=t) now+=(i+1),tmp++;
            ans=max(ans,tmp);
        }
    }
    cout<<ans<<endl;
}

