#include <iostream>
#include <vector>
#include <algorithm>
using namespace std;
using ll = long long;

const int H = 40;
ll dp[H];

struct Shop {
	ll a, b;
	Shop(ll av, ll bv) : a(av), b(bv) {}

	bool operator<(const Shop& rhs) const {
		return a * rhs.b > rhs.a * b;
	}
};

int main() {
	ios_base::sync_with_stdio(false);
	cin.tie(0);

	// Increment all b_i's and t by one to account for the time to traverse between stores

	// If we visit stores i and j, and have already spent k time, we spend
	// (a_i k + b_i) + (a_j (a_i k + b_i + k) + b_j)
	// = a_i k + b_i + a_j a_i k + a_j b_i + a_j k + b_j
	// = (a_i k + a_j k + b_i + b_j + a_i a_j k) + a_j b_i

	// So we visit i first if a_j b_i <= a_i b_j
	// that is, a_j / b_j <= a_i / b_i
	// So we visit in decreasing order of a_i / b_i

	// How many stores with a_i > 0 can we visit?
	// We go from k to at least (k + 1) + k >= 2k,
	// thus at most log_2(T)

	// 1 0, 2 1
	// 1 -> 3 -> 11
	// 1 -> 5 -> 11

	int n;
	ll t;
	cin >> n >> t;
	++t;

	dp[0] = 1;
	for (int j = 1; j < H; ++j) dp[j] = t + 1;

	vector<ll> offs = {0};
	vector<Shop> shops;
	for (int i = 0; i < n; ++i) {
		ll a, b;
		cin >> a >> b;
		++b; // Time to move to next shop
		if (a == 0) offs.push_back(b);
		else shops.emplace_back(a, b);
	}
	sort(shops.begin(), shops.end());

	for (auto sp : shops) {
		for (int m = H-2; m >= 0; --m) {
			ll off = dp[m] * (sp.a + 1) + sp.b;
			if (off <= t) dp[m+1] = min(dp[m+1], off);
		}
	}

	sort(offs.begin(), offs.end());
	for (int i = 1; i < (int)offs.size(); ++i) offs[i] += offs[i-1];

	int j = (int)offs.size() - 1;
	int res = 0;
	for (int m = 0; m < H; ++m) {
		while(j >= 0 && dp[m] + offs[j] > t) --j;
		if (j < 0) break;
		res = max(res, m + j);
	}
	cout << res << '\n';
}

