int main() {
  int N, T; std::cin >> N >> T;
  std::vector<std::pair<int,int>> ab;
  std::vector<int> zb;
  for(int i = 0; i < N; ++i) {
    int a, b; std::cin >> a >> b;
    if(a == 0) zb.push_back(b); else ab.emplace_back(a, b);
  }
  std::sort(ab.begin(), ab.end(),
    [&](auto const&l, auto const& r) {
      return (int64_t)l.first*(r.second+1) > (int64_t)r.first*(l.second+1); });
  std::sort(zb.begin(), zb.end());
  int maxP = std::min(N, 32-__builtin_clz(T));
  std::vector<int> dp(maxP+1, T+100);
  dp[0] = 0;
  for(auto const& p: ab) {
    for(int i = maxP-1; i >= 0; --i) if(dp[i]<T) {
      int64_t t = (int64_t)(p.first+1)*(dp[i]+1) + p.second;
      if(t < dp[i+1]) dp[i+1] = t;
    }
  }
  int ans = 0;
  for(int i = 0; i <= maxP; ++i) {
    int t = dp[i];
