			d[shops][j] = d[shops][j - 1];
		}
		rep(shops, 1, k+1) {
			// printf("ab: %d, %d, %d\n", ab[j-1].st, ab[j-1].nd, d[shops - 1][j-1]);
			// printf("%lld or %lld\n", (ll)d[shops][j - 1], 1 + (ll)-ab[j - 1].st * (1 + d[shops - 1][j-1]) + ab[j - 1].nd);
			d[shops][j] = min((ll)d[shops][j - 1], 1 + ab[j - 1].a * (1 + d[shops - 1][j-1]) + ab[j - 1].b);
			// printf("d[%d][%d] = %d\n", j, shops, d[shops][j]);
			if (d[shops][j] <= t) {
				int time_left = t - d[shops][j];
				auto he = besty.lower_bound({time_left + 1, -1}); --he;
				res = max(res, shops + he->nd);
			}
		}
	}
	cout << res << endl;
}

