    ll inf = 1e18;
    int M = 30;
    vvec<ll> dp(N+1,vec<ll>(M+1,inf));
    dp[0][0] = 0;
    int n = N;
    for(int i=0;i<N;i++){
        int id = idx[i];
        if(A[id]==0){
            n = i;
            break;
        }
        for(int j=0;j<M;j++) if(dp[i][j]!=inf){
            dp[i+1][j+1] = min(dp[i][j+1],(A[id]+1)*dp[i][j]+A[id]+B[id]+1);
            dp[i+1][j] = min(dp[i+1][j],dp[i][j]);
        }
    }
    int ans = 0;
    for(int j=0;j<=M;j++) if(dp[n][j]<=T){
        ll t = dp[n][j];
        int now = j;
        for(int i=n;i<N;i++){
            if(t+B[idx[i]]+1<=T){
                t += B[idx[i]]+1;
                now++;
            }else break;
        }
        ans = max(ans,now);
    }
    cout << ans << "\n";
}

