void solve(){
	ll n,t;
	cin>>n>>t;

	vector<P> ab;
	Array bb;//a=0
	REP(i,n){
		ll a,b;
		cin>>a>>b;
		b++;
		if(a==0){
			bb.push_back(b);
		}else{
			ab.push_back({a,b});
		}
	}

	//a>0のパターン
	sort(all(ab),[&](P x, P y){
		return y.first*x.second < x.first*y.second;
	});

	ll m=30;
	Matrix dp(ab.size()+1,Array(m+1,INF));//i番目までにj点回る最小時間
	dp[0][0]=0;
	REP(i,ab.size()){
		ll a=ab[i].first;
		ll b=ab[i].second;
		REP(j,m+1){
			if(dp[i][j]>t) break;
			if(j+1<=m && dp[i][j] + a*dp[i][j]+b<=t) chmin(dp[i+1][j+1],dp[i][j] + a*dp[i][j]+b);
			chmin(dp[i+1][j],dp[i][j]);
		}
	}

	//a=0のパターン
	sort(all(bb));
	Array sum(bb.size()+1,0);
	REP(i,bb.size()) sum[i+1]=sum[i]+bb[i];

	ll ans=0;
