struct T {
  ll a;
  ll b;
};

bool operator < (T f, T s) {
  ll a1 = f.a;
  ll b1 = f.b;
  ll a2 = s.a;
  ll b2 = s.b;
  return b1 * a2 + b2 < b2 * a1 + b1;
}

vector<T> a;
vector<ll> one;
const int N = 40;
const ll inf = (ll) 1e18;
ll mn[N];

ll mult(ll a, ll b) {
  if (a == 0 || b == 0) {
    return 0;
  }
  if (a == inf || b == inf) {
    return inf;
  }
  ll p = a * b;
  if (p % a == 0 && p / a == b && p <= inf) {
    return p;
  } else {
    return inf;
  }
}

ll add(ll a, ll b) {
  return min(inf, a + b);
}

int main() {
  ios::sync_with_stdio(0);
  cin.tie(0);

  cin >> n >> k;
  for (int i = 1; i <= n; i++) {
    ll x, y;
