  sort(a.begin(), a.end());
  sort(one.begin(), one.end());
  mn[0] = 0;
  for (int i = 1; i < N; i++) {
    mn[i] = k + 1;
  }
  for (auto &it : a) {
    for (int i = N - 2; i >= 0; i--) {
      mn[i + 1] = min(mn[i + 1], add(mult(mn[i], it.a), it.b));
    }
  }
  int ret = 0;
  for (int i = 0; i < N; i++) {
    if (mn[i] <= k) {
      int cur = i;
      for (auto &it : one) {
        if (add(mn[i], it) <= k) {
          mn[i] = add(mn[i], it);
          cur++;
        } else {
          break;
        }
      }
      ret = max(ret, cur);
    }
  }
  cout << ret << "\n";
}

