    rest_map[0] = 0;
    LL cum = 0;
    for(LL i = 0; i < rest.size(); ++i){
        cum += rest[i]+1;
        rest_map[cum] = i+1;
    }

    cout << solve(t, rest_map, shop) << endl;
    return 0;
}

