			for (int k=0;k<SZ(V);++k)if (!done[k]){
				pi t = V[k];
				ll c = t.f*time+t.s;
				if (c<opt){
					opt=c;
					in = k;
				}else if (c == opt){
					if (V[k].f > V[in].f){
						opt=c;
						in = k;
					}
				}
			}
			if (opt==INF)break;
			ll c = V[in].f*time+V[in].s;
			done[in] = 1;
			time += c;
			++cnt;
			outs.pb(cnt,time);
		}
		// for (auto k:outs)cout<<k.f<<' '<<k.s<<'\n';
		sort(ALL(zeroes));
		frees.pb(0,0);
		for (auto i : zeroes){
			pi t = frees.back();
			frees.pb(t.f+1, t.s+1+i);
		}
		// cout<<'\n';
		// for (auto i : frees)cout<<i.f<<' '<<i.s<<'\n';

		for (auto i : outs){
			while (SZ(frees) && frees.back().s + i.s > T){
				frees.pop_back();
			}
			if (SZ(frees)) ans = max(ans, frees.back().f + i.f);		
		}
	}
	cout<<ans;
}

