int n,t,a[200004],b[200004],ans,now;
int dp[200004][54];
vector<pair<long double, int>> v;
vector<int> p;
signed main() {
    ios::sync_with_stdio(false);
    std::cin.tie(nullptr);
    cin>>n>>t;
    rep(i,n){
        cin>>a[i]>>b[i];
        if(a[i])v.emplace_back((long double)a[i]/(long double)(b[i]+1),i);
        else p.emplace_back(b[i]+1);
    }
    p.emplace_back(0);
    sort(ALL(v),greater<pair<long double,int>>());
    sort(ALL(p));
    rep(i,p.size()){
        if (i) {
            p[i]+=p[i-1];
        }
    }
    rep(i,v.size()+1){
        rep(j,min(40ll,(int)v.size())+1){
            dp[i][j]=inf;
        }
    }
    dp[0][0]=0;
    rep(i,v.size()){
        rep(j,min(40ll,(int)v.size())){
            if (dp[i][j]>t) {
                continue;
            }
            chmin(dp[i+1][j+1], dp[i][j]+(dp[i][j]+1)*a[v[i].second]+b[v[i].second]+1);
            chmin(dp[i+1][j], dp[i][j]);
        }
    }
    rep(j,min(40ll,(int)v.size())+1){
        if (dp[v.size()][j]>t) {
            break;
        }
        int basho=upper_bound(ALL(p),t-dp[v.size()][j])-p.begin();
        basho--;
        chmax(ans, basho+j);
    }

    cout<<ans<<endl;
}

