struct shop{
    ll a,b;
};
bool comp(shop a,shop b){
    return a.a*(b.b+1)>=b.a*(a.b+1);
}

int main(){fastio
    ll n,t;cin>>n>>t;
    vector<shop>v;
    vector<ll>last;
    rep(i,0,n-1){
        shop s;cin>>s.a>>s.b;
        if(s.a==0){
            last.pb(s.b);
        }else{
            v.pb(s);
        }
    }
    sort(v.begin(),v.end(),comp);
   // for(auto x:v)cout<<x.a<<" "<<x.b<<endl;
    ll M=40;
    ll vs=v.size();
    ll dp[vs+1][M];
    rep(i,0,vs)rep(j,0,M-1)dp[i][j]=inf;
    dp[0][0]=0;
    rep(i,0,vs-1){
        shop s=v[i];
        rep(j,0,M-1){
            chmin(dp[i+1][j],dp[i][j]);
            if(j+1<=M-1)chmin(dp[i+1][j+1],(dp[i][j]+1)*(s.a+1)+s.b);
        }
    }
    ll ans=0;
    SORT(last);
    ll sz=last.size();
    vector<ll>a(sz+1);
    a[0]=0;
    rep(i,0,sz-1){
        a[i+1]=a[i]+(last[i]+1);
    }
    rep(j,0,M-1){
        ll res=t-dp[vs][j];
        if(res<0)continue;
        ll p=POSU(a,res)-1;
        chmax(ans,p+j);
    }
    cout<<ans<<endl;


