inline void read() {}
template <typename Tp1, typename ...Tp2>
inline void read(Tp1 &num, Tp2 &...rest) {
    char c = getchar();
    while (c < '0' || c > '9') c = getchar();
    for (num = 0; c >= '0' && c <= '9'; c = getchar()) num = (num << 1) + (num << 3) + (c ^ '0');
    read(rest...);
}

int main() {
    ll t;
    int n, ans = 0;
    for(read(n, t); n; n--) {
        ll a, b;
        read(a, b);
        num.insert(a);
        minn[a].push(b);
    }
    for (ll tim = 1; tim <= t; tim++) {
        ll id, qtim = INF;
        for (const ll it : num) {
            ll tmp = minn[it].top();
            if (tim * it + tmp < qtim) {
                id = it;
                qtim = tim * it + tmp;
            } 
        }
        if (tim + qtim > t) break;
        ans++; tim += qtim;
        minn[id].pop();
        if (minn[id].empty()) num.erase(id);
    }
    printf("%d\n", ans);
    return 0;
}

