bool cmp(const int &i, const int &j)
{
	return 1LL * (b[i] + 1) * a[j] < 1LL * (b[j] + 1) * a[i];
}
bool cmp2(const int &i, const int &j)
{
	return b[i] < b[j];
}
ll calc(int t, int i)
{
	return 1LL * a[i] * t + b[i];
}
