        return (ld)a.first/(a.second+1)>(ld)b.first/(b.second+1);
    });
    int pt = len+1;
    for(int i=1; i<=len; i++){
        if(arr[i].first){
            pt = i;
            break;
        }
    }
    for(int i=0; i<MAXN; i++) poss[i][0] = true;
    for(int i=pt; i<=len; i++){
        for(int k=1; k<LOGN; k++){
            if(poss[i-1][k]) dp[i][k] = dp[i-1][k], poss[i][k] = true;
            if(poss[i-1][k-1]){
                ll t = dp[i-1][k-1]+1+(dp[i-1][k-1]+1)*arr[i].first+arr[i].second;
                if(poss[i-1][k]) dp[i][k] = min(dp[i][k],t);
                else dp[i][k] = t;
                poss[i][k] = true;
            }
        }
    }
    vector<int> v;
    for(int i=1; i<pt; i++)
        v.pb(arr[i].second);
    sort(all(v));
    for(int k=0; k<LOGN; k++){
        if(!poss[len][k]) continue;
        ll sum = dp[len][k];
        if(sum <= T) res = max(res,k);
        for(int i=0; i<v.size(); i++){
            sum = sum+1+v[i];
            if(sum <= T)
                res = max(res,k+i);
        }
    }
    printf("%d\n",res);
}

