#define SZ(x) (int)(x).size()
template <typename T> using ord_set = tree <T, null_type, less <T>, rb_tree_tag, tree_order_statistics_node_update>;
mt19937 rng(chrono::steady_clock::now().time_since_epoch().count());

const int N = 2e5 + 123, K = 1800;
const ll inf = 1e18;
int n, T;

struct line {
	int k, b;
	line(int K, int B) {
		k = K, b = B;
	}
	ld it(const line & L) {
		assert(k != L.k);
		return (ld)(L.b - b) / (k - L.k);
	}
	ll val(int x) {
		return (ll)k * x + b;
	}
	bool operator < (const line & L) const {
		if (k == L.k)
			return b > L.b;
		return k < L.k;
	}
};

struct hull {
	vector <line> v;
	void add(line L) {
		while (SZ(v) > 0 && v.back().k == L.k) {
			if (v.back().b < L.b) return;
			v.pop_back();
		}
		while (SZ(v) > 1 && L.it(v[SZ(v) - 2]) > v.back().it(v[SZ(v) - 2]))
			v.pop_back();
		v.pb(L);
	}
	ll getmin(int x) {
		if (v.empty()) return inf;
		int l = 0, r = SZ(v) - 1;
		while (l < r) {
			int mid = l + r >> 1;
			if (v[mid].val(x) > v[mid + 1].val(x))
				l = mid + 1;
			else
				r = mid;
		}
		return v[l].val(x);
	}
};

struct block {
	vector <line> v;
	hull ch;
	void build() {
		ch.v.clear();
		for (line i : v)
			ch.add(i);
	}
	void del(int x, ll y) {
		for (int i = 0; i < SZ(v); i++) {
			if (v[i].val(x) == y) {
				v.erase(v.begin() + i);
				break;
			}
		}
		build();
	}
};
block b[N / K + 3];

int main() {
	ios_base::sync_with_stdio(false), cin.tie(NULL);
	#ifdef LOCAL
		freopen("input.txt", "r", stdin);
	#endif

	cin >> n >> T;
	for (int i = 0; i < n; i++) {
		int x, y;
		cin >> x >> y;
		b[i / K].v.pb(line(x, y));
	}
	for (int i = 0; i <= (n - 1) / K; i++) {
		sort(all(b[i].v));
		b[i].build();
	}
	int cur = 0, res = 0;
	for (int it = 0; it < n; it++) {
		cur++;
		int pos = -1;
		ll mn = inf;
		for (int i = 0; i <= (n - 1) / K; i++) {
			ll val = b[i].ch.getmin(cur);
			if (pos == -1 || val < mn)
				pos = i, mn = val;
		}
		if (cur + mn <= T) {
			b[pos].del(cur, mn);
			cur += mn;
			res++;
		}	else break;
	}
	cout << res;
}

