constexpr int SIZE = 40;
int main() {
  cin.tie(0);
  ios::sync_with_stdio(false);
  int n, t;
  cin >> n >> t;
  vector<pll> v(n);
  REP(i, n) cin >> v[i].first >> v[i].second;
  vl dp(SIZE, INF * INF);
  auto comp = [&](pll lhs, pll rhs) {
    return rhs.first * (rhs.second + 1) < lhs.first * (lhs.second + 1);
  };
  sort(ALL(v), comp);
  dp[0] = 0;
  REP(i, n) {
    if (v[i].first == 0) {
      break;
    }
    RREP(j, SIZE - 1) {
      if (dp[j] <= t) {
        chmin(dp[j + 1], dp[j] + 1 + v[i].first * (dp[j] + 1) + v[i].second);
      }
    }
  }
  vl b;
  REP(i, n) {
    if (v[i].first == 0)
      b.push_back(v[i].second + 1);
  }
  sort(ALL(b));
  vl c(b.size() + 1);
  REP(i, b.size()) { c[i + 1] = c[i] + b[i]; }
  ll ans = -1;
  REP(i, SIZE) {
    if (dp[i] <= t) {
      int l = 0, r = c.size();
      while (r - l > 1) {
        int mid = (r + l) / 2;
        if (c[mid] > t - dp[i]) {
          r = mid;
        } else {
          l = mid;
        }
      }
      chmax(ans, i + l);
    }
  }
  cout << ans << endl;
}

