  sort(a+1,a+n+1,cmp);
  for (int i=0;i<C;++i) dp[0][i]=m+1;
  dp[0][0]=0;
  int i=1;
  for (;i<=n;++i){
    if (a[i].x==1) break;
	for (int j=0;j<C;++j) dp[i][j]=min(dp[i-1][j],j?a[i].x*dp[i-1][j-1]+a[i].y:(LL)m);
  }
