#include<bits/stdc++.h>
using namespace std;

typedef long long ll;
const int MAXN = 200010;
const int inf = 0x3f3f3f3f;

struct Node
{
	ll a, b;
	bool operator < (const Node &A) const
	{
		return a * (1 + A.b) > A.a * (1 + b);
	}
}o[MAXN];
ll p[MAXN];

int n, T, cnto, cntp;
ll f[40];

int main()
{
	scanf("%d %d", &n, &T);
	for(int i = 1; i <= n; ++i)
	{
		int x, y; scanf("%d %d", &x, &y);
		if(!x) p[++cntp] = y;
		else o[++cnto] = (Node){x, y};
	}
	sort(p + 1, p + 1 + cntp);
	sort(o + 1, o + 1 + cnto);
	for(int i = 1; i <= cntp; ++i) p[i] += p[i - 1] + 1;
	for(int i = 1; i < 40; ++i) f[i] = inf;
	for(int i = 1; i <= cnto; ++i)
		for(int j = 35; ~j; --j)
		{
			if(f[j] == inf) continue;
			f[j + 1] = min(f[j + 1], (f[j] + 1) * (o[i].a + 1) + o[i].b);
			if(f[j + 1] > T) f[j + 1] = inf;
		}
	int ans = 0;
	for(int i = 0; i <= 35; ++i)
		if(f[i] != inf)
		{
			int x = T - f[i];
			int l = 1, r = cntp, sol = 0, mid;
			while(l <= r)
			{
				mid = (l + r) >> 1;
				if(p[mid] <= x) sol = mid, l = mid + 1;
				else r = mid - 1;
			}
			ans = max(ans, i + sol);
		}
	printf("%d\n", ans);
	return 0;
}

