struct RationalNumber{
  long long a, b;
  RationalNumber(){
    a = 0,b = 1;
  }
  RationalNumber(long long p, long long q):a(p), b(q){
  };
  void reduction(){
    long long g = __gcd(a, b);
    a /= g, b /= g;
  }
  RationalNumber &operator+=(const RationalNumber &x){
    long long q = b / __gcd(b, x.b) * x.b;
    a = a * q / b + x.a * q / x.b;
    b = q;
    reduction();
    return *this;
  }
  RationalNumber &operator-=(const RationalNumber &x){
    long long q = b / __gcd(b, x.b) * x.b;
    a = a * q / b + x.a * q / x.b;
    b = q;
    reduction();
    return *this;
  }
  RationalNumber &operator*=(const RationalNumber &x){
    a *= x.a, b *= x.b;
    reduction();
    return *this;
  }
  RationalNumber &operator/=(const RationalNumber &x){
    a *= x.b, b *= x.a;
    reduction();
    return *this;
  }
  RationalNumber operator+(const RationalNumber &x)const{
    return RationalNumber(*this) += x;
  }
  RationalNumber operator-(const RationalNumber &x)const{
    return RationalNumber(*this) -= x;
  }
  RationalNumber operator*(const RationalNumber &x)const{
    return RationalNumber(*this) *= x;
  }
  RationalNumber operator/(const RationalNumber &x)const{
    return RationalNumber(*this) /= x;
  }
  RationalNumber operator-()const{
    return RationalNumber(-a, b);
  }
  bool operator==(const RationalNumber &x)const{
    return a * x.b == b * x.a;
  };
  bool operator!=(const RationalNumber &x)const{
    return !(*this == x);
  };
  bool operator<(const RationalNumber &x)const{
    return a * x.b < b * x.a;
  }
  bool operator>(const RationalNumber &x)const{
    return a * x.b > b * x.a;
  }
  bool operator<=(const RationalNumber &x)const{
    return *this < x || *this == x;
  }
  bool operator>=(const RationalNumber &x)const{
    return *this > x || *this == x;
  }
};
