const ll MAX = 1e9 + 42;

struct node {
  node(ll a, ll b) : a(a), b(b) {}

  ll a, b;
  bool operator<(const node& other) const {
    return b * other.a < a * other.b;
  }
  ll advance(ll t) const {
    if (t > MAX) return MAX;
    return min(MAX, (a + 1) * t + b);
  }
};

int main() {
#ifdef LOCAL_EXEC
//	freopen("sample.in", "r", stdin);
