#else
  ios_base::sync_with_stdio(false); cin.tie(NULL);
#endif

  int n; ll T; cin >> n >> T;
  vector<node> vals;
  vector<ll> zero;
  while (n--) {
    ll a, b; cin >> a >> b;
    ++b;
    if (a == 0) zero.push_back(b);
    else vals.emplace_back(a, b);
  }
  sort(vals.begin(), vals.end());

  n = vals.size();
  const int LOG = 40;
  vector<vector<ll>> best(n + 1, vector<ll>(LOG, MAX));
  best[0][0] = 0;
  for (int i = 1; i <= n; i++) {
    best[i][0] = 0;
    for (int j = 1; j < LOG; j++) {
      best[i][j] = min(best[i - 1][j], vals[i - 1].advance(best[i - 1][j - 1]));
    }
  }

  sort(zero.begin(), zero.end());
  ll extra = accumulate(zero.begin(), zero.end(), 0ll);
  int ans = 0;
  for (int j = 0, e = zero.size(); j < LOG; j++) {
    ll rem = T - best[n][j];
    if (rem < 0) break;
    while (extra > rem) {
      extra -= zero[--e];
    }
    ans = max(ans, j + e);
  }
  cout << ans << endl;

  return 0;
}

