priority_queue<int, vector<int>, greater<int> > spe;

inline bool cmp(market a, market b)
{
	return b.a * (a.b + 1) < b.b * (a.a + 1);
}

int main()
{
	int n;
	long long T;
	scanf("%d%lld", &n, &T);
	int tt = 1;
	for (int i = 1; i <= n; i++, tt++)
	{
		scanf("%lld%lld", &mar[tt].a, &mar[tt].b);
		if (mar[tt].a == 0)
			spe.push(mar[tt].b + 1), tt--;
	}
	n = tt - 1;
	sort(mar + 1, mar + n + 1, cmp);
	int tn = log2(T);
	f[0] = 0;
	for (int i = 1; i <= tn; i++)
		f[i] = T + 1;
	for (int i = 1; i <= n; i++)
		for (int j = tn; j; j--)
			f[j] = min(f[j], (f[j - 1] + 1) * (mar[i].a + 1) + mar[i].b);
	int total = 0, answer = 0, cnt = 0;
	for (int i = 1; i <= tn; i++)
	{
		if (f[i] > T)
			continue;
		while (!spe.empty() && total + f[i] + spe.top() <= T)
		{
			total += spe.top();
			cnt++;
			spe.pop();
		}
		answer = max(answer, i + cnt);
	}
	printf("%d\n", answer);
	return 0;
}

