int main() {
    int n, T; cin >> n >> T;
    vector<pair<int, int> > A;
    vector<int> B;
    while (n--) {
        int x, y; cin >> x >> y;
        if (x > 0) A.push_back({x, y});
        else B.push_back(y+1);
    }
    sort(A.begin(), A.end(), [](pair<int, int> lhs, pair<int, int> rhs) {
            return (long long)rhs.first * (lhs.second + 1)
                < (long long)lhs.first * (rhs.second + 1);
        });
    sort(B.begin(), B.end());
    const int K = 35;
    vector<int> dp(K, T+1);
    dp[0] = 0;
    for (auto [a, b] : A) {
        for (int k = K-2; k >= 0; k--) {
            if (dp[k] > T) continue;
            long long arr = dp[k] + 1, wait = a * arr + b;
            if (arr + wait < dp[k+1]) dp[k+1] = arr + wait;
        }
    }
    for (int j = 1; j < int(B.size()); j++)
        B[j] = min(T+1, B[j-1] + B[j]);
    int j = B.size() - 1, ans = 0;
    for (int k = 0; k < K; k++) {
        if (dp[k] > T) break;
        while (j >= 0 && B[j] + dp[k] > T) j--;
        ans = max(ans, j + 1 + k);
    }
    cout << ans << endl;
}

