LL solve(LL t, map<LL,LL>& rest_map, vector<pair<LL,LL>>& shop){
    sort(shop.begin(), shop.end(), [](pair<LL,LL>& op1, pair<LL,LL>& op2){ return op1.first*(op2.second+1) >= op2.first*(op1.second+1); });
    vector<vector<LL>> dp(shop.size()+1, vector<LL>(30, t+1));
    dp[0][0] = 0;

    for(LL i = 0; i < shop.size(); ++i){
        for(LL j = 0; j < 29; ++j){
            dp[i+1][j] = min(dp[i+1][j], dp[i][j]);
            LL cost = (dp[i][j]+1)*shop[i].first + shop[i].second;
            dp[i+1][j+1] = min(dp[i+1][j+1], dp[i][j] + cost);
        }
    }

    LL ans = 0;
    for(LL i = 0; i < 30; ++i){
        LL rest = t - dp[shop.size()][i];
        if(rest < 0) continue;
        auto it = rest_map.lower_bound(rest);
        if(it == rest_map.end() || it->first > rest){
            --it;
        }
        ans = max(ans, i + it->second);
    }
    /*
    cerr << rest_map << endl;
    cerr << shop << endl;
    cerr << dp << endl;
    */
    return ans;
}


