    vector<pair<LL,LL>> shop;
    for(LL i = 0; i < n; ++i){
        LL a, b;
        cin >> a >> b;
        if(a == 0){
            rest.push_back(b);
        }else{
            shop.emplace_back(a, b);
        }
    }
    sort(rest.begin(), rest.end());
    map<LL,LL> rest_map;
    rest_map[0] = 0;
    LL cum = 0;
    for(LL i = 0; i < rest.size(); ++i){
        cum += rest[i]+1;
        rest_map[cum] = i+1;
    }

    cout << solve(t, rest_map, shop) << endl;
    return 0;
}

