typedef struct _tmp_t {
  int64    a;
  int64    b;
  int64    c;  
} tmp_t;


int compare_a(const void *a, const void *b)
{
  tmp_t *x;
  tmp_t *y;

  x = (tmp_t *)a;
  y = (tmp_t *)b;

  if (x->c < y->c) return -1;
  if (x->c > y->c) return 1;

  if (x->a < y->a) return -1;
  if (x->a > y->a) return 1;

  return 0;
}

int compare_b(const void *a, const void *b)
{
  tmp_t *x;
  tmp_t *y;

  x = (tmp_t *)a;
  y = (tmp_t *)b;

  if (x->b > y->b) return 1;
  if (x->b < y->b) return -1;

  return 0;
}

int compare_n(const void *a, const void *b) {
  int64 *x, *y;
  x = (int64 *)a;
  y = (int64 *)b;

  if (*x > *y) return 1;
  if (*x < *y) return -1;
  return 0;
}

void qsort_a (tmp_t *array, int size)
{
  qsort(array, size, sizeof(tmp_t), compare_a);
}

void qsort_b (tmp_t *array, int size)
{
