  tmp_t *y;

  x = (tmp_t *)a;
  y = (tmp_t *)b;

  if (x->c < y->c) return -1;
  if (x->c > y->c) return 1;

  if (x->a < y->a) return -1;
  if (x->a > y->a) return 1;

  return 0;
}

int compare_b(const void *a, const void *b)
{
  tmp_t *x;
  tmp_t *y;

  x = (tmp_t *)a;
  y = (tmp_t *)b;

