long long b;
}sd;

int sdsortfnc(const void *x,const void *y){
  long long ax=(((sd*)x)->a);
  long long bx=(((sd*)x)->b);
  long long ay=(((sd*)y)->a);
  long long by=(((sd*)y)->b);
  long long px=ay+ay*bx;
  long long py=ax+by*ax;
  if(ax==0 && ay==0){
    if(bx<by){return -1;}
    if(bx>by){return 1;}
    return 0;
  }
  if(ax==0){return 1;}
  if(ay==0){return -1;}
  if(px==py){return 0;}
  if(px<py){return -1;}
  if(px>py){return 1;}
}

