import java.util.*

fun main(args: Array<String>) {
    val (n, t) = readLine()!!.split(' ').map { it.toInt() }

    val shopList = mutableListOf<Shop>()

    repeat(n) {
        val (a, b) = readLine()!!.split(" ").map { it.toInt() }
        shopList.add(Shop(a, b))
    }


    val waitTimes = Array(n + 1) { IntArray(t + 1) { 0 } }
    for (i in 0 until n) {
        for (j in 0..t) {
            waitTimes[i][j] = shopList[i].wait(i)
        }
    }

    var visitCount = 0
    var i = 1
    while (i <= t) {
        val notVisitedList = shopList.filter { !it.visited }.map { it to it.wait(i) }
        val min = notVisitedList.minBy { it.second }
        if (min != null) {
            min.first.visited = true
            if (i + min.first.wait(i) <= t ) {
                visitCount++
            }
            i += min.first.wait(i) + 1
        } else break
    }

    println(visitCount)
}

class Shop(val waitA: Int, val waitB:Int) {
    var visited = false
    fun wait(t: Int) = waitA * t + waitB
}

