class Store(val a: Long, val b: Long) : Comparable<Store> {
    override fun compareTo(o: Store): Int {
        if (a == 0L && o.a == 0L)
            return b.compareTo(o.b)
        return ((a * (o.b + 1)).compareTo(o.a * (b + 1)))
    }
}

val mem = Array(30) { Array(200010) { -1L } }
fun dp(j: Int, id: Int, stores: Array<Store>): Long {
    if (stores.size == id) {
        return (if (j == 0) 0 else 1L.shl(30))
    }
    if (mem[j][id] != -1L) return mem[j][id]
    var w = 1L.shl(30)
    if (j > 0) {
        val t = dp(j - 1, id + 1, stores) + 1
        w = Math.min(w, t + t * stores[id].a + stores[id].b)
    }
    w = Math.min(w, dp(j, id + 1, stores))
    mem[j][id] = w
    return w
}

fun main(args: Array<String>) {

    val (N, T) = readInts(2)
    val stores = (0 until N).map {
        val (a, b) = readLongs(2)
        Store(a, b)
    }.sorted().toTypedArray()

    val (firstNonZero) = listOf(stores.indexOfFirst { it.a != 0L }).map { if (it == -1) N else it }


    var mx = 0
    for (i in 0..N) {
        var t = dp(i, firstNonZero, stores)
        if (t > T) break
        var cnt = i
        for (s in 0 until firstNonZero) {
            if (t + stores[s].b + 1 <= T) {
                t += stores[s].b + 1
                cnt += 1
            }
        }
        mx = Math.max(mx, cnt)
    }
    println(mx)






}

