    val AB = Array<Mise>(N)  { Mise(listOfInt()) }.sortedWith(compareBy({ it.b }, { it.a }))
    val f = BooleanArray(N)
    var t = 0
    var ans = 0
//System.err.println(AB)
    while (t <= T) {
        val w = mutableListOf<Pair<Int, Int>>()
        for (n in 0 until N) {
            if (!f[n]) w.add(n to t + 1 + AB[n].a * (t + 1) + AB[n].b)
        }
        val mise = w.minBy { it.second }
        if (mise != null) {
            val (n, w) = mise
            if (w <= T) {
                f[n] = true
                t = w
                ans += 1
//System.err.println("n:$n t:$t")
            } else break
        } else break
    }
    println(ans)
}
