fun main(args: Array<String>) {
    val lines = mutableListOf<String>()
    val firstLine = readLine()!!
    val n = firstLine.split(" ")[0].toInt()

    lines.add(firstLine)
    repeat(n) {
        lines.add(readLine()!!)
    }

    println(answer(lines))
}

fun String.splitSpace() = this.split(" ")
fun String.splitSpaceLong() = this.splitSpace().map { it.toLong() }

fun answer(lines: List<String>): String {
    val (n, tStr) = lines[0].splitSpace()
    val t = tStr.toLong()
    val shopList = ShopList(
        lines.subList(1, lines.size)
            .map { it.splitSpaceLong() }
            .mapIndexed { i, sp -> Shop(i.toLong(), sp[0], sp[1]) }
            .toMutableList()
    )

    val takahashi = Takahashi(0, 0)
    val shopClosedTime = t
    for (i in 0..shopClosedTime) {
        if (takahashi.isWaiting()) {
            takahashi.waitUnit(1)
        } else {
            if (shopList.empty()) {
                takahashi.addCount()
                break
            }

            takahashi.addCount()
            val minimalWaitingShop = shopList.calcMinimalWaitingShop(i + 1)
            shopList.removeShop(minimalWaitingShop)
            takahashi.lineUp(minimalWaitingShop.waitingTime(i + 1))
        }
    }

    return (takahashi.count - 1).toString()
}

data class ShopList(
    val shops: MutableList<Shop>
) {

    fun calcMinimalWaitingShop(t: Long): Shop {
        return shops.minBy { it.waitingTime(t) }!!
    }

    fun removeShop(shop: Shop) {
        shops.remove(shop)
    }

    fun empty(): Boolean = shops.isEmpty()
}

data class Shop(
    val id: Long,
    val a: Long,
    val b: Long
) {
    fun waitingTime(t: Long) = a * t + b
}

data class Takahashi(
    var count: Long,
    var restWaitingTime: Long
) {

    fun isWaiting(): Boolean = restWaitingTime > 0

    fun waitUnit(t: Long) {
        restWaitingTime -= t
    }

    fun addCount() {
        count += 1
    }

    fun lineUp(t: Long) {
        restWaitingTime = t
    }
}

