public void solve() {
	int num = ni();
	long t = nl();
	long a[][] = nl(num, 2);
	Comparator<long[]> comp = (sort1, sort2) -> {
		int c = Long.compare(- sort1[0] * (sort2[1] + 1), - sort2[0] *(sort1[1] + 1));
		if(c == 0) c = Long.compare(sort1[1], sort2[1]);
		return c;
	};
	Arrays.sort(a, comp);
	errprtln(a);
	int maxIndex = 0;
	while(maxIndex < num && a[maxIndex][0] > 0) maxIndex ++;
	long dp[] = new long[40];
	fill(dp, INF);
	dp[0] = 0;
	for(int i = 0; i < maxIndex; i ++) {
		for(int j = dp.length - 1; j > 0; j --) {
			dp[j] = min(dp[j], (dp[j - 1] + 1) * (a[i][0] + 1) + a[i][1]);
		}
	}
	errprtln(dp);
	long ans = 0;
	for(int i = 0; i < dp.length; i ++) {
		long tmp = i;
		if(dp[i] > t) continue;
		ans = max(ans, tmp);
		for(int j = maxIndex; j < num; j ++) {
			dp[i] = dp[i] + 1 + a[j][1];
			tmp ++;
			if(dp[i] > t) break;
			ans = max(ans, tmp);
		}
	}
	prtln(ans);
}



