    static class CThREE {
        List<UndirectedEdge>[] g;
        XorDeltaDSU dsu;
        int[] depths;
        int[] parent;
        int[] merged;

        public void solve(int testNumber, FastInput in, FastOutput out) {
            int n = in.readInt();
            g = Graph.createUndirectedGraph(n);
            for (int i = 1; i < n; i++) {
                int a = in.readInt() - 1;
                int b = in.readInt() - 1;
                Graph.addUndirectedEdge(g, a, b);
            }
            dsu = new XorDeltaDSU(n);
            depths = new int[n];
            parent = new int[n];
            merged = new int[n];
            Arrays.fill(merged, -1);

            TreeDiameter diameter = new TreeDiameter(g, n);
            int root = diameter.getEnds().get(0);
            dfs(root, -1, 0);

            for (int i = 0; i < n; i++) {
                if (depths[i] <= 1) {
                    continue;
                }
                if (depths[i] >= 3) {
                    dsu.merge(i, findAncestor(i, depths[i] - 3), 1);
                }
                int ff = findAncestor(i, depths[i] - 2);
                if (merged[ff] == -2 || merged[ff] == parent[i]) {
                    for (UndirectedEdge e : g[ff]) {
                        if (e.to == parent[ff] || e.to == merged[ff]) {
                            continue;
                        }
                        dsu.merge(i, e.to, 1);
                        break;
                    }
                } else if (merged[ff] == -1) {
                    merged[ff] = parent[i];
                    for (UndirectedEdge e : g[ff]) {
                        if (e.to == parent[ff] || e.to == merged[ff]) {
                            continue;
                        }
                        dsu.merge(i, e.to, 1);
                    }
                } else {
                    merged[ff] = -1;
                    for (UndirectedEdge e : g[ff]) {
                        if (e.to == parent[ff]) {
                            continue;
                        }
                        dsu.merge(i, e.to, 1);
                    }
                }
            }

            int[] colors = new int[n];
            int[] cnt = new int[2];
            for (int i = 0; i < n; i++) {
                if (dsu.find(i) == dsu.find(root)) {
                    cnt[dsu.delta(i, root)]++;
                }
            }
            IntegerDequeImpl[] dqs = new IntegerDequeImpl[3];
            for (int i = 0; i < 3; i++) {
                dqs[i] = new IntegerDequeImpl(n);
            }
            for (int i = 1; i <= n; i++) {
                dqs[i % 3].addLast(i);
            }
            int[] vals = new int[2];
            vals[0] = cnt[0] > cnt[1] ? 1 : 2;
            vals[1] = 3 - vals[0];
            for (int i = 0; i < n; i++) {
                if (dsu.find(i) == dsu.find(root)) {
                    int v = vals[dsu.delta(i, root)];
                    if (dqs[v].isEmpty()) {
                        if (dqs[0].isEmpty()) {
                            out.println(-1);
                            return;
                        }
                        colors[i] = dqs[0].removeFirst();
                    } else {
                        colors[i] = dqs[v].removeFirst();
                    }
                }
            }

            for (int i = 0; i < n; i++) {
                if (dsu.find(i) == dsu.find(0)) {
                    continue;
                }
                for (int j = 0; j < 3; j++) {
                    if (dqs[j].isEmpty()) {
                        continue;
                    }
                    colors[i] = dqs[j].removeFirst();
                    break;
                }
            }

            for (int i = 0; i < n; i++) {
                out.append(colors[i] + 1).append(' ');
            }
        }

        public int findAncestor(int root, int d) {
            if (depths[root] == d) {
                return root;
            }
            return findAncestor(parent[root], d);
        }

        public void dfs(int root, int p, int depth) {
            depths[root] = depth;
            parent[root] = p;
            for (UndirectedEdge e : g[root]) {
                if (e.to == p) {
                    continue;
                }
                dfs(e.to, root, depth + 1);
            }
        }

    }

    static class DigitUtils {
        private DigitUtils() {
        }

        public static int floorDiv(int a, int b) {
            return a < 0 ? -ceilDiv(-a, b) : a / b;
        }

        public static int ceilDiv(int a, int b) {
            if (a < 0) {
                return -floorDiv(-a, b);
            }
            int c = a / b;
            if (c * b < a) {
                return c + 1;
            }
            return c;
        }

    }

    static class IntegerList implements Cloneable {
        private int size;
        private int cap;
        private int[] data;
        private static final int[] EMPTY = new int[0];

        public IntegerList(int cap) {
            this.cap = cap;
            if (cap == 0) {
                data = EMPTY;
            } else {
                data = new int[cap];
            }
        }

        public IntegerList(IntegerList list) {
            this.size = list.size;
            this.cap = list.cap;
            this.data = Arrays.copyOf(list.data, size);
        }

        public IntegerList() {
            this(0);
        }

        public void ensureSpace(int req) {
            if (req > cap) {
                while (cap < req) {
                    cap = Math.max(cap + 10, 2 * cap);
                }
                data = Arrays.copyOf(data, cap);
            }
        }

        private void checkRange(int i) {
            if (i < 0 || i >= size) {
                throw new ArrayIndexOutOfBoundsException();
            }
        }

        public int get(int i) {
            checkRange(i);
            return data[i];
        }

        public void add(int x) {
            ensureSpace(size + 1);
            data[size++] = x;
        }

        public void addAll(int[] x, int offset, int len) {
            ensureSpace(size + len);
            System.arraycopy(x, offset, data, size, len);
            size += len;
        }

        public void addAll(IntegerList list) {
            addAll(list.data, 0, list.size);
        }

        public void sort() {
            if (size <= 1) {
                return;
            }
            Randomized.shuffle(data, 0, size);
            Arrays.sort(data, 0, size);
        }

        public void unique() {
            if (size <= 1) {
                return;
            }

            sort();
            int wpos = 1;
            for (int i = 1; i < size; i++) {
                if (data[i] != data[wpos - 1]) {
                    data[wpos++] = data[i];
                }
            }
            size = wpos;
        }

        public int[] toArray() {
            return Arrays.copyOf(data, size);
        }

        public String toString() {
            return Arrays.toString(toArray());
        }

        public boolean equals(Object obj) {
            if (!(obj instanceof IntegerList)) {
                return false;
            }
            IntegerList other = (IntegerList) obj;
            return SequenceUtils.equal(data, 0, size - 1, other.data, 0, other.size - 1);
        }

        public int hashCode() {
            int h = 1;
            for (int i = 0; i < size; i++) {
                h = h * 31 + Integer.hashCode(data[i]);
            }
            return h;
        }

        public IntegerList clone() {
            IntegerList ans = new IntegerList();
            ans.addAll(this);
            return ans;
        }

    }

