public class Main {
    public static void main(String[] args) throws Exception {
        Thread thread = new Thread(null, new TaskAdapter(), "", 1 << 27);
        thread.start();
        thread.join();
    }

    static class TaskAdapter implements Runnable {
        @Override
        public void run() {
            InputStream inputStream = System.in;
            OutputStream outputStream = System.out;
            FastInput in = new FastInput(inputStream);
            FastOutput out = new FastOutput(outputStream);
            DMangaMarket solver = new DMangaMarket();
            solver.solve(1, in, out);
            out.close();
        }
    }

    static class DMangaMarket {
        public void solve(int testNumber, FastInput in, FastOutput out) {
            int n = in.readInt();
            long t = in.readInt();
            List<Store> nonZero = new ArrayList<>(n);
            List<Store> zero = new ArrayList<>(n);

            for (int i = 0; i < n; i++) {
                int a = in.readInt();
                int b = in.readInt();
                Store store = new Store();
                store.a = a;
                store.b = b;
                if (a == 0) {
                    zero.add(store);
                } else {
                    nonZero.add(store);
                }
            }

            zero.sort((a, b) -> Long.compare(a.b, b.b));
            nonZero.sort((a, b) -> Long.compare((a.b + 1) * b.a, (b.b + 1) * a.a));
            long[][] dp = new long[nonZero.size() + 1][20];
            long inf = (long) 1e18;
            SequenceUtils.deepFill(dp, inf);
            dp[0][0] = 0;
            int m = nonZero.size();
            for (int i = 1; i <= m; i++) {
                Store s = nonZero.get(i - 1);
                for (int j = 0; j < 20; j++) {
                    dp[i][j] = dp[i - 1][j];
                    if (j > 0) {
                        dp[i][j] = Math.min(dp[i][j], dp[i - 1][j - 1] + DigitUtils.mul(dp[i - 1][j - 1] + 1, s.a, inf, inf) + s.b);
                    }
                }
            }

            long sum = 0;
            TreeMap<Long, Integer> map = new TreeMap<>();
            for (int i = 0; i < zero.size(); i++) {
                Store s = zero.get(i);
                sum += s.b + 1;
                map.put(sum, i + 1);
            }

            long ans = 0;
            for (int i = 0; i < 20; i++) {
                if (dp[m][i] > t) {
                    continue;
                }
                Map.Entry<Long, Integer> floor = map.floorEntry(t - dp[m][i]);
                ans = Math.max(ans, i + (floor == null ? 0 : floor.getValue()));
            }

            out.println(ans);
        }

    }

