  private static void solve() {
    int n = ni();
    int t = ni();

    long[][] a = new long[n][2];
    long[] b = new long[n];
    int ap = 0, bp = 0;

    for (int i = 0; i < n; i++) {
      long x = ni();
      long y = ni();
      if (x == 0) {
        b[bp++] = y + 1;
      } else {
        a[ap++] = new long[] { x, y };
      }
    }
    a = Arrays.copyOf(a, ap);
    b = Arrays.copyOf(b, bp);

    Arrays.sort(b);
    Arrays.sort(a, (o1, o2) -> {
      long x = (o2[0] - 1) * (o1[1] + 1) - (o1[0] - 1) * (o2[1] + 1);
      return Long.signum(x);
    });

    for (int i = 1; i < bp; i++) {
      b[i] += b[i - 1];
    }

    int m = 33;
    long[][] dp = new long[ap + 1][m + 1];
    for (long[] v : dp)
      Arrays.fill(v, Integer.MAX_VALUE);

    for (int i = 0; i < ap; i++) {
      dp[i][0] = 0;
      for (int j = 0; j < m; j++) {
        long now = dp[i][j];
        now += 1;
        now += a[i][0] * now + a[i][1];
        if (now >= Integer.MAX_VALUE) {
          now = Integer.MAX_VALUE;
        }
        dp[i + 1][j + 1] = Math.min(dp[i][j + 1], now);
      }
    }

    int ret = upperBound(b, t) + 1;
    for (int j = 0; j <= m; j++) {
      if (dp[ap][j] <= t) {
        ret = Math.max(ret, j + upperBound(b, t - dp[ap][j]) + 1);
      }
    }
    System.out.println(ret);
  }

  public static int upperBound(long[] a, long v) {
    int low = -1, high = a.length;
    while (high - low > 1) {
      int h = high + low >>> 1;
      if (a[h] <= v) {
        low = h;
      } else {
        high = h;
      }
    }
    return low;
  }

