        int b;
        public CustomPair(int a , int b ){
            this.a = a;
            this.b = b;
        }
    }

    public static void main(String[] args) {
        FastScanner fs = new FastScanner();
        int n = fs.nextInt();

        int[] as = new int[n-1];
        int[] bs = new int[n-1];
        for( int i = 0 ; i < n - 1; i++ ){
            int tempA = fs.nextInt();
            int tempB = fs.nextInt();
            if( tempA < tempB ){
                as[i] = tempA;
                bs[i] = tempB;
            }
            else {
                as[i] = tempB;
                bs[i] = tempA;
            }
        }

        boolean[] check = new boolean[n];
        List<CustomPair> customPairs = new ArrayList<>();
        int[] pos = new int[n];
        for( int i = 1 ; i < n + 1 ; i++ ){
            pos[i-1] = i;
            search(customPairs, as , bs , 0 , i , i , -1 , check );
        }

        for(int i = 0; i < customPairs.size() ; i++ ){
            CustomPair p = customPairs.get(i);
            int a = p.a;
            int b = p.b;
            if( ( b - a ) % 3 == 0 ){
                int notUse = -1;
                for( int j = b - 1 ; j < n ; j++ ){
                    if( !check[j] ) {
                        notUse = j;
                        check[j] = true;
                        break;
                    }
                }
                if( notUse == -1 ){
                    for( int j = b - 1 ; 0 <= j ; j-- ){
                        if( !check[j] ) {
                            notUse = j;
                            check[j] = true;
                            break;
                        }
                    }
                }
                if( notUse == -1 ){
                    System.out.println( -1 );
                    return;
                }
                int tempPos = pos[notUse];
                pos[notUse] = pos[b-1];
                pos[b-1] = tempPos;
            }
        }

        for( int i = 0 ; i < pos.length ; i++ ){
            System.out.print( pos[i] + " ");
        }

    }

    static void search(List<CustomPair> customPairs, int[] as , int[] bs , int count , int pos , int base , int before , boolean[] check ){
        for( int i = 0 ; i < as.length ; i++ ){
            if( as[i] == pos ){
                if( bs[i] != before ) {
                    if (count == 2) {
                        if( base < bs[i] ) {
                            check[base-1] = true;
                            check[bs[i]-1] = true;
                            customPairs.add(new CustomPair(base, bs[i]));
                        }
                    } else {
                        search(customPairs, as, bs, count + 1, bs[i], base, pos , check );
                    }
                }
            }
        }
        for( int i = 0 ; i < bs.length ; i++ ){
            if( bs[i] == pos ){
                if( as[i] != before ) {
                    if (count == 2) {
                        if( base < as[i] ) {
                            check[base-1] = true;
                            check[as[i]-1] = true;
                            customPairs.add(new CustomPair(base, as[i]));
                        }
                    } else {
                        search(customPairs, as, bs, count + 1, as[i], base, pos , check );
                    }
                }
            }
        }
    }

    static class FastScanner {
        private final InputStream in = System.in;
        private final byte[] buffer = new byte[1024];
        private int ptr = 0;
        private int buflen = 0;

        private boolean hasNextByte() {
            if (ptr < buflen) {
                return true;
            } else {
                ptr = 0;
                try {
                    buflen = in.read(buffer);
                } catch (IOException e) {
                    e.printStackTrace();
                }
                if (buflen <= 0) {
                    return false;
                }
            }
            return true;
        }

        private int readByte() {
            if (hasNextByte()) {
                return buffer[ptr++];
            } else {
                return -1;
            }
        }

        private static boolean isPrintableChar(int c) {
            return 33 <= c && c <= 126;
        }

        public boolean hasNext() {
            while (hasNextByte() && !isPrintableChar(buffer[ptr])) {
                ptr++;
            }
            return hasNextByte();
        }

        public String next() {
            if (!hasNext()) {
                throw new NoSuchElementException();
            }
            StringBuilder sb = new StringBuilder();
            int b = readByte();
            while (isPrintableChar(b)) {
                sb.appendCodePoint(b);
                b = readByte();
            }
            return sb.toString();
        }

        public long nextLong() {
            if (!hasNext()) {
                throw new NoSuchElementException();
            }
            long n = 0;
            boolean minus = false;
            int b = readByte();
            if (b == '-') {
                minus = true;
                b = readByte();
            }
            if (b < '0' || '9' < b) {
                throw new NumberFormatException();
            }
            while (true) {
                if ('0' <= b && b <= '9') {
                    n *= 10;
                    n += b - '0';
                } else if (b == -1 || !isPrintableChar(b)) {
                    return minus ? -n : n;
                } else {
                    throw new NumberFormatException();
                }
                b = readByte();
            }
        }

        public int nextInt() {
            long nl = nextLong();
            if (nl < Integer.MIN_VALUE || nl > Integer.MAX_VALUE) {
                throw new NumberFormatException();
            }
            return (int) nl;
        }

        public double nextDouble() {
            return Double.parseDouble(next());
        }
    }
}

import java.io.*;
import java.util.*;

class Store implements Comparable<Store> {
  final long a, b;

  Store(long a, long b) {
    this.a = a;
    this.b = b;
  }

  // ai * t + bi + aj * (t + ai * t + bi + 1) + bj
  // - (aj * t + bj + ai * (t + aj * t + bj + 1) + bi) < 0
  // ai * t + bi + aj * t + aj * ai * t + aj * bi + aj + bj
  // - (aj * t + bj + ai * t + ai *aj * t + ai *bj + ai + bi) < 0
  // ai * t + bi + aj * t + aj * ai * t + aj * bi + aj + bj
  // - aj * t - bj - ai * t - ai *aj * t - ai * bj - ai - bi < 0
  //      0 +  0 +      0 +           0 + aj * bi + aj +  0
  // -      0 -  0 -      0 -          0 - ai * bj - ai -  0 < 0
  // aj * bi + aj - ai * bj - ai < 0
  // aj * (bi + 1) - ai * (bj + 1) < 0
  public int compareTo(Store store) {
    long v = store.a * (this.b + 1) - this.a * (store.b + 1);
    if (v > 0) {
      return 1;
    } else if (v < 0) {
      return -1;
    } else {
      return 0;
    }
  }

  public long calculateBuyTime(long time) {
    return time + 1 + a * (time + 1) + b;
  }
}

class Solver {
  final int n;
  final long t;
  final long[][] abs;

  Solver(int n, long t, long[][] abs) {
    this.n = n;
    this.t = t;
    this.abs = abs;
  }

  public int solve() {
    List<Long> storeWithZeroAList = new ArrayList<>();
    List<Store> storeWithPositiveAList = new ArrayList<>();
    for (long[] ab : abs) {
      long a = ab[0];
      long b = ab[1];
      if (a > 0) {
        storeWithPositiveAList.add(new Store(a, b));
      } else {
        storeWithZeroAList.add(b);
      }
    }

    Collections.sort(storeWithPositiveAList);
    List<Long> dp = new ArrayList<>();
    dp.add(0L);
    for (Store store : storeWithPositiveAList) {
      long lastTime = dp.get(dp.size() - 1);
      long nextLastTime = store.calculateBuyTime(lastTime);
      if (nextLastTime <= t) {
        dp.add(nextLastTime);
      }
      for (int i = dp.size() - 1; i > 0; i--) {
        long otherTime = store.calculateBuyTime(dp.get(i - 1));
        if (dp.get(i) > otherTime) {
          dp.set(i, otherTime);
        }
      }
    }

    int answer = dp.size() - 1;
    Collections.sort(storeWithZeroAList);
    long sum = 0;
    for (int i = 0; i < storeWithZeroAList.size(); i++) {
      sum += storeWithZeroAList.get(i) + 1;
      for (int j = 0; j < dp.size() && sum + dp.get(j) <= t; j++) {
        answer = Math.max(answer, i + 1 + j);
      }
    }

    return answer;
  }

}

public class Main {
  private static void execute(ContestReader reader, ContestWriter out) {
    int n = reader.nextInt();
    long t = reader.nextLong();
    long[][] abs = reader.nextLong(n, 2);
