    static class Pair{
        int a,b,index;
        public Pair(int a,int b,int i)
        {
            this.a=a;
            this.b=b;
            this.index=i;
        }
    }
    public static void main(String[] args){
        Scanner sc = new Scanner(System.in);
        int n=sc.nextInt();
        int T=sc.nextInt();
        int t=0;
        Pair[] pairs=new Pair[n];
        for(int i=0;i<n;i++)
        {
            int a=sc.nextInt();
            int b=sc.nextInt();
            pairs[i]=new Pair(a,b,i);
        }
        int count=0;
        HashSet<Integer>set=new HashSet<>();
        while(t<T+0.5)
        {
            t++;
            int finalT = t;
            Arrays.sort(pairs, new Comparator<Pair>() {
                @Override
                public int compare(Pair pair1, Pair pair2) {
                    return Long.valueOf(pair1.a* finalT +pair1.b).compareTo(Long.valueOf(pair2.a* finalT +pair2.b));
                }
            });
            int i=0;
            for(i=0;i<n;i++){
                if(!set.contains(pairs[i].index)){
                    set.add(pairs[i].index);
                    break;
                }
            }
            if(i<n)t+=pairs[i].a*t+pairs[i].b;
            if(t<T+0.5)count++;
            if(count==n)break;
        }
        System.out.println(count);
    }
}

import java.util.*;

public class Main {
    public static class time implements Comparable<time>{
        long a;
        long b;

        void time(long x,long y){
            this.a=x;
            this.b=y;
        }

        public int compareTo(time t){
            if(this.a==t.a){
                return (int)(this.b-t.b);
            }else{
                return (int)(this.a-t.a);
            }
        }

        public void tostring(){
            System.out.print("[ "+this.a+" , "+this.b+" ]");
        }

    }

    public static long TIME(long a,long b,long t){
        return (t-b)/(a+1);
    }

    public static void main(String[] args) throws Exception {
        Scanner sc=new Scanner(System.in);
        int N=sc.nextInt();
        long T=sc.nextLong();
        time[] ROOT=new time[N];

        for(int i=0;i<N;i++){
            time tm=new time();
            tm.a=sc.nextLong();
            tm.b=sc.nextLong();
            ROOT[i]=tm;
        }

        Arrays.sort(ROOT);
        int idx=0;
        int ans=0;


        while(T>0&&idx<N){
            T=TIME(ROOT[idx].a,ROOT[idx].b,T);
            ans++;
            idx++;
            if(idx==N-1){
                ans++;
            }
        }
        ans--;

        System.out.println(ans);
    }
}

