import java.util.Arrays;
import java.util.Comparator;
import java.util.InputMismatchException;

public class Main {
	static InputStream is;
	static PrintWriter out;
	static String INPUT = "";

	static void solve()
	{
		// at+b, ct+d
		// u+(au+b)+c(u+au+b)+d < u+(cu+d)+a(u+cu+d)+b
		// u+(au+b)+c(u+au+b+1)+d < u+(cu+d)+a(u+cu+d+1)+b
		// cb+c < ad+a
		// c(b+1) < a(d+1)

		int n = ni(), T = ni();
		int[][] co = new int[n][];
		for(int i = 0;i < n;i++){
			co[i] = na(2);
		}
		Arrays.sort(co, new Comparator<int[]>() {
			public int compare(int[] a, int[] b) {
				int comp = Long.compare(
						(long)b[0]*(a[1]+1), 
						(long)a[0]*(b[1]+1)
						);
				if(comp != 0)return comp;
				return a[1] - b[1];
			}
		});

		long[] dp = new long[50];
		Arrays.fill(dp, Long.MAX_VALUE / 3);
		dp[0] = 0;
		int i = 0;
		for(;i < n && co[i][0] != 0;i++){
			int[] c = co[i];
			for(int j = 49;j >= 0;j--){
				if(dp[j] > T)continue;
				long can = dp[j] + 1 + ((long)c[0]*(dp[j]+1)+c[1]);
				dp[j+1] = Math.min(dp[j+1], can);
			}
		}
		int ans = 0;
		for(int j = 0;j < 50;j++){
			long time = dp[j];
			if(time > T)continue;
			int num = j;
			for(int k = i;k < n;k++){
				if(time + co[k][1] + 1 <= T){
					time += co[k][1] + 1;
					num++;
				}
			}
			ans = Math.max(ans, num);
		}
		out.println(ans);
	}

