internal partial class Solver {
    public void Run() {
        var n = ni();
        var t = ni();
        var a = new int[n];
        var b = new int[n];
        for (int i = 0; i < n; i++) {
            a[i] = ni();
            b[i] = ni();
        }

        var p = E.Range(0, n)
            .Where(i => a[i] != 0)
            .ToArray();

        Array.Sort(p, (i1, i2) => (1L * a[i2] * b[i1] + a[i2] + b[i2]).CompareTo(1L * a[i1] * b[i2] + a[i1] + b[i1]));

        long inf = t + 1000;
        var dp = new long[100];
        for (int i = 0; i < dp.Length; i++) {
            dp[i] = inf;
        }
        dp[0] = 0;

        foreach (var id in p) {
            for (int i = dp.Length - 1; i >= 1; i--) {
                var time = dp[i - 1];
                time++;
                time += a[id] * time + b[id];
                dp[i] = Math.Min(dp[i], time);
            }
        }

        var a0 = E.Range(0, n).Where(i => a[i] == 0).Select(i => b[i] + 1).ToArray();
        Array.Sort(a0);

        int ans = 0;
        long sum = 0;
        int cur = 0;

        for (int i = dp.Length - 1; i >= 0; i--) {
            if (dp[i] <= t) {
                while (cur < a0.Length && dp[i] + sum + a0[cur] <= t) {
                    sum += a0[cur];
                    cur++;
                }
                ans = Math.Max(ans, i + cur);
            }
        }

