class Solver {
    StreamWriter sw;
    Scan sc;
    void Prt(string a) => sw.WriteLine(a);
    void Prt<T>(IEnumerable<T> a) => Prt(string.Join(" ", a));
    void Prt(params object[] a) => Prt(string.Join(" ", a));
    public Solver(StreamWriter sw) {
        this.sw = sw;
        this.sc = new Scan();
    }

    public void solve() {
        int n;
        long t;
        sc.Multi(out n, out t);
        var p = new pair<long, long>[n];
        for (int i = 0; i < n; i++)
        {
            long a, b;
            sc.Multi(out a, out b);
            p[i] = new pair<long, long>(a + 1, a + b + 1);
        }
        Array.Sort(p, (x, y) => x.v2 * y.v1 + y.v2 != y.v2 * x.v1 + x.v2 ? (x.v2 * y.v1 + y.v2).CompareTo(y.v2 * x.v1 + x.v2) : y.v1.CompareTo(x.v1));
        int r = n;
        while (r > 0 && p[r - 1].v1 == 1) --r;
        var dp = new long[36];
        for (int i = 0; i < 36; i++)
        {
            dp[i] = M;
        }
        dp[0] = 0;
        for (int i = 0; i < r; i++)
        {
            for (int j = 35; j > 0 ; j--)
            {
                dp[j] = Math.Min(dp[j], dp[j - 1] * p[i].v1 + p[i].v2);
            }
        }
        int max = 0;
        for (int i = 0; i < 36; i++)
        {
            if (dp[i] <= t) {
                max = Math.Max(max, i);
            }
        }
        long sum = 0;
        int c = 0;
        for (int i = r; i < n; i++)
        {
            ++c;
            sum += p[i].v2;
            for (int j = 0; j < 36; j++)
            {
                if (dp[j] + sum <= t) {
                    max = Math.Max(max, c + j);
                }
            }
        }
        Prt(max);
    }
}

class pair<T, U> : IComparable<pair<T, U>> {
    public T v1;
    public U v2;
    public pair() : this(default(T), default(U)) {}
    public pair(T v1, U v2) { this.v1 = v1; this.v2 = v2; }
    public int CompareTo(pair<T, U> a) {
        int c = Comparer<T>.Default.Compare(v1, a.v1);
        return c != 0 ? c : Comparer<U>.Default.Compare(v2, a.v2);
    }
    public override string ToString() => v1 + " " + v2;
    public void Deconstruct(out T a, out U b) { a = v1; b = v2; }
}
