class GFG
{
    static int min = int.MaxValue;
    static List<Val> lst = new List<Val>();
    public static void Main()
    {
        var input = Console.ReadLine().Split(' ');
        var n = int.Parse(input[0]);
        var t = int.Parse(input[1]);
        for (int i = 0; i < n; i++)
        {
            var arr = Console.ReadLine().Split(' ').Select(x => int.Parse(x)).ToArray();
            Val v = new Val();
            v.a = arr[0];
            v.b = arr[1];
            lst.Add(v);
        }
        MangaMarket(n, t, lst);
    }

    static void MangaMarket(int N, int T, List<Val> lst)
    {
        lst.Sort((x, y) =>
       {
           int aa = x.a == 0 || x.b == 0 ? x.a + x.b : x.a * x.b;
           int bb = y.a == 0 || y.b == 0 ? y.a + y.b : y.a * y.b;
           return aa.CompareTo(bb);
       });

        var targettime = T + .05;
        var t = 1;
        int count = 0;
        foreach (var val in lst)
        {
            var ans = t + val.a * t + val.b;

            if (ans <= targettime)
                count++;
            else
                break;

            t = ans + 1;
        }

        Console.Write(count);


    }

}

