        var ix = dp.Length - 1;
        int res = ix;
        for (int i = 0; i < zs.Length; i++)
        {
            while (zs[i] + dp[ix] > T) ix--;
            res.UpdateMax(i + 1 + ix);
        }

        return res;
    }
