public class Program
{
    [System.Diagnostics.DebuggerBrowsable(System.Diagnostics.DebuggerBrowsableState.Never)] private ConsoleReader cr;

    public Program(ConsoleReader consoleReader) { this.cr = consoleReader; }
    static void Main() => Console.WriteLine(new Program(new ConsoleReader(Console.In)).Calc());

    #endregion
    public object Calc()
    {
        var N = cr.Int;
        var T = cr.Int;

        int[] shopsConst;
        Shop[] shops;
        {
            var shopsgroup = cr.Repeat(N).Select(cr => new Shop { a = cr.Int, b = cr.Int }).ToLookup(s => s.a == 0);
            shopsConst = shopsgroup[true].Select(s => s.b).ToArray().Sort();
            shops = shopsgroup[false].ToArray();
        }

        var lng = 0;
        long time = 0;
        foreach (var t in shopsConst)
        {
            time += t + 1;
            if (time > T)
            {
                time -= t + 1;
                break;
            }
            lng++;
        }

        if (shops.Length == 0)
            return lng;

        var cnt = 0;
        var maxLen = Math.Min(shops.Length + 1, 30);
        var dp = NewArray(shops.Length, maxLen, 1 + (long)int.MaxValue);
        for (int i = 0; i < shops.Length; i++)
            dp[i][0] = 0;

        dp[0][1] = shops[0].a + shops[0].b;

        for (int i = 1; i < shops.Length; i++)
            for (int j = 1; j < maxLen; j++)
            {
                dp[i][j] = dp[i - 1][j];
                if (dp[i - 1][j - 1] < int.MaxValue)
                {
                    dp[i][j] = Math.Min(dp[i][j], dp[i - 1][j - 1] + shops[i].a * (dp[i - 1][j - 1] + 1) + shops[i].b);
                }
            }

        if (lng == 0)
            return dp[dp.Length - 1].Select((t, i) => Tuple.Create(t, i)).Where(t => t.Item1 <= T).Max(t => t.Item2);

        for (int j = 0; j < maxLen; j++)
        {
            if (dp[dp.Length - 1][j] > T)
                break;
            while (dp[dp.Length - 1][j] + time > T)
                time -= shopsConst[--lng];
            cnt = Math.Max(cnt, j + lng);
        }

        return cnt;
    }
}
