            Array.Sort(AB1, (x, y) => (x.Item2 * y.Item1 + y.Item2).CompareTo(y.Item2 * x.Item1 + x.Item2));
            int maxj = 40;
            long maxt = T + 1;
            long[] time = Enumerable.Range(0, maxj).Select(i => maxt).ToArray();
            time[0] = 0;
            for (int i = 0; i < AB1.Length; ++i)
            {
                var ab = AB1[i];
                for (int j = maxj - 2; j >= 0; --j)
                {
                    var t = (time[j] + 1) * (ab.Item1 + 1) + ab.Item2;
                    if (t <= T)
                    {
                        time[j + 1] = Math.Min(time[j + 1], t);
                    }
                }
            }
            var bs = new List<long>();
            foreach(var ab in AB)
            {
                if (ab.Item1 == 0)
                {
                    bs.Add(ab.Item2);
                }
            }
            bs = bs.OrderBy(x => x).ToList();
            long max = 0;
            for(int i = 0; i < maxj; ++i)
            {
                if (time[i] <= T)
                {
                    max = Math.Max(max, i);
                }
                for (int j = 0; j < bs.Count; ++j)
                {
                    var t = time[i] + 1 + bs[j];
                    if (t <= T)
                    {
                        time[i] = t;
                        max = Math.Max(max, i + j + 1);
                    }
                    else
