    static int min = int.MaxValue;
    static List<Val> lst = new List<Val>();
    public static void Main()
    {
        var input = Console.ReadLine().Split(' ');
        var n = int.Parse(input[0]);
        var t = ulong.Parse(input[1]);
        for (int i = 0; i < n; i++)
        {
            var arr = Console.ReadLine().Split(' ').Select(x => ulong.Parse(x)).ToArray();
            Val v = new Val();
            v.a = arr[0];
            v.b = arr[1];
            lst.Add(v);
        }
        MangaMarket(n, t, lst);
    }

    static void MangaMarket(int N, ulong T, List<Val> lst)
    {
        lst.Sort((x, y) =>
       {
           ulong aa = x.a == 0 || x.b == 0 ? x.a + x.b : x.a * x.b;
           ulong bb = y.a == 0 || y.b == 0 ? y.a + y.b : y.a * y.b;
           return aa.CompareTo(bb);
       });


        ulong[] dp = new ulong[51];
        dp[0] = 0;
        for (int i = 0; i < N; ++i)
        {
            if (lst[i].a == 0)
                continue;
            for (int j = 51 - 1; j >= 0; --j)
            {
                ulong x = dp[j] + 1;
                x += x * lst[i].a + lst[i].b;
                dp[j + 1] = Math.Min(dp[j + 1], x);
            }
        }

        int ans = 0;
        for (int i = 0; dp[i] <= T; ++i)
        {
            int cnt = i;
            ulong x = dp[i];
            for (int j = 0; j < N; ++j)
            {
                if (lst[j].a == 0 && x + lst[j].b + 1 <= T)
                {
                    x += lst[j].b + 1;
                    ++cnt;
                }
            }
            ans = Math.Max(ans, cnt);
        }
