		b[i] = nextInt()
		c[1+a[i]+b[i]] = i
	}
	var array []int
	for key := range c {
		array = append(array, key)
	}
	sort.Ints(array)
	cnt := 0
	time := array[0]

	for time <= T {
		cnt += 1
		if cnt == N {
			break
		}
		for i := cnt; i < N; i++ {
			elapsed := 1 + a[c[array[i]]]*time + b[c[array[i]]]
			if time+elapsed <= T {
				time += elapsed
				break
			}
		}
	}
	fmt.Println(cnt)
}

