func solution(n, t int, m [][]int) int {
	sort.Slice(m, func(i, j int) bool {
		if m[i][2] == m[j][2] {
			return m[i][0] < m[j][0]
		}
		return m[i][2] < m[j][2]
	})
	var T float64 = float64(t) + 0.5
	var c, w, time int
	for i := 0; i < n; i++ {
		time++
		w = m[i][0]*time + m[i][1]
		time += w
		if float64(time) >= T {
			break
		}
		c++
	}
	return c
}

