	var n, t int
	fmt.Scan(&n, &t)

	m := make([][]int, n)
	for i := range m {
		m[i] = make([]int, 3)
		var a, b int
		fmt.Scan(&a, &b)
		m[i][0] = a
		m[i][1] = b
		m[i][2] = a + b

	}

	fmt.Println(solution(n, t, m))
}

