interface Shop {
  id: number;
  a: number;
  b: number;
}
function Main(input: string) {
  const lines = input.split('\n');
  const first = lines[0].split(' ');
  const limit = +first[1] + 0.5;
  const shops: Shop[] = Array(+first[0]);
  lines.slice(1).forEach((l, i) => {
    const split = l.split(' ');
    if (split.length === 2) {
      shops.push({ id: i, a: +split[0], b: +split[1] });
    }
  });
  console.log(visit(1, limit, 0, shops, new Set()));
}

function visit(t: number, limit: number, start: number, shops: Shop[], visited: Set<number>) {
  let max = visited.size;
  for (let i = start, length = shops.length; i < length; i++) {
    const s = shops[i];
    if (!visited.has(s.id)) {
      const next = t + t * s.a + s.b;
      if (next < limit) {
        visited.add(s.id);
        max = Math.max(max, visit(next + 1, limit, i + 1, shops, visited));
        visited.delete(s.id);
      }
    }
  }
  return max;
}

