    my @l = split(/\s+/, $l);
    $limit = $l[1] + 0.5;
}
my %shops;
{
    my $i = 0;
    while(<STDIN>){
        $i++;
        my @s = split(/\s+/);
        $shops{$i} = {
            a => $s[0],
            b => $s[1]
        };
    }
}

my $now = 1;
my $count = 0;
while ($now < $limit){
    my $minshop = minshop($now);
    $now += visit($minshop, $now);
    $count++ if $now < $limit;
    $now++;
    last if (keys %shops)+0 == 0;
}
say $count;

sub visit {
    my $s = shift;
    my $n = shift;
    my $time = $shops{$s}->{a} * $n + $shops{$s}->{b};
    delete($shops{$s});
    return $time;
}
sub minshop {
    my $now = shift;
    my %cal;
    for my $k (keys %shops){
        my $sum = $shops{$k}->{a} * $now + $shops{$k}->{b};
        $cal{$k} = $sum;
    }
    my @result = sort {$cal{$a} <=> $cal{$b}} keys %cal;
    return $result[0];
}

