      auto C = new Circle[N];
      foreach (i; 0 .. N) {
        C[i].a = readLong();
        C[i].b = readLong();
      }

      long[] zeros;
      Circle[] cs;
      foreach (ref c; C) {
        if (c.a == 0) {
          zeros ~= c.b + 1;
        } else {
          cs ~= c;
        }
      }

      zeros.sort();
      const zerosLen = cast(int)(zeros.length);
      auto zerosSum = new long[zerosLen + 1];
      foreach (j; 0 .. zerosLen) {
        zerosSum[j + 1] = zerosSum[j] + zeros[j];
      }
      debug {
        writeln("zerosSum = ", zerosSum);
      }

      // (b + 1) / a
      cs.sort!((c0, c1) => ((c0.b + 1) * c1.a < (c1.b + 1) * c0.a));

      auto dp = new long[K + 1];
      dp[] = T + 1;
      dp[0] = 0;
      foreach (ref c; cs) {
        foreach_reverse (k; 0 .. K) {
          chmin(dp[k + 1], (c.a + 1) * dp[k] + (c.a + c.b + 1));
        }
      }
      debug {
        writeln("cs = ", cs);
        writeln("dp = ", dp);
      }

      int ans;
      foreach (j; 0 .. zerosLen + 1) foreach (k; 0 .. K + 1) {
        if (dp[k] + zerosSum[j] <= T) {
          chmax(ans, j + k);
        }
      }
      writeln(ans);
    }
  } catch (EOFException e) {
  }
}

