def chkonly(tm, T, N, a, b):
    cnt=0
    i=0
    mise=0
    while i<N:
        if tm+a[i]*max(1,tm)+b[i]<=T:
            if cnt==0:
                cnt=1
                mise=i
            else:
                break
        i+=1
    return (mise,True) if cnt==1 else (mise,False)

def getmise(T, N, a, b):
    ok=-1
    ng=T
    while ng-ok>1:
        mid=(ok+ng)//2
        mise,flag=chkonly(mid, T, N, a, b)
        if flag:
            ok=mid
        else:
            ng=mid
    return ok,mise

def solve(N, T, a, b):
    ans=0
    limit=T
    while limit>0:
        ok,mise=getmise(limit, N, a, b)
        if ok==0:
            break
        if ok>=1:
            ans+=1
            limit=ok
            a[mise]=2**31-1
            b[mise]=2**31-1
        else:
            break
    print(ans)



