def main():
    N, T = map(int, sys.stdin.readline().split())
    As, Bs = map(list, zip(*(tuple(map(int, sys.stdin.readline().split())) for _ in range(N))))

    # dp[i + 1][t] := i番目までの店のうち時間 t を超えないように訪問できる店の数
    # dp[i + 1][t] | int((t - Bs[i]) / As[i]) - 1 >= 0 = max(dp[i][int((t - Bs[i]) / As[i]) - 1] + 1, dp[i][t])
    #              | otherwise                         = dp[i][t]

    memo = {}

    def dp(i, t):
        assert i >= 0
        assert t >= 0

        if i == 0:
            return 0

        if (i, t) in memo:
            return memo[i, t]

        h = i - 1

        tpre = int((t - Bs[h]) / (As[h] + 1)) - 1
        if tpre >= 0:
            x = memo[i, t] = max(dp(h, tpre) + 1, dp(h, t))
            return x
        else:
            x = memo[i, t] = dp(h, t)
            return dp(h, t)

    print(dp(N, T))
    #print(memo)

