def hoge(prev_dp, a, b):
  dp = [float("inf")] * 29
  for j in range(29):
    dp[j] = min(dp[j], prev_dp[j])
    if j != 28:
      dp[j+1] = (1 + a) * (1 + prev_dp[j]) + b
  return dp

