    dp = hoge(prev_dp, ai, bi)
    prev_dp = dp

  ans = 0
  for j, t_x in enumerate(dp):
    if t_x <= t:
      val_0 = bisect.bisect_right(cum_ab0, t - t_x, lo=0, hi=len_ab0)
