use std::cmp::{max, min};

const N: usize = 33;
const INF: u64 = 1 << 33;

fn main() {
    let (r, w) = (std::io::stdin(), std::io::stdout());
    let mut sc = IO::new(r.lock(), w.lock());
    let n: usize = sc.read();
    let time: u64 = sc.read();

    let mut ab = vec![];
    let mut a_zero = vec![];
    for _ in 0..n {
        let a = sc.read::<u64>();
        let b = sc.read::<u64>();
        if a == 0 {
            a_zero.push(b);
        } else {
            ab.push((a, b));
        }
    }
    ab.sort_by(|&(a0, b0), &(a1, b1)| {
        let c0 = a1 * (b0 + 1);
        let c1 = a0 * (b1 + 1);
        c0.cmp(&c1)
    });

    let mut dp = vec![INF; N + 1];
    dp[0] = 0;
    for (a, b) in ab.into_iter() {
        for i in (0..N).rev() {
            dp[i + 1] = min(dp[i + 1], a * (dp[i] + 1) + b);
        }
    }

    a_zero.sort();
    let mut b_sum = vec![0];
    for (i, b) in a_zero.into_iter().enumerate() {
        let prev = b_sum[i];
        b_sum.push(prev + b + 1);
    }

    let mut ans = 0;
    for (tail, tail_sum) in b_sum.into_iter().enumerate() {
        for head in 0..N {
            if tail_sum + dp[head] > time {
                continue;
            }
            ans = max(ans, tail + head);
        }
    }

    println!("{}", ans);
}

