trait Bisect<T> {
    fn lower_bound(&self, val: &T) -> usize;
    fn upper_bound(&self, val: &T) -> usize;
}

impl<T: Ord> Bisect<T> for [T] {
    fn lower_bound(&self, val: &T) -> usize {
        let mut pass = self.len() + 1;
        let mut fail = 0;
        while pass - fail > 1 {
            let mid = (pass + fail) / 2;
            if &self[mid - 1] >= val {
                pass = mid;
            } else {
                fail = mid;
            }
        }
        pass - 1
    }
    fn upper_bound(&self, val: &T) -> usize {
        let mut pass = self.len() + 1;
        let mut fail = 0;
        while pass - fail > 1 {
            let mid = (pass + fail) / 2;
            if &self[mid - 1] > val {
                pass = mid;
            } else {
                fail = mid;
            }
        }
        pass - 1
    }
}

fn solve() {
    let out = std::io::stdout();
    let mut out = BufWriter::new(out.lock());
    macro_rules! puts {
        ($($format:tt)*) => (let _ = write!(out,$($format)*););
    }
    input! {
        n: usize, t: i64,
        ab: [(i64, i64); n],
    }
    let t = t + 1;
    let mut zero = vec![];
    let mut rest = vec![];
    for &(a, b) in &ab {
        let b = b + 1;
        if a == 0 {
            zero.push(b);
        } else {
            rest.push((a + 1, b));
        }
    }
    zero.sort();
    rest.sort_by(|&(a, b), &(c, d)| (b * (c - 1)).cmp(&((a - 1) * d)));
    rest.reverse();
    let zl = zero.len();
    let rl = rest.len();
    let mut zeroacc = vec![0; zl + 1];
    for i in 0..zl {
        zeroacc[i + 1] = zeroacc[i] + zero[i];
    }
    let freeexp = zeroacc.upper_bound(&(t - 1));
    debugln!("freeexp = {}", freeexp);
    const B: usize = 30;
    let mut ma = 0;
    const INF: i64 = 1 << 50;
    for i in max(freeexp, B) - B..freeexp {
        let rem = t - zeroacc[i];
        let mut dp = [-INF; B + 1];
        dp[0] = rem;
        for j in 0..rl {
            let (a, b) = rest[j];
            for k in (0..B).rev() {
                if dp[k] >= a + b {
                    dp[k + 1] =
                        max(dp[k + 1], (dp[k] - b) / a); 
                }
            }
        }
        let mut cnt = 0;
        for i in 0..B + 1 {
            if dp[i] > 0 {
                cnt = i;
            }
        }
        ma = max(ma, i + cnt);
    }
    puts!("{}\n", ma);
}

fn main() {
    // In order to avoid potential stack overflow, spawn a new thread.
    let stack_size = 104_857_600; // 100 MB
    let thd = std::thread::Builder::new().stack_size(stack_size);
    thd.spawn(|| solve()).unwrap().join().unwrap();
