const INF: i64 = 1e9 as i64 + 1;
type Shop = (i64, i64);

fn simulate(a: Shop, b: Shop) -> i64 {
    let mut nt = 0;
    nt += a.0*(nt+1)+a.1;
    nt += b.0*(nt+1)+b.1;
    nt
}

fn solve(mut shops: Vec<Shop>) -> Vec<i64> {
    shops.sort_by(|&s1, &s2| (simulate(s1, s2)).cmp(&simulate(s2, s1)));
    let n = shops.len();

    let mut dp = dvec!(INF; n+1, 32);
    dp[0][0] = 0;
    for i in 0..n {
        let a = shops[i].0;
        let b = shops[i].1;
        for k in 0..32 {
            if dp[i][k] == INF {
                continue;
            }
            let base = dp[i][k];
            dp[i+1][k] = min(dp[i+1][k], base);

            if k+1 < 32 {
                let to = base+1+a*(base+1)+b;
                dp[i+1][k+1] = min(dp[i+1][k+1], to);
            }
        }
    }
    dp[n].clone()
}

fn main() {
    input! {
        n: usize, t: i64,
        mut shops: [(i64, i64); n]
    };
    let mut end_shop = vec![];
    let mut normal_shop = vec![];
    for (a, b) in shops {
        if a == 0 {
            end_shop.push((a, b));
        } else {
            normal_shop.push((a, b));
        }
    }
    end_shop.sort();

    let result = solve(normal_shop);

    let mut ans = 0;
    for used in 0..32 {
        if result[used] > t {
            continue;
        }
        let mut time = result[used];
        let mut count = used;
        for &(_, b) in &end_shop {
            if time+b+1 <= t {
                time += b+1;
                count += 1;
            }
        }
        ans = max(ans, count);
    }
    println!("{}", ans);
}

