fn run() {
    input! {
        n: usize,
        t: usize,
        p: [(usize, usize); n],
    }
    let mut zero = vec![];
    let mut q = vec![];
    for (a, b) in p {
        if a == 0 {
            zero.push(b);
        } else {
            q.push((a, b));
        }
    }
    q.sort_by(|a, b| (b.0 * (a.1 + 2)).cmp(&(a.0 * (b.1 + 2))));
    let m = 500;
    let mut dp = vec![t + 1; m + 1];
    dp[0] = 0;
    for (a, b) in q {
        for i in (1..(m + 1)).rev() {
            let t = dp[i - 1];
            dp[i] = std::cmp::min(dp[i], t + 1 + a * (t + 1) + b);
        }
    }
    zero.sort();
    let mut sum = zero.iter().fold(0, |s, a| s + *a);
    let mut ans = 0;
    for i in 1..(m + 1){
        while zero.len() > 0 && dp[i] + sum + zero.len() > t {
            sum -= zero.pop().unwrap();
        }
        if dp[i] + sum + zero.len() <= t {
            ans = std::cmp::max(ans, i + zero.len());
        }
    }
    println!("{}", ans);
}

fn main() {
    run();
}

