trait Bisect<T> {
    fn lower_bound(&self, val: &T) -> usize;
    fn upper_bound(&self, val: &T) -> usize;
}

impl<T: Ord> Bisect<T> for [T] {
    fn lower_bound(&self, val: &T) -> usize {
        let mut pass = self.len() + 1;
        let mut fail = 0;
        while pass - fail > 1 {
            let mid = (pass + fail) / 2;
            if &self[mid - 1] >= val {
                pass = mid;
            } else {
                fail = mid;
            }
        }
        pass - 1
    }
    fn upper_bound(&self, val: &T) -> usize {
        let mut pass = self.len() + 1;
        let mut fail = 0;
        while pass - fail > 1 {
            let mid = (pass + fail) / 2;
            if &self[mid - 1] > val {
                pass = mid;
            } else {
                fail = mid;
            }
        }
        pass - 1
    }
}

fn solve() {
    let out = std::io::stdout();
    let mut out = BufWriter::new(out.lock());
    macro_rules! puts {
        ($($format:tt)*) => (let _ = write!(out,$($format)*););
    }
    input! {
        n: usize, t: i64,
        ab: [(i64, i64); n],
    }
    let t = t + 1;
    let mut zero = vec![];
    let mut rest = vec![];
    for &(a, b) in &ab {
        let b = b + 1;
        if a == 0 {
            zero.push(b);
        } else {
            rest.push((a + 1, b));
        }
    }
    zero.sort();
    rest.sort_by(|&(a, b), &(c, d)| (b * (c - 1)).cmp(&((a - 1) * d)));
    rest.reverse();
    let zl = zero.len();
    let rl = rest.len();
    let mut zeroacc = vec![0; zl + 1];
    for i in 0..zl {
        zeroacc[i + 1] = zeroacc[i] + zero[i];
    }
    let freeexp = zeroacc.upper_bound(&(t - 1));
    debugln!("freeexp = {}", freeexp);
    const B: usize = 30;
    let mut ma = 0;
    const INF: i64 = 1 << 50;
    for i in max(freeexp, B) - B..freeexp {
        let rem = t - zeroacc[i];
        let mut dp = vec![vec![-INF; B + 1]; rl + 1];
        dp[0][0] = rem;
        for j in 0..rl {
            let (a, b) = rest[j];
            for k in 0..B + 1 {
                dp[j + 1][k] = max(dp[j + 1][k], dp[j][k]);
                if k < B && dp[j][k] >= a + b {
                    dp[j + 1][k + 1] =
                        max(dp[j + 1][k + 1], (dp[j][k] - b) / a); 
                }
            }
        }
        let mut cnt = 0;
        for i in 0..B + 1 {
            if dp[rl][i] > 0 {
                cnt = i;
            }
        }
        ma = max(ma, i + cnt);
    }
    puts!("{}\n", ma);
}

fn main() {
    // In order to avoid potential stack overflow, spawn a new thread.
    let stack_size = 104_857_600; // 100 MB
    let thd = std::thread::Builder::new().stack_size(stack_size);
    thd.spawn(|| solve()).unwrap().join().unwrap();
}

use std::cmp;

const N: usize = 33;
const INF: u64 = 1 << 50;

fn main() {
    let (r, w) = (std::io::stdin(), std::io::stdout());
    let mut sc = IO::new(r.lock(), w.lock());

    let n: usize = sc.read();
    let t: u64 = sc.read();

    let mut a0 = vec![];
    let mut ab = vec![];
    for _ in 0..n {
        let a: u64 = sc.read();
        let b: u64 = sc.read();
        if a == 0 {
            a0.push(b);
        } else {
            ab.push((a, b));
        }
    }

    ab.sort_by(|&(ai, bi), &(aj, bj)| {
        let xi = aj * (bi + 1);
        let xj = ai * (bj + 1);
        xi.cmp(&xj)
    });
    a0.sort();

    let mut dp = vec![INF; N];
    dp[0] = 0;
    for (a, b) in ab.into_iter() {
        for i in (0..(N - 1)).rev() {
            if a * dp[i] + b <= t {
                dp[i + 1] = cmp::min(dp[i + 1], a * (dp[i] + 1) + b);
            }
        }
    }

    let mut ans = 0;
    for i in 0..N {
        if dp[i] > t {
            continue;
        }
        let mut count = i;
        let mut time = dp[i];
        for &b in a0.iter() {
            if time + 1 + b <= t {
                time += b + 1;
                count += 1;
            }
        }

        ans = cmp::max(ans, count);
    }

    println!("{}", ans);
}

pub struct IO<R, W: std::io::Write>(R, std::io::BufWriter<W>);

impl<R: std::io::Read, W: std::io::Write> IO<R, W> {
    pub fn new(r: R, w: W) -> IO<R, W> {
        IO(r, std::io::BufWriter::new(w))
    }
    pub fn write<S: std::ops::Deref<Target = str>>(&mut self, s: S) {
        use std::io::Write;
        self.1.write(s.as_bytes()).unwrap();
    }
    pub fn read<T: std::str::FromStr>(&mut self) -> T {
        use std::io::Read;
        let buf = self
            .0
            .by_ref()
            .bytes()
            .map(|b| b.unwrap())
            .skip_while(|&b| b == b' ' || b == b'\n' || b == b'\r' || b == b'\t')
            .take_while(|&b| b != b' ' && b != b'\n' && b != b'\r' && b != b'\t')
            .collect::<Vec<_>>();
        unsafe { std::str::from_utf8_unchecked(&buf) }
            .parse()
            .ok()
            .expect("Parse error.")
    }
    pub fn vec<T: std::str::FromStr>(&mut self, n: usize) -> Vec<T> {
        (0..n).map(|_| self.read()).collect()
    }
    pub fn chars(&mut self) -> Vec<char> {
        self.read::<String>().chars().collect()
    }
}

