fn lower_bound<F>(l: isize, r: isize, criterion: F) -> isize
where
    F: Fn(isize) -> bool,
{
    let mut l = l;
    let mut r = r;
    while r - l > 1 {
        let mid = l + (r - l) / 2;
        if criterion(mid) {
            r = mid;
        } else {
            l = mid;
        }
    }
    l
}

fn solve() {
    let (n,t) = get!(usize, isize);
    let ab = get!(isize, isize; n);

    let mut set = BTreeSet::new();
    for (a,b) in ab {
        set.insert((a,b));
    }

    let mut current = 1isize;
    let mut count = 0usize;

    while current <= t && set.len() > 0 {
        let i = {
            let crit = |i: isize| -> bool {
                let i = i as usize;
                let &(a1,b1) = set.iter().skip(i).next().unwrap();
                let &(a2,b2) = set.iter().skip(i+1).next().unwrap();
                let res = (a2*current+b2) - (a1*current+b1);
                res > 0
            };
            (lower_bound(-1, set.len() as isize -1, crit)+1) as usize
        };
        let &(a,b) = set.iter().skip(i).next().unwrap();
        set.remove(&(a,b));
        current += a*current+b;
        if current > t {
            break;
        }
        current += 1;
        count += 1;
    }
    println!("{}", count);
}

