        n: usize,
        t: usize,
        p: [(usize, usize); n],
    }
    let mut zero = vec![];
    let mut q = vec![];
    for (a, b) in p {
        if a == 0 {
            zero.push(b);
        } else {
            q.push((a, b));
        }
    }
    q.sort_by(|a, b| (b.0 * (a.1 + 1)).cmp(&(a.0 * (b.1 + 1))));
    let m = 700;
    let mut dp = vec![t + 1; m + 1];
    dp[0] = 0;
    for (a, b) in q {
        for i in (1..(m + 1)).rev() {
            let t = dp[i - 1];
            dp[i] = std::cmp::min(dp[i], t + 1 + a * (t + 1) + b);
        }
    }
    zero.sort();
    let mut sum = zero.iter().fold(0, |s, a| s + *a);
    while sum + zero.len() > t + 1 {
        sum -= zero.pop().unwrap();
