use std::cmp;

fn main() {
    read!(n = usize, t_max = u32);
    let mut zeros = Vec::new();
    let mut shops = Vec::new();
    for (a, b) in read_lines::<(u32, u32)>() {
        let b = a+b+1;
        if a == 0 {
            zeros.push(b);
        } else {
            shops.push((a, b));
        }
    }
    shops.sort_by_key(|&(a1, b1)| Total(b1 as f64 / a1 as f64));
    zeros.sort();
    let max = cmp::min(30, shops.len());
    let mut dp = vec![vec![0; max+1]; shops.len()+1];
    for i in 1..=shops.len() {
        for k in 1..=max {
            let (a, b) = shops[i-1];
            dp[i][k] = (a+1).saturating_mul(dp[i-1][k-1]).saturating_add(b);
            if k < i {
                chmin!(dp[i][k], dp[i-1][k]);
            }
        }
    }

    let ts: Vec<_> = dp[shops.len()].iter().copied().take_while(|&t| t <= t_max).collect();
    let prefsums: Vec<_> = zeros.into_iter().lscan(0, |&acc, b| acc + b).skip(1).collect();

    let ans = (0..ts.len()).rev().scan(0, |i, j| {
        let t = ts[j];
        *i += prefsums[*i..].iter().take_while(|&&s| t + s <= t_max).count();
        Some(*i + j)
    }).max().unwrap();
    echo!(ans);
}

