fn run() {
    input! {
        n: usize,
        t: usize,
        p: [(usize, usize); n],
    }
    let mut zero = vec![];
    let mut q = vec![];
    for (a, b) in p {
        if a == 0 {
            zero.push(b);
        } else {
            q.push((a, b));
        }
    }
    q.sort_by(|a, b| (b.0 * (a.1 + 2)).cmp(&(a.0 * (b.1 + 2))));
    let m = 500;
    let mut dp = vec![t + 1; m + 1];
    dp[0] = 0;
    for (a, b) in q {
        for i in (1..(m + 1)).rev() {
