use std::cmp::{max, min};

const N: usize = 33;

fn main() {
    let (r, w) = (std::io::stdin(), std::io::stdout());
    let mut sc = IO::new(r.lock(), w.lock());
    let n: usize = sc.read();
    let time: u64 = sc.read();

    let mut ab = vec![];
    let mut a_zero = vec![];
    for _ in 0..n {
        let a = sc.read::<u64>();
        let b = sc.read::<u64>();
        if a == 0 {
            a_zero.push(b);
        } else {
            ab.push((a, b));
        }
    }
    ab.sort_by(|&(a0, b0), &(a1, b1)| {
        let c0 = a1 * (b0 + 1);
        let c1 = a0 * (b1 + 1);
        c0.cmp(&c1)
    });

    let mut dp = vec![time + 1; N + 1];
    dp[0] = 0;
    for (a, b) in ab.into_iter() {
        for i in (0..N).rev() {
            dp[i + 1] = min(dp[i + 1], (a + 1) * (dp[i] + 1) + b);
        }
    }

    a_zero.sort();
    let mut b_sum = vec![0];
    for (i, b) in a_zero.into_iter().enumerate() {
        let prev = b_sum[i];
        b_sum.push(prev + b + 1);
    }

    let mut ans = 0;
    for (tail, tail_sum) in b_sum.into_iter().enumerate() {
        for head in 0..N {
            if tail_sum + dp[head] > time {
                continue;
            }
            ans = max(ans, tail + head);
        }
    }

    println!("{}", ans);
}

pub struct IO<R, W: std::io::Write>(R, std::io::BufWriter<W>);

impl<R: std::io::Read, W: std::io::Write> IO<R, W> {
    pub fn new(r: R, w: W) -> Self {
        Self(r, std::io::BufWriter::new(w))
    }
    pub fn write<S: ToString>(&mut self, s: S) {
        use std::io::Write;
        self.1.write(s.to_string().as_bytes()).unwrap();
    }
    pub fn read<T: std::str::FromStr>(&mut self) -> T {
        use std::io::Read;
        let buf = self
            .0
            .by_ref()
            .bytes()
            .map(|b| b.unwrap())
            .skip_while(|&b| b == b' ' || b == b'\n' || b == b'\r' || b == b'\t')
            .take_while(|&b| b != b' ' && b != b'\n' && b != b'\r' && b != b'\t')
            .collect::<Vec<_>>();
        unsafe { std::str::from_utf8_unchecked(&buf) }
            .parse()
            .ok()
            .expect("Parse error.")
    }
    pub fn vec<T: std::str::FromStr>(&mut self, n: usize) -> Vec<T> {
        (0..n).map(|_| self.read()).collect()
    }
    pub fn chars(&mut self) -> Vec<char> {
        self.read::<String>().chars().collect()
    }
}

